  def solve(): Unit = {
    val N, K = ni()
    val A = na(N, -K)
    val cum = cumSum(A)
    val sorted = cum.clone()
    sort(sorted)

    val cntr = new ZippedCounter(sorted)

    var ans = 0L
    REP(N + 1) { i =>
