const ll MOD = 1000000007;

int X[524288];

ll RSQ(int s, int t, int k = 1, int l = 0, int r = 262143) {
	if (t < l || r < s)return 0;
	if (s <= l && r <= t) {
		return X[k];
	}
	ll lv = RSQ(s, t, k * 2, l, (l + r) / 2);
	ll rv = RSQ(s, t, k * 2 + 1, (l + r) / 2 + 1, r);
	return lv + rv;
}

void upd(int x, int v = 0) {
	x += 262144;
	X[x] = v;
	while (x > 1) {
		x /= 2;
		X[x] = X[x * 2] + X[x * 2 + 1];
	}
}

