	for (int i = 1;i <= N;i++) {
		cin >> Y;
		B[i] = Y - K;
		B[i] += B[i - 1];
		A[i] = { B[i],i };
		upd(i, 1);
	}
	sort(all(A));
	for (int i = 0;i <= N;i++) {
		C[A[i].second] = i;
	}
	ll ans = 0;
	for (int i = 0;i <= N;i++) {
		ans += RSQ(C[i] + 1, N);
		upd(C[i]);
	}
	cout << ans << endl;
}

