template <typename T>
class BinaryIndexTree
{
private:
	const int n;
	vector<T> bit;
public:
	BinaryIndexTree(int n) : n(n), bit(n, 0) {}
	void add(int a, T w) {
		for (int x = a; x <= n; x += x & -x) bit[x] += w;
	}
	T sum(int a) {
		T ret = 0;
		for (int x = a; x > 0; x -= x & -x) ret += bit[x];
		return ret;
	}
};

