void solve(){
	int N;
	LL K;
	cin >> N >> K;
	vector<LL> A(N);
	//値から欲しい平均値を引く
	for(int i=0;i<N;++i){
		cin >> A[i];
		A[i] -= K;
	}

	//累積和を取る
	vector<LL> sum(N);
	sum[0] = A[0];
	for(int i=1;i<N;++i){
		sum[i] = sum[i-1] + A[i];
	}

	//累積和に対して座標圧縮する。
	vector<LL> B = sum;
	B.push_back( 0 );//基準を入れておく
	UNIQUE(B);
	vector<int> sumC(N);//圧縮されたindex+1に値を変える
	for(int i=0;i<N;++i){
		int index = lower_bound(B.begin(),B.end(),sum[i]) - B.begin();
		sumC[i] = index + 1;
	}
	int size = B.size();
	BITree BIT(size);

	//基準の値
	int index = lower_bound(B.begin(),B.end(),0) - B.begin();
	BIT.add(index+1,1);//0の分

	LL ans = 0;
	for(int i=0;i<N;++i){
		LL res = BIT.sum( sumC[i] );
		ans += res;
		BIT.add(sumC[i],1);
	}
	cout << ans << endl;
}

