typedef long long s64;
int val[200001 * 80], ls[200001 * 80], rs[200001 * 80], tot, root;
s64 a[200001];
int n, k;
s64 d = 1000000000000001ll;

void ins(s64 x, int& k = root, s64 l = -1000000000000000 + d, s64 r = 1000000000000000 + d)
{
    if (!k)
    {
        k = ++tot;
    }
    val[k]++;
    if (l == r)
    {
        return;
    }
    s64 mid = (l + r) / 2;
    if (x <= mid)
    {
        ins(x, ls[k], l, mid);
    }
    else
    {
        ins(x, rs[k], mid + 1, r);
    }
}

int qry(s64 le, s64 ri, int k = root, s64 l = -1000000000000000 + d, s64 r = 1000000000000000 + d)
{
    if (!k)
    {
        return 0;
    }
    if (le <= l && r <= ri)
    {
        return val[k];
    }
    s64 mid = (l + r) / 2;
    int ans = 0;
    if (le <= mid)
    {
        ans += qry(le, ri, ls[k], l, mid);
    }
    if (mid < ri)
    {
        ans += qry(le, ri, rs[k], mid + 1, r);
    }
    return ans;
}

