        a[i] -= k;
    }
    for (int i = 1; i <= n; i++)
    {
        a[i] += a[i - 1];
    }
    ins(0 + d);
    s64 ans = 0;
    for (int i = 1; i <= n; i++)
    {
        int x = qry(-1000000000000000 + d, a[i] + d);
        ans += x;
        ins(a[i] + d);
    }
    cout << ans << endl;
    return 0;
}

