	    sum[i]=sum[i-1]+uni[i].y;

	s=0;
	for(int i=mid+1;i<=r;i++)
	{
		s+=a[i];
		int pos=search(-s);
		if (pos>=0) ans+=sum[pos];
	}

	return ans;
}


