    }

    vector<ll> sorted_sum(sum);
    sort(all(sorted_sum));
    sorted_sum.erase(unique(all(sorted_sum)),sorted_sum.end());

    map<ll,int> val2id;
    int V = 0;
    for(const auto &x:sorted_sum) val2id[x]=V++;

    SumSegTree st(V);
    rep(i,n) st.add(val2id[sum[i]],1);

    ll ans = 0;
    ll now = 0;
    rep(i,n)
    {
        int idx = lower_bound(all(sorted_sum),now)-sorted_sum.begin();
        ans += st.query(idx,V);

