using namespace std;

llint N, K;
llint a[200005];
llint sum[200005];
pair<llint, int> p[200005];

llint bit[200005];

void init()
{
	for(int i = 1; i <= N+1; i++) bit[i] = 0;
}

llint query(llint i)
{
	i++;
	llint ret = 0;
	while(i > 0){
		ret += bit[i];
		i -= i & (-i);
	}
	return ret;
}

void add(llint i, llint val)
{
	i++;
	while(i <= N+1){
		 bit[i] += val;
		i += i & (-i);
	}
}

int main(void)
{
	cin >> N >> K;
	for(int i = 1; i <= N; i++){
		cin >> a[i];
		a[i] -= K;
	}

	for(int i = 1; i <= N; i++) sum[i] = sum[i-1] + a[i];
	for(int i = 0; i <= N; i++) p[i] = make_pair(sum[i], i);
	sort(p, p+N+1);

	llint ans = 0;
	for(int i = 0; i <= N; i++){
		ans += query(p[i].second);
		add(p[i].second, 1);
	}

	cout << ans << endl;
	return 0;
}

