template<typename T>
struct BIT {
	std::vector<T> dat;

	BIT(int n) : dat(n + 1) {}

	void add(int k, T v) {
		k++;
		while (k < dat.size()) {
			dat[k] += v;
			k += k & -k;
		}
	}

	T sum(int k) {
		k++;
		T ret = 0;
		while (k > 0) {
			ret += dat[k];
			k &= k - 1;
		}
		return ret;
	}
};

int main() {
