    for(int i = 1; i <= nn-nn/2; ++i) {
        while (j <= nn/2 && s1[j] <= s2[i]) ++j; --j;
        ans3 += j;
    }
    merge(s1+1, s1+1+nn/2, s2+1, s2+1+nn-nn/2, s+1);
