//Binary Indexed Tree
class Binary_Indexed_Tree_Range_Sum_Query {
public:
	int N;
	vector<long long> node;

	Binary_Indexed_Tree_Range_Sum_Query(int N) : N(N), node(vector<long long>(N + 1, 0)) {
	}

	void update(int idx, long long var) {
		for (++idx; idx <= N; idx += idx & -idx) node[idx] += var;
	}

	long long getvar(int idx) {
		long long ret = 0;
		for (++idx; idx >= 1; idx -= idx & -idx) ret += node[idx];
		return ret;
	}
};

//Seat Pressure
class Zarts {
public:
	vector<long long> solve(const vector<long long> & ar,int cnt = 0) {
		vector<long long> ret;
		map<long long, int> mp;
		for (auto val : ar) mp[val] = 0;
		for (auto &u : mp) u.second = cnt++;
		for (auto val : ar) ret.push_back(mp[val]);
		return ret;
	}
};

int main() {
	ll N,K; cin >> N >> K;
	V<ll> a(N + 1,0);
	REP(i, N) cin >> a[i + 1];
	REP(i, N) a[i + 1] -= K;
	REP(i, N) a[i + 1] += a[i];

	Zarts Z;
	a = Z.solve(a);

	ll ans = 0;
	Binary_Indexed_Tree_Range_Sum_Query BIT(N + 100);
	REP(i, N + 1) {
		ans += BIT.getvar(a[i]);
		BIT.update(a[i], 1);
	}
	cout << ans << endl;


	return 0;
}

