int solve()
{
	scanf("%d %d", &N, &K);
	a.resize(N + 1);
	b.resize(N + 1);
	s.resize(N + 1);
	a[0] = 0;
	rep(i, N)
	{
		scanf("%d", &a[i + 1]);
	}

	b[0] = 0;
	rep(i, N)
		b[i + 1] = b[i] + a[i + 1] - K;
	rep(i, N + 1)
		s[i] = b[i];
	sort(s.begin(), s.end());

	LL count = 0;
	LL x0 = lower_bound(s.begin(), s.end(), b[0]) - s.begin();
	bit.add(x0, 1);

	repi(i, N + 1)
	{
		LL y = lower_bound(s.begin(), s.end(), b[i]) - s.begin();
		count += bit.total(y);
		LL x = lower_bound(s.begin(), s.end(), b[i]) - s.begin();
		bit.add(x, 1);
	}

	printf("%d", count);

	return 0;
}

