bool cmp(int a,int b)
{
	return a>b;
}

int search(int p)
{
	int l=-1,r=uni.size();
	while(l+1<r)
	{
		int mid=(l+r)>>1;
		if (uni[mid].x>=p) l=mid;
		else r=mid;
	}
	return l;
}

LL calc(int l,int r)
{
	if (l==r)
	{
		if (a[l]>0) return 1;
		else return 0;
	}

	int mid=(l+r)>>1;
	LL ans=calc(l,mid)+calc(mid+1,r);

	temp.clear();uni.clear();
	LL s=0;
	for(int i=mid;i>=l;i--)
	{
		s+=a[i];
		temp.push_back(s);
	}
	sort(temp.begin(),temp.end(),cmp);

	for(int i=0;i<temp.size();i++)
	{
		if (uni.size()==0 || temp[i]!=uni[uni.size()-1].x)
		    uni.push_back(mp(temp[i],1));
		else uni[uni.size()-1].y++;
	}

	sum[0]=uni[0].y;
	for(int i=1;i<uni.size();i++)
	    sum[i]=sum[i-1]+uni[i].y;

	s=0;
	for(int i=mid+1;i<=r;i++)
	{
		s+=a[i];
		int pos=search(-s);
		if (pos>=0) ans+=sum[pos];
	}

	return ans;
}


