class BIT {

public:
	vll v;
	ll size;
	BIT(ll sizeget) {
		size = sizeget;
		v.res(size + 1, 0);
	}
	BIT(vll cpyvec) {
		copy(cpyvec);
	}
	bool add(ll index, ll num) {
		index++;
		if (index > size) return false;
		while (index <= size) {
			v[index] += num;
			index += LSB(index);
		}
		return true;
	}
	ll sum(ll index) {
		index++;
		index = min(index, size);
		ll ans = 0;
		while (index) {
			ans += v[index];
			index -= LSB(index);
		}
		return ans;
	}
	void copy(vll cpyvec) {
		size = cpyvec.sz;
		v.res(size + 1, 0);
		REP(i, size) add(i, cpyvec[i]);
	}

};

ll gcd(ll a, ll b) { if (b == 0)return a; return gcd(b, a%b); }
ll lcm(ll a, ll b) { return a / gcd(a, b)*b; }

pl4 Bezout(ll a, ll b) {
	if (b != 0) {
		pl4 xy;
		xy = Bezout(b, a%b);
		return mp(xy.se, xy.fi - ((a / b)*xy.se));
	}
	if (b == 0) {
		return mp(1, 0);
	}
}
pl4 Bez(ll a, ll b, ll c) {
	pl4 xy;
	ll x, y, z, gc;
	xy = Bezout(a, b);
	gc = gcd(a, b);
	if (c%gc != 0) return mp(-1, -1);
	x = xy.fi*(c / gc); y = xy.se*(c / gc);
	if (x < 0) z = rup(-x, (b / gc));
	if (x >= 0) z = -x / (b / gc);
	x += z * (b / gc);
	y -= z * (a / gc);
	return mp(x, y);
}

