long long solve(int l, int r)
{
    if (l == r) return 0;
    if (l + 1 == r) return a[l] >= 0 ? 1 : 0;
    auto mid = (l + r) >> 1;

    vector<long long> mask;
    mask.reserve(mid - l);
    long long sum = 0;
    for(int i = mid - 1; i >= l; --i)
    {
        sum += a[i];
        mask.push_back(sum);
    }
    sort(begin(mask), end(mask));
    long long ans = 0;
    sum = 0;
    for(int i = mid; i < r; ++i)
    {
        sum += a[i];
        ans += mask.end() - lower_bound(begin(mask), end(mask), -sum);
    }
    ans += solve(l, mid) + solve(mid, r);
    return ans;
}

