typedef unsigned ui;
typedef long long ll;
typedef unsigned long long ul;

ll a[N], s[N];

ui st[1 << 18], m;
void modify(ui w) {
	w += m;
	do st[w]++; while (w >>= 1);
}

ui query(ui l, ui r) {
	ui res = 0;
	for (l += m - 1, r += m + 1; l ^ r ^ 1; l >>= 1, r >>= 1) {
		if (~l & 1) res += st[l ^ 1];
		if (r & 1) res += st[r ^ 1];
	}
	return res;
}

