struct BinaryIndexedTree {
    int length;
    vector<int> node;
    BinaryIndexedTree (int N) : length(N + 1), node(length, 0) {}
    void add(int idx, int val) {
        for (int i = idx; i < length; i += (i & -i)) node[i] += val;
    }
    int getsum(int idx) {
        int ans = 0;
        for (int i = idx; i > 0; i -= (i & -i)) ans += node[i];
        return ans;
    }
};

int main() {
