	int init = 0;

	Segment(const vector<int>& vec)
	{
		int sz = vec.size();
		n = 1;
		while(n < sz) n <<= 1;

		node.resize(2 * n - 1,init);

		for(int i = 0;i < sz;i++)
		{
			node[n - i + 1] = vec[i];
		}
		for(int i = n - 2;i >= 0;i--)
