using namespace std;
typedef long long ll;
const int N=2e5+5;
int n;ll k,a[N]={0};
int lef[4*N],rig[4*N];ll mi[4*N],ma[4*N];
void build(int k,int l,int r) {
    lef[k]=l,rig[k]=r;
    if(l==r) {
        mi[k]=ma[k]=a[l];
        return;
    }
    int mid=(l+r)>>1;
    build(k<<1,l,mid);build(k<<1|1,mid+1,r);
    mi[k]=min(mi[k<<1],mi[k<<1|1]);
    ma[k]=max(ma[k<<1],ma[k<<1|1]);
}
int query(int k,int l,int r,ll val) {
    if(l<=lef[k]&&r>=rig[k]) {
        if(mi[k]>=val) return rig[k]-lef[k]+1;
        else if(ma[k]<val) return 0;
        else return query(k<<1,l,r,val)+query(k<<1|1,l,r,val);
    }
    int mid=(lef[k]+rig[k])>>1;
    int ans=0;
    if(l<=mid) ans+=query(k<<1,l,r,val);
    if(r>mid) ans+=query(k<<1|1,l,r,val);
    return ans;
}
int main() {
    scanf("%d%lld",&n,&k);
    for(int i=1;i<=n;i++) scanf("%lld",a+i),a[i]-=k,a[i]+=a[i-1];
    ll ans=0,cur=0;
    build(1,1,n);
    for(int i=1;i<=n;i++) {
        ans+=query(1,i,n,cur);
        cur=a[i];
    }
    printf("%lld\n",ans);
    return 0;
}

