	for(i=0; i<NN; i++)
		Left[n+i] = Right[n+i] = sum3[i];
	for(; i<n; i++)
		Left[n+i] = Right[n+i] = Left[n+i-1]+1;
	for(i=n-1; i>=1; i--){
		Left[i] = Left[2*i];
		Right[i] = Right[2*i+1];
	}
