    cin >> N >> K;
    vector<int> A(N);
    rep(i, 0, N) cin >> A[i];
    rep(i, 0, N-1) A[i+1] += A[i];
    vector<ll> B(N + 1);
    rep(i, 0, N) B[i+1] = A[i] - (i + 1) * K;
    vector<int> C = compress(B);
    ll ans = 0;
    BIT bit(N + 1);
    rep(i, 0, N + 1) {
        ans += bit.sum(C[i]);
        bit.add(C[i], 1);
    }
    cout << ans << endl;
    return 0;
}

