    BIT<int> bit(cmp.size());
    int64_t ans = 0;
    for(int64_t s : S){
        int idx = lower_bound(cmp.begin(), cmp.end(), s) - cmp.begin();
        ans += bit.sum_between(0, idx);
        bit.plus(idx, 1);
    }
    cout << ans << endl;
}

