using ll = int64_t;
template <typename T>
class Bit{
    private:
        ll size;
        T *data;
        T *arr;
        T identity_ele;

    public:

        Bit(ll size, T identity_ele){
            ll newsize = 1;
            while(newsize < size)  newsize = newsize << 1;
            this->size = newsize + 1;
            this->identity_ele = identity_ele;
            data = new ll[this->size];
            arr = new ll[size];
            for(ll i = 0; i < size; ++i){
                data[i] = identity_ele;
                arr[i] = identity_ele;
            }
        }

        /*
         * 0-origin
         */
        T sum(ll pos){
            T ret = identity_ele;
            while(pos > 0){
                ret += data[pos];
                pos -= pos & -pos;
            }
            return ret;
        }

        /*
         * 0-origin
         */
        void add(ll pos, T delta){
            arr[pos] += delta;
            pos++;
            while(pos <= size){
                data[pos] = data[pos] + delta;
                pos += pos & -pos;
            }
        }

        void update(ll pos, T value){
            T delta = value - arr[pos];
            this->add(pos, delta);
        }
};
