    Bit<ll> B(ID.size(), 0);
    B.add(ID[0], 1);
    ll ans = 0;
    for(ll i = 0; i < N; i++){
        auto ite = upper_bound(uniq.begin(), uniq.end(), sum[i + 1]);
        ll idx = ite - uniq.begin() - 1;
