  ios_base::sync_with_stdio(false);

  cin >> N>>K;
  FOR(i, 0, N)cin >> a[i];
  FOR(i, 0, N)a[i] -= K;

  vector < ll >v;

  FOR(i, 1, N + 1) {
	  sum[i] += sum[i - 1] + a[i];
	  v.push_back(sum[i]);
  }
  sort(v.begin(), v.end());


  int added = 0;
  BIT<int, 20>bit;
  for (int i = N - 1; i >= 0; i--) {
	  int x = lower_bound(v.begin(), v.end(), sum[i + 1]) - v.begin();
	  added++;
	  bit.add(x, 1);
	  int y = lower_bound(v.begin(), v.end(), sum[i]) - v.begin();
	  ans += added - bit.total(y - 1);
  }

  cout << ans << endl;

  return 0;
}

