template <typename T, typename F = std::plus<T>>
class fenwick_tree {
public:
	using value_type = T;
private:
	std::vector<T> m_data;
	F m_func;
public:
	fenwick_tree()
		: m_data(1)
		, m_func()
	{ }
	explicit fenwick_tree(
		size_t n,
		const value_type& x = value_type(),
		const F& f = F())
		: m_data(n + 1)
		, m_func(f)
	{
		m_data[0] = value_type();
		for(size_t i = 1; i <= n; ++i){
			m_data[i] = x;
			for(size_t j = i; (j & 1) == 0u; j >>= 1){
				m_data[i] = m_func(m_data[j], m_data[i]);
			}
		}
	}
	size_t size() const {
		return m_data.size() - 1;
	}
	value_type query(size_t i) const {
		value_type s = m_data[i];
		for(i -= i & -i; i > 0; i -= i & -i){
			s = m_func(m_data[i], s);
		}
		return s;
	}
	void modify(size_t i, const value_type& x){
		const auto n = m_data.size();
		for(++i; i < n; i += i & -i){
			m_data[i] = m_func(m_data[i], x);
		}
	}
};

int main(){
	ios_base::sync_with_stdio(false);
	int n;
	ll k;
	cin >> n >> k;
	vector<ll> a(n);
	for(int i = 0; i < n; ++i){ cin >> a[i]; }
	vector<ll> b(n + 1);
	for(int i = 0; i < n; ++i){ b[i + 1] = b[i] + a[i]; }
	vector<ll> c(n + 1);
	for(int i = 0; i <= n; ++i){ c[i] = b[i] - i * k; }
	vector<ll> comp(c);
	sort(comp.begin(), comp.end());
	comp.erase(unique(comp.begin(), comp.end()), comp.end());
	const int m = comp.size();
	vector<int> d(n + 1);
	for(int i = 0; i <= n; ++i){
		d[i] = lower_bound(comp.begin(), comp.end(), c[i]) - comp.begin();
	}
	fenwick_tree<int> ft(m);
	for(int i = 0; i <= n; ++i){ ft.modify(d[i], 1); }
	ll answer = 0;
	for(int i = 0; i < n; ++i){
		ft.modify(d[i], -1);
		const int t = lower_bound(comp.begin(), comp.end(), c[i]) - comp.begin();
		answer += (n - i) - ft.query(t);
	}
	cout << answer << endl;
	return 0;
}

