		while(k>0){
			k=(k-1)/2;
			date[k]=date[k*2+1]+date[k*2+2];
		}
	}
	int Query(int a){
		return Query_func(a,n,0,0,n);
	}
	int Open(int k){
		return date[k+n-1];
	}
};

