class BIT
{
public:
	std::vector<LL>bit;
	void init(LL n)
	{
		bit.resize(n + 1, 0);
	}
	LL sum(LL i)
	{
		if (!i) return 0;
		return bit[i] + sum(i - (i & -i));
	}
	void add(LL i, LL x)
	{
		if (i >= (LL)bit.size()) return;
		bit[i] += x;
		add(i + (i & -i), x);
	}
};

