class BIT {
public:
    vi bit;
    int n;
    BIT(int x) {
        n = x;
        bit = vi(n+1);
    }

    void add(int i, int w) {
        ++i;
        for (int x = i; x <= n; x += (x & -x)) bit[x] += w;
    }
    //半開区間
    int sum(int i) {
        int ret = 0;
        for (int x = i; x > 0; x -= (x & -x)) ret += bit[x];
        return ret;
    }
};

bool solve() {
    int n, k; cin >> n >> k;
    vi A(n); rep (i, n) cin >> A[i], A[i] -= k;
    vi csum(n+1); csum[0] = 0;
    map<int, int> ma;
    set<int> se = {0};
    rep (i, n) csum[i+1] = csum[i] + A[i], se.insert(csum[i+1]);
    int cnt = 0;
    for (auto& s : se) {
        ma[s] = cnt;
        cnt++;
    }

    rep (i, n+1) {
        csum[i] = ma[csum[i]];
    }

    BIT bit(se.size());
    bit.add(csum[0], 1);

    int ans = 0;
    rep (i, n) {
        ans += bit.sum(csum[i+1]+1);
        bit.add(csum[i+1], 1);
    }

    cout << ans << endl;
}

