template <typename T>
class BIT{
public:
    vector<T> data;
    int n;
    BIT(int n_){
        n = n_;
        data.assign(n, T(0));
    }

    void add(int a, int w){
        for (int x = a; x < n; x |= x + 1) data[x] += w;
    }

    T sum(int a){
        int ret = 0;
        for (int x = a - 1; x >= 0; x = (x & (x + 1)) - 1) {
            ret += data[x];
        }
        return ret;
    }
};

