using namespace std;
#define MAX 200005

typedef long long ll;

int N, K, r = 0;
ll c[MAX];
int solve(ll i, ll j, ll k) {
    if (i < 0 || j >= N) return 0;
    int res = (c[j+1]-c[i])/k >= K;
    if (res) r++;
    return res;
}

int main() {
    int a[MAX], i, k;

    cin >> N >> K;
    c[0] = 0;
    set<int> s;
    set<int>::iterator it, it2;
    for (i = 0; i < N; i++) {
        cin >> a[i];
        if (a[i] >= K) s.insert(i), r++; // sequence of length 1
        c[i+1] = c[i]+a[i];
    }

    // solve for sequence of length k
    for (k = 2; k <= N; k++) {
        for (it = s.begin(); it != s.end();) {
            // check before (only if previous is >1 away)
            if ((it == s.begin() || *it - *prev(it) > 1) && solve(*it-1, *it+(k-2), k)) {
                s.insert(*it-1);
            }

            // check after
            if (solve(*it, *it+(k-1), k)) {
                ++it;
            } else {
                it2 = it;
                ++it;
                s.erase(it2);
            }
        }
    }
    cout << r << '\n';
}

