	}
	vector<int> s(N+1);
	set<int> memo;
	unordered_map<int, int> enc;
	memo.insert(0);
	for (int i = 0; i < N; ++i) {
		s[i + 1] = s[i] + A[i];
		memo.insert(s[i + 1]);
	}
	int cnt = 0;
	for (auto it = memo.rbegin(); it != memo.rend(); ++it, ++cnt) {
		enc[*it] = cnt;
	}
	int size = memo.size();
	for (int i = 0; i < N+1; ++i) {
		s[i] = enc[s[i]];
	}
	cout << mergecount(s) << endl;;
}

