typedef long long ll;

using namespace std;

ll bit[200002], n;
ll a[200002], c[200002], k;
class Solution {
public:
    long long sum(int i)
    {
        long long s = 0;
        while (i)
        {
            s += bit[i];
            i -= i & -i;
        }
        return s;
    }

    void add(int i, long long x)
    {
        while (i && i <= n)
        {
            bit[i] += x;
            i += i & -i;
        }
    }

    void solve(std::istream& in, std::ostream& out) {
        vector<ll> b;
        in >> n >> k;
        a[0] = 0;
        b.push_back(0);
        bit[0] = 0;
        for (int i = 1; i <= n; i++)
        {
            int t = 0;
            in >> t;
            a[i] = t - k;
            a[i] += a[i - 1];
            b.push_back(a[i]);
            bit[i] = 0;
        }

        sort(b.begin(), b.end());
        b.erase(unique(b.begin(), b.end()), b.end());

        ll ans = 0;
        for (int i = 0; i <= n; i++)
        {
            c[i] = (ll)(lower_bound(b.begin(), b.end(), a[i]) - b.begin());
            ans += sum(c[i] + 1);
            add(c[i] + 1, 1);
        }

        out << ans;
    }
};

void solve(std::istream& in, std::ostream& out)
{
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}


