struct It {
    struct Node {
        int ans, sum;
        vector<int> left, right;
        Node() {
            ans = sum = 0;
            left.clear(); right.clear();
        }
        Node(int val) {
            ans = (val >= 0); sum = val;
            left.pb(val); right.pb(val);
        }
        Node operator + (const Node& rhs) const {
            Node ret;
            ret.ans = ans + rhs.ans; ret.sum = sum + rhs.sum;
            for (int i : left) ret.left.pb(i);
            for (int i : rhs.left) ret.left.pb(sum + i);
            for (int i : rhs.right) ret.right.pb(i);
            for (int i : right) ret.right.pb(rhs.sum + i);
            sort(ret.left.begin(), ret.left.end() );
            sort(ret.right.begin(), ret.right.end() );
            int pter = rhs.left.size() - 1;
            for (int i = 0; i < right.size(); ++i) {
                while(pter >= 0 && right[i] + rhs.left[pter] >= 0) pter --;
                ret.ans += rhs.left.size() - pter - 1;
            }
            return ret;
        }
    } node[N << 2];
    void build_tree(int nd, int left, int right) {
        if(left == right) { node[nd] = Node(a[left]); return ; }
        int mid = left + right >> 1;
        build_tree(nd << 1, left, mid); build_tree(nd << 1 | 1, mid + 1, right);
        node[nd] = node[nd << 1] + node[nd << 1 | 1];
    }
} it;

