	ll mid = l + r >> 1;
	if(ar <= mid) return ask(ls[now],ls[pre],l,mid,al,ar);
	else if(al > mid) return ask(rs[now],rs[pre],mid+1,r,al,ar);
	else return ask(ls[now],ls[pre],l,mid,al,mid)+ask(rs[now],rs[pre],mid+1,r,mid+1,ar);  
}

