LL BIT[maxn];

/* incremental A[i] w/ value val */
void update(LL T[], const int n, int i, const LL val)
{
    if (i > 0) {
        while (i < n) {
            T[i] += val; i += (i & -i);
        }
    }
}

/* Query the *accumulative* value of A[1,i] */
LL query(const LL T[], int i)
{
    LL sum = 0;
    if (i > 0) {
        while (i > 0) {
            sum += T[i]; i -= (i & -i);
        }
    }
    return sum;
}

