void change(int rt,int nrt,int l,int r,int x)
{
	v[nrt]=v[rt]+1;if(l==r)return;int mid=(l+r)>>1;
	if(x<=mid){
		ls[nrt]=++tot;
		rs[nrt]=rs[rt];
		change(ls[rt],ls[nrt],l,mid,x);
	}else{
		rs[nrt]=++tot;
		ls[nrt]=ls[rt];
		change(rs[rt],rs[nrt],mid+1,r,x);
	}
}
int ask(int lrt,int rrt,int l,int r,int x,int y)
{
	if(x<=l&&r<=y)return v[rrt]-v[lrt];
	int mid=(l+r)>>1,tmp=0;
	if(x<=mid)tmp=ask(ls[lrt],ls[rrt],l,mid,x,y);
	if(y>mid)tmp+=ask(rs[lrt],rs[rrt],mid+1,r,x,y);
	return tmp;
}
