#include <bits/stdc++.h>
using namespace std;

const int MAXN = 2e5 + 10;

int a[MAXN];
long long sum[MAXN];

// interval tree
int cnt[MAXN];

inline void pushup (int rt) {
    cnt[rt] = cnt[rt<<1] + cnt[rt<<1|1];
}

void upd (int l, int r, int val, int st, int en, int rt) {
    if (l <= st && en <= r) {
    	cnt[rt] += val;
        return;
    }

    int md = (st+en)>>1;
    if (l <= md) upd(l,r,val,st,md,rt<<1);
    if (md < r) upd(l,r,val,md+1,en,rt<<1|1);
    pushup(rt);
}

long long query (int l, int r, int st, int en, int rt) {
    if (l <= st && en <= r) {
        return cnt[rt];
    }

    long long ret = 0;
    int md = (st+en)>>1;
    if (l <= md) ret += query(l,r,st,md,rt<<1);
    if (md < r) ret += query(l,r,md+1,en,rt<<1|1);
    return ret;
}

int bs (int val, int st, int en) {
	while (st != en) {
		int md = (st + en) >> 1;
		if (val <= sum[md]) en = md;
		else st = md + 1;
	}
	return st;
}

int main (void) {
	int n, k;
	scanf("%d%d", &n, &k);
	for (int i = 1; i <= n; i++) {
		scanf("%d", &a[i]);
		sum[i] = sum[i-1] + a[i] - k;
	}
	sort(sum,sum+n+1);
	int m = unique(sum,sum+n+1) - (sum+1);

	long long SUM = 0, ans = 0;
	for (int i = 0; i <= n; i++) {
		int pos = bs(SUM,0,m);
		upd(pos,pos,1,0,m,1);
		ans += query(0,pos,0,m,1) - 1;
		SUM += a[i+1] - k;
	}
	printf("%lld\n", ans);
}

