class RSQ{
private:
    int n;
    vector<int> node;
    int get2(int a, int b, int k, int l, int r){
        if(a==l and r==b)return node[k];
        int m=(l+r)/2;
        if(b<=m)return get2(a,b,k*2+1,l,m);
        else if(a>=m)return get2(a,b,k*2+2,m,r);
        else return get2(a,m,k*2+1,l,m)+get2(m,b,k*2+2,m,r);
    }
public:
    RSQ(vector<int> vec){
        int tmp_size=vec.size();
        n=1; while(n<tmp_size)n*=2;
        node=vector<int>(n*2-1,0);
        for(int i=0; i<tmp_size; i++)node[i+n-1]=vec[i];
        for(int i=n-2; i>=0; i--)node[i]=node[i*2+1]+node[i*2+2];
    }
    void update(int x, int v){
        x+=n-1; node[x]+=v;
        while(x>0){x=(x-1)/2;node[x]+=v;}
    }
    int get(int a, int b){return get2(a,b,0,0,n);}
};

