struct segtree
{
    segtree(){}
    void init(int N)
    {
        this->N=N;
        build(1,N,1);
    }
    void build(int l, int r, int id=1)
    {
        if(l==r)st[id]=0;
        else
        {
            int mid = (l+r)/2;
            build(l,mid,id<<1);
            build(mid+1,r,(id<<1)|1);
            up(id);
        }
    }
    void up(int id)
    {
        st[id]=st[id<<1]+st[(id<<1)|1];
    }
    int Sum(int L, int R, int l, int r, int id=1)
    {
        if(r<L||R<l)return 0;
        if(L<=l&&r<=R)return st[id];
        int mid = (l+r)/2;
        return Sum(L,R,l,mid,(id<<1))+Sum(L,R,mid+1,r,(id<<1)|1);
    }
    void mod(int pos, int d, int l, int r, int id=1)
    {
        if(l==r&&l==pos)
        {
            st[id]+=d;
            return;
        }
        int mid = (l+r)/2;
        if(pos>mid)mod(pos,d,mid+1,r,(id<<1)|1);
        else mod(pos,d,l,mid,(id<<1));
        up(id);
    }
    //helper functions
    int Sum(int L, int R)
    {
        return Sum(L,R,1,N);
    }
    void mod(int pos, int d)
    {
        mod(pos,d,1,N);
    }
    int N;
    static const int ST_MAXN = 400005;
    int st[ST_MAXN*4];
}segt;

