int sum_fenwick(long long id) {
  int sum = 0;

  for (id++; id > 0; id -= id & -id) {
    sum += fenwick[id];
  }

  return sum;
}

void add_fenwick(long long id, int value) {
  if (value == 0 || id < 0) {
    return;
  }

  for(id++; id < 200001; id += id & -id) {
    fenwick[id] += value;
  }
}


