#define N 202
using namespace std;
int n,k,tree[N],sum[N],f[N],m,ans;
int lowbit(int x){return x&-x;}
void add(int x,int k)
{
    while(x<=n)
    {
        tree[x]+=k;
        x+=lowbit(x);
    }
}
int query(int x)
{
    int ans=0;
    while(x>0)
    {
        ans+=tree[x];
        x-=lowbit(x);
    }
    return ans;
}
int main()
{
    ios::sync_with_stdio(false);
    cin>>n>>k;
    for(int i=1;i<=n;++i)
        cin>>sum[i];
    for(int i=1;i<=n;++i)
