template <typename T>
struct seg_pL {

  // 一点更新、区間取得 1~N
  using F = function<T(T,T)>;
  // f: [](int x, int y){return min(x,y);}
  // g: [](int x, int y){return y;} // 下にある値をそのまま上へ

  ll n0, n1; const F f, g; const T first_t; map<ll,T> seg;
  // f: 子の計算 g: 親と子(f)の計算

  seg_pL(ll n, const F _f, const F _g, const T& _t) : f(_f), g(_g), first_t(_t) {
    n0 = n, n1 = 1LL; while(n0 > n1) n1<<=1LL;
  }

  void set(ll k, const T& _t) {seg[k+n1]=_t;} // 1~Nのk番目に値を入れる
  void build() { for(int k=n1-1; k>=0; k--) seg[k] = f(seg[2*k], seg[2*k+1]);}

  void update(ll k, const T& t) {

    k += n1; seg[k] = f(seg[k], t); k /= 2;
