	for (i = 0; i < N; ++i) {
		scanf("%lld", &A[i]);
		A[i] -= K;
		psum[i + 1] = psum[i] + A[i];
		vt.push_back(psum[i + 1]);
	}
	sort(vt.begin(), vt.end());
	vt.erase(unique(vt.begin(), vt.end()), vt.end());

	ll cnt = 0;
	for (i = 1; i <= N; ++i) {
		if (psum[i] >= 0) cnt++;
		cnt += (ll)query(1, 0, vt.size()-1, 0, newidx(psum[i]));
		update(1, 0, vt.size()-1, newidx(psum[i]), 1);
	}
	printf("%lld", cnt);
}

