  //aとbは0-で、cとBITは1-で扱う
  for(int i = 1; i <= N; i++){ 
    b[i] = b[i-1]+a[i];
  }
 //次にbを座標圧縮する

  vector<int> c(N+1); vector<int> copy(N+1);

  for(int i = 0; i < N; i++){ copy[i] = b[i];} 

