struct bit {
  vector<T> data;
  bit(int sz) {
    data.assign(++sz, 0);
  }
  bit(int sz, int v){
    data.assign(++sz, v);
    REP(i, sz) data[i+(i&-i)] += data[i];
  }
  T sum(int k) {
    T ret = 0;
    for(++k; k > 0; k -= k & -k) ret += data[k];
    return ret;
  }
  void add(int k, T x) {
    for(++k; k < data.size(); k += k & -k) data[k] += x;
  }
};

