			val2[p] = v;
			if(flag == 0)
				left2[last] = p;
			else
				right2[last] = p;
			break;
		}
		num2[p] ++;
		if(val2[p] == v){
			cnt2[p] ++;
			break;
		}
		else if(val2[p] > v){
			last = p;
			flag = 0;
			p = left2[p];
		}
		else{
			last = p;
			flag = 1;
			p = right2[p];
		}
	}
}

int find_tree(long long v)
{
	int cc = 0;
	int p = 1;
	while(1){
		if(p == 0)
			break;
		if(val2[p] == v){
			cc += cnt2[p];
			if(left2[p] != 0)
				cc += num2[left2[p]];
			break;
		}
		else if(val2[p] < v){
			cc += cnt2[p];
			if(left2[p] != 0)
				cc += num2[left2[p]];
			p = right2[p];
		}
		else{
			p = left2[p];
		}
	}
	return cc;
}

