struct FenwickTree
{
    int N;
    vector<int> data;

    FenwickTree(const int N) : N(N), data(N+1) {}

    void increment(const int n)
    {
        for (int i = n+1; i <= N; i += i & -i)
            data[i]++;
    }

    int query(const int n)
    {
        int result = 0;
        for (int i = n+1; i >= 1; i -= i & -i)
            result += data[i];
        return result;
    }
};

int main()
{
    int N, K; cin >> N >> K;

    struct PrefixSum { int index; ll sum; };
    vector<PrefixSum> prefix_sums;
    prefix_sums.push_back({0, 0});
    ll sum = 0;
    for (int i = 1; i <= N; i++)
    {
        int x; cin >> x;
        sum += x - K;
        prefix_sums.push_back({i, sum});
    }

    const auto compare = [&](const PrefixSum a, const PrefixSum b)
    {
        if (a.sum == b.sum)
            return a.index < b.index;
        else
            return a.sum < b.sum;
    };
    sort(begin(prefix_sums), end(prefix_sums), compare);

    ll answer = 0;
    FenwickTree tree(N+1);
    for (const PrefixSum ps : prefix_sums)
    {
        answer += tree.query(ps.index);
        tree.increment(ps.index);
    }
    cout << answer << endl;
}

