template<typename T>
long long countTranspose(vector<T>& v){
	if(v.size() <= 1) return 0;
	const int n = v.size();
	vector<T> a(v.begin(), v.begin() + n/2);
	vector<T> b(v.begin() + n/2, v.end());
	long long res = countTranspose(a) + countTranspose(b);
	int idxA = 0, idxB = 0;
	for(int i=0;i<n;i++){
		if(idxB < b.size() && (idxA == a.size() || a[idxA] > b[idxB])){
			v[idxA+idxB] = b[idxB];
			++idxB;
			res += a.size() - idxA;
		} else {
			v[idxA+idxB] = a[idxA];
			++idxA;
		}
	}
	return res;
}

