    cin >> n >> k;

    vector<ll> numbers(n);
    rep(i, n) cin >> numbers[i], numbers[i] -= k;

    CumulativeSum cs(n);
    rep(i, n) cs.set(i, numbers[i]);
    cs.calculate();

    Conv conv;
    conv.cache(0);
    rep(i, n) conv.cache(cs.getSum(i));
    conv.build();

    vector<ll> imos(n + 5, 0);

    auto f = [](ll i, ll j) { return i + j; };
    SegmentTree<ll, decltype(f)> segmentTree(f, 0);
    segmentTree.build(imos);

    ll ans = 0;

    vector<ll> bs(n);
