template<typename T>
class BIT{
private:
	int n;
	T* dat;
	T init;
public:
	BIT(int x){
		n = x;
		init = 0; //書き換えする
		dat = new T[n+1];
		for(int i = 0; i < n+1; i++){
			dat[i] = init;
		}
		return;
	}

	~BIT(){
		delete[] dat;
	}

	inline T func(T x, T y){
		return x+y; //書き換えする
	}

	T query(int i){ //[0,i)へのクエリ
		T s = 0;
		while(i > 0){
			s = func(s, dat[i]);
			i -= i&-i;
		}
		return s;
	}

	void add(int i, int x){
		i++;
		while(i <= n){
			dat[i] = func(dat[i],x);
			i += i & -i;
		}
	}
};

