}

vector<int> compress(vector<ll> &A) {
	vector<ll> C = A;
	sort(C.begin(), C.end());
	C.erase(unique(C.begin(), C.end()), C.end());

	vector<int> ret(A.size());
	for (int i = 0; i < A.size(); i++) {
		ret[i] = lower_bound(C.begin(), C.end(), A[i]) - C.begin();
	}
	return ret;
}

