		pos_pref[i] = pos_pref[i -1];
		neg_pref[i] = neg_pref[i -1];

		if(a -k > 0)
			pos_pref[i] += (a -k);

		else
			neg_pref[i] += (k -a);
	}

//	for(int i = 1; i <= n; i++)
//		cout << pos_pref[i] << ' ';
//	cout << '\n';

//	for(int i = 1; i <= n; i++)
//		cout << neg_pref[i] << ' ';
//	cout << '\n';

	for(int i = 1; i <= n; i++)
		cnt[pos_pref[i] -neg_pref[i]]++;

	for(auto it = cnt.begin(); it != cnt.end(); it++)
		val.push_back(it->first);

	map <int, int> idx;
	int sz = val.size();
	for(int i = 0; i < sz; i++)
		idx[val[i]] = i;

	build(1, 0, sz -1);

//	cout << "val: ";
//	for(int i = 0; i < sz; i++)
//		cout << val[i] << ' ';
