deque<ll> v;
deque<ll> buf;
ll anti_inversion(int l, int r)
{
  if (l == r) return 0;
  int mid = (l+r)>>1;
  ll ret = anti_inversion(l, mid) + anti_inversion(mid+1, r);
  int tl = l, tr = mid+1, ptr = l;
  while (tl <= mid && tr <= r)
    if (v[tl] <= v[tr]) ret += r-tr+1, buf[ptr++] = v[tl++];
    else buf[ptr++] = v[tr++];
  while (tl <= mid) buf[ptr++] = v[tl++];
  while (tr <= r) buf[ptr++] = v[tr++];
  assert(ptr == r+1);
  for (int i = l; i <= r; ++i) v[i] = buf[i];
  return ret;
}
int main()
{
