    {
      v.resize(n);
      for (auto & e : v) scanf("%lld", &e), e -= k;
      v.push_front(0ll);
      buf.resize(v.size());
      for (int i = 1; i <= n; ++i) v[i] += v[i-1];
      printf("%lld\n", anti_inversion(0, n));
    }
}

