void solve(int l, int r) {
	if(l + 1 == r) return;
	int m = (l + r) / 2;
	vector <pair <ll, int>> v;
	for(int i = l; i < m; i ++)
		v.pb({sum[i] - i * k, 0});
	for(int i = m; i < r; i ++)
		v.pb({sum[i] - i * k, 1});
	sort(v.begin(), v.end());

	int acc = 0;
	for(auto i : v)
		if(i.second == 1)
			ans += acc;
		else
			acc ++;
	solve(l, m);
	solve(m, r);
}

