using namespace std;
typedef pair<int,int> P;
typedef pair<P, P> PP;
typedef long long ll;
int N,K;
struct FenwickTree {
  static const int MAX_N = 200011;
  int storage[MAX_N+1];
  int N;
  void init(int n) {
    N=n;
  }
  int sum(int i) { // 0<i<=N
    int ret = 0;
    while(i>0) {
      ret+=storage[i];
      i -= i&-i;
    }
    return ret;
  }
  void add(int i, int x) {// 0<=i<N
    ++i;
    while(i<=N) {
      storage[i] += x;
      i += i&-i;
    }
  }
  int rangeSum(int l, int r) {
    return sum(r)-sum(l);
  }
};
int A[200020];
int sumA[200021];
P values[200020];
FenwickTree ft;
int main() {
  scanf("%d%d", &N, &K);
  ft.init(N+1);
  FOR(N) {
    int a;
    scanf("%d", &a);
    A[i]=a;
  }
  sumA[0]=0;
  FOR(N) {
    sumA[i+1]=A[i];
    sumA[i+1]+=sumA[i]-K;
  }
  FOR(N+1) {
    values[i]=P(sumA[i],i);
  }
  sort(values, values+N+1);
  FOR(N+1) {
    sumA[values[i].second]=i;
  }
  long long answer = 0;
  for(int i=N;i>=0;--i) {
    int v=sumA[i];
    answer+=ft.rangeSum(v, N+2);
    ft.add(v,1);
  }
  printf("%lld\n", answer);
  return 0;
}

