void rotate(long long x)
{
	long long y=fa[x],z=fa[y],t=(son[y][0]==x);
	if(z)
		son[z][son[z][1]==y]=x;
	fa[x]=z;
	son[y][!t]=son[x][t];
	fa[son[y][!t]]=y;
	son[x][t]=y;
	fa[y]=x;
	pushup(y);
	pushup(x);
}



void splay(long long x,long long s)
{
	while(fa[x]!=s)
	{
		long long y=fa[x],z=fa[y];
		if(z!=s)
			if(son[z][0]==y^son[y][0]==x)
				rotate(x);
			else
				rotate(y);
		rotate(x);
	}
	if(s==0)
		root=x;
}


void insert(long long &x,long long v,long long s)
{
	if(!x)
	{
		x=++tot;
		size[x]=num[x]=1;
		son[x][0]=son[x][1]=0;
		key[x]=v;
		fa[x]=s;
		splay(x,0);
		return;
	}
	if(v==key[x])
	{
		num[x]++;
		size[x]++;
		splay(x,0);
		return;
	}
	insert(son[x][v>key[x]],v,x);
	pushup(x);
}

long long get(long long v)
{
	long long x=root;
	while(x&&v!=key[x])
		x=son[x][v>key[x]];
	return x;
}



void del(long long x)
{
	x=get(x);
	if(!x)
		return;
	splay(x,0);
	if(num[x]>1)
	{
		num[x]--;
		size[x]--;
		return;
	}
	if(!son[x][0]||!son[x][1])
		root=son[x][0]+son[x][1];
	else
	{
		long long y=son[x][1];
		while(son[y][0])
			y=son[y][0];
		splay(y,x);
		son[y][0]=son[x][0];
		fa[son[y][0]]=y;
		root=y;
	}
	fa[root]=0;
	pushup(root);
}

long long rk(long long v)
{
	insert(root,v,0);
	long long ans=size[son[root][0]];
	del(v);
	return ans;
}

int main()
{
	cin>>n>>k;
	for(long long i=1;i<=n;i++)
		cin>>a[i],a[i]-=k,s[i]=s[i-1]+a[i];
	insert(root,0,0);
	for(long long i=1;i<=n;i++)
	{
		insert(root,s[i],0);
		ans+=rk(s[i]+1)-1;
	}
	cout<<ans;
}

