struct Fenwick {
	int n;
	vector<int> f;

	Fenwick(int n_) {
		n = n_;
		f.resize(n);
	}

	int get(int x) {
		int res = 0;
		for (int i = x; i >= 0; i = (i & (i + 1)) - 1) {
			res += f[i];
		}
		return res;
	}

	void add(int x, int v) {
		for (int i = x; i < n; i = (i | (i + 1))) {
			f[i] += v;
		}
	}
};

