    int64_t ans = N*(N+1)/2;
    BinaryIndexedTree<int64_t> bit(N+1);
    for(int i=0; i<=N; i++) {
        ans -= i - bit.sum(zart[i]);
        bit.add(zart[i], 1);
    }

    cout << ans << endl;
    return 0;
}

