template <typename T>
vector<T> Vpress(vector<T> &X) {
    vector<T> vals = X;
    SORT(vals);
    vals.erase(unique(ALL(vals)), vals.end());
    REP(i,SZ(X)){
        X.at(i) = LB(ALL(vals), X.at(i)) - vals.begin();
    }
    return vals;
}

