int n, k, a[N];
ll v1[N], v2[N];
ll ans;

void solve(int l, int r){
	if(l == r){
		ans += (a[l] >= 0);
		return ;
	}
	int mid = l + r >> 1;
	v2[mid] = 0;
	for(int i = mid + 1; i <= r; i++)
		v2[i] = v2[i - 1] + a[i];
	v1[mid + 1] = 0;
	for(int i = mid; i >= l; i--)
		v1[i] = v1[i + 1] + a[i];
	sort(v1 + l, v1 + mid + 1);
	sort(v2 + mid + 1, v2 + r + 1);
	for(int i = mid + 1, j = mid + 1; i <= r; i++){
		while(v2[i] + v1[j - 1] >= 0 && j > l) j--;
		ans += mid + 1 - j;
	}
	solve(l, mid); solve(mid + 1, r);
}

