const ll MOD = 1000000007;

template <typename T>
class BIT{
public:
    vector<T> data;
    int n;
    BIT(int n_){
        n = n_;
        data.assign(n, T(0));
    }

    void add(int a, int w){
        for (int x = a; x < n; x |= x + 1) data[x] += w;
    }

    T sum(int a){
        int ret = 0;
        for (int x = a - 1; x >= 0; x = (x & (x + 1)) - 1) {
            ret += data[x];
        }
        return ret;
    }
};

int main(){
    ll N, K;
    cin >> N >> K;

    vector<ll> b(N+1);
    b[0] = 0;
    for(int i=0;i<N;i++){
        ll a;
        cin >> a;
        b[i+1] = b[i] + a - K;
    }

    vector<ll> b_s = b;
    sort(b_s.begin(), b_s.end());

    int idx = 0;
    map<ll, int> mp;
    for(int i=0;i<=N;i++){
        if(mp.count(b_s[i]) == 0){
            mp[b_s[i]] = idx++;
        }
    }

    BIT<int> bit(N+1);
    int ans = 0, total = 0;
    for(int i=N;i>=0;i--){
        int c = mp[b[i]];
        ans += total++ - bit.sum(c);
        bit.add(c, 1);
    }
    cout << ans << endl;

    return 0;
}

