    std::cin >> a[i];

  long long s = 0, t = 0;

  std::multiset<long long> set;

  segment_tree_t<long long> tree(N);

  for (int i = 0; i < N; i ++) {
    s += a[i];
    t += K;

    set.insert(s - t);

    tree.update(i, 1);
  }

  std::map<long long, std::vector<int>> map;

  int ind = 0;

  for (const auto& i : set)
    map[i].push_back(ind ++);

  for (auto& kv : map)
    std::reverse(ALL(kv.second));

  s = t = 0;

  long long c = 0;

  for (int i = 0; i < N; i ++) {
    auto it = set.lower_bound(s - t);

    if (it != std::end(set)) {
      assert(! map[*it].empty());

      c += tree.query(map[*it].back(), N);
    }

    s += a[i];
    t += K;

    set.erase(set.find(s - t));

    assert(! map[s - t].empty());

    int x = map[s - t].back(); map[s - t].pop_back();

    tree.update(x, 0);
  }

