		for(; x <= n + 1; x += x & -x) dat[x]++;
	}
	int get(int x){
		int ret = 0;
		for(; x; x -= x & -x) ret += dat[x];
		return ret;
	}
} B;

int wh(ll x){ return (int)(lower_bound(xx + 1, xx + n + 2, x) - xx); }

