		s[i] += s[i - 1];
		xx[i] = s[i];
	}
	sort(xx + 1, xx + n + 2);
	B.upd(wh(0));
	for(int i = 1; i <= n; i++){
		ans += B.get(wh(s[i]));
		B.upd(wh(s[i]));
	}
	printf("%lld\n", ans);
}

