using namespace std;

struct Node{
    int sign;
    long long min,max;
}tree[1000005];

int n;
pair<long long,int> ax[200005];
pair<long long,int> bx[200005];
int cx[200005];

bool mmp(const pair<long long,int>& a,const pair<long long,int>& b){
    return a.first<b.first;
}

int left (int x){
    return x<<1;
}

int right (int x){
    return (x<<1)+1;
}

void build (int L,int R,int i){
    if(L==R){
    tree[i].min = bx[L-1].first;
    tree[i].max = bx[L-1].first;
    tree[i].sign = 1;
    return;
    }
    int mid = (L+R)/2;
    build(L,mid,left(i));
    build(mid+1,R,right(i));
    tree[i].min = tree[left(i)].min;
    tree[i].max = tree[right(i)].max;
    tree[i].sign = tree[right(i)].sign+tree[left(i)].sign;
}

int findf (int L,int R,long long res,int i){
    if(tree[i].max<res) return 0;
    if(tree[i].min>=res) return tree[i].sign;
    if(L==R) return 0;
    int mid = (L+R)/2;
    return findf(L,mid,res,left(i))+findf(mid+1,R,res,right(i));
}

void shan (int L,int R,int res,int i){
   if(L>res||R<res)return;
   tree[i].sign -= 1;
   if(L==R) return;
   int mid = (L+R)/2;
   shan(L,mid,res,left(i));
   shan(mid+1,R,res,right(i));
}

int main()
{
    int k,i,a;
    long long res=0,mid=0,b=0;
    scanf("%d%d",&n,&k);
    for(i=0;i<n;i++){
        scanf("%d",&a);
        a -= k;
        cx[i] = a;
    }
    for(i=0;i<n;i++){
        b += (long long)cx[i];
        ax[i].first = b;
        bx[i].first = b;
        bx[i].second = i;
    }
    sort(bx,bx+n,mmp);
    for(i=0;i<n;i++){
        ax[bx[i].second].second = i+1;
    }
    build(1,n,1);
    b = 0;
    for(i=0;i<n;i++){
        res += (long long)findf(1,n,b,1);
        shan(1,n,ax[i].second,1);
        b += (long long)cx[i];
    }
    printf("%lld",res);
    return 0;
}

