template <typename T>
class BIT{
  vector<T> array;
  int n;
public:
  BIT(int num){
    n = num;
    array.resize(n + 1);
  }
  T sum(int i){
    T s = 0;
    while(i > 0){
      s += array[i];
      i -= i & -i;
    }
    return s;
  }
  T sum(int i, int j){
    return sum(j)-sum(i-1);
  }
  void add(int i, T x){
    while(i <= n){
      array[i] += x;
      i += i & -i;
    }
  }
};

