int N, K;
ll A[100100], B[100100];
bool used[100100];

void goLeft(int start){
    for(int i=start;i>=0;--i){
        if(used[i]){
            break;
        }else if(B[start] - (i > 0 ? B[i-1] : 0) >= 1ll * (start-i+1) * K){
            used[i] = true;
        }else{
            break;
        }
    }
}

void goRight(int start){
    for(int i=start;i<N;++i){
        if(used[i]){
            break;
        }else if(B[i] - (start > 0 ? B[start-1] : 0) >= 1ll * (i-start+1) * K){
            used[i] = true;
        }else{
            break;
        }
    }
}

int main(){
    std::cin.tie(nullptr);
    std::ios::sync_with_stdio(false);

    std::cin >> N >> K;

    ll res = 0ll;

    for(int i=0;i<N;++i){
        std::cin >> A[i];
        if(A[i] >= K){++res;}
    }

    B[0] = A[0];
    for(int i=0;i<N-1;++i){
        B[i+1] = B[i] + A[i+1];
    }

    for(int i=0,j=0;i<N;i=j){
        while(j < N && A[j] < K){++j;}

        if(j == N){break;}

        i = j;
        int mx_idx = i;
        while(j < N && A[j] >= K){
            if(A[mx_idx] < A[j]){mx_idx = j;}
            ++j;
        }

        if(!used[mx_idx]){
            goLeft(mx_idx);
            used[mx_idx] = false;
            goRight(mx_idx);
        }
    }

    // for(int i=0;i<N;++i){
    //     printf("%d", used[i]);
    // }
    // puts("--------------------");

    for(int i=0,j=0;i<N;i=j){
        while(j < N && !used[j]){++j;}

        if(j == N){break;}

        i = j;
        while(j < N && used[j]){++j;}

        ll n = j - i;
        if(n % 2 == 0){
            res += n / 2 * (n-1);
        }else{
            res += (n-1) / 2 * n;
        }
    }

    std::cout << res << std::endl;
}

