  rep(i,N) cin>>A[i+1];
  rep(i,N) A[i+1]+=A[i]-K;
  VL B(N+1);
  rep(i,N+1) B[i]=A[i];
  sort(all(B));
  map<ll,int> M;
  int tmp=1;
  M[B[0]]=tmp;
  rep(i,N){
    if(B[i+1]!=B[i]) tmp++;
    M[B[i+1]]=tmp;
  }
  rep(i,N+1) A[i]=M[A[i]];
  int size=20;
  VL BIT(1<<size);
  ll ans=0;
  rep(i,N+1){
    tmp=A[i];
    ll sum=0;
    do{
      sum+=BIT[tmp];
      tmp-=(tmp&(-tmp));
    }while(tmp>0);
    ans+=sum;
    tmp=A[i];
    do{
      BIT[tmp]++;
      tmp+=(tmp&(-tmp));
    }while(tmp<=size);
  }
  cout<<ans<<endl;
}

