class FenwickTree {
    int n;
    vector<int> a;
public:
    FenwickTree(int n) : n(n), a(n+1, 0) {}
    int get(int i) {
        int s = 0;
        while (i > 0) {
            s += a[i];
            i -= i & -i;
        }
        return s;
    }
    void add(int i, int x) {
        while (i <= n) {
            a[i] += x;
            i += i & -i;
        }
    }
};

