		template<class T0, class T1>void write(std::ostream& ost, std::pair<T0, T1>const& pair)
		{
			write(ost, pair.first);
			ost << " ";
			write(ost, pair.second);
		}
		template<class T>void write(std::ostream& ost, std::vector<T>const& vec)
		{
			auto size = vec.size();
			if (size == 0)
			{
				return;
			}
			write(ost, vec[0]);
			for (auto i : boost::irange<std::size_t>(1, size))
			{
				ost << " ";
				write(ost, vec[i]);
			}
		}
		template<class T>void write(std::ostream& ost, boost::multi_array<T, 2>const& ar)
		{
			write(ost, ar[0][0]);
			for (auto const& v : lib::make_range(std::next(ar[0].begin()), ar[0].end()))
			{
				ost << " ";
				write(ost, v);
			}
			for (auto ite = std::next(ar.begin()); ite != ar.end(); ++ite)
			{
				ost << std::endl;
				write(ost, *ite->begin());
				for (auto const& v : lib::make_range(std::next(ite->begin()), ite->end()))
				{
					ost << " ";
					write(ost, v);
				}
			}
		}
	}
	void write_line()
	{
		std::cout << std::endl;
	}
	template<class...Ts>void write_line(Ts const&... args)
	{
		detail::write(std::cout, args...);
		std::cout << std::endl;
	}
	void debug()
	{
		std::cerr << std::endl;
	}
	template<class...Ts>void debug(Ts const&... args)
	{
		detail::write(std::cerr, args...);
		std::cerr << std::endl;
	}
	template<class Range>void write_range(Range const& rng)
	{
		for (auto const& v : rng)
		{
			write_line(v);
		}
	}
	template<class Range>void debug_range(Range const& rng)
	{
		for (auto const& v : rng)
		{
			debug(v);
		}
	}
