std::int64_t count(int first, int last, std::vector<std::int64_t>const& sum)
{
	if (last - first == 1)
	{
		return sum[last] - sum[first] >= 0;
	}
	std::vector<std::int64_t> right;
	auto mid = (first + last) / 2;
	for (auto i : boost::irange(mid, last))
	{
		right.emplace_back(sum[i + 1] - sum[mid]);
	}
	lib::sort(right);
	auto end = right.end();
	std::int64_t ret = 0;
	for (auto i : boost::irange(first, mid))
	{
		auto v = sum[mid] - sum[i];
		auto s = end - lib::lower_bound(right, -v);
		ret += s;
	}
	return ret + count(first, mid, sum) + count(mid, last, sum);
}

