    for (int i = 1; i <= n; i++) {
        ll x;
        scanf("%lld", &x);
        pre[i].val = pre[i - 1].val + x - k;
        pre[i].pos = i;
    }
    seg.build(1, 1, n);
    sort(pre + 1, pre + 1 + n);
    ll ans = 0;
    for (int i = 1; i <= n; i++) {
        if (pre[i].val >= 0) ans++;
        ans += seg.query(1, 1, pre[i].pos - 1);
        seg.update(1, pre[i].pos, 1);
    }
    printf("%lld\n", ans);

    return 0;
}

