		sum=v;
		lz=0;
	}
}tree[4*200005];
void pushup(int x){
	tree[x].sum=tree[2*x].sum+tree[2*x+1].sum;
}
void build(int x,int l,int r){
	tree[x].l=l;
	tree[x].r=r;
	tree[x].sum=tree[x].max=tree[x].min=tree[x].lz=0;
	if(l==r){
		tree[x].sum=tree[x].max=tree[x].min=a[l];
		return ;
	}
	int mid=(l+r)/2;
	build(2*x,l,mid);
	build(2*x+1,mid+1,r);
	pushup(x);
}
void pushdown(int x){
	if(tree[x].lz!=0){
		tree[2*x].update(tree[x].lz);
		tree[2*x+1].update(tree[x].lz);
		tree[x].lz=0;
	}
}
ll querrySUM(int x,int l,int r){
	int L=tree[x].l,R=tree[x].r;
	int mid=(L+R)/2;
	ll res=0;
	if((l<=L)&&(r>=R)){
		return tree[x].sum;
	}
	pushdown(x);
	if(l<=mid)res+=querrySUM(2*x,l,r);
	if(r>mid)res+=querrySUM(2*x+1,l,r);
	pushup(x);
	return res;
}
