  rep(i, n) {
    sum += b[i];
    v.emplace_back(sum, i);
  }
  sort(all(v), [&](P a, P b) {
    return a.first < b.first;
  });
  map<int, int> mp;
  rep(i, n) mp[v[i].second] = i;
  FenwickTree<int> ft(n);
  rep(i, n) ft.update(i, 1);
  i64 ans = 0;
