      int md = (ok + ng) / 2;
      (v[md].first >= tar ? ok : ng) = md;
    }
    ans += ft.query(n) - ft.query(ok);
    ft.update(mp[i], -1);
    tar += b[i];
  }
  cout << ans << endl;
}

