                i64 sum=s[i];
                if(m>0) sum-=s[m-1];
                if(sum>=K*(i-m+1)) ub=m;
                else lb=m;
            }
            ans+=(i-ub);
        }
        {
            i64 lb=i,ub=N;
            while(ub-lb>1){
                i64 m=(lb+ub)/2;
                i64 sum=s[ub];
                if(i>0) sum-=s[i-1];
                if(sum>=K*(m-i+1)) lb=m;
                else ub=m;
            }
            ans+=lb-i;
        }
    }
    cout << ans << endl;
}

