class bitree {
public:
    int size;
    vector<T> data;
    bitree(int size) :size(size + 1), data(size + 1) {}

    // -------------------------------------------------------
    // 和に関するBIT
    // 1..rの範囲の値の和を求める．
    T sum(int r) {
        T s = 0;
        while (r) {
            s += data[r];
            r -= r&-r; //  r&-r と書くことで最下のビットを得る
        }
        return s;
    }
    // idxの要素の値をval増やす
    void add(int idx, T val) {
        while (idx <= size) {
            data[idx] += val;
            idx += idx&-idx;
        }
    }
};


