int tot,root;
void update(int x){size[x]=size[son[x][0]]+size[son[x][1]]+num[x];}
void rotate(int x)
{
    int y=fa[x],z=fa[y],t=(son[y][0]==x);
    fa[y]=x;fa[x]=z;
    if(z) son[z][son[z][1]==y]=x;
    son[y][!t]=son[x][t];fa[son[x][t]]=y;
    son[x][t]=y;
    update(x);update(y);
}
void splay(int x,int f)
{
    while(fa[x]!=f)
    {
        int y=fa[x],z=fa[y];
        if(z!=f)
        {
            if(son[y][0]==x^son[z][0]==y)rotate(x);
            else                        rotate(y);
        }
        rotate(x);
    }
    if(!f)root=x;
}
void insert(int &x,int val,int f)
{
    if(!x)
    {
        x=++tot;
        fa[x]=f;
        son[x][0]=son[x][1]=0;
        w[x]=val;
        size[x]=num[x]=1;
        splay(x,0);
        return;
    }
    if(val==w[x]){size[x]++;num[x]++;splay(x,0);return;}
    insert(son[x][val>w[x]],val,x);
    update(x);
}
int get(int val)
{
    int x=root;
    while(x&&w[x]!=val)x=son[x][val>w[x]];
    return x;
}
void delet(int w)
{
    int x=get(w);if(!x)return;
    splay(x,0);
    if(num[x]>1){num[x]--;size[x]--;return;}
    if(!son[x][0]||!son[x][1])root=son[x][0]+son[x][1];
    else
    {
        int y=son[x][1];while(son[y][0])y=son[y][0];
        splay(y,x);
        fa[son[x][0]]=y;
        son[y][0]=son[x][0];
        root=y;
        son[x][0]=son[x][1]=0;
    }
    fa[root]=0;
    update(root);
}
int getrank(int val)
{
    insert(root,val,0);
    int ans=size[son[root][0]]+num[root]-1;
    delet(val);
    return ans;
}
int kth(int k)
{
    int x=root;
    while(k<=size[son[x][0]]||k>size[son[x][0]]+num[x])
    {
        if(k<=size[son[x][0]]) x=son[x][0];
        else                   k-=size[son[x][0]]+num[x],x=son[x][1];
    }
    return w[x];
}
int getpre(int val)
{
    insert(root,val,0);
    int y=son[root][0];
    while(son[y][1])y=son[y][1];
    delet(val);
    return w[y];
}
int getne(int val)
{
    insert(root,val,0);
    int y=son[root][1];
    while(son[y][0])y=son[y][0];
    delet(val);
    return w[y];
}

