		for (;j<dat[id*2+1].hz.size();j++){
			dat[id].hz.push_back(dat[id*2+1].hz[j]);
		}		
	}
	i=0;
	j=0;
	vi=dat[id*2].qz[i];
	vj=dat[id*2+1].qz[j]+dat[id*2].sum;
	while (true){
		if (vi>vj){
			dat[id].qz.push_back(vj);
			j++;
			if (j==dat[id*2+1].qz.size()){
				break;
			}
			vj=dat[id*2+1].qz[j]+dat[id*2].sum;
		}
		else{
			dat[id].qz.push_back(vi);
