struct node{
	ll l,r;
	int cnt;
	node *chl,*chr;
	void init(ll l_,ll r_){
		l = l_;
		r = r_;
		cnt = 0;
		chl = nullptr;
		chr = nullptr;
	}
	void mkch(){
		chl = new node;
		chl->init(l,(l+r)/2);
		chr = new node;
		chr->init((l+r)/2,r);
	}
	void add(ll x){
		if(l <= x && x < r){
			cnt ++;
			if(l+1 == r)return;
			if(chl == nullptr)mkch();
			chl->add(x);
			chr->add(x);
		}
	}
	ll query(ll a,ll b){
		if(b <= l || r <= a)return 0;
		if(a <= l && r <= b)return cnt;
		if(chl == nullptr)return 0;
		return chl->query(a,b)+chr->query(a,b);
	}
}bit;

