struct node {
	int val;
	node *lt, *rt;

	node() { val = 0; lt = rt = NULL; }

	void insert(LL l, LL r, LL tar) {
//		printf(">> insert %lld %lld %lld\n", l, r, tar);
		val++;
		if (l == r) return;
		LL mid = l + (r - l) / 2;
		if (tar <= mid) {
			if (lt == NULL) lt = new node();
			lt->insert(l, mid, tar);
		} else {
			if (rt == NULL) rt = new node();
			rt->insert(mid + 1, r, tar);
		}
	}

	int query(LL l, LL r, LL tal, LL tar) {
//		printf(">> query %lld %lld %lld %lld\n", l, r, tal, tar);
		if (tal <= l && r <= tar) return val;

		LL mid = l + (r - l) / 2, ret = 0;

		if (tal <= mid && lt != NULL)
			ret += lt->query(l, mid, tal, tar);
		if (tar > mid && rt != NULL)
			ret += rt->query(mid + 1, r, tal, tar);

		return ret;
	}
} root;

