void update(int id,int l,int r,int pos){
	++sum[id];
	if(l==r) return ;
	int mid=(l+r)/2;
	if(mid>=pos) update(lson(id),l,mid,pos);
	else update(rson(id),mid+1,r,pos);
}

ll query(int id,int l,int r,int L,int R){
	if(l>=L&&r<=R) return sum[id];
	if(l>R||L>r) return 0;
	int mid=(l+r)/2;
	return query(lson(id),l,mid,L,R)
		  +query(rson(id),mid+1,r,L,R);
}

