void Merge(int l,int mid,int r)
{
    int i=l,j=mid+1,k=l;
    while(i<=mid&&j<=r)
    {
        if(arr[i]>arr[j])
        {
            a[k++]=arr[j++];
            ans+=mid-i+1;
        }
        else a[k++]=arr[i++];
    }
    while(i<=mid)
        a[k++]=arr[i++];
    while(j<=r)
        a[k++]=arr[j++];
    for(int e=l;e<=r;e++)
        arr[e]=a[e];
}
void Merge_sort(int l,int r)
{
    if(l<r)
    {
        int mid=(l+r)/2;
        Merge_sort(l,mid);
        Merge_sort(mid+1,r);
        Merge(l,mid,r);
    }
}
