class BigInt
{
	public:
	int c;
	int a[100];
	BigInt()
	{
		c=1;
		memset(a,0,sizeof(a));
	}
	BigInt(int x)
	{
		if(!x)
		{
			c=1;
			memset(a,0,sizeof(a));
			return;
		}
		c=0;
		memset(a,0,sizeof(a));
		while(x!=0)
		{
			a[c++]=x%10000;
			x/=10000;
		}
	}
	BigInt operator+(const BigInt &b)const
	{
		BigInt result;
		result.c=max(c,b.c);
		for(int i=0;i<result.c;i++)
		{
			result.a[i]+=a[i]+b.a[i];
			result.a[i+1]=result.a[i]/10000;
			result.a[i]%=10000;
		}
		if(result.a[result.c]>0)
		{
			result.c++;
		}
		return result;
	}
	BigInt operator*(const BigInt &b)const
	{
		BigInt result;
		result.c=c+b.c;
		for(int i=0;i<c;i++)
		for(int j=0;j<b.c;j++)
		{
			result.a[i+j]+=a[i]*b.a[j];
		}
		int d=0;
		for(int i=0;i<result.c;i++)
		{
			result.a[i]+=d;
			d=result.a[i]/10000;
			result.a[i]%=10000;
		}
		if(d)result.a[result.c++]=d;
		while(result.a[result.c-1]==0)result.c--;
		return result;
	}
	BigInt operator-(const BigInt &b)const
	{
		BigInt result;
		result.c=max(c,b.c);
		for(int i=0;i<result.c;i++)
		{
			result.a[i]+=a[i]-b.a[i];
			if(result.a[i]<0)result.a[i+1]--,result.a[i]+=10000;
		}
		while(result.a[result.c-1]==0)result.c--;
		return result;
	}
	void print()const
	{
		printf("%d",a[c-1]);
		for(int i=c-2;i>=0;i--)
		{
			printf("%04d",a[i]);
		}
	}
};

