template <class T>
struct BIT {
    vector<T> dat;
    BIT(int n) : dat(n+1) { }
    // initialize by a constant
    BIT(int n, T a) : dat(n+1, a) {
        dat[0] = 0;
        for (int k = 1; k+(k&-k) <= n; ++k) dat[k+(k&-k)] += dat[k];
    }
    // initialize by a vector
    BIT(vector<T> y) : dat(y.size()+1) {
        for (int k = 0; k < y.size(); ++k) dat[k+1] = y[k];
        for (int k = 1; k+(k&-k) < dat.size(); ++k) dat[k+(k&-k)] += dat[k];
    }
    void add(int k, T a) {
        for (++k; k < dat.size(); k += k&-k) dat[k] += a;
    }
    T sum(int k) {
        T s = 0;
        for (; k > 0; k &= k-1) s += dat[k];
        return s;
    }
    int lower_bound(T a) {
        if (a <= 0) return 0;
        int k = dat.size()-1;
        for (int s: {1,2,4,8,16}) k |= (k >> s);
        for (int p = ++k; p > 0; p >>= 1, k |= p)
            if (k < dat.size() && dat[k] < a) a -= dat[k]; else k ^= p;
        return k+1;
    }
};

