#include<bits/stdc++.h>
using namespace std;
using ll = int64_t;
template <typename T>
class Bit{
    private:
        ll size;
        T *data;
        T *arr;
        T identity_ele;

    public:

        Bit(ll size, T identity_ele){
            ll newsize = 1;
            while(newsize < size)  newsize = newsize << 1;
            this->size = newsize + 1;
            this->identity_ele = identity_ele;
            data = new ll[this->size];
            arr = new ll[size];
            for(ll i = 0; i < size; ++i){
                data[i] = identity_ele;
                arr[i] = identity_ele;
            }
        }

        /*
         * 0-origin
         */
        T sum(ll pos){
            T ret = identity_ele;
            while(pos > 0){
                ret += data[pos];
                pos -= pos & -pos;
            }
            return ret;
        }

        /*
         * 0-origin
         */
        void add(ll pos, T delta){
            arr[pos] += delta;
            pos++;
            while(pos <= size){
                data[pos] = data[pos] + delta;
                pos += pos & -pos;
            }
        }

        void update(ll pos, T value){
            T delta = value - arr[pos];
            this->add(pos, delta);
        }
};
int main(){
    ll N, K;
    cin >> N >> K;
    vector<ll> V(N);
    for(auto &v : V){
        cin >> v;
        v -= K;
    }
    vector<ll> sum(N + 1, 0);
    vector<ll> uniq = {0};
    for(ll i = 0; i < N; i++){
        sum[i + 1] = sum[i] + V[i];
        uniq.push_back(sum[i + 1]);
    }
    sort(uniq.begin(), uniq.end());
    auto ite = unique(uniq.begin(), uniq.end());
    uniq.erase(ite, uniq.end());
    map<ll, ll> ID;
    for(ll i = 0; i < uniq.size(); i++) ID[uniq[i]] = i;
    Bit<ll> B(ID.size(), 0);
    B.add(ID[0], 1);
    ll ans = 0;
    for(ll i = 0; i < N; i++){
        auto ite = lower_bound(uniq.begin(), uniq.end(), sum[i + 1]);
        ll idx = ite - uniq.begin();
        ans += B.sum(idx + 1);
        B.add(ID[sum[i + 1]], 1);
    }
    cout << ans << endl;
    return 0;
}

