  }

  vec2 = vec;

  sort(vec.begin(),vec.end());
  vec.erase(unique(vec.begin(),vec.end()),vec.end());

  for(int i=0;i<vec.size();i++){
    mm[vec[i]] = i;
  }

  RMQ seg(n);
  int cc[SIZE] = {};

  for(int i=0;i<=n;i++){
    int p = mm[vec2[i]];
    cc[p]++;
    seg.set(p,cc[p]);
  }

  ll ans = 0;

  for(int i=0;i<n;i++){
    int p = mm[sum[i]];

    cc[p]--;
    seg.set(p,cc[p]);

    ans += seg.query(p,INF);
