template <typename T>
struct BinaryIndexedTree {
    int n;
    vector<T> d;

    BinaryIndexedTree(int n): n(n), d(n + 1, 0) {}

    // a[1] + ... + a[k]
    T sum(int k)
    {
        T r = 0;
        while (k > 0) {
            r += d[k];
            k -= k & -k;
        }
        return r;
    }

    // a[l] + ... + a[r]
    T sum(int l, int r)
    {
        return sum(r) - sum(l - 1);
    }

    // a[k] += x
    void add(int k, T x)
    {
        while (k <= n) {
            d[k] += x;
            k += k & -k;
        }
    }
};
template <typename T> using BIT = BinaryIndexedTree<T>;

struct Compress {
    map<int, int> zip;
    vector<int> unzip;

    Compress() {}

    Compress(vector<int> v)
    {
        sort(v.begin(), v.end());
        v.erase(unique(v.begin(), v.end()), v.end());
        for (int i = 0; i < v.size(); ++i) {
            zip[v[i]] = i;
            unzip.push_back(v[i]);
        }
    }

    int size() {
        return unzip.size();
    }
};

