class BIT {
public:
    ll N;
    ll bit[1000010];

    BIT(ll N) {
        this->N = N;
    }

    void add(ll a, ll w) {
        for (ll x = a; x < N; x |= x+1) {
            bit[x] += w;
        }
    }

    ll sum(ll a) {
        ll ret = 0;
        for (ll x = a-1; x >= 0; x = (x&(x+1))-1) {
            ret += bit[x];
        }
        return ret;
    }
};

