void merge(int l,int r)
{
	int m=(l+r)/2;
	int h1=l,h2=m+1;
	int t1=m,t2=r;
	if(h1<t1) merge(h1,t1);
	if(h2<t2) merge(h2,t2);
	for(int i=l;i<=r;i++)	
	{
		if(h1<=t1&&h2<=t2)
		{
			if(s[h1]>s[h2])
			{
				temp[i]=s[h1++];
			}
			else
			{
				temp[i]=s[h2++];
				ans+=t1-h1+1;
			}
		}
		else if(h1<=t1)
		{
			temp[i]=s[h1++];
		}
		else
		{
			temp[i]=s[h2++];
		}
	}
	for(int i=l;i<=r;i++)
		s[i]=temp[i];
}
