typedef long long ll;

int N, K, r = 0;
map<p, int> u;
ll c[MAX];
int solve(ll i, ll j, ll k) {
    if (i < 0 || j >= N) return 0;
    int res = (c[j+1]-c[i])/k >= K;
    if (res && !u[p(i,j)]) u[p(i,j)] = 1, r++;
    return res;
}

int main() {
    int a[MAX], i, k;

    cin >> N >> K;
    c[0] = 0;
    vector<set<p> > ss(MAX);
    set<p>::iterator it, it2;
    for (i = 0; i < N; i++) {
        cin >> a[i];
        if (a[i] >= K) ss[1].insert(p(i,i)), r++; // sequence of length 1
        c[i+1] = c[i]+a[i];
    }

    // solve for sequence of length k
    for (k = 2; k <= N; k++) {
        set<p>& s = ss[k-1];
        for (it = s.begin(); it != s.end(); ++it) {
            // check before
            if (solve(it->first-1, it->second, k)) {
                ss[k].insert(p(it->first-1, it->second));
            }

            // check after
            if (solve(it->first, it->second+1, k)) {
                ss[k].insert(p(it->first, it->second+1));
            }
        }
    }

    cout << r << '\n';

