};

ll inv_num(vector<ll> a){
    int n = a.size();
    ll ans = 0;
    vector<pair<ll,ll> > T(n);
    rep(i, 0, n) T[i] = make_pair(a[i], i);
    stable_sort(ALL(T));
    vector<ll> X(n);
    rep(i, 0, n) X[T[i].second] = i; 
    BinaryIndexedTree<ll> bit(n);
    for(int i = 0; i < n; i++){
        ans += i - bit.sum(X[i]);
        bit.add(X[i], 1);
    }
    return ans;
}

