namespace Splay {
	struct Node {
		ll val;
		int sz;
		Node *ch[2], *pa, **rt;
		Node( ll v ) {
			val = v, sz = 1;
			ch[0] = ch[1] = pa = NULL;
			rt = NULL;
		}
		Node *maintain() {
			sz = 1;
			if( ch[0] ) sz += ch[0]->sz;
			if( ch[1] ) sz += ch[1]->sz;
			return this;
		}
		int rela() {
			return pa->ch[0] == this ? 0 : 1;
		}
		Node *rotate() {
			int x = rela();
			Node *old = pa;
			if( pa->pa ) pa->pa->ch[old->rela()] = this;
			pa = pa->pa;
			old->ch[x] = ch[x^1];
			if( ch[x^1] ) ch[x^1]->pa = old;
			ch[x^1] = old, old->pa = this;
			old->maintain(), maintain();
			if( !pa ) *rt = this;
			return this;
		}
		Node *splay( Node *tg = NULL ) {
			while( pa != tg ) {
				if( pa->pa == tg ) rotate();
				else {
					if( rela() == pa->rela() )
						pa->rotate(), rotate();
					else rotate(), rotate();
				}
			}
			return this;
		}
	};
	Node *rt = NULL;
	void insert( ll v ) {
		if( !rt ) {
			rt = new Node(v);
			rt->rt = &rt;
			return;
		}
		Node *o = rt;
		while(1) {
			int d = v <= o->val ? 0 : 1;
			if( !o->ch[d] ) {
				o->ch[d] = new Node(v);
				o->ch[d]->pa = o;
				o->ch[d]->rt = &rt;
				o->ch[d]->splay();
				return;
			} else {
				o = o->ch[d];
			}
		}
	}
	int query( ll v ) {
		int ans = 0;
		Node *o = rt;
		while( o ) {
			if( v <= o->val ) o = o->ch[0];
			else {
				++ans;
				ans += o->ch[0] ? o->ch[0]->sz : 0;
				o = o->ch[1];
			}
		}
		return rt->sz - ans;
	}
}

void solve() {
	ll zero = 0, ans = 0;
	for( int i = 0; i < n; ++i ) {
		zero -= a[i];
		Splay::insert( zero + a[i] );
		ans += Splay::query(zero);
		// printf( "%lld\n", ans );
	}
	printf( "%lld\n", ans );
}

int main() {
	input(), solve();
	return 0;
}

