    Insert(t,1);
    int64 res = 0;
    for(int i = 1 ; i <= N ; ++i) {
        t = lower_bound(val + 1,val + N + 2,sum[i]) - val;
        res += Query(t);
        Insert(t,1);
    }
    out(res);enter;
}
