struct LazySegmentTree{
    int n;
    vec node,lazy;

    LazySegmentTree(int N){
        n=1;
        while(n<N)n*=2;
        node.resize(2*n-1,0);
        lazy.resize(2*n-1,0);
    }

    //k番目のノードについて遅延評価
    void eval(int k,int l,int r){
        if(lazy[k]!=0){
            node[k]+=lazy[k];

            if(r-l>1){
                lazy[2*k+1]+=lazy[k]/2;
                lazy[2*k+2]+=lazy[k]/2;
            }
            lazy[k]=0;
        }
    }

    //[a,b)にxを加算、kは区間[l,r)の節点
    void add(int a,int b,ll x,int k,int l,int r){
        eval(k,l,r);

        if(b<=l || r<=a)return;

        if(a<=l && r<=b){
            lazy[k]+=x*(ll)(r-l);
            eval(k,l,r);
        }

        else{
            add(a,b,x,2*k+1,l,(l+r)/2);
            add(a,b,x,2*k+2,(l+r)/2,r);
            node[k]=node[2*k+1]+node[2*k+2];
        }
    }

    //[a,b)の区間和を取得
    ll getsum(int a,int b,int k,int l,int r){
        if(b<=l || r<=a) return 0;

        eval(k,l,r);
        if(a<=l && r<=b) return node[k];
        ll vl=getsum(a,b,2*k+1,l,(l+r)/2);
        ll vr=getsum(a,b,2*k+2,(l+r)/2,r);
        return vl+vr;
    }   
};

int main(){
    int N;ll K; scanf("%d %lld",&N,&K);
    vec a(N+1),S(N+1);S[0]=0;
    vector<P> T(N+1);T[0]={0,0};
    for(int i=1;i<=N;i++){
        scanf("%lld",&a[i]);
        S[i]=S[i-1]+a[i];
        T[i]={S[i]-i*K,i};
    }
    sort(T.begin(),T.end());
    vec U(N+1);
    for(int i=0;i<=N;i++){
        U[T[i].second]=i;
    }
    ll ans=0;
    LazySegmentTree LST(N+1);
    for(int i=0;i<=N;i++){
        ans+=LST.getsum(0,U[i],0,0,LST.n);
        LST.add(U[i],U[i]+1,1,0,0,LST.n);
    }
    printf("%lld\n",ans);
    return 0;
}

