const LL margin = 1e14;

LL range(LL x)
{
	x += margin;
	x--;
	LL ret = 0;
	while (x > 0)
	{
		ret += bit[x];
		x -= (x & (-x));
	}
	return ret;
}

void increment(LL x)
{
	x += margin;
	while (x <= width)
	{
		bit[x]++;
		x += (x & (-x));
	}
}

LL N, K;

int main(void)
{
	while (width < margin + margin)width *= 2;
