int N,K;
struct FenwickTree {
  static const int MAX_N = 200011;
  ll storage[MAX_N+1];
  int N;
  void init(int n) {
    N=n;
  }
  ll sum(int i) { // 0<i<=N
    int ret = 0;
    while(i>0) {
      ret+=storage[i];
      i -= i&-i;
    }
    return ret;
  }
  void add(int i, ll x) {// 0<=i<N
    ++i;
    while(i<=N) {
      storage[i] += x;
      i += i&-i;
    }
  }
  ll rangeSum(int l, int r) {
    return sum(r)-sum(l);
  }
};
int A[200020];
long long sumA[200021];
P values[200020];
FenwickTree ft;
int main() {
  scanf("%d%d", &N, &K);
