  sumA[0]=0;
  FOR(N) {
    sumA[i+1]=A[i];
    sumA[i+1]+=sumA[i]-K;
  }
  FOR(N+1) {
    values[i]=P(sumA[i],i);
  }
  sort(values, values+N+1);
  FOR(N+1) {
    A[values[i].second]=i;
  }
  long long answer = 0;
  for(int i=N;i>=0;--i) {
    int v=A[i];
    answer+=1ll*ft.rangeSum(v, N+2);
    ft.add(v,1);
  }
