l f(vl& v, l a, l b, l K) { // [a, b)
  if (a >= b) return 0;
  if (b - a == 1) return (v[a] >= K) ? 1 : 0;
  l m = a + (b - a) / 2;
  vl left, right;
  l t = 0, j = 0;
  l r = f(v, a, m, K) + f(v, m, b, K);
  B(i, m - 1, a - 1) {
    t += v[i];
    j++;
    left.emplace_back(K * j - t);
  }
  sort(all(left)); // TODO: remove?
  t = 0; j = 0;
  F(i, m, b) {
    j++;
    t += v[i];
    right.emplace_back(t - K * j);
  }
  sort(all(right));
  for (auto i : left) {
    auto p = lower_bound(all(right), i);
    r += distance(p, right.end());
  }
  return r;
}

