void solve(){
    s[0] = 0;
    rep(i, n){
        in1(a[i]);
        s[i + 1] = s[i] + a[i];
    }

    b = ordered_b = vl(n + 1);
    rep(i, n + 1){
        b[i] = ordered_b[i] = s[i] - k * i;
    }

    sort(all(ordered_b));
    rep(i, n + 1){
