int ope(int a,int b)
{
	return a + b;
}
struct Segment
{
	vector<int> node;
	int n;

	int init = 0;

	Segment(const vector<int>& vec)
	{
		int sz = vec.size();
		this->n = 1;
		while(this->n < sz) this->n <<= 1;

		node.resize(2 * n - 1,init);

		for(int i = 0;i < sz;i++)
		{
			node[n - i + 1] = vec[i];
		}
		for(int i = n - 2;i >= 0;i--)
		{
			node[i] = ope(node[i * 2 + 1] , node[i * 2 + 2]);

		}
	}

	void update(int i)
	{
		i += this->n - 1;

		node[i]++;

		while(i > 0)
		{
			i = (i - 1) / 2;
			node[i] = ope(node[i * 2 + 1],node[i * 2 + 2]);
		}
	}

	int get_inter(int a,int b,int k = 0,int l = 0,int r = -1)
	{
		if(r < 0) r = this->n;

		if(a <= l && r <= b) return node[k];

		if(r <= a || b <= l) return init;

		int lv = get_inter(a,b,2 *k + 1 ,l ,(l + r) / 2);
		int rv = get_inter(a,b,2 * k + 2,(l + r) / 2,r);

		return ope(lv,rv);
	}
};

