void merge_sort(long long l,long long r)
{
	if (l>=r) return;
	long long mid=(l+r)/2,i,j;
	merge_sort(l,mid);
	merge_sort(mid+1,r);
	i=l;
	j=mid+1;
	vector<long long> v;
	while (i<=mid&&j<=r)
	{
		if (sum[i]<=sum[j])
		{
			ans+=(r-j+1);
			v.push_back(sum[i]);
			i++;
		}
		else
		{
			v.push_back(sum[j]);
			j++;
		}
	}
	while (i<=mid)
	{
		v.push_back(sum[i]);
		i++;
	}
	while (j<=r)
	{
		v.push_back(sum[j]);
		j++;
	}
	for (i=0;i<v.size();i++) sum[l+i]=v[i];
}
