template <typename T>
class BIT
{
public:
  BIT(int size)
  {
    BITTable.assign(++size, 0);
  }
  T sum(int k)
  {
    T res = 0;
    for (++k; k > 0; k -= k & -k)
    {
      res += BITTable[k];
    }
    return res;
  }

  T sum(int l, int r)
  {
    if (l == 0)
      return sum(r);
    return sum(r) - sum(l - 1);
  }

  void update(int k, T x)
  { // b[k] += x;
    for (++k; k < (int)BITTable.size(); k += k & -k)
      BITTable[k] += x;
  }

private:
  vector<T> BITTable;
};

int n;
ll k;
ll a[200001];
ll b[200011], c[200011];
map <ll, int> map1;

int main() {
#ifdef LOCAL_DEFINE
  show(MOD);
#endif
  // テキトー考察
  //
  // 問題文を数式にすると、\sum_{i = l}^{r} a[i] >= k * (r - l - 1)となる.
  // これを式変形してもいいが、プログラムしやすさを考慮し、[l, r)の形で数式化すると
  // \sum_{i = l}^{r - 1} a[i] >= k * (l - r) 
  // <=> \sum_{i = 0}^{r - 1} a[i] - \sum_{i = 0}^{l - 1} a[i] >= k * (r - l)
  // <=> \sum_{i = 0}^{r - 1} a[i] - k * r >= \sum_{i = 0}^{l - 1} a[i] - k * l
  // b[i] = \sum_{j = 0}^{i - 1} a[j] - k * i とすると
  // b[r] >= b[l] となる(l, r)のペアを数える問題に変わる.(0 <= l < r <= n)
  // [l, r]は式変形のしにくさ、(l, r]は添字に負の数が出てくるのでちょっと嫌だなどの理由から[l, r)に.
  // あとは、転倒数をしっているかどうかの問題になる
  // 自分は、(全体の通り数) - (b[r] < b[l]の通り数)で求めた.
  // 0 <= l < r <= nなので注意.
  // 0 から n - 1ではなく 0 から nだよ.
  cin >> n >> k;
  rep(i, 0, n) cin >> a[i];
  ll now = 0LL;
  b[0] = 0;
  rep(i, 1, n + 1) {
    now += a[i - 1];
    b[i] = now - k * i;
    c[i] = b[i];
  }
  sort(c, c + n + 1);
  rep(i, 0, n + 1) {
    if (map1.find(c[i]) == map1.end()) map1[c[i]] = i;
  }
  showA(b, n + 1);
  BIT<int> bit(n + 1);
  bit.update(map1[b[n]], 1);
  ll ans = 0;
  rrep(i, n - 1, -1) {
    ans += bit.sum(map1[b[i]] - 1);
    bit.update(map1[b[i]], 1);
  }
  cout << (ll)(n + 1) * n / 2LL - ans << endl;
#ifdef  LOCAL_DEFINE
  cerr << "Time elapsed: " << 1.0 * clock() / CLOCKS_PER_SEC << "s." << endl;
#endif
  return 0;
}

