long long build(long long l,long long r)
{
	long long mid=(l+r)>>1,rt=++tot;
	if(l==r)return rt;
	ls[rt]=build(l,mid);
	rs[rt]=build(mid+1,r);
	return rt;
}
void change(long long rt,long long nrt,long long l,long long r,long long x)
{
	v[nrt]=v[rt]+1;if(l==r)return;long long mid=(l+r)>>1;
	if(x<=mid){
		ls[nrt]=++tot;
		rs[nrt]=rs[rt];
		change(ls[rt],ls[nrt],l,mid,x);
	}else{
		rs[nrt]=++tot;
		ls[nrt]=ls[rt];
		change(rs[rt],rs[nrt],mid+1,r,x);
	}
}
long long ask(long long lrt,long long rrt,long long l,long long r,long long x,long long y)
{
	if(x<=l&&r<=y)return v[rrt]-v[lrt];
	long long mid=(l+r)>>1,tmp=0;
	if(x<=mid)tmp=ask(ls[lrt],ls[rrt],l,mid,x,y);
	if(y>mid)tmp+=ask(rs[lrt],rs[rrt],mid+1,r,x,y);
	return tmp;
}
