    for (auto & a : A) cin >> a;
    vector<ll> cum(N + 1, 0);
    for (int i = 0; i != N; ++i) cum[i + 1] = cum[i] + A[i] - K;
    unordered_map<ll, int> zip;
    vector<ll> unzip;
    compress(cum, zip, unzip);
    int n = unzip.size();
    BIT<ll> freq(n);
    for (auto c : cum) freq.add(zip[c], 1);
    ll ans = 0;
    for (auto c : cum){
        freq.add(zip[c], -1);
        ans += freq.range_sum(zip[c], n - 1);
    }
    cout << ans << endl;
    return 0;
}

