template <class Handler>
struct Segtree : Handler {
    using Value = typename Handler::Value;
    using Handler::unit; // () -> Value
    using Handler::merge; // (Value,Value) -> Value

    vector<Value> v; // use v[1..size-1]
    int size; // power of 2

    Segtree() : v(), size(0) {}
    Segtree(int n, Value const& x = unit()) { init(n,x); }
    template <class It> Segtree(It first, It last) { init(first, last); }
    void init(int n, Value const& x = unit()) {
        assert(n >= 0);
        for (size = 1; size < n; size <<= 1) ;;
		v.assign(2*size, x);
    }
    template <class It> void init(It first, It last) {
        init(distance(first,last));
        copy(first, last, next(v.begin(), size));
        for (int i = size-1; i >= 1; i--) v[i] = merge(v[2*i],v[2*i+1]);
    }
    void set(int i, Value const& x) {
        assert(0 <= i && i < size);
        i += size; v[i] = x;
        while (i > 1) i >>= 1, v[i] = merge(v[2*i],v[2*i+1]);
    }
    Value operator[](int i) const {
        assert(0 <= i && i < size);
        return v[size + i];
    }
    // [l,r)
    Value fold(int l, int r) const {
        assert(0 <= l && l <= r && r <= size);
        Value x = unit(), y = unit();
        for (l += size, r += size; l < r; l >>= 1, r >>= 1) {
            if (l&1) x = merge(x, v[l++]);
            if (r&1) y = merge(v[--r], y);
        }
        return merge(x,y);
    }
};

