class BIT{
    public:
    int size;
    vector<int> tree;

    void set(int n){
        size = n;
        tree = vector<int>(n+1, 0);
        return;
    }

    void add(int a, int n) {
        int x = n;
        while (x <= size){
            tree[x] += a;
            x += (x & -x);
        }
        return;
    }

    int sum(int a) {
        int x = a;
        int sum = 0;
        while (x > 0) {
            sum += tree[x];
            x -= (x & -x);
        }
        return sum;
    }

};


