struct fenwick_tree{
	// Number of elements
	int n;

	// Items of the tree
	ll ft[MAXN];

	// Initialization
	void init(ll *vals){
		REP(i, 0, n){
			upd_val(i, vals[i]);
		}
	}

	// Get query [l ... r]
	ll get_val(int l, int r){
		return get_val(r) - get_val(l - 1);
	}

	// Get query [0 ... r]
	ll get_val(int r){
		ll res = 0;
		for(; r >= 0; r = (r & (r + 1)) - 1){
			res += ft[r];
		}
		return res;
	}

	// Update query
	void upd_val(int pos, ll add){
		for(; pos < n; pos = (pos | (pos + 1))){
			ft[pos] += add;
		}
	}
} ft;

