        printf("[%lld %lld) %d\n", lo, hi, cnt);
        if (left) left->dump();
        if (right) right->dump();
    }
};

class Tree {
public:
    ll minv, maxv, width;
    int bits, cnt;
    Node *root;

    Tree(ll minv, ll maxv) : minv(minv), maxv(maxv) { // [minv, maxv]
        ll w = maxv - minv + 1;
        for (width=1, bits=0; width < w; width<<=1, ++bits) ;
        // printf("w = %lld, width = %lld, bits = %d\n", w, width, bits);
        root = new Node(0, width);
        cnt = 0;
    }
    ~Tree() {
        delete root;
    }

    void insert(ll val) {
        root->insert(val - minv);
        ++cnt;
    }
    void remove(ll val) {
        root->remove(val - minv);
        --cnt;
    }

    int count_till(ll till) { // exclusive, [minv, till)
        ll x = till - minv;

        ll m = 1LL << bits;
        if (x & m) return cnt;

        Node *node = root;
        int ans = 0;
        for (ll m=1LL<<(bits-1); m>=1; m>>=1) {
            // printf("count_till %lld, m=%lld, p=%d\n", x, m, !!(x & m));
            if (x & m) {
                // >>
                if (node->left) ans += node->left->cnt;
                if (node->right) node = node->right; else break;
            } else {
                // <<
                if (node->left) node = node->left; else break;
            }
            // if (!node) break;
        }
        return ans;
    }
    int count_from(ll from) { // inclusive, [from, maxv]
        return cnt - count_till(from);
    }

    void dump() {
        root->dump();
    }

};


void solve(int N, int K, vector<int>& a) {
    rep(i, N) a[i] -= K;

    vector<ll> ac(N+1, 0);
    rep(i, N) ac[i+1] = ac[i] + a[i];

    ll minv = *min_element(ALL(ac)), maxv = *max_element(ALL(ac));

    // (-1e9 .. +1e9)x2e5
    Tree *tree = new Tree(minv, maxv);
    rep1(i, N) tree->insert(ac[i]);
    // tree->dump();

    ll total = 0;
    rep1(i, N) {
        ll from = ac[i-1];
        int cnt_from = tree->count_from(from);
        total += cnt_from;
        // printf("%d) %lld, count_from(%lld)=%d\n", i, ac[i], from, cnt_from);
        tree->remove(ac[i]);
    }

    cout << total << endl;
    fflush(stdout);

    delete tree;
}

