struct CumulativeSum {
    int n;
    vector<long long> nums;
    vector<long long> s;
    CumulativeSum(int n) : n(n), s(n + 1, 0) { }
    void add(long long num) {
        nums.push_back(num);
    }
    void build() {
        for (int i = 0; i < n; ++i) s[i+1] = s[i] + nums[i];
    }
    // [l, r), l and r is 0-indexed.
    long long sum(int l, int r) {
        return s[r] - s[l];
    }
};

template <typename TFunc>
long long binary_searc(long long ng, long long ok, TFunc is_ok) {
    while (abs(ok - ng) > 1) {
        long long mid = (ok + ng) / 2;

        if (is_ok(mid)) ok = mid;
        else ng = mid;
    }
    return ok;
}

void insertionSort(vl& array) {
    int i, j, k;
    for (i = 1; i < array.size(); i++) {
		k = array[i];
		j = i - 1;
        while ((j >= 0) && (array[j] > k)) {
            array[j + 1] = array[j];
            j--;
        }
        array[j + 1] = k;
    }
}

