	}
	cs.build();
	vl SK(N + 1);
	REP(i,N + 1) {
		SK[i] = cs.sum(0, i) - K * i;
	}
	// debug(SK);
	vl sorted_SK = {};
	int res = 0;
	REP(i,N + 1) {
		int ng = sorted_SK.size();
		int ok = -1;
