			if (sorted_SK[idx] <= SK[i]) return true;
			else return false;
		};
		int idx = binary_searc(ng, ok, f);
		res += idx + 1;
		sorted_SK.push_back(SK[i]);
		insertionSort(sorted_SK);
	}
	cout << res << endl;
}

