struct FenwickTree {
  static const int MAX_N = 200011;
  int storage[MAX_N+1];
  int N;
  void init(int n) {
    N=n;
  }
  int sum(int i) { // 0<i<=N
    int ret = 0;
    while(i>0) {
      ret+=storage[i];
      i -= i&-i;
    }
    return ret;
  }
  void add(int i, int x) {// 0<=i<N
    ++i;
    while(i<=N) {
      storage[i] += x;
      i += i&-i;
    }
  }
  int rangeSum(int l, int r) {
    return sum(r)-sum(l);
  }
};
