int update(int node, int l, int r, int p, int val) {
	if (p < l || p > r) return seg[node];
	if (l == r) return seg[node] += val;
	int m = (l + r) >> 1;
	return seg[node] = update(2 * node, l, m, p, val) + update(2 * node + 1, m + 1, r, p, val);
