    if(low > slow || high < slow)
        return;

    ll mid = (low+high)/2;

    update(low,mid,pos*2+1,slow);
    update(mid+1,high,pos*2+2,slow);
    seg[pos] = seg[pos*2+1] + seg[pos*2+2];
    return;
}

