//   if(r>mid) sum+=ask(mid+1,r,rt*2+1);
//   return sum;
//}
int ask(int l,int r,int rt)
{
    if(tree[rt].l==l&&tree[rt].r==r)
    {
        return tree[rt].sum;
    }
    int mid=(tree[rt].l+tree[rt].r)/2;
    if(l>mid)
    {
         return ask(l,r,2*rt+1);
    }
    else if(r<=mid)
    {
        return ask(l,r,2*rt);
    }
    else
    {
        return ask(l,mid,2*rt)+ask(mid+1,r,2*rt+1);
    }
}
