    u64 mx=1ULL<<60;
    __gnu_pbds::gp_hash_table<u64,int>bit;
    int sz=0;
    lint sum(u64 x){
        lint res=0;
        for(u64 i=x;i;i-=i&-i)res+=bit[i];
        return res;
    }
    u64 sum(u64 x,u64 y){
        return sum(y)-sum(x);
    }
