template<class T> struct SegmentTree {
    using F = function<T(T, T)>;
private :
    int n;          // size
    T id;           // identity element
    vector<T> node; // data
    F f;            // operation
    F g;            // update
public :
    // sz : size, f : operation, g : update, def : identity
    SegmentTree(int sz, F f, F g, T id) : n(1), f(f), g(g), id(id) {
        while (n < sz) n *= 2;
        node = vector<T>(2*n-1, id);
    }

    // v : vector, f : operation, g : update, def : identity
    SegmentTree(vector<T> v, F f, F g, T id) : n(1), f(f), g(g), id(id) {
        while (n < (int)v.size()) n *= 2;
        node = vector<T>(2*n-1, id);
        for (int i = 0; i < (int)v.size(); i++) node[i+n-1] = v[i];
        for (int i = n-2; i >=0; i--) node[i] = f(node[i*2+1], node[i*2+2]);
    }

    // update
    void update (int i, T x) {
        i += n - 1;
        assert(i < node.size());
        node[i] = g(node[i], x);
        while (i > 0) {
            i = (i-1)/2;
            node[i] = f(node[2*i+1], node[2*i+2]);
        }
    }

    // query [a, b)
    T query(int a, int b, int k, int l, int r) {
        if (r <= a || b <= l) return id;
        if (a <= l && r <= b) return node[k];
        T vl = query(a, b, 2*k+1, l, (l+r)/2);
        T vr = query(a, b, 2*k+2, (l+r)/2, r);
        return f(vl, vr);
    }

    T query (int a, int b) { return query(a, b, 0, 0, n); }

    T operator[] (int i) const { return node[i+n-1]; } 

};

int main() {
    int n, k;
    cin >> n >> k;
    vector<long long> a(n), sum(n+1, 0);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        a[i] -= k;
        sum[i+1] = sum[i] + a[i];
    }

    vector<long long> v = sum;
    sort(v.begin(), v.end());
    auto idx = [&] (int x) -> int {
        return lower_bound(v.begin(), v.end(), x) - v.begin();
    };

    auto f = [](long long a, long long b) { return a + b; };
    SegmentTree<long long> seg(n+5, f, f, 0);

    long long ans = 0;
    for (int i = 0; i <= n; i++) {
        int id = idx(sum[i]);
        ans += seg.query(0, id+1);
        seg.update(id, 1LL);
    }

    cout << ans << endl;
    return 0;
}

