template<typename T>
class compress_fn_t {
public:
  void add(T x) {
    if (! map_.count(x))
      map_[x] = 0;
  };

public:
  void clear() {
    map_.clear();
  };

public:
  std::pair<std::map<T, int>, std::vector<T>> get() {
    int size = map_.size(), i = 0;

    std::pair<std::map<T, int>, std::vector<T>> pair;

    pair.second.resize(size);

    for (auto& kv : map_) {
      kv.second = i;

      pair.second[i] = kv.first;

      i ++;
    }

    pair.first = map_;

    return std::move(pair);
  };

private:
  std::map<T, int> map_;
};


template<class T>
class binary_index_tree_t {
public:
  binary_index_tree_t(int size) : size_(size) {
    a_ = new T[size_ + 1];

    memset(a_, 0, sizeof(T) * (size_ + 1));
  };

  ~binary_index_tree_t() {
    delete[] a_;
  };

public:
  void add(int i, int x) {	// a_i += x, 1-index
    assert(i > 0);
    assert(i <= size_);

    for ( ; i <= size_; i += i & -i)
      a_[i] += x;
  };

  T query(int i) {		// a_1 + ... + a_i, 1-index
    assert(i > 0);
    assert(i <= size_);

    T s = 0;

    for ( ; i; i -= i & -i)
      s += a_[i];

    return s;
  };

private:
  T* a_;

  int size_;
};


