template<class T> class BIT {
public:
    vector<T> dat;
    int N;

    BIT() {}
    BIT(int N) : N(N) { dat.assign(N, 0); }
    // sum [0,c)
    T sum(int i) {
        T ret = 0;
        for (--i; i >= 0; i = (i&(i + 1)) - 1) ret += dat[i];
        return ret;
    }
    // sum [c,j1)
    T sum(int i1, int i2) { return sum(i2) - sum(i1); }
    T at(int i) { return sum(i, i + 1); }
    // add x to c
    void add(int i, T x) { for (; i < N; i |= i + 1) dat[i] += x; }
};

