struct node {
  static mt19937 rd(time(0));
  ll x;
  int s = 1;
  int y = rd();

  node* l = 0;
  node* r = 0;

  node(ll v) {
    x = v;
  }

  ~node() {
    delete l;
    delete r;
  }

  node* upd() {
    s = 1;
    s += l ? l->s : 0;
    s += r ? r->s : 0;
    return this;
  }
};

struct treap {
  node* root = 0;

  ~treap() {
    delete root;
  }

  node* join(node* l, node* r) {
    if(not l) return r;
    if(not r) return l;

    if(l->y < r->y) {
      l->r = join(l->r, r);
      return l->upd();
    } else {
      r->l = join(l, r->l);
      return r->upd();
    }
  }

  pair<node*,node*> split(node* p, ll x) {
    if(not p) return make_pair(nullptr,nullptr);

    if(x < p->x) {
      auto t = split(p->l, x);
      p->l = t.second;
      t.second = p->upd();
      return t;
    } else {
      auto t = split(p->r, x);
      p->r = t.first;
      t.first = p->upd();
      return t;
    }
  }

  void insert(ll x) {
    auto t = split(root, x);
    root = join(t.first, join(new node(x), t.second));
  }

  int query(ll x) {
    auto t = split(root, x);
    int cnt = t.first ? t.first->s : 0;
    root = join(t.first, t.second);
    return cnt;
  }
};

