struct SegTree
{
	int len=0;
	vl s;
	vl tree;
	void init()
	{
		len=1;
		while(len<=sz(s)) len<<=1;
		while(sz(s)<len) s.PB(s.back());
		tree.rsz(len*2,0);
	}
	void change(int k,int d)
	{
		int i=lb(all(s),k)-begin(s)+len;
		while(i>0)
		{
			tree[i]+=d;
			i>>=1;
		}
	}
	ll get(int x,int l,int r,ll k)
	{
		if(s[r-1]<k) return 0;
		if(s[l]>=k) return tree[x];
		int mid=(l+r)>>1;
		return get(x*2,l,mid,k)+get(x*2+1,mid,r,k);
	}
}box;


