	}
	int m=(s+e)/2;
	LL ret=f(s,m)+f(m,e);
	LL l=0,r=0;
	vector<LL> ls,rs;
	for(int i=m-1;i>=s;i--){
		l+=a[i];
		ls.push_back(l);
	}
	for(int i=m;i<e;i++){
		r+=a[i];
		rs.push_back(r);
	}
	sort(ls.begin(),ls.end());
	sort(rs.begin(),rs.end());
	int q=rs.size();
	for(auto v:ls){
		while(q>0&&rs[q-1]+v>=0){
			q--;
		}
		ret+=rs.size()-q;
	}
	return ret;
}
