void insert(int val ,node *n , ll s= -1e15 , ll e= 1e15  ){
    if(val >e || val < s) return  ;
    if(e==s){
        n->sum++;
//        cout << s << ' ' << e << ' ' <<n->sum <<endl;
        return ;
    }
    ll mid=s+(e-s)/2;
    if(!n->left){
        n->left = new node() ;
    }
    if(!n->right) n->right = new node();
    insert(val , n->left , s, mid );
    insert(val , n->right ,  mid +1 , e);
    n->sum = n->left->sum + n->right->sum ;
//    cout << s << ' ' << e << ' ' <<n->sum <<endl;
}


pair<int,bool> get(int val ,node *n , ll s= -1e15 , ll e= 1e15  ){
    if(val > e  ) return make_pair(n->sum,0) ;
    if(val < s ) return make_pair(0,0) ;
    if(e==s){
        return make_pair(n->sum,1);
    }
    ll mid=s+(e-s)/2;
    if(!n->left){
        n->left = new node() ;
    }

    if(!n->right) n->right = new node();
    pair<int,bool> p = get(val, n->left , s, mid);
    if(p.second)return {p.first,1};
    return make_pair(p.first + get(val , n->right , mid+1 ,e).first , 1 );

}


