class BIT {
   public:
    explicit BIT(int64_t n) : values(n + 1) {}

    void inc(int64_t idx) {
        ++idx;

        while (idx < values.size()) {
            ++values[idx];
            idx += (idx & -idx);
        }
    }

    // [0, idx) in 0-indexed
    // [1, idx] in 1-indexed
    int64_t query(int64_t idx) {
        int64_t ret = 0;

        while (idx > 0) {
            ret += values[idx];
            idx -= (idx & -idx);
        }

        return ret;
    }

    vector<int64_t> values;
};

