struct TreeNode {
    ll val;
    int lessCnt;
    TreeNode* left;
    TreeNode* right;
    TreeNode(ll v) : val(v), lessCnt(0), left(nullptr), right(nullptr) {};
};

ll n, k, cnt, res;
vector<ll> nums;
unordered_map<ll, ll> helper;

void gao(TreeNode* root, ll v) {
    TreeNode* pre = nullptr;
    TreeNode* tmp = root;
    while (tmp) {
        if (v >= tmp->val) {
            res += tmp->lessCnt + 1;
            pre = tmp;
            tmp = tmp->right;
        } else {
            ++(tmp->lessCnt);
            pre = tmp;
            tmp = tmp->left;
        }
    }
    if (v >= pre->val) {
        pre->right = new TreeNode(v);
    } else {
        pre->left = new TreeNode(v);
    }
}

int main() {
    cin >> n >> k;
    vector<ll> tmp;
    ll s = 0;
    nums.push_back(0);
    tmp.push_back(0);
    for (int i = 1; i <= n; ++i) {
        ll num;
        scanf("%lld", &num);
        s += num;
        nums.push_back(s - k * i);
        tmp.push_back(s - k * i);
    }
    sort(tmp.begin(), tmp.end());
    cnt = 0;
    for (int i = 0; i <= n; ++i) {
        if (i == 0 || tmp[i] != tmp[i - 1]) {
            helper[tmp[i]] = ++cnt;
        }
    }
    for (int i = 0; i <= n; ++i) {
        nums[i] = helper[nums[i]];
    }
    res = 0;
    TreeNode* root = new TreeNode(nums[0]);
    for (int i = 1; i <= n; ++i) {
        gao(root, nums[i]);
    }
    cout << res;

    return 0;
}

