bool cmp(int a, int b) {
    return p[a] < p[b];
}
inline int lowbit(int x) {
    return x & (-x);
}
inline int q(int x) {
    int ans = 0;
    for (; x; x -= lowbit(x)) ans += b[x];
    return ans;
}
inline void c(int x, int delta) {
    for (; x < N; x += lowbit(x)) b[x] += delta;
}
int main() {
    scanf("%d%lld", &n, &k);
    for (int i = 1; i <= n; i++) {
        scanf("%lld", a + i);
        a[i] -= k;
        p[i] = p[i - 1] + a[i];
    }
    for (int i = 0; i <= n; i++)
        l[i] = i;
    std::sort(l, l + n + 1, cmp);
    for (int i = 0; i <= n; i++) {
        if (p[l[i]] == pre) {
            r[l[i]] = cnt;
        } else {
            r[l[i]] = ++cnt;
            pre = p[l[i]];
        }
    }
    for (int i = 0; i <= n; i++) {
        tot += q(r[i]);
        c(r[i], 1);
    }
