struct SegTree {
  int n_count;
  vector<ll> pos;

  SegTree(ll N) {
    n_count = 1; while(n_count<N) n_count<<=1;
    pos.resize(2*n_count, 0);
  }

  ll operator[](const ll &k) const { return pos[k+n_count]; }

  void set(ll k, const ll x) { pos[k+n_count] = x; }
  void build() { for (int i=n_count-1; i>=0; i--) pos[i] = pos[i*2] + pos[i*2+1]; }
  void update(ll k, const ll x) { set(k,x); k += n_count; while(k >>= 1) pos[k] = pos[k*2] + pos[k*2+1]; }
  ll query(ll a,ll b) {
    ll L = 0, R = 0;
    for ( a+=n_count, b+=n_count; a<b; a>>=1, b>>=1 ) {
      if (a&1) { L+=pos[a]; a++; }
      if (b&1) { b--; R+=pos[b]; }
    }
    return L + R;
  }

};

struct num { ll i; ll v; };

int main() {
  ll N, K; cin >> N >> K;
  num a[N+1]; a[0] = {0,0};
  rep(i,N) { ll tmp; cin >> tmp; a[i+1] = {i+1,a[i].v+(tmp-K)}; }
  sort(a,a+(N+1),[](const num &x, const num &y){return x.v<y.v;});
  rep(i,N+1) a[i].v = i;
  sort(a,a+(N+1),[](const num &x, const num &y){return x.i<y.i;});  
  // rep(i,N+1) cout << a[i].i << ":" << a[i].v << " "; cout << endl;
  SegTree tree(N+1);
  ll result = 0;
  rep(i,N+1) {
    result += tree.query(0,a[i].v+1);
    tree.update(a[i].v,1);
  }
  cout << result << endl;
  return 0;
}

