struct BIT
{
    vector<ll> bit;
    ll MAX_N;

    BIT(ll n) : bit(n), MAX_N(n)
    {
        for(int i = 0; i < MAX_N; i++)
        {
            bit[i] = 0;
        }
    }

    ll sum(ll i)
    {
        ll s = 0;
        while(i > 0)
        {
            s += bit[i];
            i -= i & -i;
        }
        return s;
    }
    void add(ll i, ll x)
    {
        while(i <= MAX_N)
        {
            bit[i] += x;
            i += i & -i;
        }
    }
};

