class Myset {
  Myset *lch, *rch;
  LL value;
  LL same;
  LL size;
  Myset* update() {
    this->size = sz(this->lch) + this->same + sz(this->rch);
    return this;
  }
  Myset* _push(Myset *ch) {
    if (ch->value == this->value) {
      this->same += ch->same;
      this->push(ch->lch);
      this->push(ch->rch);
    } else if(ch->value < this->value) {
      !this->lch ?
        this->lch = ch :
        this->lch = this->lch->push(ch);
    } else {
      !this->rch ?
        this->rch = ch :
        this->rch = this->rch->push(ch);
    }
    return this->update();
  }
public:
  static int sz(Myset *s) { return !s ? 0 : s->size; }
  Myset() : lch(NULL), rch(NULL), value(0), same(1), size(1) {}
  Myset(LL v) : lch(NULL), rch(NULL), value(v), same(1), size(1) {}
  Myset* push(Myset *s) {
    if(!this || !s) return !this ? s : this;
    uniform_int_distribution<> r(1, this->size + s->size);
    if(r(mt) <= this->size) { return this->_push(s); }
    else { return s->_push(this); }
  }
  LL count_le(LL x) {
    if(!this) return 0;
    if(this->value <= x) {
      return sz(this->lch) + this->same
        + this->rch->count_le(x);
    } else {
      return this->lch->count_le(x);
    }
  }
  void dump(int d = 0) {
    if(lch) lch->dump(d+1);
    cout << d << " " << this->size << " " << this->value << endl;
    if(rch) rch->dump(d+1);
  }
};

Myset pool[262144];

int main(void)
{
  int n;
  LL k;
  cin >> n >> k;
  vector<LL> a(n);
  REP(i, n) { cin >> a[i]; a[i] -= k; }
  LL sum = 0ll;
  LL answer = 0ll;
  pool[n] = Myset(0);
  Myset* root = &pool[n];
  REP(i, n) {
    sum += a[i];
    answer += root->count_le(sum);
    pool[i] = Myset(sum);
    root = root->push(&pool[i]);
  }
  cout << answer << endl;
  return 0;
}

