namespace Treap {
	const int MAX_NODE = MAX_N;

	struct Node {
		ll key;
		int val, s;
		Node *ls, *rs;

		inline void maintain() {
			s = ls->s + rs->s + 1;
		}
	} pool[MAX_NODE], *pit, *null;

	void init() {
		pit = pool;
		null = new Node();
		null->s = 0;
	}

	inline Node *newNode(ll v) {
		pit->key = v, pit->val = rand();
		pit->s = 1, pit->ls = pit->rs = null;
		return pit++;
	}

	Node *merge(Node *a, Node *b) {
		if (a == null) return b;
		if (b == null) return a;
		if (a->val < b->val) {
			a->rs = merge(a->rs, b);
			a->maintain();
			return a;
		} else {
			b->ls = merge(a, b->ls);
			b->maintain();
			return b;
		}
	}

	typedef pair<Node *, Node *> Droot;
	Droot split(Node *o, int k) {
		Droot d(null, null);
		if (o == null) return d;
		int s = o->ls->s;
		if (k <= s) {
			d = split(o->ls, k);
			o->ls = d.second;
			o->maintain();
			d.second = o;
		} else {
			d = split(o->rs, k - s - 1);
			o->rs = d.first;
			o->maintain();
			d.first = o;
		}
		return d;
	}

	int lowerCount(const Node *o, ll v) { // 找到最后一个小于 v 的数的排名
		if (o == null) return 0;
		return v <= o->key ? lowerCount(o->ls, v) : lowerCount(o->rs, v) + o->ls->s + 1;
	}

	int upperCount(const Node *o, ll v) { // 找到最后一个小于等于 v 的数的排名
		if (o == null) return 0;
		return v < o->key ? upperCount(o->ls, v) : upperCount(o->rs, v) + o->ls->s + 1;
	}

	inline void insert(Node *&root, ll v) {
		int x = lowerCount(root, v);
		Droot l = split(root, x);
		root = merge(merge(l.first, newNode(v)), l.second);
	}
}

