struct Fenwick {
	vl t;
	Fenwick(int n) : t(n+1) {}
	ll sum(int pos) {
		++pos;
		ll ret = 0;
		while(pos > 0) {
			ret += t[pos];
			pos &= (pos-1);
		}
		return ret;
	}
	void add(int pos, ll val) {
		++pos;
		while(pos < t.size()) {
			t[pos] += val;
			pos += (pos & -pos);
		}
	}
};

