int main(int argc, char** argv) {
    long long N, K;

    cin >> N >> K;

    vector<long long> a(N), a_sum(N+1);

	for (int i = 0; i < N; i++) 
		cin >> a[i];

	a_sum[0] = 0;

	for (int i = 1; i <= N; i++)
		a_sum[i] = a_sum[i - 1] + a[i - 1] - K;

	long long ans = 0;
	int n_sqrt = int(sqrt(N)) + 1;
	vector<long long> sorted, unsorted;


	for (int i = 0; i <= N; i++) {
		// ソート済の部分は2分探索で
		ans += upper_bound(sorted.begin(), sorted.end(), a_sum[i]) - sorted.begin();

		// ソートしていない部分はナイーブに
		for (int j = 0; j < unsorted.size(); j++)
			ans += a_sum[i] >= unsorted[j];

		unsorted.push_back(a_sum[i]);

		if (unsorted.size() >= n_sqrt) {
			sort(unsorted.begin(), unsorted.end());
			int size = sorted.size();
			sorted.insert(sorted.end(), unsorted.begin(), unsorted.end());
			inplace_merge(sorted.begin(), sorted.begin() + size, sorted.end());
			unsorted.clear();
		}

	}

	cout << ans << endl;
}

