const int MAXN = 200001;


int n, k;
int c[MAXN];
int d[4 * MAXN];


void change(int i, int x) {
    d[i] += x;
    while (i >> 1 > 0) {
        i >>= 1;
        d[i] = d[i << 1] + d[(i << 1) + 1];
    }
}


int rmq(int v, int vl, int vr, int l, int r) {
    if (l > vr || vl > r) {
        return 0;
    }
    if (l <= vl && vr <= r) {
        return d[v];
    }
    return rmq(v << 1, vl, (vl + vr) >> 1, l, r) + rmq((v << 1) + 1, ((vl + vr) >> 1) + 1, vr, l, r);
}


map<long long, int> where;


