    while (ss <= MAXN) {
        ss <<= 1;
    }
    change(ss + MAXN, 1);
    vector<long long> kek;
    long long sum = 0;
    for (int i = 0; i < n; i++) {
        sum += c[i];
        kek.push_back(sum);
