pair<UM<ll,ll>,UM<ll,ll>> compress(vi v){
  vi unique; unique.PB(v[0]);
  FOR(i,1,ll(v.size())) if(v[i]!=v[i-1]) unique.PB(v[i]);
  ll N=unique.size();
  UM<ll,ll> newToOld,oldToNew;
  sort(ALL(unique));
