  return {oldToNew,newToOld};
}

struct RSQRAQ{
  ll size;
  ll *t1,*t2;
  RSQRAQ(ll sz){
    ll logsize; for(logsize=0;(1ll<<logsize)<=sz;logsize++);
    size=(1ll<<logsize);
    t1=new ll[size*2-1];
    t2=new ll[size*2-1];
    REP(i,size*2-1) t1[i]=t2[i]=0;
  }
  void add(ll s,ll t,ll x){
    add(s,t,0,size,0,x);
  }
  void add(ll s,ll t,ll l,ll r,ll k,ll x){
    if(r<=s||t<=l||r<=l) return;
    if(l+1==r) {t1[k]+=x; return;}
    if(s<=l&&r<=t) {t1[k]+=x*(r-l); t2[k]+=x*(r-l); return;}
    t1[k]+=(min(r,t)-max(l,s))*x;
    ll mid=(l+r+1)/2;
    add(s,t,l,mid,k*2+1,x);
    add(s,t,mid,r,k*2+2,x);
  }
  ll getSum(ll s,ll t){
    return getSum(s,t,0,size,0);
  }
  ll getSum(ll s,ll t,ll l,ll r,ll k){
    if(r<=s||t<=l||r<=l) return 0;
    if(l+1==r) return t1[k];
    if(s<=l&&r<=t) return t1[k];
    ll mid=(l+r+1)/2;
    t1[k*2+1]+=t2[k]/2; t2[k*2+1]+=t2[k]/2;
    t1[k*2+2]+=t2[k]/2; t2[k*2+2]+=t2[k]/2;
    t2[k]=0;
    return getSum(s,t,l,mid,k*2+1)+getSum(s,t,mid,r,k*2+2);
  }
};

