  vi c(N+1); REP(i,N+1) c[i]=b[i]-i*K;
  pair<UM<ll,ll>,UM<ll,ll>> cmp=compress(c);
  UM<ll,ll> oldToNew=cmp.first,newToOld=cmp.second;
  vi d(N+1); REP(i,N+1) d[i]=oldToNew[c[i]];

  ll ans=0;
