class BIT {
  int size;
  vector<int> v;
public:
  BIT(int n)
    : size(n), v(n + 1) {
  }

  void add(int i, int del) {
    ++i;
    for (; i <= size; i += i & -i) {
      v[i] += del;
    }
  }

  int get(int i) {
    int sum = 0;
    for (; i > 0; i -= i & -i) {
      sum += v[i];
    }
    return sum;
  }
};

