      LI xs(n);
      for(long &x : xs) scan(x);
      for(long &x : xs) x -= k;
      // for(long x : xs) printf("%ld ", x);
      // putchar('\n');
      LI ys(n+1);
      ys[0] = 0;
      for(long i = 0; i < (long)xs.size(); ++i) ys[i+1] = ys[i] + xs[i];
      // for(long y : ys) printf("%ld ", y);
      // putchar('\n');
      LI ts = ys;
      std::sort(ts.begin(), ts.end());
      ts.erase(std::unique(ts.begin(), ts.end()), ts.end());
      std::map<long, long> map;
      for(long i = 0; i < (long)ts.size(); ++i) map[ts[i]] = i;
      N002<long> rangeSum((long)ts.size(), 0,
                          [](long x, long y){ return x + y; });
      long res = 0;
      for(long i = 0; i < (long)xs.size(); ++i) {
         long index = map[ys[i+1]];
         update(rangeSum, index, rangeSum.xs[index+rangeSum.n] + 1);
         long index2 = map[ys[i]];
         res += rangeCompose(rangeSum, index2, (long)ts.size());
         dumpll(i, res);
      }
      printf("%ld\n", res);
   }
};

