long long msort(long long A[], long long B[], long long l, long long r) {
	if (l >= r) return 0;
	long long m = (l + r) >> 1;
	long long tot = msort(A, B, l, m) + msort(A, B, m + 1, r);
	long long i = l, j = m + 1, k = l;
	while (i <= m && j <= r)
		if (A[i] <= A[j]) B[k++] = A[i++];
		else B[k++] = A[j++], tot += m - i + 1;
	while (i <= m) B[k++] = A[i++];
	while (j <= r) B[k++] = A[j++];
	for (long long i = l; i <= r; ++i) A[i] = B[i];
	return tot;
}

