struct Node{
    int sign,min,max;
}tree[1000005];

int n;
pair<int,int> ax[200005];
pair<int,int> bx[200005];
int cx[200005];

bool mmp(const pair<int,int>& a,const pair<int,int>& b){
    return a.first<b.first;
}

int left (int x){
    return x<<1;
}

int right (int x){
    return (x<<1)+1;
}

void build (int L,int R,int i){
    if(L==R){
    tree[i].min = bx[L-1].first;
    tree[i].max = bx[L-1].first;
    tree[i].sign = 1;
    return;
    }
    int mid = (L+R)/2;
    build(L,mid,left(i));
    build(mid+1,R,right(i));
    tree[i].min = tree[left(i)].min;
    tree[i].max = tree[right(i)].max;
    tree[i].sign = tree[right(i)].sign+tree[left(i)].sign;
}

int findf (int L,int R,int res,int i){
    if(tree[i].max<res) return 0;
    if(tree[i].min>=res) return tree[i].sign;
    if(L==R) return 0;
    int mid = (L+R)/2;
    return findf(L,mid,res,left(i))+findf(mid+1,R,res,right(i));
}

void shan (int L,int R,int res,int i){
   if(L>res||R<res)return;
   tree[i].sign -= 1;
   if(L==R) return;
   int mid = (L+R)/2;
   shan(L,mid,res,left(i));
   shan(mid+1,R,res,right(i));
}

