template<typename T>
class BIT {
public:
    int N;
    vector<T> dat;

    BIT(int N) : N(N + 1) {
        dat.resize(N + 1, 0);
    }

    // sum[a0 + ... +ak)
    T get_sum(int k) {
        T ret = 0;
        //k & -kはkの２進表示の最も右のビットの表す数
        for(; k > 0; k -= (k & -k)) {
            ret += dat[k];
        }

        return ret;
    }

    //a[k] = a[k] + x;
    void add(int k, T x){
        k++;
        for(; k < N; k += (k & -k)) {
            dat[k] += x;
        }
    }
};

int compress(ll *x, int N){
  vector<ll> y;
  for(int i = 0; i < N; i++){
    y.push_back(x[i]);
  }

  sort(y.begin(), y.end());
  y.erase(unique(y.begin(), y.end()), y.end());

  for(int i = 0; i < N; i++){
    x[i] = lower_bound(y.begin(), y.end(), x[i]) - y.begin();
  }

  return (int)y.size();
}

