struct node {
	ll s,e,m;
	ll v;
	node *l,*r;
	node(ll _S,ll _E){
		s=_S,e=_E,m=(s+e)>>1;
		v=0;
		l=r=0;
	}
	void update(ll x,ll nval) {
		if(s==e) {
			v += nval;
			return;
		}
		if(x>m) cr(), r->update(x,nval); else cl(), l->update(x,nval);
		v=(l?l->v:0)+(r?r->v:0);
	}
	ll rmq(ll x,ll y) {
		if(s==x&&e==y) return v;
		if(x>m) return r?r->rmq(x,y):0;
		else if(y<=m) return l?l->rmq(x,y):0;
		else return (l?l->rmq(x,m):0)+(r?r->rmq(m+1,y):0);
	}
	void cl() { if(!l) l=new node(s,m); }
	void cr() { if(!r) r=new node(m+1,e); }
} *seg;
