    auto m = unordered_map<i64, i64>();
    m.reserve(N + 1);
    i64 n = 0;
    FORE (x, xs) {
        if (m.find(x) == m.end()) {
            m.insert({x, n});
            n += 1;
        }
    }

    i64 result = 0;
    BIT<i64> bit(N);
    bit.add(m.find(0)->second, 1);
    FORE (a, sum) {
        auto b = m.find(a)->second;
        result += bit.sum(b + 1);
        bit.add(b, 1);
    }

    cout << result << endl;

    return 0;
}

