    vector<long long> a(N+1);
    REP(i, N) cin >> a[i+1];

    REP(i, N){
        a[i+1] -= K;
        a[i+1] += a[i];
    }

    // 座標圧縮; a[0], [1], ... , a[N] -> [0, N] に圧縮
    auto comp_a = coordComp<long long>(a);

    BIT<> bit(N+1); // BIT で 0~N の出現回数を管理
    long long ans = 0;
    // r を探索
    REP(i, N+1){
        ans += bit.sum(comp_a[i]+1);
        bit.add(comp_a[i]+1, 1);
    }
    cout << ans << endl; 

