#include<bits/stdc++.h>
using namespace std;
vector< vector< long long > >tree(800009);

void make(int cur,int l,int r,vector<long long>&arr2)
{
    if(l==r)
    {
        tree[cur].push_back(arr2[l]);
        return;
    }
    int mid=(l+r)/2;
    make(2*cur+1,l,mid,arr2);
    make(2*cur+2,mid+1,r,arr2);
    for(int i=0;i<tree[2*cur+1].size()+tree[2*cur+2].size();i++)tree[cur].push_back(0);
    merge( tree[2*cur+1].begin(),tree[2*cur+1].end(),tree[2*cur+2].begin(),tree[2*cur+2].end() ,tree[cur].begin() );
}

int get(int cur,int l,int r,int s,int e,long long value)
{
    if(l>e || r<s)
        return 0;

    if(l>=s && r<=e)
    {
        int ret=upper_bound( tree[cur].begin(),tree[cur].end(),value-1)-tree[cur].begin();
        return tree[cur].size()-ret;
    }

    int mid=l+r >> 1;
    return get(2*cur+1,l,mid,s,e,value) + get(2*cur+2,mid+1,r,s,e,value);
}

