class BIT {
public:
    vector<T> v;
    BIT(int n) {
        v.resize(n + 1, 0);
    }
    void add(int pos, T x) {
        pos++;
        for (; pos < static_cast<int>(v.size()); pos += (pos & (-pos))) {
            v[pos] += x;
        }
