    memset(dp,0,sizeof(dp));
    dp[0] = 0;
    v.push_back(0);
    for(int i=1;i<=n;i++)
    {
        dp[i] = dp[i-1]+A[i];
        v.push_back(dp[i]);
    }
    sort(v.begin() , v.end());
    ll last = v[0];
    my[v[0]] = 1;
    my2[1] = v[0];
    int cnt = 2;
    for(int i=1;i<v.size();i++)
    {
        if(v[i]!= last)
        {
            my[v[i]] = cnt;
            my2[cnt] = v[i];
            cnt++;
        }
        last = v[i];
    }
    ll TT = cnt+100;
    dp[0] = my[dp[0]];
    for(int i=1;i<=n;i++)
    {
