struct AVLNode{
    ll value;
    ll cnt = 1;
    AVLNode *l = nullptr, *r = nullptr;
    int height;
    AVLNode(ll v): value(v), height(1){ }
    void updateHeight(){
        height = 1 + max(l ? l->height : 0, r ? r->height : 0);
    }
    AVLNode* add(ll v){
        if(v == value){ cnt++; return this; }
        auto& child = v < value ? l : r;
        if(&child == &r){
            cnt++;
        }
        if(child){
            child = child->add(v);
        }else{
            child = new AVLNode(v);
        }
        updateHeight();
        return check();
    }
    AVLNode* check(){
        int ld = l ? l->height : 0, rd = r ? r->height : 0;
        // prints(height, l, r, ld, rd);
        if(abs(ld - rd) <= 1){ return this; }
        // auto small = ld < rd ? l : r;
        auto large = ld >= rd ? l : r;
        int lld = large->l ? large->l->height : 0, rrd = large->r ? large->r->height : 0;
        // if((ld < rd && lld > rrd) || (ld > rd && lld < rrd)){
        //     large->rotate(lld >= rrd);
        // }
        return rotate(ld >= rd);
    }
    AVLNode* rotate(bool leftChild){
        AVLNode *AVLNode::*left = leftChild ? &AVLNode::l : &AVLNode::r,
                *AVLNode::*right = leftChild ? &AVLNode::r : &AVLNode::l;
        auto child = this->*left;
        if(leftChild){
            child->cnt += cnt;
        }else{
            cnt -= child->cnt;
        }
    // (child->*right)->cnt += cnt;
        this->*left = child->*right;
        child->*right = this;
        child->updateHeight();
        updateHeight();
        return child;
    }
};
struct AVLTree{
    AVLNode* root = nullptr;
    ll added = 0;
    void add(ll v){
        added -= v;
        v += added;
        if(!root){
            root = new AVLNode(v);
        }else{
            root = root->add(v);
        }
    }
    ll beq(ll num){
        num += added;
        AVLNode* n = root;
        ll acc = 0;
        while(n){
            if(n->value > num){
                acc += n->cnt;
                n = n->l;
            }else if(n->value == num){
                return n->cnt + acc;
            }else{
                n = n->r;
            }
        }
        return acc;
    }
};
