#define N (ll)(2e6+5)
#define INF (ll)(1e18+3)

#define ll long long
#define rep(i,a,n) for(ll i = a; i < n; i++)
#define per(i,a,n) for(ll i = n-1; i >= a; i--)

using namespace std;

ll a[N], p[N], p2[N];

ll t[N];
ll n, k;

void modify(int pp, int value) {  // set value at position p
  for (t[pp += n] = value; pp > 1; pp >>= 1) t[pp>>1] = t[pp] + t[pp^1];
}

int query(int l, int r) {  // sum on interval [l, r)
  int res = 0;
  for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
    if (l&1) res += t[l++];
    if (r&1) res += t[--r];
  }
  return res;
}

void solve() {
    cin >> n >> k;
    n++; p[0] = 0;
    rep(i,1,n) {
        cin >> a[i];
        p[i] = a[i] + p[i-1];
    }
    rep(i,0,n) {
        p[i] -= k*(i+1);
        p2[i] = p[i];
    }

    sort(&p2[0],&p2[n]);
    map<ll,ll> ma;
    ll cur = 0;
    rep(i,0,n) {
        if (!i || p2[i] != p2[i-1])
            ma[p2[i]] = cur++;
    }
    rep(i,0,n) {
        p[i] = ma[p[i]];
    }

    ll ans = 0;
    rep(i,0,n) {
        ans += query(0,p[i]+1);
        modify(p[i],t[p[i]+n]+1);
    }
    cout << ans << endl;
}

int main() {
    solve();
}

