int n,k,tree[N],sum[N],f[N],m,ans;
int lowbit(int x){return x&-x;}
void add(int x,int k)
{
    while(x<=n)
    {
        tree[x]+=k;
        x+=lowbit(x);
    }
}
int query(int x)
{
    int ans=0;
    while(x>0)
    {
        ans+=tree[x];
        x-=lowbit(x);
    }
    return ans;
}
int main()
{
    ios::sync_with_stdio(false);
    cin>>n>>k;
    for(int i=1;i<=n;++i)
        cin>>sum[i];
    for(int i=1;i<=n;++i)
        f[i]=sum[i]+=sum[i-1]-k;
    sort(f+1,f+n+1);
    m=unique(f+1,f+n+1)-f-1;
    for(int i=1;i<=n;++i)
        sum[i]=lower_bound(f+1,f+m+1,sum[i])-f;
    for(int i=n;i>=1;--i)
    {
        if(sum[i]>=0) ++ans;
        ans+=query(sum[i]);
        add(1,1);add(sum[i]+1,-1);
    }
