template <class T>
class bit
{
public:
    vector<T> dat;
    int n;

    bit(int n) : n(n) { dat.assign(n, 0); }
    bit(int n, T ini) : n(n) { dat.assign(n, ini); }
    // sum [0,i)
    T sum(int i)
    {
        int ret = 0;
        for (--i; i >= 0; i = (i & (i + 1)) - 1)
            ret += dat[i];
        return ret;
    }
    // sum [i,j)
    T sum(int i, int j) { return sum(j) - sum(i); }
    // add x to i
    void add(int i, T x)
    {
        for (; i < n; i |= i + 1)
            dat[i] += x;
    }
};
