#include <bits/stdc++.h>

using namespace std;

const int N = 2e5 + 5;

int n, k, a[N], used[N], cnt = 0;
long long f[N], bit[N];
vector <pair <long long, int> > comp;

void update (int x, int val) {
    for (int i = x; i < N; i += i & -i) bit[i] += val;
}

long long get (int x) {
    long long ans = 0;
    for (int i = x; i > 0; i -= i & -i) ans += bit[i];
    return ans;
}

signed main(){
    scanf("%d %d", &n, &k);
    long long ans = 0;

    f[0] = 0;
    for (int i = 1; i <= n; i++) scanf("%d", &a[i]);
    for (int i = 1; i <= n; i++) f[i] = f[i - 1] + a[i];
    for (int i = 1; i <= n; i++) comp.push_back(make_pair(f[i] - 1LL * k * i, i));
    comp.push_back(make_pair(0, 0));

    sort(comp.begin(), comp.end());
    used[comp[0].second] = ++cnt;
    for (int i = 1; i < comp.size(); i++) {
        if (comp[i].first > comp[i - 1].first) used[comp[i].second] = ++cnt;
        else used[comp[i].second] = cnt;
    }

    for (int i = 1; i <= n; i++) {
        update(used[i - 1], 1);
        ans += get(used[i]);
    }

    printf("%lld", ans);
    return 0;
}

