using namespace std;

typedef long long ll;

ll sum[200005], b[200005], c[200005];

// Segment Tree
constexpr int MAX_N = 1 << 17;
constexpr int INI = 0;
int num, dat[2 * MAX_N - 1];

// まず呼ぶ
void init(int n_) {
	num = 1;
	while (num < n_) num *= 2;
	for (int i = 0; i < 2 * num - 1; ++i) dat[i] = INI;
}

// k番目(0-indexed)の値をaに更新
void update(int k, int a) {
	k += num - 1;
	dat[k] = a;
	while (k > 0) {
		k = (k - 1) / 2;
		dat[k] = dat[2 * k + 1] + dat[2 * k + 2];
	}
}

// [a, b)の値を取得
// kはノードのインデックス
// [left, right)はノードkが対応する範囲
// query(a, b, 0, 0, num)で呼ぶ.
int query(int a, int b, int k, int left, int right) {
	if (right <= a || b <= left) return INI; // 結果に影響しない値を返すようにする 用変更
	if (a <= left && right <= b) return dat[k];
	int vleft = query(a, b, 2 * k + 1, left, left + (right - left) / 2);
	int vright = query(a, b, 2 * k + 2, left + (right - left) / 2, right);
	return vleft + vright;
}

int main() {
	int n; ll k; cin >> n >> k;
	for (int i = 1; i <= n; ++i) {
		ll a; cin >> a;
		sum[i] = a;
	}
	for (int i = 1; i <= n; ++i) sum[i] += sum[i - 1];
	for (int i = 0; i <= n; ++i) b[i] = sum[i] - i*k;
	sort(b, b + n + 1);
	int pos = 1;
	c[0] = b[0];
	for (int i = 1; i <= n; ++i) {
		if (c[pos - 1] == b[i]) continue;
		c[pos++] = b[i];
	}
	for (int i = 0; i <= n; ++i) {
		int lo = -1, hi = pos;
		while (hi - lo > 1) {
			int mid = lo + (hi - lo) / 2;
			if (c[mid] <= sum[i] - i*k) lo = mid;
			else hi = mid;
		}
		b[i] = lo;
	}
	init(pos);
	ll ans = 0;
	for (int i = 0; i <= n; ++i) {
		ans += (ll)query(0, b[i] + 1, 0, 0, num);
		update(b[i], query(b[i], b[i] + 1, 0, 0, num) + 1);
	}
	cout << ans << endl;
	return 0;
}

