    }
    solve();
    build(1, 0, c);
    for(int i = 0; i <= n; i++){
        ans = 0;
        query(1, 0, a[i]);
        res += ans;
        update(1, a[i], 1);
    }
    printf("%d\n", res);
    return 0;
}

