const int maxn = 2e5 + 10;

typedef long long ll;

ll p[maxn];
ll a[maxn],b[maxn];
unordered_map<ll,int> m;
ll lowbit(ll x) {return x & -x;};

ll sum(ll x) {
    ll res = 0;
    while (x > 0) {
        res += p[x];
        x -= lowbit(x);
    }
    return res;
}

void add(ll x) {
    while (x < maxn) {
        p[x]++;
        x += lowbit(x);
    }
}

