    for (int i = 0; i <= n; i++) {
        if (m[b[i]]) continue;
        m[b[i]] = len++;
    }
    ll res = 0;
    for (int i = 0; i <= n; i++) {
        ll t = m[a[i]];
        res += sum(t);
        add(t);
    }
