template<typename T> class BIT
{
   private:
      vector<T> bit;
      int len;
   public:
      BIT(int n) {
         len = n+1;
         bit.resize(len);
      }
      void add(int i, T x) {
         i += 1;
         while (i < len) {
            bit[i] += x;
            i += i & -i;
         }
      }
      int sum(int i) {
         i += 1;
         T s = 0;
         while (i > 0) {
            s += bit[i];
            i -= i & -i;
         }
         return s;
      }
};

void compose(const vector<int>& v, vector<int>& u) {
   int N = v.size();
   vector<pair<int,int>> tmp(N);
   for (int i = 0; i < N; i++) tmp[i] = make_pair(v[i],i);
   sort(tmp.begin(),tmp.end());
   for (int i = 0; i < N-1; i++) {
      u[tmp[i+1].second] = u[tmp[i].second] + (tmp[i+1].first == tmp[i].first ? 0 : 1);
   }
}

