template <class T>
vector<T> sumup(const vector<T>& a) {
  int N = a.size();
  vector<T> res(N + 1);
  for (int i = 0; i < N; i++) res[i + 1] = res[i] + a[i];
  return res;
}

template <class T>
ll invs(vector<T>& A) {
  ll res = 0;
  int N = A.size();
  if (N > 1) {
    vector<T> X(A.begin(), A.begin() + N / 2);
    vector<T> Y(A.begin() + N / 2, A.end());
    res += invs(X);
    res += invs(Y);
    int ai = 0, xi = 0, yi = 0;
    while (yi < Y.size()) {
      while (xi < X.size() && X[xi] <= Y[yi]) A[ai++] = X[xi++];
      A[ai++] = Y[yi++];
      res += X.size() - xi;
    }
    while (xi < X.size()) A[ai++] = X[xi++];
  }
  return res;
}

