        int m = (l + r) / 2;
        dv(l, m);
        dv(m + 1, r);
        vector < ll > v;
        int j = m + 1;
        ll cnt = 0;
        for(int i = l; i <= m; i++){
                while(j <= r && b[j] < b[i]){
                        v.pb(b[j++]);
