struct binary_indexed_tree{
    ll n, bit[MAX_V+1];
    //要素数N(0〜N-1)の初期化されたBITを構築
    binary_indexed_tree(int N){
        n = 1;
        while(n < N) n *= 2;
        fill_n(bit, n+1, 0);
    }
    //i番目(0から数える)の要素にx加える
    void add(int i, ll x){
        i++;
        while(i <= n){
            bit[i] += x;
            i += (i & -i);
        }
    }
    //sum(i)で[0,i)の和を取得
    ll sum(int i){
        ll s = 0;
        while(i > 0){
            s += bit[i];
            i -= (i & -i);
        }
        return s;
    }
    //query(l,r)で[l,r)の和を取得
    ll query(int l, int r){
        return sum(r) - sum(l);
    }
};

