typedef long long ll;
const ll INF = 2000000000000000;

struct node{
	ll l,r;
	int cnt;
	node *chl,*chr;
	void init(ll l_,ll r_){
		l = l_;
		r = r_;
		cnt = 0;
		chl = nullptr;
		chr = nullptr;
	}
	void mkchl(){
		chl = new node;
		chl->init(l,(l+r)/2);
	}
	void mkchr(){
		chr = new node;
		chr->init((l+r)/2,r);
	}
	void add(ll x){
		if(l <= x && x < r){
			cnt ++;
			if(l+1 == r)return;
			if(x < (l+r)/2){
				if(chl == nullptr)mkchl();
				chl->add(x);
			}
			else {
				if(chr == nullptr)mkchr();
				chr->add(x);
			}
		}
	}
	ll query(ll a,ll b){
		if(b <= l || r <= a)return 0;
		if(a <= l && r <= b)return cnt;
		ll ret = 0;
		if(chl != nullptr)ret += chl->query(a,b);
		if(chr != nullptr)ret += chr->query(a,b);
		return ret;
	}
}bit;

