#include<bits/stdc++.h>
#define MAX 200005
#define INF 1000000000000007
using namespace std;
typedef long long ll;

ll a[MAX];
ll jun(int l, int r){
  if(r - l == 1) return 0;
  int mid = (l+r)/2;
  ll ans = 0;
  ans += jun(l, mid) + jun(mid, r);
  ll s[MAX], t[MAX];
  for(int i = l; i < mid; i++) s[i-l] = a[i];
  for(int i = mid; i < r; i++) t[i-mid] = a[i];
  s[mid-l] = INF;
  t[r-mid] = INF;
  int i = 0, j = 0;
  while(i < mid-l || j < r-mid){
    if(s[i] <= t[j]){
      a[l+i+j] = s[i];
      i++;
    }else {
      a[l+i+j] = t[j];
      ans += i;
      j++;
    }
  }
  return ans;
}

int main(){
  int n, k;
  ll s, ans;
  a[0] = 0;
  scanf("%d%d", &n, &k);
  for(int i = 0; i < n; i++){
    scanf("%lld", &s);
    a[i+1] = a[i] + s - k;
  }
  ans = jun(0, n+1);
  printf("%lld", ans);
}

