ll inversePairs(vector<ll> &a, int l, int r) {
  if (l + 1 >= r) return 0;
  int m = (l + r) / 2;

  ll cnt = 0;
  cnt += inversePairs(a, l, m);
  cnt += inversePairs(a, m, r);

  vector<ll> tmp(a.begin() + l, a.begin() + m);
  int lsize = m - l;
  int i = 0, j = m;
  int tail = l;
  while (i < lsize && j < r) {
    if (tmp[i] > a[j]) {
      cnt += lsize - i;
      a[tail++] = a[j++];
    } else {
      a[tail++] = tmp[i++];
    }
  }
  while (i < lsize) {
    a[tail++] = tmp[i++];
  }

  return cnt;
}

