template <typename T>
vector<T> compress(vector<T> &X){
  vector<T> vals = X;
  sort(ALL(vals));
  vals.erase(unique(ALL(vals)), vals.end());
  for(int i=0; i<(int)X.size(); i++){
    X[i] = lower_bound(ALL(vals), X[i]) - vals.begin();
  }
  return vals;
}

template<typename T>
struct BIT{
  private:
    vector<T> bit;
    int N;

  public:
    BIT(int size){
      N = size;
      bit.resize(N+1);
    }

    void add(int k, int w){
      for(int x=k; x<=N; x+=(x & -x)) bit[x] += w;
    }

    T sum(int k){
      T ret = 0;
      for(int x=k; x>0; x-=x&-x) ret += bit[x];
      return ret;
    }
};

