    FORE (x, xs) {
        if (m.find(x) == m.end()) {
            m.insert({x, n});
            n += 1;
        }
    }

    u64 result = 0;
    BIT<i64> bit(N);
    bit.add(m.find(0)->second, 1);
    FORE (a, sum) {
        auto b = m.find(a)->second;
        result += bit.sum(b + 1);
        bit.add(b, 1);
    }

    cout << result << endl;

    return 0;
