struct BIT{
    int n;
    vector<int> bit;

    BIT(int N){
        bit.resize(N+1);
        n = N;
    }
    void add(int a, int w){
        for(int x = a;x <= n; x += x&-x){
            bit[x] += w;
        }
    }
    int sum(int a){
        int ret = 0;
        for(int x = a; x > 0; x -= x&-x){
            ret += bit[x];
        }
        return ret;
    }
};

int main(){
    int n, k;
    cin >> n >> k;
    vector<long long> a(n);
    for(int i=0;i<n;i++){
        cin >> a[i];
        a[i] -= k;
    }
    vector<pair<long long, int>> accum(n+1);
    for(int i=1;i<n+1;i++){
        accum[i] = make_pair(accum[i-1].first + a[i-1], i);
    }

    sort(accum.begin(), accum.end());

    vector<int> order(n+1);
    int num = -INF;
    int noword = 0;
    for(int i=0;i<n+1;i++){
        int pos = accum[i].second;
        if(accum[i].first > num)
            noword++;
        num = accum[i].first;
        order[pos] = noword;
    }
    BIT bit(n+2);
    long long ans = 0;
    for(int i=0;i<n+1;i++){
        int num = bit.sum(order[i]);
        ans += num;
        bit.add(order[i], 1);
    }
    cout << ans << endl;

    return 0;
}

