ll merge(int arr[], ll l, ll r){
	int tmp[1234567];
	ll k = l;
	ll i = l;
	ll j = (l+r)/2;
	ll inv = 0;
	while(i < (l+r)/2 && j < r){
		if(arr[i] <= arr[j])	tmp[k++] = arr[i++];
		else{
			tmp[k++] = arr[j++];
			inv += (l+r)/2 - i;
		}
	}
	if(i == (l+r)/2){
		while(j < r) tmp[k++] = arr[j++];
	}
	else{
		while(i < (l+r)/2) tmp[k++] = arr[i++];
	}

	for(int i = l; i < r; i++){
		arr[i] = tmp[i];
//		printf("%d ", arr[i]);
	}
//	printf("\n");

//	printf("%lld %lld %lld\n", l, r, inv);
	return inv;
}
ll ms(int arr[], ll l, ll r){
	if(l == r-1){	
		return 0;
	}
	ll mid = (l+r)/2;
	ll inv = ms(arr, l, mid);
	inv += ms(arr, mid, r);
	inv += merge(arr, l, r);
	return inv;
}


