struct BinaryIndexedTree {
    int n;
    int bit[200020];

    BinaryIndexedTree(int _n): n(_n) {
		for (int i = 0; i <= n; i++) bit[i] = 0;
	}

    int sum(int i) {
        int res = 0;
        while (i > 0) {
            res += bit[i];
            i -= i & -i;
        }
        return res;
    }

    void add(int i, ll x) {
        while(i <= n) {
            bit[i] += x;
            i += i & -i;
        }
    }
};

