ll RSQ(int s, int t, int k = 1, int l = 0, int r = 131071) {
	if (t < l || r < s)return 0;
	if (s <= l && r <= t) {
		return X[k];
	}
	ll lv = RSQ(s, t, k * 2, l, (l + r) / 2);
	ll rv = RSQ(s, t, k * 2 + 1, (l + r) / 2 + 1, r);
	return lv + rv;
}

