struct node {
	ll v=0;
	node *l = 0, *r = 0;
	node (ll s, ll e) {
		v = 0;
		l=r=0;
	}
	void update(ll s, ll e, ll x, ll nval) {
		ll m = floor(((double)s+e)/2.0);
		if(s==e) {
			v+=nval;
			return;
		}
		if (x>m) {
			if (!r) r = new node(m+1,e);
			r->update(m+1,e,x,nval);
		} else {
			if (!l) l = new node(s,m);
			l->update(s,m,x,nval);

		}
		v=(l?l->v:0)+(r?r->v:0);
	}
	ll query(ll s, ll e, ll qs, ll qe) {
		ll m = floor(((double)s+e)/2.0);
		if (s==qs&&qe==e) return v;
		if (qs>m) return r?r->query(m+1,e,qs,qe):0;
		else if (qe<=m) return l?l->query(s,m,qs,qe):0;
		else return (l?l->query(s,m,qs,m):0) + (r?r->query(m+1,e,m+1,qe):0);
	}

