template <class T>
struct segment_tree {
	int n;
	vector<T> x;
	segment_tree(int n_) {
		n=1;
		while(n < n_)n*=2;
		x.assign(n*2,init_val());
	}

	T init_val(){
		return 0;
	}
	T f(const T &a, const T &b){
		return a+b;
	}
	T range(int a,int b,int i,int l,int r){
		if(r<=a or b<=l)return init_val();
		if(a<=l and r<=b)return x[i];
		else{
			int m = (l+r)/2;
			return f(range(a,b,i*2+1,l,m),range(a,b,i*2+2,m,r));
		}
	}
	T range(int a,int b){
		return range(a,b,0,0,n);
	}
	void add(int a,const T &v,int i,int l,int r){
		if(r-l==1){
			x[i] += v;
		}else{
			int m = (l+r)/2;
			if(a<m)add(a,v,i*2+1,l,m);
			else add(a,v,i*2+2,m,r);
			x[i] = f(x[i*2+1],x[i*2+2]);
		}
	}
	void add(int a,const T &v){
		add(a,v,0,0,n);
	}
};
