int lowbit(int x){
    return x&(-x);
}

int ask(int x){
    int ret=0;
    for (;x;x-=lowbit(x)) ret+=c[x];
    return ret;
}

void change(int x,int y){
    for (;x<=n+1;x+=lowbit(x)) c[x]+=y;
}

