vector<P> data[N];
class kdTree {
  private:
    int n;

    void init(int k, int l, int r, P *d) {
      if(r-l == 1) {
        data[k].push_back(d[l]);
      } else {
        int lch = 2*k+1, rch = 2*k+2;
        init(lch, l, (l+r)/2, d);
        init(rch, (l+r)/2, r, d);
        data[k].resize(r-l);

        merge(
            data[lch].begin(), data[lch].end(),
            data[rch].begin(), data[rch].end(),
            data[k].begin()
            );
      }
    }
    int r_query(int a, int b, int x0, int x1, int k, int l, int r) {
      if(b <= l || r <= a) {
        return 0;
      } else if(a <= l && r <= b) {
        vector<P>::iterator it0 = upper_bound(data[k].begin(), data[k].end(), P(x0, -1));
        vector<P>::iterator it1 = upper_bound(data[k].begin(), data[k].end(), P(x1, -1));
        int sz = it1 - it0;
        return sz;
      } else {
        int lc = r_query(a, b, x0, x1, 2*k+1, l, (l+r)/2);
        int rc = r_query(a, b, x0, x1, 2*k+2, (l+r)/2, r);
        return lc + rc;
      }
    }
  public:
    kdTree(int n, P *d) {
      this->n = n;
      init(0, 0, n, d);
    }
    // [a, b) * [x0, x1)
    int query(int a, int b, ll x0, ll x1) {
      return r_query(a, b, x0, x1, 0, 0, n);
    }
};

