ll merge(vector<ll> &line,int l,int m,int r){
  int as = m - l;
  int bs = r - m;
  vector<ll> A(as+1);
  vector<ll> B(bs+1);
  rep(i,as)A[i] = line[l+i];
  rep(i,bs)B[i] = line[m+i];
  A[as] = INT64_MIN;
  B[bs] = INT64_MIN;
  ll res = 0;
  int ap = 0;
  int bp = 0;
  rep(i,r-l){
    if(A[ap]<=B[bp]){
      line[l+i] = B[bp];
      ++bp;
      res += as-ap;
    }else{
      line[l+i] = A[ap];
      ++ap;
    }
  }
  return res;
}

ll merge_sort(vector<ll> &line,int l,int r){
  if(r-l==1)return 0;
  ll res = 0;
  int mid = (r+l) / 2;
  res += merge_sort(line,l,mid);
  res += merge_sort(line,mid,r);
  res += merge(line,l,mid,r);
  return res;
}
