int bit_sum(int i) {
  int s = 0;
  while(i > 0) {
    s += bit[i];
    i -= i & (-i);
  }
  return s;
}

void bit_add(int i, int val) {
  while(i <= n) {
    bit[i] += val;
    i += i & (-i);
  }
}

