void solve(int l,int r)
{
    if(l==r)
    {
        ans+=(a[l]>=0);
        return;
    }
    int mid=(l+r)>>1;
    solve(l,mid);
    solve(mid+1,r);
    //printf("l=%d,r=%d,ans=%I64d\n",l,r,ans);
    int cnt=0;
    pre[cnt]=0;
    for(int i=mid+1;i<=r;++i)
    {
        cnt++;
        pre[cnt]=pre[cnt-1]+a[i];
    }
    sort(pre+1,pre+cnt+1);
    ll sum=0;
    for(int i=mid;i>=l;--i)
    {
        sum+=a[i];
        int lx=lower_bound(pre+1,pre+cnt+1,-sum)-pre;
        //printf("l=%d,r=%d,lx=%d,cnt=%d\n",l,r,lx,cnt);
        ans+=max(0,cnt-lx+1);
    }
}
