  int n = x.size();
  vector<T> y = x, ret(n);
  sort(y.begin(), y.end());
  y.erase(unique(y.begin(), y.end()), y.end());
  for (int i = 0; i < n; i++) {
    ret[i] = lower_bound(y.begin(), y.end(), x[i]) - y.begin() + offset;
  }
  return ret;
}

// {10, 3, 1, -5, 1} -> {3, 2, 1, 0, 1} + offset
// unzip: {-5, 1, 3, 10}
template <typename T>
vector<T> CoordinateCompression(const vector<T> &x, vector<T> &unzip, int offset = 0) {
  int n = x.size();
  vector<T> ret(n);
  unzip = x;
  sort(unzip.begin(), unzip.end());
  unzip.erase(unique(unzip.begin(), unzip.end()), unzip.end());
  for (int i = 0; i < n; i++) {
    ret[i] = lower_bound(unzip.begin(), unzip.end(), x[i]) - unzip.begin() + offset;
  }
  return ret;
}

// Binary Indexed Tree 0-indexed
struct BIT0 {
  ll n;
  vector<ll> bit;
  BIT0(ll n) : n(n), bit(n, 0) {}
  void add(ll a, ll w) {
    for (; a < n; a |= a + 1) {
      bit[a] += w;
    }
  }
  // v: 0-indexed, size = n
  void build(const vector<ll> &v) {
    n = v.size();
    bit = v;
    ll unit = 1;
    while (unit * 2 < n) {
      for (int i = unit * 2 - 1; i < n; i += unit * 2) {
        bit[i] += bit[i - unit];
      }
      unit <<= 1;
    }
  }
  ll sum(ll a) {
    ll ret = 0;
    for (; a >= 0; a = (a & (a + 1)) - 1) {
      ret += bit[a];
    }
    return ret;
  }
  // [a, b]
  ll sum(ll a, ll b) {
    return sum(b) - sum(a - 1);
  }
};


