    lint prv = std::numeric_limits<lint>::min();
    int now = -1;
    auto pairs = coenumerate(a);
    std::sort(all(pairs));
    for (auto&& pair : pairs) {
      lint x; int i; std::tie(x,i) = pair;
      assert(prv <= x);
      if (prv < x) now++;
      rank.at(i) = now;
