template<typename T>
struct BIT {
  vector<T> bit;
  const int sz;

  BIT(int n) : bit(n+1, 0), sz(n) {}

// [1, i] 1-indexed
  T sum(int i) {
    T s = 0;
    while (i > 0) { s += bit[i]; i -= i & -i; }
    return s;
  }

// [l, r] 1-indexed
  T sum(int l, int r) {
    return sum[r] - sum[l-1];
  }

  void add(int i, T x) {
    while (i <= sz) { bit[i] += x; i += i & -i; }
  }
};

void solve() {
  int n, k; cin >> n >> k;
