// 1. set n
// 2. init bit[0] ... bit[n + 1]
// 3. use add(i, x) and sum(i)


ll bit[MAX_N + 1], n;

int sum(int i) {
  ll s = 0;
  while(i > 0) {
    s += bit[i];
    i -= i & -i;
  }
  return s;
}

void add(int i, ll x) {
  while(i <= n) {
    bit[i] += x;
    i += i & -i;
  }
}

