template<class T>
class segment_tree_t {
public:
  segment_tree_t(int size) : size_(1) {
    while (size_ < size)
      size_ *= 2;

    a_ = new T[size_ * 2];

    memset(a_, 0, sizeof(T) * size_ * 2);
  };

  ~segment_tree_t() {
    delete[] a_;
  };

public:
  void update(int i, T x) {	// 0-index
    i += size_ - 1;

    a_[i] = x;

    while (i > 0) {
      i = (i - 1) / 2;

      a_[i] = a_[i * 2 + 1] + a_[i * 2 + 2];
    }
  };

  T query(int a, int b, int i = -1, int l = -1, int r = -1) {	// [a, b)
    if (i < 0) {
      return query(a, b, 0, 0, size_);
    }
    else {
      if (r <= a || b <= l)
        return 0;

      if (a <= l && r <= b) {
        return a_[i];
      }
      else {
        return
          query(a, b, i * 2 + 1, l, (l + r) / 2) +
          query(a, b, i * 2 + 2, (l + r) / 2, r);
      }
    }
  };

private:
  int size_;

  T* a_;
};


