// BIT木を実装する

const int MAX_N = 3e7;

int bit[MAX_N]; int n;

void init(const int &N){ 

  n = 1LL;
  while( n < N){ n *= 2;} //bitは最初から0だから更新する必要なし
}

void add(int i, const int &x){
  while( i <= n ){ bit[i] += x; i += i& (-i);}
}

int sum(int i){ //a1+...+asまでの和
  int s = 0;
  while( i > 0 ){ s += bit[i]; i -= i&(-i);}
  return s;
}

