	rep(i, N) {
		B[i+1] = B[i] + A[i];
	}
	auto dfs = [&B](auto&& f, int l, int r) -> int {
		if (r - l == 1) return 0;
		int m = (r + l) / 2;
		int res = f(f, l, m) + f(f, m, r);
		vector<int> L = vector<int>(B.begin() + l, B.begin() + m);
		vector<int> R = vector<int>(B.begin() + m, B.begin() + r);
		size_t i = 0, j = 0;
		for (; i < L.size() && j < R.size();) {
			if (L[i] <= R[j]) {
				B[l + i + j] = L[i];
				i++;
			}
			else {
				B[l + i + j] = R[j];
				res += int(L.size()) - i;
				j++;
			}
		}
		for (; i < L.size(); i++) B[l + i + j] = L[i];
		for (; j < R.size(); j++) B[l + i + j] = R[j];
		return res;
	};
	cout << (N + 1) * N / 2 - dfs(dfs, 0, N + 1) << endl;
	return 0;
}

