struct SegmentTree{
  vector <int> Tree[20];
  void Make(){
    for (int i = 0; i < 20; i++){
      Tree[i].resize(1<<i);
    }
  }

  void Add(int num, ll val){
    for (int i = 19; i >= 0; i--){
      Tree[i][num] += val;
      num /= 2;
    }
  }

  ll Count(int num){
    int now = 19; 
    ll ans = Tree[now][num];
    while (now > 0 && num > 0){
      if (num % 2 != 0){
        num--;
      }else{
        now--; num /= 2; num--;
      }
      ans += Tree[now][num];
    }
    return ans;
  }

};

