int merge(
	vector<int> a, 
	const int& n, 
	const int& l,
	const int& m,
	const int& r)
{
	int n1 = m - l;
	int n2 = r - m;
	vector<int> L, R;
	REP(i, n1)L.push_back(a[l + i]);
	REP(i, n2)R.push_back(a[m + i]);
	L.push_back(INF);
	R.push_back(INF);


	int i, j, k, cnt = 0;
	i = j = 0;
	FOR(k, l, r) {
		if (L[i] <= R[j]) {
			a[k] = L[i++];
		}
		else {
			a[k] = R[j++];
			cnt += n1 - i;
		}
	}
	return cnt;
}

int mergeSort(
	vector<int> a,
	const int& n,
	const int& l,
	const int& r)
{
	int mid;
	int v1, v2, v3;

	if (l + 1 < r) {
		mid = (l + r) / 2;
		v1 = mergeSort(a, n, l, mid);
		v2 = mergeSort(a, n, mid, r);
		v3 = merge(a, n, l, mid, r);
		return v1 + v2 + v3;
	}
	else {
		return 0;
	}
}

