        seg[root].val++;
        if(l==r) return ;
        LL mid=(l+r)>>1;
        if(val<=mid) update(seg[root].lson,l,mid,val);
        else update(seg[root].rson,mid+1,r,val);
    }
    LL query(int root,LL l,LL r,LL ql,LL qr)
    {
        if(root==-1) return 0;
        if(l==ql&&r==qr) return seg[root].val;
        LL mid=(l+r)>>1;
        if(qr<=mid) return query(seg[root].lson,l,mid,ql,qr);
        else if(ql>mid) return query(seg[root].rson,mid+1,r,ql,qr);
        else return query(seg[root].lson,l,mid,ql,mid)+query(seg[root].rson,mid+1,r,mid+1,qr);
    }
    /**
    void debug(int i)
    {
        if(i==-1) return ;
        printf("node=%d val=%lld lson=%d rson=%d\n",i,seg[i].val,seg[i].lson,seg[i].rson);
        debug(seg[i].lson),debug(seg[i].rson);
