vector<ll> vec;

int fd(ll a) {
	return lower_bound(all(vec), a) - vec.begin();
}

void solve() {
	cin >> N >> K;
	rep(i, 1, N + 1) {
		cin >> B[i];
		B[i] += B[i - 1];
	}
	rep(i, 1, N + 1) {
