template <class Tp>
struct fenwick_tree{
	typedef unsigned size_type;
	std::vector<Tp> bit;

	fenwick_tree(){}
	explicit fenwick_tree(size_type n){
		init(n);
	}
	void init(size_type n){
		bit.assign(n + 1, Tp());
	}
	Tp sum(size_type i) const{
		Tp s = 0;
		while(i){
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}
	Tp summod(size_type i, Tp mod) const{
		Tp s = 0;
		while(i){
			s = (s + bit[i]) % mod;
			i -= i & -i;
		}
		if(s < 0){ s += mod; }
		return s;
	}
	void add(size_type i, Tp x){
		size_type sz = bit.size();
		while(i < sz){
			bit[i] += x;
			i += i & -i;
		}
	}
	void addmod(size_type i, Tp x, Tp mod){
		size_type sz = bit.size();
		x %= mod;
		if(x < 0){ x += mod; }
		while(i < sz){
			bit[i] = (bit[i] + x) % mod;
			i += i & -i;
		}
	}
	void clear(){
		bit.clear();
	}
	void swap(fenwick_tree &f){
		bit.swap(f.bit);
	}
	size_type lower_bound(Tp x) const{
		if(bit.empty()){ return 0; }
		size_type n = bit.size() - 1;
		size_type t = n;
		while(t & (t - 1)){
			t ^= t & -t;
		}
		size_type ans = 0;
		Tp s = Tp();
		for(; t; t >>= 1){
			size_type tmp = ans | t;
			if(tmp <= n && s + bit[tmp] < x){
				s += bit[tmp];
				ans = tmp;
			}
		}
		return ans + 1;
	}
	size_type upper_bound(Tp x) const{
		if(bit.empty()){ return 0; }
		size_type n = bit.size() - 1;
		size_type t = n;
		while(t & (t - 1)){
			t ^= t & -t;
		}
		size_type ans = 0;
		Tp s = Tp();
		for(; t; t >>= 1){
			size_type tmp = ans | t;
			if(tmp <= n && s + bit[tmp] <= x){
				s += bit[tmp];
				ans = tmp;
			}
		}
		return ans + 1;
	}
};

