template<typename T>
vector<int> compress(const vector<T> &src){
    const int n = src.size();
    vector<pair<T, int>> sorted(n);
    for (int i = 0; i != n; ++i){
        sorted[i] = {src[i], i};
    }
    sort(sorted.begin(), sorted.end());
    int j = 0;
    auto prev_val = sorted[0].first;
    vector<int> compressed(n, 0);
    for (int i = 0; i != n; ++i){
        if (sorted[i].first != prev_val) {
            ++j;
            prev_val = sorted[i].first;
        }
        compressed[sorted[i].second] = j;
    }
    return compressed;
};



template<typename T>
struct BIT{
    vector<T> bit;
    BIT(int n) : bit(n, 0){}
    T range_sum(int i, int j) {return sum(j) - sum(i - 1);}
    // return sum of v[i] to v[j] including both ends.
    T sum(int j){
        T s = 0;
        for (; j >= 0; j = (j & (j + 1)) - 1) s += bit[j];
        return s;
    }
    void add(int k, T a) {for (; k < bit.size(); k |= k + 1) bit[k] += a;}
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll N, K;
    cin >> N >> K;
    vector<ll> cum(N + 1);
    ll a;
    cum[0] = 0;
    for (int i = 0; i != N; ++i) {
        cin >> a;
        cum[i + 1] = cum[i] + a - K;
    }
    auto compressed = compress(cum);
    int n = *max_element(compressed.begin(), compressed.end());
    BIT<ll> freq(n + 1);
    ll ans = 0;
    for (auto c : compressed) freq.add(c, 1);
    for (auto c : compressed){
        freq.add(c, -1);
        ans += freq.range_sum(c, n);
    }
    cout << ans << endl;
    return 0;
}

