void Update(int idx, int cnt){
	idx += B;
	tree[idx] += cnt; idx >>= 1;
	while (idx){
		tree[idx] = tree[idx << 1] + tree[(idx << 1) + 1];
		idx >>= 1;
	}
}
int Get(int l, int r){
	l += B, r += B;
	int res = 0;
	while (l <= r){
		if (l & 1) res += tree[l++];
		if (!(r & 1)) res += tree[r--];
		l >>= 1, r >>= 1;
	}
	return res;
}
