int t[4 * 200200];

void add(int v, int l, int r, int pos) {
    if(l == r) {
        t[v]++;
        return;
    }
    int mid = (l + r) >> 1;
    if(pos <= mid) add(LS, pos);
    else add(RS, pos);
    t[v] = t[v+v] + t[v+v+1];
}

int get(int v, int l, int r, int L, int R) {
    if(r < L || R < l) return 0;
    if(L <= l && r <= R) return t[v];
    int mid = (l + r) >> 1;
    return get(LS, L, R) + get(RS, L, R);
}

