int lowbit(int x)
{
    return x&-x;
}
void add(int x)
{
    for(int i=x;i<N;i+=lowbit(i))
        f[i]++;
}
ll query(int x)
{
    ll ans=0;
    for(int i=x;i;i-=lowbit(i))
        ans+=f[i];
    return ans;
}
int main()
{
