	cin.tie(0);
	ios_base::sync_with_stdio(false);
	cout << fixed << setprecision(50);
	ll n, k; cin >> n >> k;
	vl a(n); REP(i, n) cin >> a[i];
	struct P {
		ll num = 0;
		vl l, r;
	};
	function<P(ll, ll)> recur = [&](ll l, ll r) {
		if (l == r) {
			P p; 
			p.num = a[l] >= k;
			p.l = { a[l] - k };
			p.r = { a[l] - k };
			return p;
		}
		ll c = (r + l) / 2;
		auto lhs = recur(l, c);
		auto rhs = recur(c + 1, r);
		P p;
		p.num = lhs.num + rhs.num;
		p.l = std::move(lhs.l);
		ll pl = p.l.size();
		REP(i, rhs.l.size()) p.l.push_back(p.l[pl-1] + rhs.l[i]);
		p.r = std::move(rhs.r);
		ll pr = p.r.size();
		REP(i, lhs.r.size()) p.r.push_back(p.r[pr-1] + lhs.r[i]);

		sort(ALL(rhs.l));
		REP(i, lhs.r.size()) p.num += rhs.l.end() - lower_bound(ALL(rhs.l), -lhs.r[i]);

		return p;
	};
	auto ans = recur(0, n - 1);
	cout << ans.num << endl;

	return 0;
}

