    long long sum =0;
    long long ans = 0;
    s[1] = 0;
    for(int i = 1; i <= n; ++i) {
        cin >> a[i];
        sum = sum + a[i];
        long long t = sum - 1LL*k*i;
        s[i+1] = t;
    }
    ans = cal(s, n+1);
    cout << ans << endl;
}

