#define ALL(c) (c).begin(),(c).end()
#define EACH(i,c) for(auto i=(c).begin();i!=(c).end();++i)
using namespace std;

typedef int Type;
struct Fenwick{
    vector<Type> bit;
    Fenwick(int n){
        bit = vector<Type>(n + 1);
    }
    void update(int i, Type v){
        int n = bit.size();
        ++i;
        while(i <= n){
            bit[i] += v;
            i += i & -i;
        }
    }
    Type get(int i){
        Type res = 0;
        ++i;
        while(i > 0){
            res += bit[i];
            i -= i & -i;
        }
        return res;
    }
};

int main(){
	int N, K;
	cin >> N >> K;
	vector<int> a(N), b(N + 10);
	for(int i = 0; i < N; ++i) {
		cin >> a[i];
	}
	b[0] = 0;
	for(int i = 1; i <= N; ++i) {
		b[i] = b[i-1] + (i - 1) * K + a[i - 1] - i * K;
	}
	vector<int> c = b;
	sort(ALL(c));
	c.erase(unique(ALL(c)), c.end());

	int sum = 0;
	Fenwick bit(c.size());
	bit.update(lower_bound(ALL(c), b[N]) - c.begin(), 1);
	for(int i = N - 1; i >= 0; --i) {
		int t = lower_bound(ALL(c), b[i]) - c.begin();
		sum += (N - i) - bit.get(t - 1);
		bit.update(t, 1);
	}
	cout << sum << endl;
	return 0;
}

