using namespace std;
using VI = vector<int>;

class RangeIka {
    const int ST_SIZE = (1 << 18) - 1;
    int n;
    VI data;
    vector<VI> segtree;

    void init(int k, int l, int r) {
        if (r - l == 1) {
            segtree[k].push_back(data[l]);
        } else {
            int lch = k * 2 + 1;
            int rch = k * 2 + 2;
            init(lch, l, (l + r) / 2);
            init(rch, (l + r) / 2, r);
            segtree[k].resize(r - l);

            merge(segtree[lch].begin(), segtree[lch].end(), segtree[rch].begin(), segtree[rch].end(), segtree[k].begin());
        }
    }

    // number of x in [i, j)
    int query(int i, int j, int x, int k, int l, int r) {
        if (j <= l || r <= i) {
            return 0;
        }

        if (i <= l && r <= j) {
            return upper_bound(segtree[k].begin(), segtree[k].end(), x) - segtree[k].begin();
        }

        int lc = query(i, j, x, k * 2 + 1, l, (l + r) / 2);
        int rc = query(i, j, x, k * 2 + 2, (l + r) / 2, r);
        return lc + rc;
    }

public:
    RangeIka(VI v) {
        n = v.size();
        data = VI(v);
        segtree = vector<VI>(ST_SIZE);
        init(0, 0, n);
    }

    int get(int i, int j, int x) {
        return query(i, j, x, 0, 0, n);
    }
};

int main() {
    long n, k;
    cin >> n >> k;
    VI as;
    for (int i = 0; i < n; i++) {
        long a;
        cin >> a;
        a -= k;
        as.push_back(a);
    }
    VI sum = {0};
    for (auto a: as) {
        sum.push_back(sum.back() + a);
    }

    long ans = 0;
    RangeIka r(sum);
    for (int i = 0; i < n; i++) {
        ans += n - i - r.get(i + 1, n + 1, sum[i] - 1);
    }

    cout << ans << endl;
}

