template <typename T>
struct FenwickTree {
    int n;
    vector<T> dat;

    FenwickTree(vector<T>& d) {
        n = d.size();
        dat.resize(n + 1, 0);
        for (int i = 0; i < n; i++) dat[i + 1] = d[i];
    }

    FenwickTree(int size) {
        n = size;
        dat = vector<T>(n + 1, 0);
    }

    // 0-indexed
    T sum(int i) {
        if (i < 0) return 0;

        i++;
        T res = 0;
        while (i > 0) {
            res += dat[i];
            i -= i & -i;
        }
        return res;
    }

    // [i, j]
    T sum(int i, int j) {
        return sum(j) - sum(i - 1);
    }

    void add(int i, T x) {
        i++;
        while (i <= n) {
            dat[i] += x;
            i += i & -i;
        }
    }
};

