template<typename T>
class bit {
public:
  T e;
  function<T(T, T)> f;
  unsigned int n;
  vector<T> v;
  bit(T _e, function<T(T, T)> _f, unsigned int _n) {
    e = _e;
    f = _f;
    n = _n;
    vector<T> _v((1 << n) - 1, e); v.swap(_v);
  }
  void update(unsigned int i, T x){
    assert(0 < i);
    while (i + 1 < 1u << n){
      v[i] = v[i] + x;
      i += i & -i;
    }
