    for (size_t i = 0; i < n; i++)
    {
        r[i + 1] = r[i] + a[i];
        p[i + 1] = r[i + 1] - (i + 1) * k; //転倒数(i番目以下でp[i]より小さい要素の数)を求めたい数列
    }
    //座標圧縮,重複要素があることに注意
    vector<ll> b = p;
    map<ll, ll> mp;
    sort(all(b));
    for (int i = 0; i < n + 1; i++)
    {
        if (mp.find(b[i]) == mp.end())
            mp[b[i]] = i; //0-indexでいいのか？これ
    }
    //セグ木にぶち込む
    ll ans = 0;
    segment_tree<int> seg(n + 2, [](int a, int b) { return a + b; }, 0);
    seg.build();
    for (int i = 0; i < n + 1; i++)
    {
        ans += seg.query(0, mp[p[i]]); //i番目以下でp[i]より小さい要素の数
        seg.update(mp[p[i]], seg[p[i]] + 1);
    }

