struct SegTree {
	vector<LL> dat[(1 << 19) - 1];
	void init(int k, int l, int r, LL A[], int N) {
		if (r - l == 1) {
			if (l < N) dat[k].push_back(A[l]);
			else dat[k].push_back(1LL << 60);
		}
		else {
			int lch = k * 2 + 1, rch = k * 2 + 2;
			init(lch, l, (l + r) / 2, A, N);
			init(rch, (l + r) / 2, r, A, N);
			dat[k].resize(r - l);
			merge(dat[lch].begin(), dat[lch].end(), dat[rch].begin(), dat[rch].end(), dat[k].begin());
		}
	}
	int query(int i, int j, LL x, int k, int l, int r) {
		if (j <= l || r <= i) return 0;
		if (i <= l && r <= j) {
			return upper_bound(dat[k].begin(), dat[k].end(), x) - dat[k].begin();
		}
		int lc = query(i, j, x, k * 2 + 1, l, (l + r) / 2);
		int rc = query(i, j, x, k * 2 + 2, (l + r) / 2, r);
		return lc + rc;
	}
};
LL A[200000];
SegTree s;
