//////
 ll dac(int a,int b,ll K)
 {
	if(a==b) 
	{
		if(tab[a]>=K) return 1;
		return 0;
	}

	int v;
	v=(a+b)/2;
	ll wn,sm;
	wn=dac(a,v,K);
	wn+=dac(v+1,b,K);

	vector<ll> srt;
	sm=0;

	for(int i=v;i>=a;i--)
	{
		sm+=tab[i];
		srt.push_back(sm-K*(v-i+1));
	}		

	sort(srt.begin(),srt.end());

	sm=0;
	for(int i=v+1;i<=b;i++)
	{
		sm+=tab[i];
		auto z=lower_bound(srt.begin(),srt.end(),(i-v)*K-sm);
		wn+=distance(z,srt.end());
	}

	return wn;
 }

