inline void inserttree(long long l,long long r,long long x,int& node)
{
	if (! node)
		sum_node++,node=sum_node;
	if (l==r)
		tree[node].num++;
	else
	{
		long long mid=(l+r+2*inf)/2-inf;
		if (x<=mid)
			inserttree(l,mid,x,tree[node].left);
		else
			inserttree(mid+1,r,x,tree[node].right);
		tree[node].num=tree[tree[node].left].num+tree[tree[node].right].num;
	}
	return;
}

inline int asktree(long long l,long long r,long long x,long long y,int node)
{
	if (! node)
		return 0;
	if ((l==x) && (r==y))
		return tree[node].num;
	long long mid=(l+r+2*inf)/2-inf;
	if (y<=mid)
		return asktree(l,mid,x,y,tree[node].left);
	if (x>mid)
		return asktree(mid+1,r,x,y,tree[node].right);
	return asktree(l,mid,x,mid,tree[node].left)+asktree(mid+1,r,mid+1,y,tree[node].right);
}

