struct SegTree {
  ll n_count;
  vector<ll> pos;

  SegTree(const ll N) {
    n_count = 1; while(n_count<N) n_count<<=1;
    pos.assign(2*n_count, 0);
    build();
  }

  ll operator[](const ll &k) const { return pos[k+n_count]; }

  void set(ll k, const ll x) { pos[k+n_count] = x; }
  void build() { for (ll i=n_count-1; i>0; i--) pos[i] = pos[i*2]+pos[i*2+1]; }
  void update(ll k, const ll x) { set(k,x); k += n_count; while(k >>= 1) pos[k] = pos[k*2]+pos[k*2+1]; }
  ll query(ll a,ll b) {
    ll L = 0, R = 0;
    for ( a+=n_count, b+=n_count; a<b; a>>=1, b>>=1 ) {
      if (a&1) { L+=pos[a]; a++; }
      if (b&1) { b--; R+=pos[b]; }
    }
    return L + R;
  }

};

int main() {
  ll N, K; cin >> N >> K;
  vector<p_ll> sum; sum.push_back(make_pair(0,0));
  rep(i,N) {
    ll a; cin >> a; a -= K;
    sum.push_back(make_pair(i+1,sum[i].second+a));
  }
  sort(sum.begin(), sum.end(), [](const p_ll &x, const p_ll &y){return x.second<y.second;});
  rep(i,N+1) sum[i].second = i;
  sort(sum.begin(), sum.end(), [](const p_ll &x, const p_ll &y){return x.first<y.first;});

  SegTree tree(N+1);
  ll result = 0;
  for(auto x: sum) {
    result += tree.query(0,x.second+1);
    tree.update(x.second, 1);
    // rep(j,N+1) cout << tree[j] << " "; cout << endl;
  }
  cout << result << endl;
  return 0;
}

