		}
		v=(l?l->v:0)+(r?r->v:0);
	}
	ll query(ll s, ll e, ll qs, ll qe) {
		ll m = floor(((double)s+e)/2.0);
		if (s==qs&&qe==e) return v;
		if (qs>m) return r?r->query(m+1,e,qs,qe):0;
		else if (qe<=m) return l?l->query(s,m,qs,qe):0;
