struct Node {
    Node *left;
    Node *right;
    // This node contains information for [lo,hi)
    ll lo, hi, v;
    Node(ll lo, ll hi): lo(lo), hi(hi) {
        /*if (lo + 1 == hi) {
            v = d[lo];
            return;
        }
        int mid = (lo + hi) / 2;
        left = new Node(lo, mid);
        right = new Node(mid, hi);
        v = min(left->v, right->v);*/
        left = NULL;
        right = NULL;
        v = 0;
        return;
    }

    // get minimum in [L,R)
    ll query(ll L, ll R) {
        assert(L < R);
        if (hi <= L || R <= lo) return 0ll;
        if (L <= lo && hi <= R) return v;
        if (left == NULL) {
            ll mid = (lo + hi) / 2;
            left = new Node(lo, mid);
            right = new Node(mid, hi);
        }
        return (left->query(L, R) + right->query(L, R));
    }

    // not lazy
    void update(ll L, ll R) {
        assert(L < R);
        if (hi <= L || R <= lo) return;
        if (lo == L && hi == R) {
            v += 1;
            return;
        }
        if (left == NULL) {
            ll mid = (lo + hi) / 2;
            left = new Node(lo, mid);
            right = new Node(mid, hi);
        }
        left->update(L, R);
        right->update(L, R);
        v = left->v + right->v;
    }
};


