// ここで、累積和をsum[i]という配列に入れたとしたとき、「区間和の右側はsum[i]以下であれば全部カウントしてよい」という特徴があります。
// となると、左から見ていき、今まで出てきたsumを記録しておいて、新しいsum[i]に対してsum[i]が何番目に相当するかを調べることが出来れば解けそうです。
// 具体的には、記録した見ている箇所より左の集合の中で、「sum[i]より小さなもの」の個数がそこを左端とする個数です。（右側を探しているので、引くことに注意）
// 私はこれをBitIndexedTree(多分分科会であとでやります）を用いて実装しました。vectorは挿入に実は最悪O(N)かかるので、結構大変なので。
// 他の実装方法もあると思うので、頑張ってみてください。

// Bit Indexed Tree
// 0は使わないので注意。
int bit[200010];
int N;

void init(int n) {
	N = 1;
	while (N <= n)	N <<= 1;
}

void update(int k, int a) {
	while (k < N) {
		bit[k] += a;
		k += k&-k;
	}
}

int getsum(int k) {
	int ret = 0;
	while (k > 0) {
		ret += bit[k];
		k -= k&-k;
	}
	return ret;
}

// 当然ですが、答えはint型に収まらないことがあるので注意

int main() {
	int n, k;	cin >> n >> k;
	vector<ll> a(n);
	rep(i, n) {
		cin >> a[i];	a[i] -= k;
	}
	vector<ll> sum(n + 1);
	SREP(i, 1, n) {
		sum[i] = sum[i - 1] + a[i - 1];
	}
	// bit用にソートした累積和配列を用意
	// aの値そのままでbitをやると死ぬので、座標圧縮をします。
	vector<ll> sorted = sum;
	sort(all(sorted));

	init(n + 1);
	ll ret = 0;
	REP(i, n) {
		// sum[i]の位置を調べます。
		int addidx = lower_bound(all(sorted), sum[i]) - sorted.begin();
		// そこより左の個数をカウント（自身は含めません）
		ret += getsum(addidx + 1);
		// sum[i]を追加します。
		update(addidx + 1, 1);
	}
	cout << ret << endl;
	return 0;
}

