        a[i] -= k;
        sum[i+1] = sum[i] + a[i];
    }

    vector<long long> v = sum;
    sort(v.begin(), v.end());
    v.erase(unique(v.begin(), v.end()), v.end());
    auto idx = [&] (int x) -> int {
        return lower_bound(v.begin(), v.end(), x) - v.begin();
    };

    long long ans = 0;
    BinaryIndexedTree<long long> bit(n+5);
    for (const auto& e : sum) {
        int id = idx(e);
        ans += bit.get(id);
        bit.add(id, 1);
    }
    cout << ans << endl;
    return 0;
}

