struct BIT // 0-indexed
{
    ll n;
    vector<ll> bit;
    // 初期化
    void init(ll n_input)
    {
        n = n_input + 1;
        bit.resize(n + 1, 0);
    }
    // v[0] + ... + v[k-1]
    ll sum(ll k)
    {
        ll res = 0;
        for (ll i = k - 1; i >= 0; i = (i & (i + 1)) - 1)
        {
            res += bit[i];
        }
        return res;
    }
    // v[i] + ... + v[j]
    ll sum_between(ll i, ll j)
    {
        return i <= j ? sum(j + 1) - sum(i) : 0;
    }
    // v[k] += x
    void add(ll k, ll x)
    {
        for (ll i = k; i < n; i |= i + 1)
        {
            bit[i] += x;
        }
    }
};

