ll mergeCount(vector<pair<ll, ll>>& A, ll l, ll c, ll r)
{
    ll count = 0;
    vector<pair<ll, ll>> B(r - l + 1);
    ll j = 0;
    ll i1 = l;
    ll i2 = c + 1;
    while (i1 <= c || i2 <= r){
        if (r < i2 || (i1 <= c && A[i1].second <= A[i2].second)){
            B[j].second = A[i1].second;
            ++i1;
        }else{ // i2 <= r && (c < i1 || A[i2].second < A[i1].second)
            count += c - i1 + 1;
            B[j].second = A[i2].second;
            ++i2;
        }
        ++j;
    }
    for (ll j = 0; j < B.size(); ++j){
        A[l + j].second = B[j].second;
    }
    return count;
}

ll mcount(vector<pair<ll, ll>>& A, ll l, ll r)
{
    if (r <= l) return 0;
    const ll c = l + (r - l) / 2;
    return mcount(A, l, c) + mcount(A, c + 1, r) + mergeCount(A, l, c, r);
}

