      }
      else
      {
            int tm = (tl + tr) >> 1;
            if(pos <= tm)
                  update(pos, x, v << 1, tl, tm);
            else
                  update(pos, x, (v << 1) | 1, tm + 1, tr);
            t[v] = t[v << 1] + t[(v << 1) | 1];
