long long bubblecount(vector<long long> a){
    long long result = 0;
    vector<long long> sorted;
    copy(a.begin(),a.end(),back_inserter(sorted));
    sort(sorted.begin(),sorted.end());
    BIT bit(a.size());
    for(int i = 0;i < a.size();i++){
        int index = lower_bound(sorted.begin(),sorted.end(),a[i]) - sorted.begin() + 1;
        result += bit.sum(index);
        bit.add(index,1);
    }
    return result;
}

