int64 ans;
int64 tmp[MAXN];
void merge_sort(int l, int r) {
    if (l == r) return;
    int mid = (l + r) >> 1;
    merge_sort(l, mid);
    merge_sort(mid + 1, r);
    int i = l, j = mid + 1;
    int k = l;
    while (i <= mid && j <= r) {
        if (v[i] <= v[j]) {
            tmp[k++] = v[i++];
            ans += r - j + 1;
        } else {
            tmp[k++] = v[j++];
        }
    }
    while (i <= mid) {
        tmp[k++] = v[i++];
    }
    while (j <= r) {
        tmp[k++] = v[j++];
    }
    for (int i = l; i <= r; i++) {
        v[i] = tmp[i];
    }
}

