struct BinaryIndexedTree{
    private:
    vector<int> dat;
    public:
    BinaryIndexedTree(int n_){
        dat.resize(++n_,0);
    }
    void add(int a,int w){
        for (int i=a;i<=dat.size();i+=i&-i) dat[i]+=w;
    }
    int sum(int a){
        int res=0;
        for (int i=a;i>0;i-=i&-i) res+=dat[i];
        return res;
    }
    int binarysearch(int w){
        if (w<=0) return 0;
        int x=0,n=dat.size();
        for (int k=n;k>0;k/=2){
            if (x+k<=n&&dat[x+k]<w){
                w-=dat[x+k];
                x+=k;
            }
        }
        return x;
    }
};

