#define MAXN (200006)
ll n, k, A[MAXN];
struct node {
	pi key;
	ll prior, sz;
	node *l, *r;
}; typedef node* pnode;
void init(pnode &t,pi key) {
	t->key=key;
	t->prior=rand(0, 1e18);
	t->sz=1;
	t->l=t->r=0;
}
ll cnt(pnode t) {
	return t?t->sz:0;
}
void insert(pnode &t, pnode k) {
	if(!t) return void(t=k);
	if(t->prior > k->prior) {
		if(t->key > k->key) insert(t->l, k);
		else insert(t->r, k);
	} else {
		if(t->key > k->key) k->r = t, t=k;
		else k->l = t, t=k;
	}
	t->sz = cnt(t->l) + cnt(t->r) + 1;
}
ll query(pnode t, pi key) {
	if(!t) return 0;
	if(t->key <= key) {
		return cnt(t->l) + 1 + query(t->r, key);
	} else {
		return query(t->l, key);
	}
}
