int mergesort(int a, int b) {
    int l = b - a;
    if (l == 0) return 0;

    int m = (a+b)/2;
    int res = mergesort(a, m) + mergesort(m + 1, b);

    int p = a;
    int q = m+1;
    int r = a;

    //cerr << a << " " << b << " " << res << "\n";
    while (p <= m && q <= b) {
        if (s[p] <= s[q]) {
            buf[r++] = s[p++];
        } else {
            buf[r++] = s[q++];
            res += m - p + 1;
        }
    }

    //cerr << a << " " << b << " " << res << "\n";
    while (p <= m) buf[r++] = s[p++];
    while (q <= b) buf[r++] = s[q++];

    for (int i = a; i <= b; i++) s[i] = buf[i];
    return res;
}


