	mergesort(b, lo, mid);
	mergesort(b, mid + 1, hi);
	vector <ll> temp;
	int i = lo, j = mid + 1;
	while (i <= mid && j <= hi) {
        if (b[i] <= b[j]) { // big to small
			temp.push_back(b[j++]);
