//
// O(n log n)
ll countLR(vll a) {
    ll n = a.size();
    vector<P> ai(n);
    rep(i, n) {
        ai[i] = P(a[i], i);
    }
    sort(all(ai));

    fenwick_tree<ll> c(n);
    ll ret = 0;
    rep(i, n) {
        (ret += c.query(ai[i].se-1));
        c.update(ai[i].se, 1);
    }

    return ret;
}

