            int lb = 0, ub = n;
            while (ub - lb > 1) {
                int mid = (lb + ub) / 2;
                if (a[i] > b[mid]) lb = mid;
                else ub = mid;
            }
            r[i] = ub + 1;
        }
    }
    long long bit[200002] = {};
    long long ans = 0;
    for (int i = 0; i <= n; i++) {
        for (int j = r[i]; j > 0; j -= j&-j) ans += bit[j];
        for (int j = r[i]; j <= n; j += j&-j) bit[j]++;
    }
    cout << ans << endl;
}

