const int N=2e5+5;
int n;ll m,a[N]={0},tree[20][N],as[N];
int num[20][N];
void build(int c,int lef,int rig) {
    int mid=(lef+rig)>>1,left_num=mid-lef+1,l=lef,r=mid+1;
    for(int i=lef;i<=rig;i++) if(tree[c][i]<as[mid]) left_num--;
    for(int i=lef;i<=rig;i++) {
        num[c][i]=num[c][i-1];
        if(i==lef) num[c][i]=0;
        if(tree[c][i]==as[mid]) {
            if(left_num) left_num--,num[c][i]++,tree[c+1][l++]=tree[c][i];
            else tree[c+1][r++]=tree[c][i];
        }
        else if(tree[c][i]<as[mid]) tree[c+1][l++]=tree[c][i],num[c][i]++;
        else tree[c+1][r++]=tree[c][i];
    }
    if(lef==rig) return;
    build(c+1,lef,mid);build(c+1,mid+1,rig);
}
ll query(int c,int lef,int rig,int ql,int qr,int k) {
    int s,ss,mid=(lef+rig)>>1;//s为ql--qr区间进入左子树的个数，ss为lef--ql-1区间进入左子树的个数
    int b,bb;//b为lef--qr-1区间进入右子树的个数，bb为ql--qr区间进入右子树的个数
    if(ql==lef) s=num[c][qr],ss=0;
    else s=num[c][qr]-num[c][ql-1],ss=num[c][ql-1];
    if(lef==rig) return tree[c][lef];
    if(s>=k) {
        ql=lef+ss;qr=ql+s-1;
        return query(c+1,lef,mid,ql,qr,k);
    }
    else {
        b=ql-lef-ss;
        bb=qr-ql+1-s;
        ql=mid+b+1;//需要忽略lef--ql-1区间中进入右子树的数
        qr=ql+bb-1;
        return query(c+1,mid+1,rig,ql,qr,k-s);
    }
}
int main() {
    scanf("%d%lld",&n,&m);
    for(int i=1;i<=n;i++) scanf("%lld",a+i),a[i]-=m,a[i]+=a[i-1],as[i]=a[i];
    for(int i=1;i<=n;i++) tree[0][i]=a[i];
    ll ans=0,cur=0;
    sort(as+1,as+1+n);
    build(0,1,n);
    for(int i=1;i<=n;i++) {
        int l=i,r=n+1,mid;
        while(l<r) {
            mid=((l+r)>>1)-i+1;
            if(query(0,1,n,i,n,mid)<cur) l=mid+i;
            else r=mid+i-1;
        }
        ans+=n+1-r;
        cur=a[i];
    }
    printf("%lld\n",ans);
    return 0;
}

