class Normalizator
{
public:
    vector<LL> ord;
    unordered_map<LL, int> mp;

    void add(LL x)
    {
        if(mp.count(x)) return;
        mp[x];
        ord.push_back(x);
    }

    void normalize()
    {
        sort(ord.begin(), ord.end());
        for(int i = 0; i < ord.size(); i++)
            mp[ ord[i] ] = i + 1;
    }

    int get(LL x) { return mp[x]; }
}nrm;

class BinaryIndexedTree
{
public:
    int N;
    int aib[NMAX];

    void init(int _N) { N = _N; }

    void U(int pos, int val)
    {
        for(; pos <= N; pos += (pos & (-pos)))
            aib[pos] += val;
    }

    int Q(int pos)
    {
        int ans = 0;
        for(; pos > 0; pos -= (pos & (-pos)))
            ans += aib[pos];
        return ans;
    }
}aib;

