typedef long long int LL;

const LL inf = 1123456789012345;

// min
class SegmentTree1
{
private:
	LL n;
	std::vector<LL>node;

public:
	void init(LL size)
	{
		n = 1;
		while (n < size) n *= 2;
		node.resize(2 * n - 1, inf);
	}

	// node[i] += x 
	void update(LL i, LL x)
	{
		i += n - 1;
		node[i] = x;
		while (i > 0)
		{
			i = (i - 1) / 2;
			node[i] = std::min(node[2 * i + 1], node[2 * i + 2]);
		}
	}

	// min([a, b))
	// ex.) [0, N - 1] == [0, N)
	LL get_min(LL a, LL b, LL k = 0, LL l = 0, LL r = -1)
	{
		if (r < 0) r = n;
		if (r <= a || b <= l) return inf;
		if (a <= l && r <= b) return node[k];
		LL vl = get_min(a, b, 2 * k + 1, l, (l + r) / 2);
		LL vr = get_min(a, b, 2 * k + 2, (l + r) / 2, r);
		return std::min(vl, vr);
	}
};

// max
class SegmentTree2
{
private:
	LL n;
	std::vector<LL>node;

public:
	void init(LL size)
	{
		n = 1;
		while (n < size) n *= 2;
		node.resize(2 * n - 1, -inf);
	}

	// node[i] += x 
	void update(LL i, LL x)
	{
		i += n - 1;
		node[i] = x;
		while (i > 0)
		{
			i = (i - 1) / 2;
			node[i] = std::max(node[2 * i + 1], node[2 * i + 2]);
		}
	}

	// max([a, b))
	// ex.) [0, N - 1] == [0, N)
	LL get_max(LL a, LL b, LL k = 0, LL l = 0, LL r = -1)
	{
		if (r < 0) r = n;
		if (r <= a || b <= l) return -inf;
		if (a <= l && r <= b) return node[k];
		LL vl = get_max(a, b, 2 * k + 1, l, (l + r) / 2);
		LL vr = get_max(a, b, 2 * k + 2, (l + r) / 2, r);
		return std::max(vl, vr);
	}
};

SegmentTree1 minTree;
SegmentTree2 maxTree;

// [l, r)
LL cnt(LL l, LL r, LL x)
{
	LL min = minTree.get_min(l, r), max = maxTree.get_max(l, r);
	if (min >= x) return r - l;
	if (max < x) return 0;
	return cnt(l, (l + r) / 2, x) + cnt((l + r) / 2, r, x);
}

int main()
{
	LL N, K;
	in >> N >> K;
	std::vector<LL>a(N);
	rep(i, N) in >> a[i];

	std::vector<LL>a_imos(N + 1);
	minTree.init(N + 1); maxTree.init(N + 1);
	rep(i, N)
	{
		a[i] -= K;
		a_imos[i + 1] = a_imos[i] + a[i];
		minTree.update(i + 1, a_imos[i + 1]);
		maxTree.update(i + 1, a_imos[i + 1]);
	}

	LL ans = 0;
	for (LL i = 1; i <= N; ++i) ans += cnt(i, N + 1, a_imos[i - 1]);
	out << ans << std::endl;
}

