template <typename T>
struct BinaryIndexedTree {
    int n;
    vector<T> d;

    BinaryIndexedTree(int n): n(n), d(n + 1, 0) {}

    // a[1] + ... + a[k]
    T sum(int k)
    {
        T r = 0;
        while (k > 0) {
            r += d[k];
            k -= k & -k;
        }
        return r;
    }

    // a[l] + ... + a[r]
    T sum(int l, int r)
    {
        return sum(r) - sum(l - 1);
    }

    // a[k] += x
    void add(int k, T x)
    {
        while (k <= n) {
            d[k] += x;
            k += k & -k;
        }
    }
};
