struct Compress {
    map<int, int> zip;
    vector<int> unzip;

    Compress() {}

    Compress(vector<int> v)
    {
        sort(v.begin(), v.end());
        v.erase(unique(v.begin(), v.end()), v.end());
        for (int i = 0; i < v.size(); ++i) {
            zip[v[i]] = i;
            unzip.push_back(v[i]);
        }
    }

    int size() {
        return unzip.size();
    }
};

