#include <bits/stdc++.h>
using namespace std;

int N, K;

int lowbit(int x) {
    return x & (-x);
}

long long compute(const vector<long long>& a) {
    int n = a.size();
    vector<long long> b ( a );
    sort(b.begin(), b.end());
    b.erase(unique(b.begin(), b.end()), b.end());
    unordered_map<long long, int> dic;
    for (int i = 0; i < b.size(); ++ i) {
        dic[b[i]] = i + 1;
    }

    long long res = 0;
    vector<int> count(b.size() + 1, 0);
    for (auto val : a) {
        int index = dic[val];
        while (index > 0) {
            res += count[index];
            index -= lowbit(index);
        }
        index = dic[val];
        while (index <= b.size()) {
            count[index] ++;
            index += lowbit(index);
        }
    }
    return res;
}

int main()
{
    cin >> N >> K;
    int x;
    vector<int> a;
    for (int i = 0; i < N; ++ i) {
        cin >> x;
        a.push_back(x);
    }
    vector<long long> b(a.size() + 1, 0);
    long long sum = a[0];
    for (int j = 1; j <= N; ++ j) {
        b[j] = sum - j * 1LL * K ;
        sum += a[j];
    }
    cout << compute(b) << endl;
    return 0;
}

