struct BIT
{
    int n;
    vector<T> bit;

    BIT(){}

    BIT(int n) : n(n){
        bit.resize(n + 1);
    }

    T sum(int i){
        i++;
        T res = 0;
        while(i){
            res += bit[i];
            i -= (i & -i);
