class Segtree {
  vector<int> tree;
  int n;
 public:
  Segtree(const int len) {
    n = len;
    tree = vector<int>(2 * n, 0);
  }

  void update(int pos, int val) {
    pos += n;
    tree[pos] = val;
    int par = pos / 2;
    while (par > 0) {
      tree[par] = tree[par * 2] + tree[par * 2 + 1];
      par /= 2;
    }
  }

  int query(int l, int r) {
    l += n;
    r += n;
    int ret = 0;
    while (l <= r) {
      if (l & 1) {
        ret +=tree[l];
        l++;
      }
      if ((r & 1) == 0) {
        ret += tree[r];
        r--;
      }
      l /= 2;
      r /= 2;
    }
    return ret;
  }
};
