    sort(v.begin(), v.end());
    v.erase(unique(v.begin(), v.end()), v.end());

    BinaryIndexTree bit(v.size() + 5);
    ll ans = 0;
    bit.add((lower_bound(v.begin(), v.end(), 0) - v.begin()) + 1, 1);
    s = 0;
    REP(i, N) {
        s += A[i];
        ll n = s - K * (i + 1);
        ll index = lower_bound(v.begin(), v.end(), n) - v.begin();

        ans += bit.sum(index + 1);
        bit.add(index + 1, 1);
    }
    cout << ans << endl;
    return 0;
}

