map<ll, ll> hsh;
ll temp[200005];
set<ll> num;
ll bit[200005];
ll freq[200005];
ll query (ll i) {
	return ((i == 0) ? 0 : bit[i] + query(i - (i & (-i))));
}
void update (ll i, ll v) {
	if (i > 200001) return;
	bit[i] += v;
	update(i + (i & (-i)), v);
	return;
}
int main () {
	ll a, b, c, d, e, f, g, h, i, j, k, l, m, n, o, p, q;
	scanf("%lld %lld", &a, &b);
	psum[0] = temp[0] = 0;
	for (i = 1; i <= a; i++) {
		scanf("%lld", &psum[i]);
		psum[i] += psum[i - 1] - b;
		temp[i] = psum[i];
	}
	stable_sort(temp, temp + a + 1);
	hsh[temp[0]] = c = 1;
	for (i = 1; i <= a; i++) {
		if (temp[i] != temp[i - 1]) hsh[temp[i]] = ++c;
		else hsh[temp[i]] = c;
	}
	hsh[1e18] = ++c;
	SET(bit, 0); SET(freq, 0);
	num.insert(0); update(hsh[0], 1); freq[hsh[0]] = 1;
	num.insert(1e18); update(c, 1); freq[c] = 1;
	d = 0; 
	for (i = 1; i <= a; i++) {
		auto r = num.upper_bound(psum[i]);
		e = hsh[*r];
		d += max(query(e) - freq[e], 0LL);
		f = hsh[psum[i]];
		update(f, 1); freq[f]++;
		num.insert(psum[i]);
	}
	printf("%lld\n", d);
	return 0;
}

