int get(int v, int tl, int tr, int l, int r) {
    if (r < tl || tr < l) return 0;
    if (l <= tl && tr <= r) return t[v];
    int tm = (tl + tr) >> 1;
    return get(v + v, tl, tm, l, r) + get(v + v + 1, tm + 1, tr, l, r);
}                                         

void upd(int v, int tl, int tr, int pos) {
    if (tl == tr) {
        t[v]++;
        return;
    }
    int tm = (tl + tr) >> 1;
    if (pos <= tm) {
        upd(v + v, tl, tm, pos);
    }
    else {
        upd(v + v + 1, tm + 1, tr, pos);
    }
    t[v] = t[v + v] + t[v + v + 1];
}

