class myset{
    using u64=uint_fast64_t;
    u64 mx=1ULL<<60;
    unordered_map<u64,int>bit;
    int sz=0;
    lint sum(u64 x){
        lint res=0;
        for(u64 i=x;i;i-=i&-i)res+=bit[i];
        return res;
    }
    u64 sum(u64 x,u64 y){
        return sum(y)-sum(x);
    }
    void add(u64 x,int val){
        for(u64 i=x+1;i<=mx;i+=i&-i)bit[i]+=val;
    }
    int lower_bound(int w){
        assert(0<=w&&w<sz);
        if(w<=0)return 0;
        int x=0;
        for(u64 k=1ULL<<int(log2(w));k;k/=2){
            if (x+k<=mx&&bit[x+k]<w) {
                w-=bit[x+k];
                x+=k;
            }
        }
        return x+1;
    }
    public:
    inline void insert(u64 x){add(x,1);sz++;}
    inline bool erase(u64 x){
        bool b=sum(x+1)-sum(x);
        if(b)add(x,-1),sz--;
        return b;
    }
    inline int lower_bound(u64 x){return sum(x);}
	inline int upper_bound(u64 x){return sum(x+1);}
    inline int count(u64 x){return sum(x+1)-sum(x);}
	inline int size(){return sz;}
	inline u64 operator[](int idx){return lower_bound(idx);}
};

