class BIT{
public:
  vector <ll> bit;
  const int n;
  BIT(int N): bit(N,0),n(N){};
  void add(int i, ll v){
    for(; i < n; i |= i + 1){
      bit[i] += v;
    }
  }

  ll sum(int i) {//sum [0,i)
    ll res = 0;
    --i;
    for (; i >= 0; i = (i & (i+1)) - 1) {
      res += bit[i];
    }
    return res;
  }

  ll sum(int a, int b) { // sum [a,b)
    return sum(b) - sum(a);
  }

  ll get(int a) {//a番目の値を見る
    return sum(a+1) - sum(a);
  }

  void setv(int i, ll v) {//i番目の値をvにする
    add(i, v - get(i));
  }
};
