// {{{ fenwick
template <class Group>
class fenwick {
  public:
    using value_type = typename Group::value_type;
  private:
    int len;
    vector<value_type> data;
  public:
    fenwick(int n): len(n + 1), data(len, Group::identity) {}
    value_type product(int k) const { // excluding k
      value_type total = Group::identity;
      for (int i = k; i > 0; i -= i & -i) {
        total = Group::product(ix(data, i), total);
      }
      return total;
    }
    void multiply(int pos, value_type x) {
      pos++;
      for (int i = pos; i < len; i += i & -i) {
        ix(data, i) = Group::product(ix(data, i), x);
      }
    }
};
