struct Z_add {
  using value_type = Z;
  static constexpr Z identity = 0;
  static inline constexpr Z product(Z x, Z y) {
    return x + y;
  }
};



int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  cout.precision(10);
  cout << fixed;
  Z N, K;
  cin >> N >> K;
  vector<Z> as(N);
  cin >> as;
  vector<Z> ps(N + 1);
  for (auto i = N - 1; i >= 0; i--) {
    ix(ps, i) = ix(ps, i + 1) + ix(as, i);
  }
  set<Z> vals;
  for (auto i = 0; i <= N; i++) {
    vals.insert(ix(ps, i) + K * i);
  }
  map<Z, Z> compressed;
  Z next_unused = 0;
  for (auto&& v : vals) {
    compressed[v] = next_unused;
    next_unused++;
  }
  fenwick<Z_add> fwt(vals.size() + 1);
  Z ans = 0;
  for (auto i = 0; i <= N; i++) {
    Z v = ix(ps, i) + K * i;
    ans += fwt.product(compressed[v] + 1);
    fwt.multiply(0, 1);
    fwt.multiply(compressed[v] + 1, -1);
  }
  cout << ans << '\n';
}

