	if (tl == tr) {
		t[v] += 1;
		return;
	}
	int tm = (tl + tr) / 2;
	if (pos <= tm) {
		incr(v * 2, tl, tm, pos);
	}
	else {
		incr(v * 2 + 1, tm + 1, tr, pos);
	}
	t[v] = t[v * 2] + t[v * 2 + 1];
}
int get_sum(int v, int tl, int tr, int l, int r) {
	if (tl > r || l > tr) return 0;
	if (tl >= l && tr <= r) return t[v];
	int tm = (tl + tr) / 2;
	return get_sum(v * 2, tl, tm, l, r) + get_sum(v * 2 + 1, tm + 1, tr, l, r);
}
