    }

    vector<ll> b(N + 1, 0);
    for (ll i = 0; i <= N; i++) {
        b[i] = a[i] - i * K;
    }

    auto compressed = compress(b);
    int n = compressed.size();

    SegmentTree st(vector<int>(n, 0), 0);
    ll ans = 0;
    for (int i = 0; i <= N; i++) {
        int idx = compressed[b[i]];
        ans += st.query(0, idx + 1);
        int cur = st.query(idx, idx + 1);
        st.update(idx, cur + 1);
    }

