int _main()
{
        ll n, k;
        llin(n); llin(k);

        V<ll> alist;
        llinl1(alist, n);

        rep (i, n) alist[i] -= k;

        V<t2> sumidxlist;   // (sum, idx)
        ll sum = 0LL;
        rep (i, n) {
                sum += alist[i];
                sumidxlist.pb(t2(sum, i));
        }
        sort_reverse(sumidxlist);

        int idx_to_sumidx[n+1];
        rep (sumidx, n) {
                ll idx = get<1>(sumidxlist[sumidx]);
                idx_to_sumidx[idx] = sumidx;
        }

        V<ll> borderlist;
        sum = 0LL;
        rep (i, n) {
                borderlist.pb(sum);
                sum += alist[i];
        }

        BIT bitree(n, 1LL);
        ll ans = 0LL;

        rep (i, n) {
                ll border = borderlist[i];
                int good_sumidx = -1;

                int left = 0;
                int right = n-1;
                int sumidx = (left + right) / 2;
                for ( ; left <= right; sumidx = (left + right) / 2) {
                        ll sum = get<0>(sumidxlist[sumidx]);
                        if (sum < border) {
                                right = sumidx - 1;
                        }
                        else {
                                good_sumidx = max(good_sumidx, sumidx);
                                left = sumidx + 1;
                        }
                }

                if (good_sumidx >= 0) {
                        // BIT idx is 1 origin
                        ans += bitree.sum(good_sumidx + 1);
                }

                // BIT idx is 1 origin
                bitree.add(idx_to_sumidx[i] + 1, -1LL);
        }

        cout << ans;

        return 0;
}

