class Segment_Tree{
	private:
	int n;
	vi date;
	int Query_func(int a,int b,int k,int l,int r){
		if(r<=a||b<=l) return 0;
		if(a<=l&&r<=b) return date[k];
		int m=(l+r)/2;
		return Query_func(a,b,k*2+1,l,m)+Query_func(a,b,k*2+2,m,r);
	}
	public:
	Segment_Tree(int n_){
		n=1;
		while(n<n_) n*=2;
		date=vi(2*n-1);
	}
	void Update(int k){
		k+=n-1;
		date[k]++;
		while(k>0){
			k=(k-1)/2;
			date[k]=date[k*2+1]+date[k*2+2];
		}
	}
	int Query(int a){
		return Query_func(a,n,0,0,n);
	}
	int Open(int k){
		return date[k+n-1];
	}
};

