using namespace std;

struct Node{
    LL key;
    Node *left;
    Node *right;
    LL size;
    Node(LL key){
        this->key = key;
        this->size = 1;
        this->left = this->right = NULL;
    }
    int size_of_children(){
        return (left==NULL ? 0 : left->size) + (right==NULL ? 0 : right->size);
    }
};

Node* merge(Node *a, Node *b){
    if(a==NULL && b==NULL)return NULL;
    if(a==NULL)return b;
    if(b==NULL)return a;
    if(a->size*RAND_MAX <= rand()*(a->size + b->size)){
        a->size += b->size;
        if(a->key < b->key)a->right = merge(a->right, b);
        else a->left = merge(a->left, b);
        return a;
    }else{
        b->size += a->size;
        if(b->key < a->key)b->right = merge(b->right, a);
        else b->left = merge(b->left, a);
        return b;
    }
}

Node* find(Node *n, LL k){
    if(n==NULL)return NULL;
    if(k==n->key)return n;
    if(k<=n->key)return find(n->left, k);
    else return find(n->right, k);
}

Node* _erase(Node *n, LL k){
    if(n==NULL)return NULL;
    if(k==n->key){
        return merge(n->left, n->right);
    }
    if(k<=n->key){
        n->left = _erase(n->left, k);
        n->size = 1 + n->size_of_children();
    }
    else{
        n->right = _erase(n->right, k);
        n->size = 1 + n->size_of_children();
    }
    return n;
}

Node *lower_bound(Node *n, LL k){
    if(n==NULL)return NULL;
    if(k==n->key)return n;
    if(k<=n->key){
        Node *x = find(n->left, k);
        return x==NULL ? n : x;
    }else return NULL;
}

struct ZipTree{
    Node *root;
    ZipTree(){
        this->root = NULL;
    }
    void insert(LL k){
        Node *x = new Node(k);
        this->root = merge(this->root, x);
    }
    void erase(LL k){
        this->root = _erase(this->root, k);
        // cerr << "new root: " << this->root << endl;
    }
    int rank(LL k){
        Node *x = lower_bound(this->root, k);
        if(x==NULL)return 0;
        int res = x->size - (x->right==NULL ? 0 : x->right->size);
        return res;
    }
    void _print(Node *n){
        if(n==NULL)return;
        _print(n->left);
        cerr << n->key << " " ;
        _print(n->right);
    }
    void print(){
        cerr << "print nodes..." << endl;
        _print(this->root);
        cerr << endl;
    }
};



