struct Node {
    int x, y, sz, pl;
    Node* L;
    Node* R;

    Node(int x) : x(x), y(rand()), sz(1), L(NULL), R(NULL), pl(0) {}
};

const int MAX_N = 2e5 + 10;

int n;
long long k;
long long a[MAX_N];

void rec(Node* v) {
    if (v == NULL) {
        return;
    }
    v->sz = 1 + v->pl;
    if (v->L != NULL) {
        v->sz += v->L->sz;
    }
    if (v->R != NULL) {
        v->sz += v->R->sz;
    }
}

pair<Node*, Node*> split(Node* v, int k) {
    if (v == NULL) {
        return {NULL, NULL};
    }
    if (k > v->x) {
        auto p = split(v->R, k);
        v->R = p.first;
        rec(v);
        return {v, p.second};
    }
    auto p = split(v->L, k);
    v->L = p.second;
    rec(v);
    return {p.first, v};
}

Node* merge(Node* v, Node* u) {
    if (u == NULL) {
        return v;
    }
    if (v == NULL) {
        return u;
    }
    if (v->y > u->y) {
        v->R = merge(v->R, u);
        rec(v);
        return v;
    }
    u->L = merge(v, u->L);
    rec(u);
    return u;
}

Node* insert(Node* v, int x) {
    auto p = split(v, x);
    Node* ans = merge(p.first, new Node(x));
    rec(ans);
    ans = merge(ans, p.second);
    rec(ans);
    return ans;
}

bool inc(Node* v, int x) {
    if (v == NULL) {
        return 0;
    }
    if (x == v->x) {
        v->pl++;
        rec(v);
        return 1;
    }
    if (x < v->x) {
        bool ans = inc(v->L, x);
        rec(v);
        return ans;
    }
    bool ans = inc(v->R, x);
    rec(v);
    return ans;
}

