    REP(i, N) {
        now += A[i];
        sums.PB(now - (i + 1) * K);
    }

    map<LL, int> za = zaatu(sums);
    BIT<LL> bit(N + 1);
    LL ans = 0;
    REP(i, N + 1) {
        //cout << i << " " << sums[i] << " " << za[sums[i]] << " " << i - bit.sum(za[sums[i]]) << endl;
        ans += i - bit.sum(za[sums[i]]);
        bit.add(za[sums[i]], 1);
    }
    cout << (LL)(N + 1) * N / 2 - ans << endl;
    return 0;
}

