namespace BIT{
	ll c[MAXN];
	inline int lowbit( int x ){ return x&-x; }
	inline void add( int pos, int x ){
		for( int i = pos; i <= Index; i += lowbit(i) )
			c[i] += x;
	}
	inline ll query( int pos ){
		ll ret = 0;
		for( int i = pos; i; i -= lowbit(i) )
			ret += c[i];
		return ret;
	}
}

namespace Discrete{
	int pcnt; ll *ptr[MAXN];
	inline bool cmp( ll *a, ll *b ){
		return *a < *b;
	}
	inline void insert( ll *p ){
		ptr[++pcnt] = p;
	}
	inline void init(){
		sort( ptr+1, ptr+pcnt+1, cmp );
		Index = 1; ll last = *ptr[1];
		for( int i = 1; i <= pcnt; ++i ){
			if( last == *ptr[i] ) *ptr[i] = Index;
			else last = *ptr[i], *ptr[i] = ++Index;
		}
	}
}

