ll tot,root;
void update(ll x){size[x]=size[son[x][0]]+size[son[x][1]]+num[x];}
void rotate(ll x)
{
    ll y=fa[x],z=fa[y],t=(son[y][0]==x);
    fa[y]=x;fa[x]=z;
    if(z) son[z][son[z][1]==y]=x;
    son[y][!t]=son[x][t];fa[son[x][t]]=y;
    son[x][t]=y;
    update(x);update(y);
}
void splay(ll x,ll f)
{
    while(fa[x]!=f)
    {
        ll y=fa[x],z=fa[y];
        if(z!=f)
        {
            if(son[y][0]==x^son[z][0]==y)rotate(x);
            else                        rotate(y);
        }
        rotate(x);
    }
    if(!f)root=x;
}
void insert(ll &x,ll val,ll f)
{
    if(!x)
    {
        x=++tot;
        fa[x]=f;
        son[x][0]=son[x][1]=0;
        w[x]=val;
        size[x]=num[x]=1;
        splay(x,0);
        return;
    }
    if(val==w[x]){size[x]++;num[x]++;splay(x,0);return;}
    insert(son[x][val>w[x]],val,x);
    update(x);
}
ll get(ll val)
{
    ll x=root;
    while(x&&w[x]!=val)x=son[x][val>w[x]];
    return x;
}
void delet(ll w)
{
    ll x=get(w);if(!x)return;
    splay(x,0);
    if(num[x]>1){num[x]--;size[x]--;return;}
    if(!son[x][0]||!son[x][1])root=son[x][0]+son[x][1];
    else
    {
        ll y=son[x][1];while(son[y][0])y=son[y][0];
        splay(y,x);
        fa[son[x][0]]=y;
        son[y][0]=son[x][0];
        root=y;
        son[x][0]=son[x][1]=0;
    }
    fa[root]=0;
    update(root);
}
ll getrank(ll val)
{
    insert(root,val,0);
    ll ans=size[son[root][0]]+num[root]-1;
    delet(val);
    return ans;
}
ll kth(ll k)
{
    ll x=root;
    while(k<=size[son[x][0]]||k>size[son[x][0]]+num[x])
    {
        if(k<=size[son[x][0]]) x=son[x][0];
        else                   k-=size[son[x][0]]+num[x],x=son[x][1];
    }
    return w[x];
}
ll getpre(ll val)
{
    insert(root,val,0);
    ll y=son[root][0];
    while(son[y][1])y=son[y][1];
    delet(val);
    return w[y];
}
ll getne(ll val)
{
    insert(root,val,0);
    ll y=son[root][1];
    while(son[y][0])y=son[y][0];
    delet(val);
    return w[y];
}

