typedef long long ll;

typedef int _loop_int;
#define REP(i,n) for(_loop_int i=0;i<(_loop_int)(n);++i)
#define FOR(i,a,b) for(_loop_int i=(_loop_int)(a);i<(_loop_int)(b);++i)

int n;
ll k;
ll a[252521];

ll sortl[252521], sortr[252521];
ll tmp[252521];

ll solve(int l,int r){
  if(r-l==1){
    sortl[l] = a[l];
    sortr[l] = a[l];
    return (ll)(a[l]>=0);
  }
  int mid = (l+r)/2;
  // divide
  ll ret = solve(l,mid) + solve(mid,r);
  // merge
  int lena = mid-l;
  int lenb = r-mid;
  // conquer
  int tailr = r-1;
  FOR(i,l,mid){
    while(tailr >= mid){
      if(sortl[tailr] + sortr[i] >= 0)tailr--;
      else break;
    }
    ret += (r-1) - tailr;
  }
  // merge sort
  {
    // left
    ll sum = 0;
    FOR(i,l,mid)sum += a[i];
    int headl = l, headr = mid;
    REP(i,r-l){
      if(headl<mid && (headr>=r || sortl[headl] < sum+sortl[headr])){
        tmp[i] = sortl[headl++];
      }else{
        tmp[i] = sum+sortl[headr++];
      }
    }
    REP(i,r-l){
      sortl[l+i] = tmp[i];
    }
  }
  {
    // right
    ll sum = 0;
    FOR(i,l,mid)sum += a[i];
    int headl = l, headr = mid;
    REP(i,r-l){
      if(headl<mid && (headr>=r || sum+sortr[headl] < sortr[headr])){
        tmp[i] = sum+sortr[headl++];
      }else{
        tmp[i] = sortr[headr++];
      }
    }
    REP(i,r-l){
      sortr[l+i] = tmp[i];
    }
  }
  return ret;
}

