using namespace std;
template <typename Mnd>
struct segment_tree
{
    int sz;
    vector<Mnd> data;
    function<Mnd(Mnd, Mnd)> f;
    Mnd e;
    //サイズだけ指定して初期化
    segment_tree(int _sz, function<Mnd(Mnd, Mnd)> _f, Mnd _e) : f(_f), e(_e)
    {
        sz = 1;
        while (sz < _sz)
            sz <<= 1;
        data.assign(sz * 2, e);
    }
    //参照渡しなので代入とかもできる
    Mnd &operator[](const int &k)
    {
        return data[k + sz];
    }
    //木を構築 O(n)
    void build()
    {
        for (int i = sz - 1; i > 0; i--)
            data[i] = f(data[2 * i], data[2 * i + 1]);
    }
    //更新しつつ木を再構築 O(log n)
    void update(int k, Mnd x)
    {
        data[k += sz] = x;
        while (k >>= 1)
            data[k] = f(data[2 * k], data[2 * k + 1]);
    }
    //[a,b)でのクエリに答える　O(log n)
    Mnd query(int a, int b) const
    {
        Mnd l = e, r = e;
        for (a += sz, b += sz; a < b; a >>= 1, b >>= 1)
        {
            if (a & 1)
                l = f(l, data[a++]);
            if (b & 1)
                r = f(r, data[--b]);
        }
        return f(l, r);
    }
};
int main()
{
    ll n, k;
    cin >> n >> k;
    vector<ll> a(n);
    for (size_t i = 0; i < n; i++)
    {
        cin >> a[i];
    }
    vector<ll> r(n + 1, 0), p(n + 1, 0);
    for (size_t i = 0; i < n; i++)
    {
        r[i + 1] = r[i] + a[i];
        p[i + 1] = r[i + 1] - (i + 1) * k; //転倒数(i番目以下でp[i]より小さい要素の数)を求めたい数列
    }
    //座標圧縮,重複要素があることに注意
    vector<ll> b = p;
    map<ll, ll> mp;
    sort(all(b));
    for (int i = 0; i < n + 1; i++)
    {
        if (mp.find(b[i]) == mp.end())
            mp[b[i]] = i;
    }
    //セグ木にぶち込む
    ll ans = 0;
    segment_tree<int> seg(n + 10, [](int a, int b) { return a + b; }, 0);
    seg.build();
    for (int i = 0; i < n + 1; i++)
    {
        ans += seg.query(0, mp[p[i]] + 1); //i番目以下でp[i]より小さい要素の数
        seg.update(mp[p[i]], seg[p[i]] + 1);
    }

    cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
#define ll long long


class BIT{
    public:
    int size;
    vector<int> tree;

    void set(int n){
        size = n;
        tree = vector<int>(n+1, 0);
        return;
    }

    void add(int a, int n) {
        int x = n;
        while (x <= size){
            tree[x] += a;
            x += (x & -x);
        }
        return;
    }

    int sum(int a) {
        int x = a;
        int sum = 0;
        while (x > 0) {
            sum += tree[x];
            x -= (x & -x);
        }
        return sum;
    }

};


int main(){
    int N, K;
    cin >> N >> K;

    vector<ll> a(N);
    for (int i = 0; i < N; i++) cin >> a[i];

    vector<ll> sum(N+1, 0);
    for (int i = 1; i <= N; i++) sum[i] = sum[i-1] + a[i-1] - K;
    vector<ll> t;
    t = sum;
    sort(t.begin(), t.end());
    auto result = unique(t.begin(), t.end());
    t.erase(result, t.end());
    for (int i = 0; i < N+1; i++) {
        sum[i] = distance(t.begin(), lower_bound(t.begin(), t.end(), sum[i]))+1;
    }

    BIT bit;
    bit.set(N+1);
    ll ans = 0;
    for (int i = 0; i < N+1; i++) {
        bit.add(1, sum[i]);
        ans += bit.sum(sum[i]) - 1;
    }
    cout << ans << endl;
}

