const int MAX_N = 200010;

int n, width;
int dat[MAX_N*4];

void init(){
    width = 1;
    while(width<n) width*=2;
    REP(i,2*width-1) dat[i] = 0;
}

void update(int i, int x){
    i += width-1;
    dat[i] = x;
    while (i>0){
        i = (i-1)/2;
        dat[i] = dat[i*2+1] + dat[i*2+2];
    }
}

int query(int a, int b, int k, int l, int r){
    if (r<=a || b<=l) return 0;
    if (a<=l && r<=b) return dat[k];
    int vl = query(a,b,k*2+1,l,(l+r)/2);
    int vr = query(a,b,k*2+2,(l+r)/2,r);
    return vl + vr;
}

int main(){
    ll m, k;
    cin >> m >> k;
    VL a(m);
    REP(i,m){
        scanf("%lld", &a[i]);
        a[i] -= k;
    }

    VL s(m+1);
    REP(i,m){
        s[i+1] = s[i] + a[i];
    }

    vector<pair<ll, ll> > b(m+1);
    REP(i,m+1){
        b[i].first = s[i];
        b[i].second = i;
    }
    sort(ALL(b));

    REP(i,m+1){
        s[b[i].second] = i;
    }

    n = m + 1;
    init();

    ll ans = 0;
    REP(i,m){
        update(s[i], 1);
        ans += query(0, s[i+1], 0, 0, width);
    }
    cout << ans << endl;

    return 0;
}

