const int MAX_N = 200000;

template <typename T>
class BIT{
private:
	vector<T> bit; //[1, n]
public:
	BIT(){
		bit = vector<T>(MAX_N + 1, 0);
	}
	T sum(int i){
		if(i == 0) return 0;
		assert(1 <= i and i <= MAX_N and "invalid argument");
		T s = 0;
		while(i > 0){
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}

	void add(int i, int x){
		assert(1 <= i and i <= MAX_N and "invalid argument");
		while(i <= MAX_N){
			bit[i] += x;
			//bit[i] = max(bit[i], x);
			i += i & - i;
		}
	}
};

