struct node {
	node *lch,*rch;
	int sum;
	node() {
		lch = rch = nullptr;
		sum = 0;
	}
	void modify(ll l,ll r,ll pos) {
		if(l == r)
			sum++;
		else {
			ll mid = (l+r)>>1;
			if(pos <= mid) {
				if(lch == nullptr)	lch = new node();
				lch->modify(l,mid,pos);
			}
			else {
				if(rch == nullptr)	rch = new node();
				rch->modify(mid+1,r,pos);
			}
			sum = (lch == nullptr ? 0 : lch->sum) + (rch == nullptr ? 0 : rch->sum);
		}
	}
	int query(ll l,ll r,ll ql,ll qr) {
		if(l == ql && r == qr)
			return sum;
		else {
			ll mid = (l+r)>>1;
			if(qr <= mid)
				return (lch == nullptr ? 0 : lch->query(l,mid,ql,qr));
			else if(ql > mid)
				return (rch == nullptr ? 0 : rch->query(mid+1,r,ql,qr));
			else
				return (lch == nullptr ? 0 : lch->query(l,mid,ql,mid)) + 
							(rch == nullptr ? 0 : rch->query(mid+1,r,mid+1,qr));
		}
	}
};
