    // get minimum in [L,R)
    ll query(ll L, ll R) {
        assert(L < R);
        if (hi <= L || R <= lo) return 0ll;
        if (L <= lo && hi <= R) return v;
        if (left == NULL) {
            return 0ll;
            ll mid = (lo + hi) / 2;
            left = new Node(lo, mid);
            right = new Node(mid, hi);
        }
        return (left->query(L, R) + right->query(L, R));
    }

    // not lazy
    void update(ll L, ll R) {
        assert(L < R);
        if (hi <= L || R <= lo) return;
        if (lo == L && hi == R) {
            v += 1;
            return;
        }
        if (left == NULL) {
            ll mid = (lo + hi) / 2;
            left = new Node(lo, mid);
            right = new Node(mid, hi);
        }
        left->update(L, R);
        right->update(L, R);
        v = left->v + right->v;
    }
};


