template<typename T>
struct Compress {
private:
    vector<T> value;

public:
    Compress() {}
    Compress(const vector<T> &v, bool distinct = false) {
        int n = v.size();
        value.resize(n);
        value = v;
        sort(value.begin(), value.end());
        if (distinct) value.erase(unique(value.begin(), value.end()), value.end());
    }

    int size() {
        return value.size();
    }

    int val(int idx) {
        return value[idx];
    }

    int get(int v) {
        return lower_bound(value.begin(), value.end(), v) - value.begin();
    }
};

template<typename T>
struct BinaryIndexedTree {
private:
    int n;
    vector<T> bit;

public:
    BinaryIndexedTree(int _n) : n(_n + 1), bit(n + 1, 0){}

    T sum(int idx) {
        T s(0);
        for(int x = idx + 1; x > 0; x -= (x & -x)) s += bit[x];
        return s;
    }

    void add(int idx, T a) {
        for(int x = idx + 1; x <= n; x += (x & -x)) bit[x] += a;
    }

    T query(int l, int r) {
        return sum(r - 1) - sum(l - 1);
    }
};

