const int N = 2e5 + 1;
long long pref[N];
int n;

struct node {
	node* L, *R;
	long long x, y;
	int size;
	node(long long key) {
		y = rand();
		x = key;
		size = 1;
		L = R = NULL;
	}
};

int size(node* t) {
	return t == NULL ? 0 : t->size;
}

void update(node* x) {
	x->size = size(x->L) + 1 + size(x->R);
}

node* merge(node* a, node* b) {
	if (b == NULL) return a;
	if (a == NULL) return b;
	if (a->y > b->y) {
		a->R = merge(a->R, b);
		update(a);
		return a;
	} else {
		b->L = merge(a, b->L);
		update(b);
		return b;
	}
}

pair <node*, node*> split(node* t, long long key) {
	if (t == NULL)
		return { t, t };
	if (t->x <= key) {
		auto lr = split(t->R, key);
		t->R = lr.first;
		update(t);
		lr.first = t;
		return lr;
	} else {
		auto lr = split(t->L, key);
		t->L = lr.second;
		update(t);
		lr.second = t;
		return lr;
	}
}


node* root = NULL;


void insert(long long key) {
	auto lr = split(root, key);
	auto lr2 = split(lr.first, key - 1);
	root = merge(merge(lr2.first, merge(lr2.second, new node(key))), lr.second);
}


