	for (int i = 0; i < n; ++i)
		pref[i + 1] = readInt() + pref[i] - k;

	long long ans = 0;
	for (int i = 0; i < n; ++i) {
		insert(pref[i]);
		//check pref[i + 1];
		auto lr = split(root, pref[i + 1]);
		ans += size(lr.first);
		root = merge(lr.first, lr.second);
	}
	cout << ans << endl;

	return 0;
}

