template<typename T>
struct Binary_Indexed_Tree{
    vector<T> bit;

    Binary_Indexed_Tree(int N){
        bit.assign(N+1, 0);
    }

    void add(int i, const T &x){
        for(i++; i < bit.size(); i += (i & -i)) bit[i] += x;
    }

    T sum(int i){
        T res = 0;
        for(i = i; i > 0; i -= (i & -i)) res += bit[i];
        return res;
    }

    T query(int l, int r){
        return sum(r) - sum(l);
    }

    void clear(){
        fill(bit.begin(), bit.end(), 0);
    }
};

