struct BIT{
    int N;
    vector<int> data;

    BIT(int n){
        N = n;
        data.resize(N, 0);
    }

    // 0-indexed
    void add(int a, int w){
        for(int x = a; x < N; x |= x + 1)
            data[x] += w;
    }

    int sum(int a){
        int ret = 0;
        for(int x = a-1; x >= 0; x = (x & (x+1)) - 1)
            ret += data[x];
        return ret;
    }
};

