template< typename Monoid >
class SegmentTree {
public:
	using F = function< Monoid(Monoid, Monoid) >;

	ll sz;
	vector< Monoid > seg;

	const F f;
	const Monoid M1;

	SegmentTree(ll n, const F f, const Monoid &M1) : f(f), M1(M1) {
		sz = 1;
		while(sz < n) sz <<= 1;
		seg.assign(2 * sz, M1);
	}

	void set(ll k, const Monoid &x) {
		seg[k + sz] = x;
	}

	void build() {
		for(ll k = sz - 1; k > 0; k--) {
			seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
		}
	}

	void update(ll k, const Monoid &x) {
		k += sz;
		seg[k] = x;
		while(k >>= 1) {
			seg[k] = f(seg[2 * k + 0], seg[2 * k + 1]);
		}
	}

	Monoid query(ll a, ll b) {
		Monoid L = M1, R = M1;
		for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
			if(a & 1) L = f(L, seg[a++]);
			if(b & 1) R = f(seg[--b], R);
		}
		return f(L, R);
	}

	Monoid operator[](const ll &k) const {
		return seg[k + sz];
	}

	template< typename C >
	ll find_subtree(ll a, const C &check, Monoid &M, bool type) {
		while(a < sz) {
			Monoid nxt = type ? f(seg[2 * a + type], M) : f(M, seg[2 * a + type]);
			if(check(nxt)) a = 2 * a + type;
			else M = nxt, a = 2 * a + 1 - type;
		}
		return a - sz;
	}

	template< typename C >
	ll find_first(ll a, const C &check) {
		Monoid L = M1;
		if(a <= 0) {
			if(check(f(L, seg[1]))) return find_subtree(1, check, L, false);
			return -1;
		}
		ll b = sz;
		for(a += sz, b += sz; a < b; a >>= 1, b >>= 1) {
			if(a & 1) {
				Monoid nxt = f(L, seg[a]);
				if(check(nxt)) return find_subtree(a, check, L, false);
				L = nxt;
				++a;
			}
		}
		return -1;
	}

	template< typename C >
	ll find_last(ll b, const C &check) {
		Monoid R = M1;
		if(b >= sz) {
			if(check(f(seg[1], R))) return find_subtree(1, check, R, true);
			return -1;
		}
		ll a = sz;
		for(b += sz; a < b; a >>= 1, b >>= 1) {
			if(b & 1) {
				Monoid nxt = f(seg[--b], R);
				if(check(nxt)) return find_subtree(b, check, R, true);
				R = nxt;
			}
		}
		return -1;
	}
};

template< typename T >
class Compress {
public:
	vector< T > xs;

	Compress() = default;

	Compress(const vector< T > &vs) {
		add(vs);
	}

	Compress(const initializer_list< vector< T > > &vs) {
		for(auto &p : vs) add(p);
	}

	void add(const vector< T > &vs) {
		copy(begin(vs), end(vs), back_inserter(xs));
	}

	void add(const T &x) {
		xs.emplace_back(x);
	}

	void build() {
		sort(begin(xs), end(xs));
		xs.erase(unique(begin(xs), end(xs)), end(xs));
	}

	vector< ll > get(const vector< T > &vs) const {
		vector< ll > ret;
		transform(begin(vs), end(vs), back_inserter(ret), [&](const T &x) {
			return lower_bound(begin(xs), end(xs), x) - begin(xs);
		});
		return ret;
	}

	ll get(const T &x) const {
		return lower_bound(begin(xs), end(xs), x) - begin(xs);
	}

	const T &operator[](ll k) const {
		return xs[k];
	}
};

