int count_sort(int s, int e, vl &S, vl &temp) {
	if (e - s <= 1) {
		return 0;
	}
	int mean = (e + s) / 2;
	int ans = 0;
	ans += count_sort(s, mean, S, temp);
	ans += count_sort(mean, e, S, temp);
	for (int i = s; i < e; i++) {
		temp[i] = S[i];
	}
	int i1 = s;
	int i2 = mean;
	int is = s;
	while (is<e) {
		if (i1 != mean && (i2 == e || temp[i1] <= temp[i2])) {
			S[is] = temp[i1];
			is++;
			i1++;
		}
		else {
			S[is] = temp[i2];
			ans += mean - i1;
			is++;
			i2++;
		}
	}
	return ans;
}


