	int n, k;
	scanf("%d%d", &n, &k);
	for (int i = 1; i <= n; i++) {
		scanf("%d", &a[i]);
		sum[i] = sum[i-1] + a[i] - k;
	}
	sort(sum,sum+n+1);
	int m = unique(sum,sum+n+1) - (sum+1);

	long long SUM = 0, ans = 0;
