long long merge_count(vector<pair<long long, int>> & a) {
	int n = a.size();
	if (n <= 1) return 0;

	long long cnt = 0;
	vector<pair<long long, int>> b(a.begin(), a.begin() + n / 2);
	vector<pair<long long, int>> c(a.begin() + n / 2, a.end());

	cnt += merge_count(b);
	cnt += merge_count(c);

	int ai = 0, bi = 0, ci = 0;
	while (ai < n) {
		if (bi < b.size() && (ci == c.size() || b[bi] <= c[ci])) {
			a[ai++] = b[bi++];
		}
		else {
			cnt += bi;
			a[ai++] = c[ci++];
		}
	}
	return cnt;
}

