// 0-indexed
template<typename T>
class FenwickTree {
	private:

		const int n;
		vector<T> bits;
		const int log_val;

	public:

		FenwickTree(int N) : n(N), bits(N+1, 0), log_val(__lg(N)) {}

		FenwickTree(vector<T>& arr) : FenwickTree(arr.size()) {
			for(int i = 0; i < n; ++i)
				add(i, arr[i]);
		}

		void add(int idx, T delta){
			for (++idx; idx <= n; idx += (idx & -idx))
				bits[idx] += delta;
		}

		T sum(int r){
			T ret = 0;
			for (++r; r > 0; r -= (r & -r))
				ret += bits[r];
			return ret;
		}

		T sum(int l, int r){
			return sum(r) - sum(l - 1);
		}

		int find_kth_by_order(T val){
			/*
			 * Returns lowest i st sum(0,i) >= val.
			 * Note that if no such value exists, it returns n, which is outside the legal positions of the array.
			 */

			int pos = 0;

			for(int i = log_val; i >= 0; --i){
				int next_pos = pos + (1 << i);

				if(next_pos <= n and bits[next_pos] < val){
					pos = next_pos;
					val -= bits[next_pos];
				}
			}

			return pos;
		}

		friend ostream& operator << (ostream& os, FenwickTree<T>& ft){
			os << "N:" << ft.n << " ==> " << ft.bits;
			return os; 
		}
};

void solve(){
	int n, k;
	cin >> n >> k;

	vector<int> arr(n);
	for(auto& i: arr) cin >> i;

	// count of (i,j) st \Sigma_{k = arr[i..j]} / (j - i + 1) >= k
	//                st presum(j) - presum(i - 1) >= k * j - k * (i - 1)
	//                st presum(j) - k * j >= presum(i - 1) - k * (i - 1)

	vector<ll> vec(1, 0);
	for(auto i: arr) vec.push_back(i + vec.back());
	for(int i = 0; i <= n; ++i) vec[i] -= k * i;

	// ans = count inversions in vec !

	ll cou = 0;

	// COMPRESS
	// sort
	set<ll> s(vec.begin(), vec.end());
	//find ordering
	map<ll,int> m;
	int no = 0; for(auto element: s) m[element] = no++;
	// transform vec
	for(auto& i: vec) i = m[i];

	FenwickTree<int> fen{no};
	fen.add(vec.front(), 1);

	for(int i = 1; i <= n; ++i){
		cou += fen.sum(vec[i]);
		fen.add(vec[i], 1);
	}

	cout << cou << "\n";
}

