    REP(i, N) {
        now += A[i];
        sums.PB(now - (i + 1) * K);
    }

    map<int, int> za = zaatu(sums);
    BIT<LL> bit(N + 1);
    LL ans = 0;
    REP(i, N + 1) {
        //cout << i << " " << sums[i] << " " << za[sums[i]] << " " << i - bit.sum(za[sums[i]]) << endl;
        ans += i - bit.sum(za[sums[i]]);
