const ll P=1000000000+7;
// 1baseでs1,...,snの和を計算
class BIT{
private:
  ll bit[MAX_N];
  int n;
public:
  BIT(int sz){
    n=sz;
    for(int i=0;i<=n;i++)
      bit[i]=0;
  }
  ll sum(int i){
    ll s=0;
    while(i>0){
      s+=bit[i];
      s%=P;
      i-=i&-i;
    }
    return s;
  }
  // from-to間の総和を求める
  ll rangeSum(int from,int to){
    ll res=0;
    res=(sum(to)-sum(from-1)+P)%P;
    return res;
  }
  void add(int i,ll x){
    while(i<=n){
      bit[i]+=x;
      bit[i]%=P;
      i+=i&-i;
    }
  }
  // sumとaddを組み合わせて、iの場所にxの値を代入
  void insert(int i,ll x){
    add(i,-(sum(i)-sum(i-1))+x);
  }
};

