class BIT {
public:
    int N;
    vector<int> bit;

    BIT(int N) {
        this->N = N;
        this->bit = vector<int>(N);
    }

    void add(int a, int w) {
        for (int x = a; x < N; x |= x+1) {
            bit[x] += w;
        }
    }

    int sum(int a) {
        int ret = 0;
        for (int x = a-1; x >= 0; x = (x & (x + 1)) - 1) {
            ret += bit[x];
        }
        return ret;
    }
};

