typedef long long ll;
ll source[200005],tmp[200005];
ll co=0;
void mergesort(int st,int mid,int en)
{
    int i=st,j=mid+1,k=st;
    while(i!=mid+1&&j!=en+1)
    {
        if(source[i]<=source[j]) tmp[k++]=source[i++];
        else
        {
            tmp[k++]=source[j++];
            co+=i-st;
        }
    }
    while(i!=mid+1)
        tmp[k++]=source[i++];
    while(j!=en+1)
    {
        tmp[k++]=source[j++];
        co+=i-st;
    }
    for(i=st;i<=en;++i)
        source[i]=tmp[i];
}
void merge_sort(int st,int en)
{
    if(st<en)
    {
        int mid=(st+en)/2;
        merge_sort(st,mid);
        merge_sort(mid+1,en);
        mergesort(st,mid,en);
    }
}
int main()
{
