    scanf("%d%d",&n,&k);
    for(int i=1;i<=n;++i)
    {
        scanf("%d",&f);
        source[i]=f-k+source[i-1];
    }
    merge_sort(0,n);
    cout<<co<<endl;
    return 0;
}

