#define MaxT 600000
#define MaxN 200005
#define INF 2140000000

using namespace std;

long long T[MaxT],P,Val;
long long N,K,ans=0;
struct spec
{
	long long val;
	int pos;
}S[MaxN];
bool cond( spec a,spec b)
{
	return a.val<b.val||(a.val==b.val&&a.pos<b.pos);
}
void Update(int node,int start,int end)
{
	if(start==end)
		T[node]++;
	else
	{
		int mid=(start+end)>>1;
		if(P<=mid)
			Update(2*node,start,mid);
		else Update(2*node+1,mid+1,end);
		T[node]=T[2*node]+T[2*node+1];
	}
}
void Query(int node,int start,int end)
{
	if(end<=P)
		Val+=T[node];
	else
	{
		int mid=(start+end)>>1;
		Query(2*node,start,mid);
		if(mid<P)
			Query(2*node+1,mid+1,end);
	}
}
int main()
{
	cin>>N>>K;
	for(int i=1;i<=N;i++)
		cin>>S[i].val,S[i].val+=S[i-1].val-K,S[i].pos=i;
	sort(S,S+1+N,cond);
	for(int i=0;i<=N;i++)
	{
		P=S[i].pos;
		Update(1,0,N);
		if(P==0)
			continue;
		P--;
		Val=0;
		Query(1,0,N);
		ans=ans+1LL*Val;
	}
	cout<<ans;
	return 0;
}

