template<int64 N>
struct BIT {
    int64 arr[N+1];

    BIT(int sz) {
        fill(arr, arr+N+1, 0);
    }

    void add(int x, int64 v) {
        for (int i = x; i <= N; i += i & -i) {
            arr[i] += v;
        }
    }

    int64 sum(int x) {
        int64 ans = 0;
        for (int i = x; i > 0; i -= i & -i) {
            ans += arr[i];
        }
        return ans;
    }
};

