ll N,K,TN;
ll p[500500];
ll ans = 0;

void solve(int l, int r){
	if( r < l ) return;
	if( l == r ) {
		if( p[l] >= K ) ans++;
		return;
	}

	int m = (l+r)/2;
	solve(l,m); solve(m+1,r);

	vector<Pll> v;
	ll sum = 0, cnt = 0;
	for(int i=m+1;i<=r;i++){
		cnt++; sum += p[i];
		v.push_back({sum,cnt});
	}
	sum = 0, cnt = 0;
	sort(all(v), [](Pll a, Pll b){
		return K*a.Se-a.Fi < K*b.Se-b.Fi;
	});

	for(int i=m;i>=l;i--){
		cnt++; sum += p[i];
		int low = 0, high = sz(v)-1, res = -1;
		while( low <= high ){
			int mid = (low+high)/2;
			if( sum - K*cnt >= K*v[mid].Se - v[mid].Fi ){
				res = mid; low = mid+1;
			}
			else high = mid-1;
		}
		//Debug(sum,cnt,)
		ans += res+1;
	}

}

