		cin >> t;
		sum[i] = sum[i - 1] + t;
		value[i].first = sum[i] - k * i;
		value[i].second = i;
	}

	sort(value, value + n + 1);
	int size_order[N];
	int num = 1;
	size_order[value[0].second] = num;
	for (int i = 1; i <= n; ++i) {
		if (value[i - 1].first == value[i].first) {
			size_order[value[i].second] = num;
		}
		else size_order[value[i].second] = ++num;
	}

	long long ans = 0;
	n++;
	for (int i = 0; i < n; ++i) {
		ans += get(size_order[i]);
		set(size_order[i]);
	}

	cout << ans;
}

