    vector<int> order(n+1);
    int num = -INF;
    int noword = 0;
    for(int i=0;i<n+1;i++){
        int pos = accum[i].second;
        if(accum[i].first > num)
            noword++;
        num = accum[i].first;
        order[pos] = noword;
    }
    BIT bit(n+1);
