        a[i] -= k;
        s[i] = a[i];
        if(i > 0) s[i] += s[i - 1];
        if(s[i] >= 0) ans++;
        p[i] = P(s[i], i);
    }
    sort(p, p + n);
    int nth[200004];
    for(int i = 0; i < n; i++) nth[p[i].second] = i;
    SegmentTree<ll> seg(n, [](ll a, ll b){return a + b;}, (ll)0);
    for(int i = 0; i < n; i++) seg.set(i, (ll)0);
    seg.build();
    for(int i = n - 1; i >= 0; i--){
        int insert = lower_bound(p, p + n, P(s[i], -1)) - p;
        ans += seg.query(insert, n);
