vector<int> compressor(const vector<ll> &x_) {
  int n = x_.size();
  vector<ll> x = x_;
  vector<int> ret(n);
  sort(ALL(x));
  auto itr = unique(ALL(x));
  REP(i,n) ret[i] = lower_bound(x.begin(), itr, x_[i]) - x.begin();
  return ret;
}

template<class T>
struct BIT{
  vector<T> bit;
  BIT(int n) : bit(n, 0) {}
  void add(int k, T a) {
    for(int x = k; x < bit.size(); x |= x + 1) bit[x] += a;
  }
  T sum(int i, int j) {
    if(i == 0) {
      T S = 0;
      for(int k = j; k >= 0; k = (k & (k + 1)) - 1) S += bit[k];
      return S;
    }else{
      return sum(0, j) - sum(0, i - 1);
    }
  }
};

