{
public:
    vector<int> bit;
    int M;

    BIT(const int M):
        bit(vector<int>(M+1, 0)), M(M) {}

    int sum(const int i) {//1~iまでの和
        if (!i) return 0;
        return bit[i] + sum(i-(i&-i));
    }

    void add(const int i, const int x) {//bit[i]にxを足す更新
        if (i > M) return;
        bit[i] += x;
        add(i+(i&-i), x);
    }
};


