int M=1;
std::vector<int> seg;
void init(int N){
  while(M<N) M*=2;
  M=M*2-1;
  for(int i=0;i<M;i++) {
    seg.push_back(0);
  }
}
void update(int l, int r, int k){
  k+=(M+1)/2-1;
  seg[k]++;
  while(k>0){
    k = (k-1)/2;
    seg[k]++;
  }
}
ll query(int a, int b, int l, int r, int k){
  if(r<=a || b<=l) return 0;
  if(a<=l && r<=b) return seg[k];
  ll A = query(a, b, l, (l+r)/2, k*2+1);
  ll B = query(a, b, (l+r)/2, r, k*2+2);
  return A + B;
}
