struct Treap {
    Treap *lc,*rc;
    LL key,pri;
    int sz;
    Treap(LL _key) {
        lc=rc=NULL;
        sz=1;
        pri=rand();
        key = _key;
    }
};

int Sz(Treap* t) {
    return t?t->sz:0;
}

void pull(Treap* t) {
    if (!t) return;
    t->sz = Sz(t->lc) + Sz(t->rc) + 1;
}

Treap* merge(Treap* a,Treap* b) {
    if (!a || !b) return a?a:b;
    else if (a->pri > b->pri) {
        a->rc=merge(a->rc,b);
        pull(a);
        return a;
    }
    else {
        b->lc=merge(a,b->lc);
        pull(b);
        return b;
    }
}

void split(Treap* t,LL k,Treap* &a,Treap* &b) {
    if (!t) a = b = NULL;
    else if (t->key <= k) {
        a=t;
        split(t->rc,k,a->rc,b);
        pull(a);
    }
    else {
        b=t;
        split(t->lc,k,a,b->lc);
        pull(b);
    }
}

Treap* root;

void add(LL val) {
    Treap* tl;
    split(root,val,tl,root);
    root = merge(merge(tl,new Treap(val)),root);
}

void deleted(LL val) {
    Treap *tl,*tr;
    split(root,val-1,tl,root);
    split(root,val,root,tr);
    root=merge(merge(tl,root->lc),merge(root->rc,tr));
}

LL query(LL val) {
    Treap *tl;
    split(root,val-1,tl,root);
    LL ret=Sz(root);
    root=merge(tl,root);
    return ret;
}

