typedef long long ll;
const int M=200010;

struct Node *null;
struct Node
{
	ll v;int t;
	Node *lch,*rch;
	Node() {}
	Node(ll _v) : v(_v),t(1),lch(null),rch(null) {}
	bool isbad() {return lch->t*3>t*2+10||rch->t*3>t*2+10;}
	void update() {t=lch->t+rch->t+1;}
}*root,*vec[M];
int tot;

void dfs(Node *p)
{
	if(p->lch!=null) dfs(p->lch);
	vec[tot++]=p;
	if(p->rch!=null) dfs(p->rch);
}

Node *divide(int l,int r)
{
	if(l==r) return null;
	int mi=l+r>>1;
	Node *p=vec[mi];
	p->lch=divide(l,mi);
	p->rch=divide(mi,r);
	p->update();
	return p;
}

void rebuild(Node *&p)
{
	tot=0;
	dfs(p);
	p=divide(0,tot);
}

Node **top;
void insert(Node *&p,ll v)
{
	if(p==null)
	{
		p=new Node(v);
		top=&null;
		return;
	}
	if(v<p->v) insert(p->lch,v);
	else insert(p->rch,v);
	p->update();
	if(p->isbad()) top=&null;
	if(p==root&&*top!=null) rebuild(*top);
}

int query(Node *p,int v)
{
	if(p==null) return 0;
	if(v<p->v) return query(p->lch,v);
	return p->lch->t+1+query(p->rch,v);
}

