#define N 200010
using namespace std;

int n;
long long k;
int tree[N];

void set(int i) {
	while (i <= n) {
		tree[i]++;
		i += (i & -i);
	}
}

int get(int i) {
	int ret = 0;
	while (i) {
		ret += tree[i];
		i &= i - 1;
	}
	return ret;
}

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);

	cin >> n >> k;
	long long sum[N] = {};
	pair<long long, int> value[N] = {};

	int t;
	for (int i = 1; i <= n; ++i) {
		cin >> t;
		sum[i] = sum[i - 1] + t;
		value[i].first = sum[i] - k * i;
		value[i].second = i;
	}

	sort(value, value + n + 1);
	int size_order[N];
	int num = 1;
	size_order[value[0].second] = num;
	for (int i = 1; i <= n; ++i) {
		if (value[i - 1].first == value[i].first) {
			size_order[value[i].second] = num;
		}
		else size_order[value[i].second] = ++num;
	}

	long long ans = 0;
	for (int i = 0; i < n + 1; ++i) {
		ans += get(size_order[i]);
		set(size_order[i]);
	}

	cout << ans;
}

