struct BinaryIndexedTree{
	vector<ll> bit;

	BinaryIndexedTree(int n){
		bit.assign(++n, 0);
	}

	void add(int k, int x){
		for(k++;k<=bit.size();k+=k&-k) bit[k] += x;
	}

	int get(int k){
		int ret = 0;
		for(k++;k>0;k-=k&-k) ret += bit[k];
		return ret;
	}
};

int main(){
	ll n,k; cin >> n >> k;
	REP(i,0,n) cin >> a[i];

	ll sum = 0, pos = 0;
	REP(i,0,n){
		sum += a[i]; pos += k;
		s[i] = sum - pos;
	}

	vector<ll> vec;
	REP(i,0,n) vec.push_back(s[i]); sort(vec.begin(), vec.end());
	vec.erase(unique(vec.begin(), vec.end()), vec.end());

	sum = 0;
	BinaryIndexedTree bit(vec.size());
	RREP(i,n-1,0){
		if(s[i] < 0) sum--;
		int c = vec.size() - 1 - (lower_bound(vec.begin(), vec.end(), s[i]) - vec.begin());
		bit.add(c, 1);
		sum += bit.get(c);
	}

	cout << sum << endl;
	return 0;
}

