const int BN = 18;
const int TN = 1<<BN;
ll N, K, A[200000], S[200001], T[TN];
vector<ll> v;
map<ll, ll> mi;
ll getter(int i){
  ll ret = 0, j = i + 1;
  FOR(k, 0, BN + 1){
    if(j & (1 << k)){
      ret += T[((j >> k) << k) - 1];
    }
  }
  return ret;
}
void setter(int i){
  FOR(k, 0, BN){
    if(!(i & (1 << k))){
      T[(((i >> k) + 1) << k) - 1] += 1;
    }
  }
}
main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  ll d, s = 0, ans = 0;
  cin >> N >> K;
  S[0] = 0;
  v.pb(0);
  FOR(i, 0, N){
    cin >> d;
    d -= K;
    A[i] = d;
    s += d;
    S[i + 1] = s;
    v.pb(s);
  }
  unique(v.begin(), v.end());
  sort(v.begin(), v.end());
  d = 0;
  for(vector<ll>::iterator itr = v.begin(); itr != v.end(); itr++){
    mi[*itr] = d;
    d++;
  }
  FOR(i, 0, N + 1){
    d = mi[S[i]];
    ans += getter(d);
    setter(d);
  }
  cout << ans << endl;
}

