void insert(int l,int r,int &now)
{
	tr[++cnt]=tr[now];
	now=cnt;
	tr[now].sum++;
	if(l==r)return;
	int mid=(l+r)>>1;
	if(v<=num[mid])insert(l,mid,tr[now].l);
	else insert(mid+1,r,tr[now].r);
