LL query(int l,int r,int now1,int now2)
{
	if(num[l]>=v)return tr[now1].sum-tr[now2].sum;
	int mid=(l+r)>>1;
	if(v<=num[mid])return query(l,mid,tr[now1].l,tr[now2].l)+query(mid+1,r,tr[now1].r,tr[now2].r);
	return query(mid+1,r,tr[now1].r,tr[now2].r);
}

