template <typename T=long long>
class BIT  
{
    private:
        int sz;  // BIT の大きさ
        vector<T> bit;  // BIT を保存する vector; 区間の右端で番号付け

    public:
        BIT(int N): sz(N), bit(N+1, 0) {};

        // v[idx] に w を足す
        void add(int idx, T w){
            // x&(-x) で x の最も下の立っているbitが取り出せる
            for(int x = idx; x <= sz; x += x&(-x)) bit[x] += w;  // 1-index
            // for(int x = idx; x < sz; x |= x+1) bit[x] += w;  // 0-index
        }

        // v[1]+...+v[idx] を返す
        T sum(int idx){
            T ret = 0;
            for(int x = idx; x > 0; x -= x&(-x)) ret += bit[x];  // 1-index
            // for(int x = idx-1; x >= 0; x = (x&(x+1))-1) ret += bit[x];  // 0-index
            return ret;
        }

        // v[left+1]+...+v[right] を返す
        T sum(T left, T right){ return sum(right)-sum(left); }
};

// 座標圧縮 O(NlogN)
template <typename T>
vector<T> coordComp(vector<T>& a)
{
    int n = a.size();
    vector<T> ret(n), tmp(a);

    sort(tmp.begin(), tmp.end());  // sort
    tmp.erase(unique(tmp.begin(), tmp.end()), tmp.end());  // unique な値のみ残す

    for(int i = 0; i < n; ++i){
        ret[i] = lower_bound(tmp.begin(), tmp.end(), a[i]) - tmp.begin();
    }

    return ret;
}


int main()
{
    int N, K;
    cin >> N >> K;
    vector<long long> a(N+1);  // 1-index
    REP(i, N) cin >> a[i+1];

    REP(i, N){
        a[i+1] -= K;
        a[i+1] += a[i];
    }

    // 座標圧縮; a[1], ... , a[N] -> [0, N) に圧縮
    auto comp_a = coordComp<long long>(a);

    BIT<> bit(N+1); // BIT で 0~N-1 の出現回数を管理
    long long ans = 0;
    REP(i, N+1){
        ans += bit.sum(comp_a[i]+1);
        bit.add(comp_a[i]+1, 1);
        // cout << i << " " << ans << endl;
    }
    cout << ans << endl; 

    return 0;
}

