template <typename T>
struct compress {
  vector<T> xs;
  compress() = default;
  compress(const vector<T> &vs) {
    add(vs);
  }
  compress(const initializer_list<vector<T>> &vs) {
    for (auto &p : vs) add(p);
  }
  void add(const vector<T> &vs) {
    copy(begin(vs), end(vs), back_inserter(xs));
  }
  void add(const T &x) {
    xs.emplace_back(x);
  }
  void build() {
    sort(begin(xs), end(xs));
    xs.erase(unique(begin(xs), end(xs)), end(xs));
  }
  vector<int> get(const vector<T> &vs) const {
    vector<int> ret;
    transform(begin(vs), end(vs), back_inserter(ret), [&](const T &x) {
      return lower_bound(begin(xs), end(xs), x) - begin(xs);
    });
    return ret;
  }
  int get(const T &x) const {
    return lower_bound(begin(xs), end(xs), x) - begin(xs);
  }
  const T &operator[](int k) const {
    return xs[k];
  }
};

void solve(int N, int K, vi a) {
  each(x, a)x -= K;
  vi cum(N);
  cum[0] = a[0];
  rep(i, 1, N)cum[i] = cum[i - 1] + a[i];
  compress<int> comp(cum);
  comp.build();
  segment_tree<int> st(N, [](int a, int b){ return a + b; }, 0);
  each(x, comp.get(cum))st.update(x, st[x] + 1);
  int ans = 0, now = 0;
  rep(i, N) {
    int index = comp.get(now);
    ans += st.query(index, N);
    int cur = comp.get(cum[i]);
    st.update(cur, st[cur] - 1);
    now = cum[i];
  }
  COUT(ans);
}


