map<ll,ll> zip;
ll unzip[200010];
ll compress(vector<ll> ve) {
    SORT(ve);
    ve.erase(unique(ALL(ve)),ve.end());
    rep(i,ve.size()){
        zip[ve[i]] = i;
        unzip[i] = ve[i];
    }
    return ve.size();
}

struct BIT{
    int M;
    vector<ll> bit;
    BIT(int n): M(n), bit(M+1,0) {}

    void add(int a, ll w=1) { // aを +w  aは 1-indexed
        for(int x=a; x<=M; x+= x& -x){
            bit[x] += w;
        }
    }

    ll sum(int a) { // [1,a] 1-indexed
        ll ret=0;
        for(int x=a; x>0; x-= x& -x){
            ret+= bit[x];
        }
        return ret;
    } // 左上のものをすべて足す
};

//--MAIN-----------------------------------
void Main() {
    ll N,K; cin>>N>>K;
    vector<ll> A(N),B(N);
    rep(i,N) cin>>A[i];
    rep(i,N) B[i]=A[i]-K;
    reps(i,1,N) B[i]+=B[i-1];
    compress(B);
    BIT bi(N+1);
    ll ans=0;

    rep(i,N){
        ans+=bi.sum(zip[B[i]]+1);
        bi.add(zip[B[i]]+1);
        if(B[i]>=0) ++ans;
    }

    cout<< ans <<"\n";
}
