template<class T>struct SegTree{
	vector<vector<T>> dat;
	int n;
	SegTree(const vector<T> &v){
		int size = v.size();
		for(n = 1; n < size; n *= 2);
		dat.resize(2 * n - 1);

		rep(i, n) dat[i + n - 1].pb(v[i]);
		for(int i = n - 2; i >= 0; i--){
			int l = i * 2 + 1, r = i * 2 + 2;
			dat[i].resize(dat[l].size() + dat[r].size());
			merge(all(dat[l]), all(dat[r]), dat[i].begin());
		}
	}
	~SegTree(){ delete [] dat; }

	int query(int a, int b, T val, int k, int l, int r){
		if(r <= a || b <= l) return 0;
		if(a <= l && r <= b) return dat[k].end() - lower_bound(all(dat[k]), val);

		int vl = query(a, b, val, k * 2 + 1, l, (l + r) / 2);
		int vr = query(a, b, val, k * 2 + 2, (l + r) / 2, r);

		return vl + vr;
	}
	int query(int a, int b, T val){ return query(a, b, val, 0, 0, n); }
};
