    for (size_t begin = 0; begin < n; begin++) {
        for (size_t end = begin + 1;  end <= n; end++) {
            if (xs[end] - xs[begin] >= k * (end - begin)) {
                count++;
            }
        }
    }
    std::cout << count << std::endl;
    return 0;
}

