template <typename T>
struct seg_pL {

  // 一点更新、区間取得 1~N
  using F = function<T(T,T)>;
  // f: [](int x, int y){return min(x,y);}
  // g: [](int x, int y){return y;} // 下にある値をそのまま上へ

  ll n0, n1; const F f, g; const T first_t; map<ll,T> seg;
  // f: 子の計算 g: 親と子(f)の計算

  seg_pL(ll n, const F _f, const F _g, const T& _t) : f(_f), g(_g), first_t(_t) {
    n0 = n, n1 = 1LL; while(n0 > n1) n1<<=1LL;
  }

  void set(ll k, const T& _t) {seg[k+n1]=_t;} // 1~Nのk番目に値を入れる
  void build() { for(int k=n1-1; k>=0; k--) seg[k] = f(seg[2*k], seg[2*k+1]);}

  void update(ll k, const T& t) {

    k += n1; seg[k] = f(seg[k], t); k /= 2;
    while(k > 0) {seg[k] = g(seg[k], f(seg[2*k], seg[2*k+1])); k /= 2;}
    //cout << seg << endl;
  }
  T get(int k){return seg[k+n1];}

  T query(ll a, ll b, ll k, ll l, ll r) { // (0, 4+1)
  //cout<<"@ "<<a<<" "<<b<<" "<<k<<" "<<l<<" "<<r<<endl;
    if (r<=a || l>=b) return first_t;
    if (a<=l && r<=b) {
      if (seg.find(k) != seg.end()) {return seg[k];}
      else return first_t;
    }
    else {
      T q1 = query(a, b, 2*k, l, (l+r)/2);
      T q2 = query(a, b, 2*k+1, (l+r)/2, r);
      //cout << q1 << " " << q2 << endl;
      return f(q1, q2);
    }
  }

  T query(ll a, ll b) {
    return query(a, b, 1, 0, n1);
  }

  void print() {
    for(P x : seg) {
      caut(x.first,x.second);
    }
    cout<<endl;
  }

  void print2() {
    for(int i=1,j=1;i<=2*n1;i++) {
      if (i+1 > (1<<j)) {cout<<endl; j++;}
      cout<<seg[i]<<" ";
    } cout<<endl;
  }
};

