using namespace std;
typedef long long LL;
LL MOD = 1000000007LL;
struct SegTree {
	vector<LL> dat[(1 << 19) - 1];
	void init(int k, int l, int r, LL A[], int N) {
		if (r - l == 1) {
			if (l < N) dat[k].push_back(A[l]);
			else dat[k].push_back(1LL << 60);
		}
		else {
			int lch = k * 2 + 1, rch = k * 2 + 2;
			init(lch, l, (l + r) / 2, A, N);
			init(rch, (l + r) / 2, r, A, N);
			dat[k].resize(r - l);
			merge(dat[lch].begin(), dat[lch].end(), dat[rch].begin(), dat[rch].end(), dat[k].begin());
		}
	}
	int query(int i, int j, LL x, int k, int l, int r) {
		if (j <= l || r <= i) return 0;
		if (i <= l && r <= j) {
			return upper_bound(dat[k].begin(), dat[k].end(), x) - dat[k].begin();
		}
		int lc = query(i, j, x, k * 2 + 1, l, (l + r) / 2);
		int rc = query(i, j, x, k * 2 + 2, (l + r) / 2, r);
		return lc + rc;
	}
};
LL A[200000];
SegTree s;
int main() {
	int N, K;
	cin >> N >> K;
	for (int i = 0; i < N; i++) cin >> A[i];
	for (int i = 1; i < N; i++) A[i] += A[i - 1];
	for (int i = 0; i < N; i++) A[i] -= K*i;
	int M = 1;
	while (M < N) M *= 2;
	s.init(0, 0, M, A, N);
	LL ans = 0;
	for (int i = 0; i < N; i++) if (A[i] >= K) ans++;
	for (int i = 1; i < N; i++) {
		ans += s.query(0, i, A[i], 0, 0, M * 2 - 1);
	}
	cout << ans << endl;
}

#include<bits/stdc++.h>
using namespace std;
using ll = long long;

template <class Abel> struct BIT {
	vector<Abel> dat;
	Abel UNITY_SUM = 0;

	// [1, n]
	BIT(int n) {
		dat.resize(n+1);
		for(int i=0;i<(int)dat.size();i++) {
			dat[i] = UNITY_SUM;
		}
	}

	// a is 1-indexed
	inline void add(int a, Abel x) {
		for(int i=a;i<(int)dat.size();i += i & -i) {
			dat[i] = dat[i] + x;
		}
	}

	// [1, a], a is 1-indexed
	inline Abel sum(int a) {
		Abel res = UNITY_SUM;
		for(int i=a;i>0;i -= i & -i) {
			res += dat[i];
		}
		return res;
	}

	// [a, b), a and b are 1-indexed
	inline Abel sum(int a, int b) {
		return sum(b - 1) - sum(a - 1);
	}
};

int main() {
	int N;
	ll K;
	cin >> N >> K;
	vector<ll> A(N);
	for(auto &a : A) cin >> a;

	vector<ll> B(N+1, 0), C(N+1, 0);
	for(int i=1;i<=N;i++) {
		B[i] = B[i-1] + A[i-1];
	}
	for(int i=1;i<=N;i++) {
		B[i] -= (i * K);
		C[i] = B[i];
	}

	sort(C.begin(), C.end());
	C.erase(unique(C.begin(), C.end()), C.end());

	// 0 <= j < i <= Nのとき, Bi >= Bjの個数
	ll ans = 0;
	BIT<ll> bit(N+1);
	bit.add((int)(lower_bound(C.begin(), C.end(), 0) - C.begin()) + 1, 1);
	for(int i=1;i<=N;i++) {
		int b = (int)(lower_bound(C.begin(), C.end(), B[i]) - C.begin()) + 1;
		ans += bit.sum(b);
		bit.add(b, 1);
	}
	cout << ans << endl;
}

