void solve(int l, int r) {
    if (l == r) {
        return;
    }

    int m = (l + r) / 2;
    vector<ll> lp, rp;
    for (int i = l; i <= m; i++) {
        lp.push_back(ps[i]);
    }
    for (int i = m + 1; i <= r; i++) {
        rp.push_back(ps[i]);
    }
    sort(lp.begin(), lp.end());
    sort(rp.begin(), rp.end());
    int ptr = 0;
    for (ll x : rp) {
        while (ptr < lp.size() && lp[ptr] <= x) {
            ptr++;
        }
        ans += ptr;
    }
    solve(l, m);
    solve(m + 1, r);
}

