		cin >> a[i];
		a[i] -= K;
	}
	VL sum(N + 1, 0);
	FOR(i, 0, N) {
		sum[i + 1] = sum[i] + a[i];
	}

	VL xs(sum);
	SORT(xs);
	UNIQ(xs);
	BIT<LL> bit(SZ(sum));
	FOR(i, 0, SZ(sum)) {
		int id = lower_bound(ALL(xs), sum[i]) - xs.begin();
		ans += bit.sum(id + 1);
		bit.add(id + 1, 1);
	}
	cout << ans << "\n";

	return 0;
}

