void merge_sort(int l, int r, ll *A) {
	if (l >= r)
    {
        if(b[l]>=0)
            cnt++;
        return ;
    }
	int mid = (l + r) >> 1;
	merge_sort(l, mid, A);
	merge_sort(mid + 1, r, A);
	ll pl = l, pr = mid + 1, tmpp = 0;
	while(pl <= mid && pr <= r) {
		if (A[pl] <= A[pr]) tmpA[tmpp++] = A[pl++],cnt +=r - pr + 1;
		else tmpA[tmpp++] = A[pr++];
	}
	while(pl <= mid) tmpA[tmpp++] = A[pl++];
	while(pr <= r) tmpA[tmpp++] = A[pr++];
	for (int i = 0; i < tmpp; i++) A[i + l] = tmpA[i];
}

