// interval tree
int cnt[MAXN<<2];

inline void pushup (int rt) {
    cnt[rt] = cnt[rt<<1] + cnt[rt<<1|1];
}

void upd (int l, int r, int val, int st, int en, int rt) {
    if (l <= st && en <= r) {
    	cnt[rt] += val;
        return;
    }

    int md = (st+en)>>1;
    if (l <= md) upd(l,r,val,st,md,rt<<1);
    if (md < r) upd(l,r,val,md+1,en,rt<<1|1);
    pushup(rt);
}

long long query (int l, int r, int st, int en, int rt) {
    if (l <= st && en <= r) {
        return cnt[rt];
    }

    long long ret = 0;
    int md = (st+en)>>1;
    if (l <= md) ret += query(l,r,st,md,rt<<1);
    if (md < r) ret += query(l,r,md+1,en,rt<<1|1);
    return ret;
}

int bs (long long val, int st, int en) {
	while (st != en) {
		int md = (st + en) >> 1;
		if (val <= sum[md]) en = md;
		else st = md + 1;
	}
	return st;
}

