	for (int i = 0; i <= n; i++) {
		int pos = bs(SUM,0,m);
		upd(pos,pos,1,0,m,1);
		ans += query(0,pos,0,m,1) - 1;
		SUM += a[i+1] - k;
	}
	printf("%lld\n", ans);
}

