int const MAX = 200002;
long long const MAX_A = 1000000000000000002;
long long a[MAX];
long long l[MAX / 2 + 2], r[MAX / 2 + 2];

long long Merge(long long a[], int left, int mid, int right) {
	int i, j;
	long long cnt = 0;
	int n1 = mid - left;
	int n2 = right - mid;
	for (i = 0; i < n1; i++) {
		l[i] = a[left + i];
	}
	for (i = 0; i < n2; i++) {
		r[i] = a[mid + i];
	}
	l[n1] = MAX_A; r[n2] = MAX_A;
	i = 0; j = 0;
	for (int k = left; k < right; k++) {
		if (l[i] <= r[j]) {
			a[k] = l[i];
			i++;
		}
		else {
			a[k] = r[j];
			j++;
			cnt += n1 - i;
		}
	}
	return cnt;
}
long long MergeSort(long long A[], int left, int right) {
	int mid;
	long long v1, v2, v3;
	if (left + 1 < right) {
		mid = (left + right) / 2;
		v1 = MergeSort(A, left, mid);
		v2 = MergeSort(A, mid, right);
		v3 = Merge(A, left, mid, right);
		return v1 + v2 + v3;
	}
	else { return 0; }
}

