    int cnt = 0;
    for(ll val : st){
        mp[val] = cnt++;
    }



    ll ans = 0;
    RSQ seg(N+1);
    seg.update(mp[0],1);
    for(int i=1;i<=N;i++){
        int idx = mp[b[i]];
        ll sum = seg.query(0,idx+1);
        ans += sum;
        ll tmp = seg.data[idx+N];
        seg.update(idx,tmp+1);
    }
    cout << ans << endl;
}

