	for(int i=0;i<sz;i++){
		pam[v[i]]=0;
	}
	//新座標が1からほしいときはnc=1にする
	int nc=0;
	for(pair<int,int> i:pam){
		pam[i.first]=nc;
		nc++;
	}
	vector<int> w;
	for(int i=0;i<sz;i++){
		w.push_back(pam[v[i]]);
	}
	return w;
}
