/** @class BinaryIndexedTree
 *  @brief Range Sum Query on BIT
 **/
template<typename T>
struct BinaryIndexedTree {
    int N;
    std::vector<T> node;

    BinaryIndexedTree(int n) : N(n), node(n+1, 0) {}

    BinaryIndexedTree(const std::vector<T>& v) : BinaryIndexedTree(v.size()) {
        for (int i = 0; i < N; i++) {
            add(i+1, v[i]);
        }
    }

    /// @brief Add value to the i-th element (1-indexed)
    /// @param i index
    /// @param x value
    void add(int i, T v) {
        while (i <= N) {
            node[i] += v;
            i += i & -i;
        }
    }

    /// @brief Get sum in [1, i] range (1-indexed)
    /// @param i index
    /// @return the sum of [1, i]
    T sum(int i) const {
        T res = 0;
        while (i > 0) {
            res += node[i];
            i -= i & -i;
        }
        return res;
    }
};

template<typename T>
long long calcInversion(const std::vector<T>& v) {
    int n = v.size();
    std::vector<int> ord(n);
    for (int i = 0; i < n; i++) ord[i] = i;

    std::sort(ord.begin(), ord.end(), [&](int a, int b){return v[a] < v[b];});

    int index = 0;
    std::vector<int> u(n);
    for (int i = 0; i < n; i++) {
        int p = ord[i];
        if (!(i > 0 && v[p] == v[ord[i-1]])) {
            index++;
        }
        u[p] = index;
    }

    BinaryIndexedTree<int> bit(index);
    long long res = 0;

    for (int i = 0; i < n; i++) {
        res += i - bit.sum(u[i]);
        bit.add(u[i], 1);
    }

    return res;
}

