	for(LL i = 1; i <= n; i++)
	{
		sum += a[i];
		//Count number of PST[j] such that (PST[i]-PST[j])/(i-j) >= k, or PST[i]-PST[j] >= ki - kj
		//PST[i]-ki >= PST[j]-kj or
		//(PST[i]-ki,i) > (PST[j]-kj,j)
		ans += (LL)tracker.order_of_key({sum-k*i,i});
		tracker.insert({sum-k*i,i});
	}
	cout<<ans<<endl;

	return 0;
}

