template <class Tp>
class fenwick_tree{
	std::vector<Tp> bit;
public:
	fenwick_tree(){}
	explicit fenwick_tree(std::size_t n) : bit(n + 1) {}
	Tp sum(std::size_t i) const{
		i++;
		assert(i); // 0 ha dame zettai !
		Tp s = 0;
		while(i){
			s += bit[i];
			i -= i & -i;
		}
		return s;
	}
	void add(std::size_t i, Tp x){
		i++;
		assert(i); // 0 ha dame zettai !
		while(i < bit.size()){
			bit[i] += x;
			i += i & -i;
		}
	}
	void clear(){
		bit.clear();
	}
	void assign(std::size_t n){
		bit.assign(n + 1, Tp());
	}
	void swap(fenwick_tree &f){
		bit.swap(f.bit);
	}
};


