template<typename T>
struct BIT {
  int n;
  vector<T> d;

  BIT(int n=0):n(n),d(n+1) {}
  void add(int i, T x=1) {
    for (i++; i <= n; i += i&-i) {
      d[i] += x;
    }
  }
  //[0,i)の和
  T sum(int i) {
    i--;
    T x = 0;
    for (i++; i; i -= i&-i) {
      x += d[i];
    }
    return x;
  }
  //[l,r)の和
  T sum(int l, int r) {
    return sum(r) - sum(l);
  }
};

