    scanf ( "%d%d" , &n , &k ) ;
    for ( int i = 1 ; i <= n ; ++ i ) {
        scanf ( "%d" , &a[ i ] ) ;
        pref[ i ] = ( pref[ i - 1 ] + a[ i ] - k ) ;
    }
