    w.init ( 1 , 0 , n ) ;
    long long ans = 0 ;
    for ( int i = 0 ; i <= n ; ++ i ) {
        ans += w.query ( 1 , 0 , n , 0 , srt[ i ].second ) ;
        w.update ( 1 , 0 , n , srt[ i ].second ) ;
    }
    printf ( "%lld\n" , ans ) ;
}


