typedef long long ll;

struct wyr
{
    ll a, nowe_a, nr;
};

bool porownanie(wyr a, wyr b)
{
    if (a.a < b.a) return true;
    else return false;
}

bool porownanie2(wyr a, wyr b)
{
    if (a.nr < b.nr) return true;
    else return false;
}

vector<ll> T;
int l, size;

void Stworz(int n)
{
    int p = 1;
    while (p < n) p *= 2;
    l = p;
    size = 2 * p - 1;
    for (int i = 0; i <= size; ++i) T.push_back(0);
}

void Dodaj(int a)
{
    a += l;
    while (a != 0)
    {
        ++T[a];
        a /= 2;
    }
}

ll Pyt(int a, int b)
{
    a += l;
    b += l;
    ll s = T[a];
    if (a != b) s += T[b];
    while (a / 2 != b / 2)
    {
        if (a % 2 == 0) s += T[a + 1];
        if (b % 2 == 1) s += T[b - 1];
        a /= 2;
        b /= 2;
    }
    return s;
}

int main()
{
    int n, k;
    scanf("%d %d", &n, &k);
    vector<wyr> A(n);
    for (int i = 0; i < n; ++i)
    {
        scanf("%lld", &A[i].a);
        A[i].a -= k;
        A[i].nr = i;
        if (i != 0) A[i].a += A[i - 1].a;
    }
    sort(A.begin(), A.end(), porownanie);
    A.push_back({10000000000, 0, 0});
    ll akt = 0;
    for (int i = 0; i < n; ++i)
    {
        A[i].nowe_a = akt;
        if (A[i].a != A[i + 1].a) ++akt;
    }
    A.pop_back();
    sort(A.begin(), A.end(), porownanie2);
    Stworz(akt + 1);
    ll wyn = 0;
    Dodaj(A[0].nowe_a);
    if (A[0].a >= 0) ++wyn;
    for (int i = 1; i < n; ++i)
    {
        wyn += Pyt(0, A[i].nowe_a);
        if (A[i].a >= 0) ++wyn;
        Dodaj(A[i].nowe_a);
    }
    printf("%lld", wyn);
    return 0;
}

