int nd[maxn*80], ls[maxn*80], rs[maxn*80], rt[maxn];
int n, k, a[maxn], tot;
ll s[maxn], ans, delta;

void insert(int &now,int pre,ll l,ll r,ll x)
{
	now = ++ tot;
	nd[now] = nd[pre] + 1;
	if(l == r) return;
	ll mid = l + r >> 1;
	if(x <= mid) insert(ls[now],ls[pre],l,mid,x), rs[now] = rs[pre];
	else insert(rs[now],rs[pre],mid+1,r,x), ls[now] = ls[pre];
}

int ask(int now,int pre,ll l,ll r,ll al,ll ar)
{
	if(!now) return 0; 
	if(al <= l && r <= ar) return nd[now]-nd[pre];
	ll mid = l + r >> 1;
	if(ar <= mid) return ask(ls[now],ls[pre],l,mid,al,ar);
	else if(al > mid) return ask(rs[now],rs[pre],mid+1,r,al,ar);
	else return ask(ls[now],ls[pre],l,mid,al,mid)+ask(rs[now],rs[pre],mid+1,r,mid+1,ar);  
}

