{
	scanf("%d%d",&n,&k);
	fo(i,1,n) scanf("%d",&a[i]), a[i] -= k;
	fo(i,1,n) s[i] = s[i-1] + a[i], insert(rt[i],rt[i-1],-lim,lim,s[i]);
	fo(i,1,n) ans += ask(rt[n],rt[i-1],-lim,lim,s[i-1],lim);
