void msort(int l, int r){
	if(l == r) return;

	int mid = (l + r) / 2;

	msort(l, mid);
	msort(mid + 1, r);

	vector <long long> left, right;

	for(int ii = l; ii <= mid; ii++)
	left.push_back(sum[ii]);
	for(int ii = mid + 1; ii <= r; ii++)
	right.push_back(sum[ii]);

	int p = 0;

	for(int ii = 0; ii < right.size(); ii++){
		while(p < left.size() && right[ii] - left[p] >= 0)
		p++;

		res += p;
	}

	vector <long long> m;

	p = 0;
	int p1 = 0;

	while(p < left.size() && p1 < right.size()){
		if(left[p] < right[p1])
		m.push_back(left[p++]);
		else
