string bits(long long n, long long k) {
	// nをk桁のbitで表示したstringを返す
	string s = "";
	rep(i, k) {
		char c = '0' + (n % 2);
		s += c;
		n /= 2;
	}
	reverse(all(s));
	return s;
}
