ll rsq(int l, int r) {
    return pf[r] - pf[l-1];
}

bool can(int l, int r) {
    return rsq(l, r) >= 1LL*K*(r-l+1);
}

int bin(int l) {
    int lo=l, hi=N, mid;
    int ans=0;
    while(lo<=hi) {
        mid = (lo+hi)/2;
        if(can(l, mid)) {
            ans = max(ans, N-mid+1);
            hi = mid-1;
        } else {
            lo = mid+1;
        }
    }
    return ans;
}

