struct BIT{
    vector<ll> data;
    int n;
    // 最大値求めたいとき最初は0を入れておく？
    // データはaddで随時追加してもいいし最初に全部入れても良い問題による
    BIT(int n) : data(n + 1, 0), n(n){
        return;
    }
    ll sum(int l, int r){
        return sum_(r) - sum_(l);
    }
    ll sum_(int i){
        ll res = 0;
        while(i > 0){
            res += data[i];
            i -= i & -i;
        }
        return res;
    }
    void add(int i, int x){
        while(i <= n){
            data[i] += x;
            i += i & -i;
        }
        return;
    }
};

