struct FenwickTree{
	vector<ll> data;
	FenwickTree(int n):data(n+1){}
	void AddRange(int i,int x){
		for(;i;i-=i&-i)
			data[i]+=x;
	}
	void AddRange(int i,int j,int x){
		AddRange(i,-x);
		AddRange(j,x);
	}
	int Get(int i){
		ll res=0;
		for(i++;i<data.size();i+=i&-i)
			res+=data[i];
		return res;
	}
};

int main()
{
	for(int n,k;cin>>n>>k&&n|k;){
		vi a(n);
		rep(i,n) cin>>a[i],a[i]-=k;

		FenwickTree ft(2*n);
		int l=n,r=n;
		ll res=0;
		rep(i,n){
			if(a[i]<0)
				l--;
			else
				r++;
			ft.AddRange(l,r,a[i]);

			int lo=l,hi=r;
			while(lo<hi){
				int mi=(lo+hi)/2;
				if(ft.Get(mi)>=0)
					hi=mi;
				else
					lo=mi+1;
			}
			res+=r-lo;
		}
		cout<<res<<endl;
	}
}

