    vector<T> s;
    int n;
    BIT(int n_) : n(n_+1), s(n_+1) {};
    T sum(int i) {
        ++i;
        T ret = 0;
        while(i > 0) {
            ret += s[i];
            i -= i & -i;
        }
        return ret;
    }
    // [l, r)
    T query(int l, int r) {
        return sum(r-1) - sum(l-1);
    }
