struct Sorted {
    Node* root = nullptr;
    ll added = 0;
    void insert(int num){
        added -= num;
        num += added;
        Node* n = root;
        if(!root){ root = new Node(num); return; }
        while(n){
            // prints(n);
            if(n->value <= num){
                n->cnt++;
                if(!n->r){ n->r = new Node(num); break; }
                n = n->r;
            }else{
                // n->cnt++;
                if(!n->l){ n->l = new Node(num); break; }
                n = n->l;
            }
        }
        // n = new Node(num);
    }
    int beq(int num){
        num += added;
        Node* n = root;
        int acc = 0;
        while(n){
            if(n->value > num){
                acc += n->cnt;
                n = n->l;
            }else if(n->value == num){
                return n->cnt + acc;
            }else{
                n = n->r;
            }
        }
        return acc;
    }
