        sa[i] = a[i];
    }
    sort(sa, sa + n + 1);
    int m = int(unique(sa, sa + n + 1) - sa);

    Fenwick fw(m);
    ll ans = 0;
    for (int i = 0; i <= n; i++) {
        int ord = int(lower_bound(sa, sa + n + 1, a[i]) - sa);
        ans += fw.sum(ord);
        fw.add(ord, 1);
    }
    cout << ans << endl;
    return 0;
}

