    }
    Compress<ll> comp(sum);
    rep(i,n+1){
        sum[i]=comp.id(sum[i])+1;
    }
    BIT<ll> seg(n+1);
    ll ans=0;
    seg.add(sum[0],1);
    FOR(r,1,n+1){
        ans+=seg.sum(sum[r]);
        seg.add(sum[r],1);
    }
    cout<<ans<<endl;
}

