// バイナリーインデクスドツリー
template <class T>
struct binary_indexed_tree {
    int n;
    vector<T> x;
    binary_indexed_tree(int n_ = 0) : n(n_), x(n + 1, 0) {}
    int size() const { return n; }
    T sum(int r) const {
        T S = 0;
        for (r = r - 1; r >= 0; r = (r & (r + 1)) - 1) S += x[r];
        return S;
    }
    T sum(int l, int r) const { return sum(r) - sum(l); }
    void add(int k, const T &a) {
        for (; k < n; k |= k + 1) x[k] += a;
    }
    void set(int k, const T &a) { add(k, a - sum(k, k + 1)); }
};

int main(void) {
    lint n, k; cin >> n >> k;
    vector<lint> a(n); repeat(i, n) cin >> a[i];
    repeat(i, n) a[i] -= k;

    vector<lint> s(n+1);
    s[0] = 0;
    repeat(i, n) s[i+1] = s[i] + a[i];

    // 座標圧縮 ソート → 一意要素を前に → 後半に残る重複要素を削除 → 二分探索で元の数字のindexを調べる
    auto t = s;
    sort(t.begin(), t.end());
    auto it = unique(t.begin(), t.end());
    t.erase(it, t.end());
    for(auto &e: s) {
        e = lower_bound(t.begin(), t.end(), e) - t.begin();
    }

    // 転倒数カウント
    lint ans = 0;
    lint N = *max_element(s.begin(), s.end());
    binary_indexed_tree<lint> bit(N+1);

    repeat(i, n+1) {
        ans += bit.sum(s[i]+1);
        bit.add(s[i], 1);
    }
    cout << ans << endl;
    return 0;
}

