void update(int k,int a){
	k+=n_-1;
	dat[k]+=a;
	while(k>0){
		k=(k-1)/2;
		dat[k]=dat[k*2+1]+dat[k*2+2];
	}
}

ll query(int a,int b,int k=0,int l=0,int r=n_){
	if(r<=a || b<=l)return 0;
	if(a<=l && r<=b)return dat[k];
	ll vl=query(a,b,k*2+1,l,(l+r)/2);
	ll vr=query(a,b,k*2+2,(l+r)/2,r);
	return vl+vr;
}

int main(void){
	scanf("%d%lld",&n,&k);
	for(int i=0;i<n;i++){
		scanf("%lld",&a[i]);
		a[i]-=k;
		sum[i+1]=sum[i]+a[i];
	}
	for(int i=1;i<=n;i++){
		va.push_back(sum[i]);
	}
	sort(va.begin(),va.end());
	va.erase(unique(va.begin(),va.end()),va.end());
	for(int i=1;i<=n;i++){
		sum[i]=lower_bound(va.begin(),va.end(),sum[i])-va.begin();
		update(sum[i],1);
	}
	ll res=0;
	ll now=0;
	for(int i=0;i<n;i++){
		int le=lower_bound(va.begin(),va.end(),now)-va.begin();
		res+=query(le,va.size());
		now+=a[i];
		int mn=lower_bound(va.begin(),va.end(),now)-va.begin();
		update(mn,-1);
	}
	printf("%lld\n",res);
	return 0;
}

