  pool[n] = Myset(0);
  Myset* root = &pool[n];
  REP(i, n) {
    sum += a[i];
    root->dump();
    answer += root->count_le(sum);
    pool[i] = Myset(sum);
    root = root->push(&pool[i]);
  }
  cout << answer << endl;
  return 0;
}

