    for (int i = 0; i < N+1; i++) {
        m[s[i]] = 1;
    }
    int ind = 1;
    for (auto v : m) {
        m[v.first] = ind;
        ind++;
    }
    for (int i = 0; i < N+1; i++) {
        s[i] = m[s[i]];
    }

    BIT bit(N);
    ll ans = 0;
    for (int i = 0; i < N+1; i++) {
        ans += bit.getSUM1(s[i]);
        bit.add(s[i], 1);
    }
    printf("%lld\n", ans);
}

