typedef long long ll;

class BIT {
public:
    ll N;
    vector<ll> bit;

    BIT(ll N) {
        this->N = N;
        this->bit = vector<ll>(N);
    }

    void add(ll a, ll w) {
        for (ll x = a; x < N; x |= x+1) {
            bit[x] += w;
        }
    }

    ll sum(ll a) {
        ll ret = 0;
        for (ll x = a-1; x >= 0; x = (x&(x+1))-1) {
            ret += bit[x];
        }
        return ret;
    }
};

