void merge_sort(ll* A, int x, int y, ll* T) {
    if (y - x > 1) {
        int m = x + (y - x) / 2;
        int p = x, q = m, i = x;
        merge_sort(A, x, m, T);
        merge_sort(A, m, y, T);
        while (p < m || q < y) {
            if (q >= y || (p < m && A[p] <= A[q])) T[i++] = A[p++];
            else { T[i++] = A[q++]; cnt += m - p; }
        }
        for (i = x; i < y; i++) A[i] = T[i];
    }
}

