        b[i] = (i ? s[i - 1] : 0) - K * i;
    }
    b[n] = s[n - 1] - n * K;
    merge_sort(b, 0, n + 1, t);
    printf("%lld\n", (ll)n * (n + 1) / 2 - cnt);
    return 0;
}

