ll bit[200002], n;
ll a[200002], b[200002], c[200002], k;

class Solution {
public:
    long long sum(int i)
    {
        long long s = 0;
        while (0 < i)
        {
            s += bit[i];
            i -= i & -i;
        }
        return s;
    }

    void add(int i, long long x)
    {
        while (i <= n)
        {
            bit[i] += x;
            i += i & -i;
        }
    }

    void solve(std::istream& in, std::ostream& out) {
        in >> n >> k;
        for (int i = 1; i <= n; i++)
        {
            int t = 0;
            in >> t;
            a[i] = a[i - 1] + t - k;
            b[i] = a[i];
        }

        sort(b + 1, b + n + 1);
        ll len = unique(b + 1, b + n + 1) - b - 1;

        for (int i = 0; i <= n; i++)
        {
            c[i] = (ll)(lower_bound(b + 1, b + len + 1, a[i]) - b);
        }

        ll ans = 0;
        for (int i = 1; i <= n; i++)
        {
            add(c[i], 1);
            ans += sum(c[i]);
        }

        out << ans;
    }
};

void solve(std::istream& in, std::ostream& out)
{
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}


