struct node{
  pli val;
  int H, sum;
  node *L , *R;
  node(pli _val = pli(0,0)){
   val = _val;
   H = rand();
   L = R = null;
   sum = 1;
                           }
};

int get(node* vr){
  return vr ? vr->sum : 0;
}

void update(node* vr){
  if(vr){
    vr->sum = 1 + get(vr->L) + get(vr->R);
  }
}

void split(node* vr , const pli& on , node*& l , node*& r){
  if(!vr){
   l = r = null;
   return;
         }
  if(vr->val >= on){
   split(vr->L , on , l , vr->L);
   r = vr;
   update(r);
                   }
  else{
   split(vr->R , on , vr->R , r);
   l = vr;
   update(l);
      }
}

node* merge(node* l , node* r){
  if(!l || !r)return l ? l : r;
  if(l->H < r->H){
   l->R = merge(l->R , r);
   update(l);
   return l;
                 }
  else{
   r->L = merge(l , r->L);
   update(r);
   return r;
      }
}

