const int N = 200100;
using namespace std;

long long pos_pref[N];
long long neg_pref[N];

int T[4 *N];
vector <long long> val;
map <long long, int> cnt;

inline int c1(int n) { return (n << 1); }
inline int c2(int n) { return (n << 1)|1; }

void build(int curr, int st, int end)
{
	if(st == end)
	{
		T[curr] = cnt[val[st]];
		return;
	}

	int mid = st +end >> 1;

	build(c1(curr), st, mid);
	build(c2(curr), mid +1, end);

	T[curr] = T[c1(curr)] +T[c2(curr)];
}

void update(int curr, int st, int end, int idx)
{
	if(st == end)
	{
		T[curr]--;
		return;
	}

	int mid = st +end >> 1;

	if(idx <= mid)
		update(c1(curr), st, mid, idx);

	else
		update(c2(curr), mid +1, end, idx);

	T[curr] = T[c1(curr)] +T[c2(curr)];
}

int query(int curr, int st, int end, int l, int r)
{
	if(st > end || r < st || end < l)
		return 0;

	if(l <= st && end <= r)
		return T[curr];

	int mid = st +end >> 1;

	int q1 = query(c1(curr), st, mid, l, r);
	int q2 = query(c2(curr), mid +1, end, l, r);

	return q1 +q2;
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(NULL);

	int n, k;
	cin >> n >> k;

	for(int i = 1; i <= n; i++)
	{
		int a;
		cin >> a;

		pos_pref[i] = pos_pref[i -1];
		neg_pref[i] = neg_pref[i -1];

		if(a -k > 0)
			pos_pref[i] += (a -k);

		else
			neg_pref[i] += (k -a);
	}

	for(int i = 1; i <= n; i++)
		cnt[pos_pref[i] -neg_pref[i]]++;

	for(auto it = cnt.begin(); it != cnt.end(); it++)
		val.push_back(it->first);

	map <long long, int> idx;
	int sz = val.size();
	for(int i = 0; i < sz; i++)
		idx[val[i]] = i;

	build(1, 0, sz -1);

	long long res = 0, offset = 0;
	for(int i = 1; i <= n; i++)
	{
		auto it = lower_bound(val.begin(), val.end(), offset);

		if(it == val.end())
		{
			offset = (pos_pref[i] -neg_pref[i]);
			update(1, 0, sz -1, idx[pos_pref[i] -neg_pref[i]]);
			continue;
		}

		res += query(1, 0, sz -1, idx[*it], sz -1);
		offset = (pos_pref[i] -neg_pref[i]);
		update(1, 0, sz -1, idx[pos_pref[i] -neg_pref[i]]);
	}

	cout << res << '\n';
	return 0;
}

