////////// BIT (binary indexed tree) //////////

//1-indexed
class BIT{
public:
  ll n;
  vector<ll> bit;
  BIT(ll n):n(n),bit(n+1,0){}

  void add(ll i,ll x){
    if(i==0) return;
    for(ll k=i;k<=n;k+=(k & -k)) bit[k]+=x;
  }

  ll sum(ll i){
    ll s=0;
    if(i==0) return s;
    for(ll k=i;k>0;k-=(k & -k)) s+=bit[k];
    return s;
  }

  //a_1 + a_2 + … + a_i >= x となるような最小のiを求める(a_k >= 0)
  //xが0以下の場合は該当するものなし→0を返す
  ll lower_bound(ll x){
    if(x<=0) return 0;
    else{
      ll i=0,r=1;
      //最大としてありうる区間の長さを取得する
      //n以下の最小の二乗のべき(BITで管理する数列の区間で最大のもの)を求める
      while(r<n) r=r<<1;
      //区間の長さは調べるごとに半分になる
      for(int len=r;len>0;len=len>>1){
        //その区間を採用する場合
        if(i+len<n && bit[i+len]<x){
          x-=bit[i+len];
          i+=len;
        }
      }
      return i+1;
    }
  }
};

