  }
  vector <long long> sum(n + 1);
  for (int i = 0; i < n; i++) {
    sum[i + 1] = sum[i] + a[i] - k;
  }
  compress(sum);
  Fenwick<int> bit(n + 100);
  long long ans = 0;
  for (int i = 0; i <= n; i++) {
    ans += bit.get(zip[sum[i]]);
    bit.add(zip[sum[i]], 1);
  }
  cout << ans << '\n';
  return 0;
}

