	if (L + 1 == R) return;
	int M = (L + R) / 2, i = L, j = M, c = L;
	merge_sort(L, M), merge_sort(M, R), memcpy(b + L, a + L, (R - L) << 3);
	for (; i < M && j < R; a[c++] = (b[i] <= b[j] ? b[i++] : (I += M - i, b[j++])));
	i < M ? memcpy(a + c, b + i, (M - i) << 3) : memcpy(a + c, b + j, (R - j) << 3);
}

