template<class T>
class BinaryIndexedTree{
    int n;
    vector<T> bit;

public:
    BinaryIndexedTree(int _n = 0){
        init(_n);
    }

    BinaryIndexedTree(const vector<T> &v){
        build(v);
    }

    void init(int _n = 0){
        n = _n;
        bit.clear();
        bit.resize(n + 1);
        return;
    }

    void build(const vector<T> &v){
        int _n = v.size();
        init(_n);

        for(int i = 0 ; i < _n ; ++i){
            add(i + 1, v[i]);
        }

        return;
    }

    bool add(int i, T x){
        if(i <= 0 || n < i){
            return false;
        }

        while(i <= n){
            bit[i] += x;
            i += i & -i;
        }

        return true;
    }

    bool update(int i, T x){
        T _x = x - sum(i - 1, i);
        return add(i, _x);
    }

    T sum(int i){
        T s = T(0);
        while(i > 0){
            s += bit[i];
            i -= i & -i;
        }
        return s;
    }

    T sum(int l, int r){
        return sum(r) - sum(l);
    }

    int lower_bound(T x){
        int i = 1, res = 0;
        while((i << 1) <= n){
            i <<= 1;
        }

        while(i > 0){
            if(res + i <= n && bit[res + i] < x){
                x -= bit[res + i];
                res += i;
            }
            i >>= 1;
        }

        return res + 1;
    }

    int upper_bound(T x){
        int i = 1, res = 0;
        while((i << 1) <= n){
            i <<= 1;
        }

        while(i > 0){
            if(res + i <= n && bit[res + i] <= x){
                x -= bit[res + i];
                res += i;
            }
            i >>= 1;
        }

        return res + 1;
    }
};

template<class T>
class CoordinateCompression{
    vector<T> dat;
    int s;

public:
    CoordinateCompression(const vector<T>& dat_, int s_ = 0){
        build(dat_, s_);
    }

    void build(const vector<T>& dat_, int s_ = 0){
        dat = dat_;

        sort(dat.begin(), dat.end());
        dat.erase(unique(dat.begin(), dat.end()), dat.end());

        s = s_;

        return;
    }

    int get(T x){
        return (int)(lower_bound(dat.begin(), dat.end(), x) - dat.begin()) + s;
    }

    T restore(int k){
        return dat[k];
    }
};

