class BinaryIndexedTree {
  int N;
  vl bit;

public:
  BinaryIndexedTree(int N) {
    this->N = N;
    bit = vl(N);
  }

  // v[i] += w;
  void add(int i, int w) {
    for (int x = i; x < N; x |= x + 1) {
      bit[x] += w;
    }
  }

  // v[0] + ... + v[a-1]
  int sum(int a) {
    int ret = 0;
    for (int x = a - 1; x >= 0; x = (x & (x + 1)) - 1) {
      ret += bit[x];
    }
    return ret;
  }
};

