struct BIT {
	vector<int> data;
	BIT(int size) : data(size, 0) {}
	void add(int idx, int x) {
		for (int i = idx; i <= data.size() - 1; i += i & -i)data[i] += x;
	}
	int sum(int idx) {
		int s = 0;
		for (int i = idx; i > 0; i -= i & -i)s += data[i];
		return s;
	}
};

