    bit(int n, T ini) : n(n) { dat.assign(n, ini); }
    // sum [0,i)
    T sum(int i)
    {
        int ret = 0;
        for (--i; i >= 0; i = (i & (i + 1)) - 1)
            ret += dat[i];
        return ret;
    }
    // sum [i,j)
    T sum(int i, int j) { return sum(j) - sum(i); }
    // add x to i
