struct BIT {
    int64_t N;
    vector<int64_t> bit;

public:
    BIT(int64_t size) {
        N = 1LL;
        while(N < size) {
            N <<= 1LL;
        }
        bit.assign(N + 1, 0);
    }

    void add(int x, int64_t w) {
        for(int i = x; i <= N; i += i & (-i)) {
            bit[i] += w;
        }
    }

    int64_t sum(int x) {
        int64_t s = 0LL;
        for(int i = x; i > 0; i -= i & (-i)) {
            s += bit[i];
        }
        return s;
    }

    void clear() {
        bit.clear();
    }

    void debug() {
        for(int i = 1; i <= N; i++) {
            cout << ' ' << sum(i);
        }
        cout << endl;
    }
};

