    rep(i, N){
        sum[i+1] = A[i] + sum[i];
    }

    vl cp = sum; sort(ALL(cp));
    cp = uniquen(cp);
    vl comp(N+1);
    rep(i, N+1){
        comp[i] = lower_bound(ALL(cp), sum[i]) - cp.begin();
    }

    auto seg = SegmentTree<ll> (N+1,
                                [](const ll a, const ll b){
                                    return a+b;
                                },
                                0);

    ll ans = 0;
    for(ll i = N; i >= 0; i--){
        ans += seg.query(comp[i], N+1);
        seg.update(comp[i], seg[comp[i]]+1);
    }
    cout << ans << endstr;
    return 0;
}

