int compress(vector<ll> &x)
{
    vector<ll> tmp = x;
    sort(tmp.begin(), tmp.end());
    tmp.erase(unique(tmp.begin(), tmp.end()), tmp.end());

    rep(i, x.size()) {
        x[i] = lower_bound(tmp.begin(), tmp.end(), x[i]) - tmp.begin() + 1;
    }

    return tmp.size();
}

template<class T>
class BIT {
    int n;
    vector<T> dat;

public:
    BIT(int _n) : n(_n), dat(vector<T>(_n+1)) {}

    void add(int i, T x)
    {
        while (i <= n) {
            dat[i] += x;
            i += i & -i;
        }
    }

    T sum(int i)
    {
        T res = 0;
        while (i > 0) {
            res += dat[i];
            i -= i & -i;
        }
        return res;
    }

    // [l, r]
    T sum(int l, int r)
    {
        return sum(r) - sum(l-1);
    }
};

