	FOR(i, 1, n) {
		if (ss[i] >= 0) ans++;
		ss[i] = lower_bound(v.begin(), v.end(), ss[i]) - v.begin() + 1;
		ans += query(ss[i]);
		update(ss[i], n, 1);
	}
	cout << ans;
}

