long long cal(long long s[], int nn) {
    if (nn == 1) return 0;
    long long s1[nn/2+2], s2[nn/2+2];
    for(int i = 1; i <= nn/2; ++i) s1[i] = s[i];
    for(int i = nn/2+1; i <= nn; ++i) s2[i-nn/2] = s[i];
    long long ans1 = cal(s1, nn/2);
    long long ans2 = cal(s2, nn-nn/2);
    sort(s1+1, s1+1+nn/2);
    long long ans3 = 0;
    for(int i = 1; i <= nn-nn/2; ++i) {
        int inf = 1, sup = nn/2, mid, tt = 0;
        while (inf <= sup) {
            mid = inf + sup >> 1;
            if (s1[mid] <= s2[i]) {
                tt = mid;
                inf = mid + 1;
            } else sup = mid - 1;
        }
        ans3 += tt;
    }
    return ans1 + ans2 + ans3;
}
