const int SIZE = 1 << 18;
struct segtree {
    vector<ll> node;
    segtree() {
        node = vector<ll>(2*SIZE);
    }
    void update(int x) {
        x += SIZE - 1;
        node[x]++;
        while(x > 0) {
            x = (x - 1) / 2;
            node[x] = node[2*x+1] + node[2*x+2];
        }
    }
    ll query(int a, int b, int l=0, int r=SIZE, int k=0) {
        if(b <= l || r <= a) return 0;
        if(a <= l && r <= b) return node[k];
        int mid = (l + r) / 2;
        ll vl = query(a, b, l, mid, 2*k+1);
        ll vr = query(a, b, mid, r, 2*k+2);
        return vl + vr;
    }
};

segtree seg;
int main() {
    ll N, K; scanf("%lld%lld", &N, &K);
    ll sum = 0;

    vector<ll> A(N);
    map<ll, int> comp;
    comp[0] = 0;
    for(int i=1; i<=N; i++) {
        ll val; scanf("%lld", &val);
        sum += val;
        A[i-1] = sum - i*K;
        comp[ A[i-1] ]++;
    }

    int idx = 0;
    for(auto &x : comp) {
        x.second = idx++;
    }

    ll ans = 0;
    seg.update( comp[0] );
    for(int i=0; i<N; i++) {
        int k = comp[ A[i] ];
        ans += seg.query(0, k+1);
        seg.update(k);
    }

    printf("%lld\n", ans);
    return 0;
}

