int srch(int nd, long long ll, long long rr)
{
	if(Left[nd]>=ll && Right[nd]<=rr)
		return Tree[nd];
	if(Left[nd]>rr || Right[nd]<ll)
		return 0;
	int c1 = srch(2*nd, ll, rr);
	int c2 = srch(2*nd+1, ll, rr);
	return c1+c2;
}

int find_tree(long long v)
{
	int nd = 1;
	//int cc = srch(nd, -1000000000, v);
	int cc = srch(nd, sum3[0], v);
	return cc;
}

void add_tree(long long v)
{
	int l=0, r=NN-1;
	int mm;
	while(l<=r){
		mm = (l+r)/2;
		if(sum3[mm] == v)
			break;
		else if(sum3[mm] < v)
			l = mm+1;
		else
			r = mm-1;
	}
	int nd = mm+n;
	while(nd>=1){
		Tree[nd] ++;
		nd /= 2;
	}
}

