class Bit {
private:
  size_t arraySize;
  int *dataArray;
public:
  Bit(size_t size) {
    arraySize = size + 1;
    dataArray = new int[arraySize + 1];
    for(int i = 0; i < arraySize; i++) {
      dataArray[i] = 0;
    }
  }

  void add(size_t position, int value) {
    for(; position < arraySize; position += (position & -position)) {
      dataArray[position] += value;
    }
  }

  int sum(size_t position) {
    int ret = 0;
    for(; position > 0; position -= (position & -position)) {
      ret += dataArray[position];
    }
    return ret;
  }
};

void compressVector(vector<int> &v) {
  vector<int> sorted(v);
  sort(sorted.begin(), sorted.end());
  unordered_map<int, int> keyTable;
  for(int i = 0; i < v.size(); i++) {
    keyTable[sorted[i]] = i;
  }
  for(int i = 0; i < v.size(); i++) {
    v[i] = keyTable[v[i]] + 1;
  }
}


