void ins(int x,LL l,LL r,LL v)
{
	T[x].sum++;
	if (l == r) return;
	LL mid = (l+r) >> 1;
	if (v <= mid)
	{
		if (!T[x].ls)
			T[x].ls = ++cnt;
		ins(T[x].ls,l,mid,v);
	}
	else
	{
		if (!T[x].rs)
			T[x].rs = ++cnt;
		ins(T[x].rs,mid+1,r,v);
	}
}

LL query(int x,LL l,LL r,LL v)
{
	if (l == r) return T[x].sum;
	LL mid = (l + r) >> 1;
	if (v <= mid)
		return query(T[x].ls,l,mid,v);
	else
		return T[T[x].ls].sum + query(T[x].rs,mid+1,r,v);
}

