    ios_base::sync_with_stdio(false);
    return body(argc, argv);
}
int body(int &argc, char **argv) {
    auto N = read<i64>();
    auto K = read<i64>();
    auto as = read<i64>(N);
    FORE (a, as) {
        a -= K;
    }

    auto sum = V<i64>(N);
    REP (i, N) {
        if (i == 0) {
            sum[i] = as[i];
        } else {
            sum[i] = sum[i - 1] + as[i];
        }
    }

    // メモ：転倒数

    // 座標圧縮
    auto xs = sum;
    xs.push_back(0);
    sort(xs.begin(), xs.end());
    auto m = unordered_map<i64, i64>();
    m.reserve(N + 1);
    i64 n = 0;
    REP (i, xs.size()) {
        auto x = xs[i];
        if (m.find(x) == m.end()) {
            m.insert({x, n});
            n += 1;
        }
    }

    i64 result = 0;
    BIT<i64> bit(N);
    bit.add(m.find(0)->second, 1);
    REP (i, N) {
        auto a = sum[i];
        auto b = m.find(a)->second;
        result += bit.sum(b + 1);
        bit.add(b, 1);
    }

    cout << result << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
#define rep(i, N) for (int i = 0; i < (int)N; i++)

class BIT {
private:
  int n;
  vector<int> bit;

public:
  BIT(int _n) {
    n = _n;
    bit = vector<int>(n, 0);
  }

  int sum(int i) {
    int s = 0;
    while(i > 0) {
      s += bit[i];
      i -= i & (-i);
  }
    return s;
  }

  void add(int i, int val) {
    while(i <= n) {
      bit[i] += val;
      i += i & (-i);
    }
  }

  ~BIT() {
    vector<int> tv;
    bit.swap(tv);
  }
};

int main () {
  int n, k;
  scanf("%d%d", &n, &k);

  vector<ll> s(n+1);

  s[0] = 0;
  rep(i,n) {
    int a;
    scanf("%d", &a);
    s[i+1] = s[i] + (a - k);
  }

  vector<ll> ss(s);
  sort(ss.begin(), ss.end());

  // map {s} to [1, n+1]
  // BIT operations: O(log(s_max)) -> O(log(n))
  for(int i = 0; i <= n; i++) {
    s[i] = distance(ss.begin(), lower_bound(ss.begin(), ss.end(), s[i])) + 1;
  }

  BIT bit(n+2);
  ll c = 0;
  for(int i = n; i >= 0; i--) {
    c += bit.sum(s[i] - 1);
    bit.add(s[i], 1);
  }

  printf("%lld\n", ll(n)*(n+1)/2 - c);

  return 0;
}

