#define int ll

int a[N], pref[N];

vector <pair <int, int> > v;

int ans = 0;
int t[N];

int get(int pos) {
	int ans = 0;
	for (; pos >= 0; pos = (pos & (pos + 1)) - 1)
		ans += t[pos];
	return ans;
}

void upd(int pos, int x) {
	for (; pos <= N; pos = (pos | (pos + 1)))
		t[pos] += x;
}

int calc(int l, int r) {
	return get(r) - get(l - 1);
}

void solve() {
	int n, k;
	cin >> n >> k;
	for (int i = 0; i < n; ++ i)
		cin >> a[i];
	for (int i = 1; i <= n; ++ i)
		pref[i] = pref[i - 1] + a[i - 1];
	for (int i = 0; i <= n; ++ i)
		pref[i] -= (i * k);
	for (int i = 0; i <= n; ++ i)
		v.eb(mkp(pref[i], i));
	sort(all(v));
	int cnt = 0;
	for (int i = 0; i < sz(v); ++ i) {
		if (v[i].first > v[i - 1].first and i > 0)
			++cnt;
		pref[v[i].second] = cnt;
	}
	int res = 0;
	for (int i = 0; i <= n; ++ i) {
		res += calc(0, pref[i]);
		upd(pref[i], 1);
	}
	cout << res << '\n';
}

main() {
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	solve();
	return 0;
}

