inline int gi(){
  char ch=getchar();int x=0,q=0;
  while(ch<'0' || ch>'9') ch=='-'?q=1:0,ch=getchar();
  while(ch>='0' && ch<='9') x=x*10+ch-'0',ch=getchar();
  return q?(-x):x;
}
struct date{
  ll s; int l,r,siz,p;
}tr[N];
ll sum,ans;
int rt;
int getrk(int x,ll s){
  if (!x) return 0;
  if (tr[x].s<=s)
    return getrk(tr[x].r,s)+tr[tr[x].l].siz+1;
  return getrk(tr[x].l,s);
}
void update(int x){
  tr[x].siz=tr[tr[x].l].siz+tr[tr[x].r].siz+1;
  return;
}
date split(int x,int k){
  if (!x) return (date){0,0};
  date p;
  if (tr[tr[x].l].siz+1<=k){
    p=split(tr[x].r,k-tr[tr[x].l].siz-1);
    tr[x].r=p.l,p.l=x;
  }
  else{
    p=split(tr[x].l,k);
    tr[x].l=p.r,p.r=x;
  }
  return update(x),p;
}
int merge(int x,int y){
  if (!x||!y) return x+y;
  if (tr[x].p<tr[y].p){
    tr[x].r=merge(tr[x].r,y);
    return update(x),x;
  }
  else{
    tr[y].l=merge(x,tr[y].l);
    return update(y),y;
  }
}
int main(){
  srand(19260817);
  int n=gi(),k=gi(),r,h;
  date g;
  rt=1;
  for (int i=2; i<=n+1; ++i){
    sum+=(h=gi()-k);
    tr[i]=(date){sum,0,0,1,rand()};
    r=getrk(rt,sum);
    ans+=getrk(rt,sum);
    g=split(rt,r);
    rt=merge(g.l,merge(i,g.r));
  }
  cout<<ans;
  return 0;
}

