    B.resize(N + 1);
    B[0] = 0;
    for(int i=0;i+1<=N;++i){
        B[i+1] = B[i] + A[i];
    }

    for(int i=0;i<=N;++i){
        B[i] -= 1ll * i * K;
        A[i] = B[i];
    }

    sort(B.begin(), B.end());
    B.erase(unique(B.begin(), B.end()), B.end());

    for(int i=0;i<=N;++i){
        A[i] = lower_bound(B.begin(), B.end(), A[i]) - B.begin();
    }

    ll res = 0ll;
    for(int i=0;i<=N;++i){
        res += segtree.query(0, A[i] + 1);
        segtree.update(A[i], segtree.query(A[i], A[i]+1) + 1);
    }

    std::cout << res << std::endl;
}

