    i -= i & -i; // xの下のビットをみる
  }
  return s;
}

void add(int i,ll x){
  // 親に更新伝えて行く
  while(i <= n){
    bit[i] += x;
    i += i & -i; // xのもっとも下の立っている最も下のビット
  }
}

void cocomp(VLL &v){
    VLL p(v);
    sort(all(p));
    map<ll,ll> mp;
    ll cnt = 1;
    int n = v.size();
    rep(i,n){
        if(mp[p[i]] != 0){
            continue;
        }else{
            mp[p[i]] = cnt;
            cnt++;
        }
    }
    rep(i,n){
        v[i] = mp[v[i]];
    }
}


