typedef long long ll;
int N, K, Xn;
vector<int> arr;
vector<ll> X;
map<ll, int> dx;

struct BIT {
    vector<int> tree;
    void init() {
        tree = vector<int>(4*Xn, 0);
    }
    void upd(int idx, int val, int l, int r, int n) {
        if(idx < l || r < idx) return;
        if(l == r) {
            tree[n] += val;
            return;
        }
        int m = (l + r)>>1;
        upd(idx, val, l, m, 2*n);
        upd(idx, val, m + 1, r, 2*n + 1);
        tree[n] = tree[2*n] + tree[2*n + 1];
    }
    int quer(int a, int b, int l, int r, int n) {
        if(b < l || r < a) return 0;
        if(a <= l && r <= b) return tree[n];
        int m = (l + r)>>1;
        int L = quer(a, b, l, m, 2*n);
        int R = quer(a, b, m + 1, r, 2*n + 1);
        return L + R;
    }
} bit;

int main() {
    scanf("%d %d", &N, &K);
    arr.resize(N);
    for(int i = 0; i < N; i++) {
        scanf("%d", &arr[i]);
        arr[i] -= K;
    }
    X.resize(N);
    for(int i = N - 1; i >= 0; i--) {
        X[i] = -arr[i];
        if(i != N - 1) X[i] += X[i + 1];
    }
    X.push_back(0);
    sort(X.begin(), X.end());
    X.resize(unique(X.begin(), X.end()) - X.begin());
    Xn = X.size();
    for(int i = 0; i < Xn; i++) dx[ X[i] ] = i;

    bit.init();
    ll offset = 0;
    ll ans = 0;

    for(int i = N - 1; i >= 0; i--) {
        bit.upd(dx[ -offset ], 1, 0, Xn - 1, 1);
        offset += arr[i];
        ans += bit.quer(dx[ -offset ], Xn - 1, 0, Xn - 1, 1);
    }

    printf("%lld", ans);
}

