using namespace std;
const int size=1e6+10;
const int INF=1e9;
typedef long long LL;
LL tree[size];
int a[size];
int b[size];
int lowbit(int x)
{
    return x&(-x);
}
void update(int x)
{
    while(x<size)
    {
        tree[x]+=1;
        x+=lowbit(x);
    }
}
LL ask(int x)
{
    LL sum=0;
    while(x)
    {
       sum+=tree[x];
       x-=lowbit(x);
    }
    return sum;
}
int main()
{
   int n,p;
   while(scanf("%d%d",&n,&p)!=EOF)
   {
       memset(tree,0,sizeof(tree));
       LL ans=0;
