     for(int i=1;i<=n;i++)
     {
         b[i]-=p;
         b[i]=b[i]+b[i-1];   if(b[i]>=0) ans++;
         a[i-1]=b[i];
     }
     sort(a,a+n);
     int cnt=unique(a,a+n)-a;
     LL temp=lower_bound(a,a+cnt,b[1])-a+2;;
     update(temp);
     for(int i=2;i<=n;i++)
     {
          temp=lower_bound(a,a+cnt,b[i])-a+2;
          ans+=ask(temp);
          update(temp);
     }
