template<typename T>
struct BIT {
    int n, p;
    vector<T> d;
    BIT(int n=0) : n(n), d(n+1) {
        p = 1;
        while (p < n) p *= 2;
    }
    void add(int i, T x=1) {
        for (i++; i <= n; i += i&-i) d[i] += x;
    }
    //[0, i)
    T sum(int i) {
        T res = 0;
        for (; i; i -= i&-i) res += d[i];
        return res;
    }
    //[a, b)
    T sum(int l, int r) { return sum(r) - sum(l);} 
    // v0 + v1 + v2 + ... + vx　>= w となる最小のxを求める
    int lower_bound(T w) {
        if (w <= 0) return 0;
        int x = 0;
        for (int i = p; i; i /= 2) {
            if (i+x <= n && d[i+x] < w) {
                w -= d[i+x];
                x += i;
            }
        }
        return x;
    }
};

