	}
	for (int i = 0;i < a.size();++i) {
		if (summing[i] >= 0) ans++;
	}
	map<long long, long long> appeared;
	sort(summing.begin(), summing.end());
	int cnter = 0;
	for (int i = 0;i < a.size();++i) {
		if (appeared[summing[i]] == false){
			zip[summing[i]] = cnter;
			unzip[cnter] = summing[i];
			cnter++;
			appeared[summing[i]] = true;
		}
	}
	long long seg_size = 262144;
	for (int i = 0;i < summing.size();++i) {
		segment_tree[seg_size + zip[summing[i]]]++;
		seg_set((seg_size + zip[summing[i]]) / 2);
	}
	long long deleting = 0;
	for (int i = 0;i < a.size()-1;++i) {
		deleting += a[i];
		segment_tree[seg_size+zip[deleting]]--;
		seg_set((seg_size + zip[deleting]) / 2);
		long long top = cnter-1;
		long long bot = 0;
		while (top - bot > 1) {
			long long mid = (top + bot) / 2;
			if (unzip[mid] >= deleting) {
				top = mid;
			}
			else bot = mid;
		}
		long long consider = 0;
		if (unzip[bot] >= deleting) {
			consider = bot;
		}
		else if (unzip[top] >= deleting) {
			consider = top;
		}
		else goto nya;
		ans += seg_find(0,seg_size,consider,cnter, 1);
		nya:;
	}
	cout << ans << endl;
	return 0;
}

