void init(){
    zerop = k * n - n + 1;
    BIT.assign((a_max - k) * n + zerop + 1, 0);
    maxp = (a_max - k) * n + zerop;
}

void update(int k){
    int s = k + zerop;
    for(int i = s; i <= maxp; i += i & -i){
        BIT[i]++;
    }
}

int getSum(int k){
    int s = k + zerop;
    int sum = 0;
    for(int i = s; i > 0; i -= i & -i){
        sum += BIT[i];
    }
    return sum;
}

