ll segsum(vl&s,int l,int r){
	l|=s.size()/2;
	r|=s.size()/2;
	if(l==r)return s[l];
	ll z=s[l]+s[r];
	for(;l/2<r/2;l/=2,r/=2){
		l&1||(z+=s[l^1]);
		r&1&&(z+=s[r^1]);
	}
	return z;
}
void segadd(vl&s,int i,ll x){
	s[i|=s.size()/2]+=x;
	for(;i/2>=1;i/=2){
		s[i/2]=s[i]+s[i^1];
	}
}
