void update(int pos,int l,int r,int rt)
{
    if(l==r)
    {
        tree[rt].sum++; return ;
    }
    int mid=(l+r)>>1;
    if(pos<=mid) update(pos,l,mid,rt*2);
    else update(pos,mid+1,r,rt*2+1);
