        while (a < bit.size()) {
            bit[a] += c;
            a += lsb(a);
        }
    }

    int64_t get(int64_t a) {
        a++; // 1-based index
        int64_t r = 0;
        while (a > 0) {
            r += bit[a];
            a -= lsb(a);
        }
        return r;
    }
private:
    int64_t lsb(int64_t a) {
        return a & -a;
    }

    vi bit;
};

int bin_search(const vi &v, int l, int r, int64_t x) {
    while (r - l > 1) {
        auto m = l + (r - l) / 2;
        (v[m] >= x ? l : r) = m;
    }
    return l;
}


int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n; int64_t k; std::cin >> n >> k;
    vi v(n);
    for (auto &a : v) std::cin >> a;
    for (auto &a : v) a -= k; // remove k, now positive sum denotes mean > k
    for (int i = 1; i < n; i++) v[i] += v[i-1]; // make cumulative
    // compress to range 0..n-1
    auto c = v;
    v.push_back(0); n++; // make it possible to lookup zero
    sort(v.begin(), v.end(), std::greater<int64_t>());
    for (auto &a : c) a = bin_search(v, 0, n, a);
    BIT bit(n);
    for (auto &a : c) bit.inc(a, 1);

    int64_t r = bit.get(bin_search(v, 0, n, 0));
    for (auto &a : c) {
        bit.inc(a, -1);
        r += bit.get(a);
    }

    std::cout << r << std::endl;
}

