    ll i = 0, j = 0;
    rep(k, left, right) {
        if (L[i] <= R[j]) {
            b[k] = L[i++];
        } else {
            b[k] = R[j++];
            cnt += n1 - i;
        }
    }
    return cnt;
}

ll merge_sort(vll &b, ll n, ll left, ll right) {
    if (left+1 < right) {
        ll mid = (left + right) / 2;
        ll ans1 = merge_sort(b, n, left, mid);
        ll ans2 = merge_sort(b, n, mid, right);
        ll ans3 = merge(b, n, left, mid, right);
        return ans1 + ans2 + ans3;
    } else return 0;
}

