template <typename T> map<T, int> coordinate_compression(vector<T> x) {
    sort(x.begin(), x.end());
    x.erase(unique(x.begin(), x.end()), x.end());
    map<T, int> res;
    for (int v : x) res[v] = res.size();
    return res;
}

// Binary Indexed Tree
template <class T> struct BIT {
    vector<T> d;
    BIT(int n) { init(n); }
    void init(int n) { d.assign(n + 1, 0); }
    // a: 1-indexed
    inline void add(int a, T x) {
        for (int i = a; i < (int)d.size(); i += i & -i) d[i] = d[i] + x;
    }
    // [1, a]
    // a: 1-indexed
    inline T sum(int a) {
        T res = 0;
        for (int i = a; i > 0; i -= i & -i) res = res + d[i];
        return res;
    }
    // [a, b)
    // a, b: 1-indexed
    inline T sum(int a, int b) {
        return sum(b - 1) - sum(a - 1);
    }
};

