void mergg(int l,int r);
void merge_sort(int l,int r)
{
    if (l < r)
    {
        int mid = l + ((r-l)>>1);
        merge_sort(l,mid);
        merge_sort(mid+1,r);
        mergg(l,r);
    }
}

void mergg(int l,int r)
{
    ll* b = new ll[r + 1];           
    int mid = l + ((r-l)>>1);

    for (int i = l;i <= r;i++)
        b[i] = f[i];

    ll i = l;
	ll j = mid + 1;
	ll k = l;
    while (i <= mid && j <= r)
    {
        if (b[i] <= b[j])
        {
            f[k++] = b[i++];
        }
        else
        {
            f[k++] = b[j++];
            ans += (mid - i + 1ll);
        }
    }
    while (i <= mid) { f[k++] = b[i++]; }
    while (j <= r)   { f[k++] = b[j++]; }
    delete []b;
}


