void change(int i, int l, int r, int ind){
    if (r - l == 1){
        rmq[i] = 1;
    }
    else{
        int m = (l + r) / 2;
        if (ind < m) change(2*i+1, l, m, ind);
        else change(2*i+2, m, r, ind);
        rmq[i] = rmq[2*i+1] + rmq[2*i+2];
    }
}
int get(int i, int l, int r, int l1, int r1){
    if (l1 >= r1) return 0;
    if (l == l1 && r == r1){
        return rmq[i];
    }
    int m = (l + r) / 2;
    return get(2*i+1, l, m, l1, min(r1, m)) + get(2*i+2, m, r, max(l1, m), r1);
}
