long long segment_tree[1000000] = {};
void seg_set(long long now) {
	segment_tree[now] = segment_tree[now * 2] + segment_tree[now * 2 + 1];
	if (now != 1) seg_set(now / 2);
}
long long seg_find(long long left, long long right, long long want_left, long long want_right, long long now) {
	if (left >= want_right || right <= want_left) return 0;
	if (want_left <= left&&want_right >= right){
		return segment_tree[now];
    }
	return seg_find(left, (left + right) / 2, want_left, want_right, now * 2) + seg_find((left+right) / 2, right, want_left, want_right, now * 2 + 1);
}
