		}
	}
	long long seg_size = 262144;
	for (int i = 0;i < summing.size();++i) {
		segment_tree[seg_size + zip[summing[i]]]++;
		seg_set((seg_size + zip[summing[i]]) / 2);
	}
	long long deleting = 0;
	for (int i = 0;i < a.size()-1;++i) {
