		seg_set((seg_size + zip[deleting]) / 2);
		long long top = a.size() - 1;
		long long bot = 0;
		while (top - bot > 1) {
			long long mid = (top + bot) / 2;
			if (unzip[mid] >= deleting) {
				top = mid;
			}
			else bot = mid;
		}
		long long consider = 0;
		if (unzip[bot] >= deleting) {
			consider = bot;
		}
		else if (unzip[top] >= deleting) {
