struct SegTree {
  ll n_count;
  vector<ll> pos;

  SegTree(const ll N) {
    n_count = 1; while(n_count<N) n_count<<=1;
    pos.assign(2*n_count, 0);
    build();
  }

  ll operator[](const ll &k) const { return pos[k+n_count]; }

  void set(ll k, const ll x) { pos[k+n_count] = x; }
  void build() { for (ll i=n_count-1; i>=0; i--) pos[i] = pos[i*2]+pos[i*2+1]; }
  void update(ll k, const ll x) { set(k,x); k += n_count; while(k >>= 1) pos[k] = pos[k*2]+pos[k*2+1]; }
  ll query(ll a,ll b) {
    ll L = 0, R = 0;
    for ( a+=n_count, b+=n_count; a<b; a>>=1, b>>=1 ) {
      if (a&1) { L+=pos[a]; a++; }
      if (b&1) { b--; R+=pos[b]; }
    }
    return L + R;
  }

};

