template <typename T> struct BinaryIndexedTree {
  BinaryIndexedTree(size_t n) : n(n + 1), v(n + 2) {}

  size_t n;
  vector<T> v;

  T sum(int k) {
    T ret = 0;
    for (++k; k; k -= k & -k) ret += v[k];
    return ret;
  }

  void add(int k, T x) {
    for (++k; k <= n; k += k & -k) v[k] += x;
  }
};

template <typename T> struct Compresser {
  Compresser(vector<T> &v) : formatted(v.size(), -1), zip(v) {
    sort(zip.begin(), zip.end());
    zip.erase(unique(zip.begin(), zip.end()), zip.end());
    for (int i = 0; i < formatted.size(); ++i) {
      formatted[i] = lower_bound(zip.begin(), zip.end(), v[i]) - zip.begin();
    }
  }

  vector<T> zip;
  vector<int> formatted;

  size_t size() {
    return formatted.size();
  }

  inline int operator[](size_t idx) {
    return formatted[idx];
  }

  T unzip(size_t idx) {
    return zip[formatted[idx]];
  }
};

