int BIT[300000];

int Sum(int I)
{
    long long S=0;
    I = 300000-I;
    I -= 2;
    I++;
    while (I > 0)
    {
        S += BIT[I];
        I -= I & (-I);
    }
    return S;
}

void Update(int I)
{
    I = 300000-I;
    I -= 2;
    I++;
    while (I < 300000)
    {
        BIT[I]++;
        I += I & (-I);
    }
}

