        cin >> a[i];
        a[i] -= k;
        s[i] = a[i];
        if(i > 0) s[i] += s[i - 1];
        if(s[i] >= 0) ans++;
        p[i] = P(s[i], i);
    }
    sort(p, p + n);
    int nth[200004];
    for(int i = 0; i < n; i++) nth[p[i].second] = i;
