  vec.erase(unique(vec.begin(),vec.end()),vec.end());

  for(int i=0;i<vec.size();i++){
    mm[vec[i]] = i;
  }

  RMQ seg(n);
  int cc[SIZE] = {};

  for(int i=0;i<=n;i++){
    int p = mm[vec2[i]];
    cc[p]++;
    seg.set(p,cc[p]);
  }

