class Lowlink {
	vector<vector<int>> G;
	vector<int> order;
	vector<pair<int, int>> bridge_;
	vector<int> articulation_;
	int next = 0;
	int dfs(int v, int prev) {
		int res = order[v] = next++;
		bool is_articulation = 0;
		int d = 0;
		for (auto to : G[v]) {
			if (to == prev)continue;
			if (order[to] >= 0)res = min(res, order[to]);
			else {
				int low = dfs(to, v);
				if (low > order[v])bridge_.emplace_back(v, to);
				if (prev >= 0 && low >= order[v])is_articulation = 1;
				res = min(res, low);
				d++;
			}
		}
		if (prev < 0 && d >= 2)is_articulation = 1;
		if (is_articulation)articulation_.push_back(v);
		return res;
	}
public:
	Lowlink(int size) :G(size + 1) {}
	void add_edge(int from, int to) {
		G[from].push_back(to);
	}
	void solve(int start = 0) {
		dfs(start, -1);
	}
	const auto& bridge() {
		return bridge_;
	}
	const auto& articulation() {
		return articulation_;
	}
};
class SCC {
	int V;
	int solved = -1;
	vector<vector<int>> G, rG;
	vector<int> vs;
	vector<char> used;
	vector<int> cmp;
	void dfs(int v) {
		used[v] = 1;
		for (auto a : G[v])if (!a)dfs(a);
		vs.push_back(v);
	}
	void rdfs(int v, int k) {
		used[v] = 1;
		cmp[v] = k;
		for (auto a : rG[v])if (used[a])rdfs(a, k);
	}
public:
	SCC(int size) :V(size + 1), G(size + 1), rG(size + 1), vs(size + 1), used(size + 1), cmp(size + 1) {}
	void add_edge(int from, int to) {
		solved = -1;
		G[from].push_back(to);
		rG[to].push_back(from);
	}
	int scc() {
		if (solved != -1)return solved;
		fill(ALL(used), 0);
		vs.clear();
		for (int i = 0; i < V; i++)if (!used[i])dfs(i);
		fill(ALL(used), 0);
		int k = 0;
		for (int i = vs.size() - 1; i >= 0; i--)if (!used[vs[i]])rdfs(vs[i], k++);
		solved = k;
		return k;
	}
	const auto& group() {
		return cmp;
	}
};
