void solve(int l, int r) {
	if (l == r) {
		if (arr[l].val >= 0)
			ans++;
		return;
	}
	int mid = (l + r) / 2;
	solve(l, mid);
	solve(mid + 1, r);
	int leftIndex = l;
	int rightIndex = r;
	while (leftIndex <= mid && rightIndex >= mid + 1) {
		if (arr[leftIndex].rightValSorted + arr[rightIndex].leftValSorted >= 0) {
			ans += mid - leftIndex + 1;
			rightIndex--;	
		}
		else 
			leftIndex++;
	}
	leftIndex = l;
	rightIndex = mid + 1;
	for (int i = l; i <= r; i++) 
		tmp[i].val = arr[i].val;
