	for (int i = r; i >= mid + 1; i--)
		tmp[i].rightVal = arr[i].rightVal;
	for (int i = mid; i >= l; i--) 
		tmp[i].rightVal = arr[mid + 1].rightVal + arr[i].rightVal;
	while (leftIndex <= mid || rightIndex <= r) {
		if (leftIndex > mid) {
			tmp[leftIndex + rightIndex - (mid + 1)].leftValSorted = arr[mid].leftVal + arr[rightIndex++].leftValSorted;
		}
		else if (rightIndex > r) {
			tmp[leftIndex + rightIndex - (mid + 1)].leftValSorted = arr[leftIndex++].leftValSorted;
		}
		else {
			if (arr[leftIndex].leftValSorted <= arr[mid].leftVal + arr[rightIndex].leftValSorted)
				tmp[leftIndex + rightIndex - (mid + 1)].leftValSorted = arr[leftIndex++].leftValSorted;
			else
				tmp[leftIndex + rightIndex - (mid + 1)].leftValSorted = arr[mid].leftVal + arr[rightIndex++].leftValSorted;			
		}
	}
	leftIndex = l;
	rightIndex = mid + 1;
	while (leftIndex <= mid || rightIndex <= r) {
		if (leftIndex > mid) {
			tmp[leftIndex + rightIndex - (mid + 1)].rightValSorted = arr[rightIndex++].rightValSorted;
		}
		else if (rightIndex > r) {
			tmp[leftIndex + rightIndex - (mid + 1)].rightValSorted = arr[mid + 1].rightVal + arr[leftIndex++].rightValSorted;
		}
		else {
			if (arr[leftIndex].rightValSorted + arr[mid + 1].rightVal <= arr[rightIndex].rightValSorted)
				tmp[leftIndex + rightIndex - (mid + 1)].rightValSorted = arr[leftIndex++].rightValSorted + arr[mid + 1].rightVal;
			else
				tmp[leftIndex + rightIndex - (mid + 1)].rightValSorted = arr[rightIndex++].rightValSorted;			
		}
	}
	for (int i = l; i <= r; i++)
