void solve() {
	ll N,K;
	cin>>N>>K;
	vector<ll> a(N,0);
	rep(i,N)cin>>a[i];

	vector<ll> rui(N+1, 0);
	rep(i,N) rui[i+1] = rui[i] + a[i];

	vector<ll> T(N+1,0);
	rep(i,N+1)T[i]=rui[i]-i*K +2*K*N;

	ll ans=0;
	const ll bitlength = 1 + log2(2e9);
	DynamicWaveletMatrix<ll,bitlength,0LL> dwm;
	rep(i,T.size())dwm.insert(i, T[i]);

	rep(i,N+1){
		ll index=dwm.rangefreq(0, i, 0, T[i]+1);
		ans+=index;
	}

	p(ans);
}

