void ins(int v,ll l,ll r,ll pos){
    t[v].s++;
    if(l==r)return;
    ll mid=(l+r)>>1;
    if(mid>=pos){
        if(t[v].l==0)t[v].l=++cnt;
        ins(t[v].l,l,mid,pos);
    }else{
        if(t[v].r==0)t[v].r=++cnt;
        ins(t[v].r,mid+1,r,pos);
    }
}

void del(int v,ll l,ll r,ll pos){
    t[v].s--;
    if(l==r)return;
    ll mid=(l+r)>>1;
    if(mid>=pos)del(t[v].l,l,mid,pos);
    else del(t[v].r,mid+1,r,pos);
}

int query(int v,ll l,ll r,ll ql,ll qr){
    if(l>=ql&&r<=qr)return t[v].s;
    ll mid=(l+r)>>1;
    int res=0;
    if(mid>=ql)res+=query(t[v].l,l,mid,ql,qr);
    if(mid<qr)res+=query(t[v].r,mid+1,r,ql,qr);
    return res;
}

