typedef long long ll;

class BIT{
public:
	vector<ll> bit;
	int n;
	//1-indexed
	BIT(){init();}
	BIT(int n):n(n){init();}
	void init(){
		bit.clear();
		bit.resize(n+1,0);
	}
	ll sum(int i){
		ll s=0;
		while(i>0){
			s+=bit[i];
			i-=i&-i;
		}
		return s;
	}
	void add(int i,ll x){
		while(i<=n){
			bit[i]+=x;
			i+=i&-i;
		}
	}
	ll sum0(int i){
		return sum(i+1);
	}
	void add0(int i,ll x){
		add(i+1,x);
	}
};

