template<typename T>
int countTranspose(vector<T>& v){
	if(v.size() <= 1) return 0;
	const int n = v.size();
	vector<T> a(v.begin(), v.begin() + n/2);
	vector<T> b(v.begin() + n/2, v.end());
	int res = countTranspose(a) + countTranspose(b);
	int idxA = 0, idxB = 0;
	for(int i=0;i<n;i++){
		if(idxB < b.size() && (idxA == a.size() || a[idxA] > b[idxB])){
			v[idxA+idxB] = b[idxB];
			++idxB;
			res += a.size() - idxA;
		} else {
			v[idxA+idxB] = a[idxA];
			++idxA;
		}
	}
	return res;
}

int main(){
	int N; long long K;
	while(cin >> N >> K){
		vector<long long> l;
		l.push_back(0);
		long long sum = 0;
		for(int i=0;i<N;i++){
			long long a; cin >> a;
			sum += a - K;
			l.push_back(sum);
		}
		cout << (N * (N+1LL) / 2 - countTranspose(l)) << endl;
	}
}

