struct node {
    node *l = 0, *r = 0;
    int key, prior, siz = 0;
    node(int _key) { key = _key, prior = rand(), siz = 1; }
};

typedef pair<node*, node*> pairn;

ll size(node* v) {
    if (!v) return 0;
    else return v->siz;
}
node* rt = 0;

void upd(node* v) {
    if (!v) return;

    v->siz = size(v->l) + size(v->r) + 1;
}
pairn split(node* v, ll x) {
    if (!v) return { 0, 0 };

    if (v->key <= x) {
        pairn q = split(v->r, x);
        v->r = q.first;
        upd(v);
        return { v, q.second };
    }
    else {
        pairn q = split(v->l, x);
        v->l = q.second;
        upd(v);
        return { q.first, v };
    }
}

node* merge(node* l, node* r) {
    if (!l) return r;
    if (!r) return l;

    if (l->prior > r->prior) {
        l->r = merge(l->r, r);
        upd(l);
        return l;
    }
    else {
        r->l = merge(l, r->l);
        upd(r);
        return r;
    }
}

ll find(node* rt, ll val) {
    if (!rt) return 0;

    ll q = 0;
    if (rt->key <= val) {
        q = size(rt->l) + 1 + find(rt->r, val);
    }
    else {
        q = find(rt->l, val);
    }

    return q;
}

void ins(int x) {
    pairn q = split(rt, x);
    node* t = new node(x);
    rt = merge(merge(q.first, t), q.second);
}

