struct BIT{
    int N;
    vector<int> data;

    BIT(int n){
        N = n;
        data.resize(N+1, 0);
    }

    void add(int a, int x){
        for(int i = a; i <= N; i += i & -i)
            data[i] += x;
    }

    int sum(int a){
        int ret = 0;
        for(int x = a; x > 0; x -= x & -x)
            ret += data[x];
        return ret;
    }

};

