		vec.push_back(a[i]);
	}

	sort(vec.begin(),vec.end());

	i64 res = 0;
	i64 now = 0;

	Segment seg(vector<int>(n + 1,0));
	for(int i = 0;i < n;i++)
	{
		int ite = lower_bound(vec.begin(),vec.end(),now) - vec.begin();
		res += n - ite - seg.get_inter(ite,n + 1);
		now = a[i];
		ite = lower_bound(vec.begin(),vec.end(),now) - vec.begin();
		seg.update(ite);
	}

	cout << res << endl;
}

