template<class T>
class segment_tree_t {
public:
  segment_tree_t(int size) : size_(1) {
    while (size_ < size)
      size_ *= 2;

    a_ = new T[size_ * 2];

    memset(a_, 0, sizeof(T) * size_ * 2);
  };

  ~segment_tree_t() {
    delete[] a_;
  };

public:
  void update(int i, T x) {	// 0-index
    i += size_ - 1;

    a_[i] = x;

    while (i > 0) {
      i = (i - 1) / 2;

      a_[i] = a_[i * 2 + 1] + a_[i * 2 + 2];
    }
  };

  T query(int a, int b, int i = -1, int l = -1, int r = -1) {	// [a, b)
    if (i < 0) {
      return query(a, b, 0, 0, size_);
    }
    else {
      if (r <= a || b <= l)
        return 0;

      if (a <= l && r <= b) {
        return a_[i];
      }
      else {
        return
          query(a, b, i * 2 + 1, l, (l + r) / 2) +
          query(a, b, i * 2 + 2, (l + r) / 2, r);
      }
    }
  };

private:
  int size_;

  T* a_;
};


int main(int argc, char** argv)
{
  std::cin.tie(0);
  std::ios_base::sync_with_stdio(0);

  std::cout << std::fixed << std::setprecision(6);

  int N, K, a[222222];

  std::cin >> N >> K;

  for (int i = 0; i < N; i ++)
    std::cin >> a[i];

  long long s = 0, t = 0;

  std::multiset<long long> set;

  segment_tree_t<int> tree(N + 1);

  for (int i = 0; i < N; i ++) {
    s += a[i];
    t += K;

    set.insert(s - t);

    tree.update(i, 1);
  }

  std::map<long long, std::vector<int>> map;

  int ind = 0;

  for (const auto& i : set)
    map[i].push_back(ind ++);

  s = t = 0;

  long long c = 0;

  for (int i = 0; i < N; i ++) {
    auto it = set.lower_bound(s - t);

    if (it != std::end(set)) {
      assert(! map[*it].empty());

      c += tree.query(map[*it].back(), N);
    }

    s += a[i];
    t += K;

    set.erase(set.find(s - t));

    assert(! map[s - t].empty());

    int x = map[s - t].back(); map[s - t].pop_back();

    tree.update(x, 0);
  }

  std::cout << c << std::endl;

  return 0;
}

