template <typename T>
struct BIT {
    int N;
    vector<T> bit;

    BIT (int N) {
        this -> N = N;
        for (int i = 0; i <= N; i++) {
            bit.push_back(0);
        }
    }

    /*
     * a_1 + a_2 + ... + a_n
     * O(log n)
     */
    T sum (int n) {
        T ret = 0;
        while (n > 0) {
            ret += bit[n];
            // nの最後の1のビットに対応する数を引く
            // ex) 0110 -> 0100 (= 0110 - 0010)
            n -= n & -n;
        }
        return ret;
    }

    /*
     * a_n += x
     * O(log n)
     */
    void add (int n, T x) {
        while (n <= N) {
            bit[n] += x;
            // nの最後の1のビットに対応する数を足す
            // ex) 0101 -> 0110 (= 0101 + 0001)
            n += n & -n;
        }
    }
};

