class CoordinateCompression {
public:
    unordered_map<long long, int> zip;    // 元の値 ->　圧縮した値
    unordered_map<int, long long> unzip;  // 圧縮した値 -> 元の値

    CoordinateCompression(const vector<long long> &v) {
        set<long long> s(v.begin(), v.end());

        int no = 0;
        for (long long x : s) {
            zip[x] = no;
//            zip[x] = x;
            unzip[no] = x;
            ++no;
        }
    }
};

class BinaryIndexedTree {
public:
    unsigned int n = 0; // (a.size() - 1)
    vector<long long> a;

    BinaryIndexedTree(unsigned int n) : n(n) {
        this->a = vector<long long>(n + 1, 0);
    }

    // sum[0, i)
    long long sum(int i) {
        assert(0 <= i && i <= this->n);

        long long s = 0;
        i -= 1;
        while (i >= 0) {
            s += this->a[i];
            i = (i & (i + 1)) - 1;
        }
        return s;
    }

    // sum[left, right)
    long long sum(int left, int right) {
        assert(left <= right);
        return this->sum(right) - this->sum(left);
    }

    // a[i] += x(0-origin)
    void add(int i, int x) {
        assert(0 <= i && i < this->n);

        while (i < this->n) {
            this->a[i] += x;
            i |= i + 1;
        }
    }
};


int solve(LL N, LL K, const vector<LL> &A) {

    vector<LL> cs(A.size() + 1, 0);
    FOR(i, 0, A.size()) {
        cs[i + 1] = cs[i] + (A[i] - K);
    }

    CoordinateCompression cc(cs);

    int ans = 0;
    BinaryIndexedTree bit(N + 10);
    FOR(i, 0, cs.size()) {
        int x = cc.zip[cs[i]];
        ans += bit.sum(x + 1);
        bit.add(x, 1);
    }
    cout << ans << endl;
}


