const int N = (int) 1e5 + 5;
const int INF = (int) 1e9 + 9;

int n, k;
int a[N];
int cnt[N][2];
int fw[N][2];

void compress() {
	vector <int> zip; zip.push_back(-INF);
	for (int i = 0; i <= n; i++) {
		zip.push_back(cnt[i][1] - cnt[i][0]);
	}
	sort(zip.begin(), zip.end());
	zip.resize(distance(zip.begin(), unique(zip.begin(), zip.end())));
	for (int i = 0; i <= n; i++) {
		a[i] = lower_bound(zip.begin(), zip.end(), cnt[i][1] - cnt[i][0]) - zip.begin();
	}
}

void upd(int i, int idx) {
	for (; i <= n + 1; i += i & -i) fw[i][idx]++;
}

long long get(int i, int idx) {
	long long r = 0;
	for (; i >= 1; i -= i & -i) r += fw[i][idx];
	return r;
}

int main() {
	//freopen(".inp", "r", stdin); freopen(".out", "w", stdout);
	scanf("%d %d", &n, &k);
	for (int i = 1; i <= n; i++) {
		int v; scanf("%d", &v);
	 	(v >= k) ? v = 1 : v = 0;
	 	for (int x = 0; x < 2; x++) cnt[i][x] = cnt[i - 1][x];
	 	cnt[i][v]++;
	}
	compress();
	long long ans = 0;
	upd(a[0], 0);
	for (int i = 1; i <= n; i++) {
		if (i & 1) {
			ans += get(a[i], 0);
			ans += get(a[i] - 1, 1);
		} else {
			ans += get(a[i] - 1, 0);
			ans += get(a[i], 1);
		}
		upd(a[i], (i & 1));
	}
	printf("%lld\n", ans);
	return 0;
}

