// range sum query using segment tree

class segment_tree {
	vector<long> t;
	long size;
public:
	segment_tree() {
	}

	segment_tree(long n) {
		t.assign(4 * n + 1, 0);
		size = n;
	}

	void initialize(long n) {
		t.assign(4 * n + 1, 0);
		size = n;
	}

	void initialize_with_array(long startpos, long l, long r, vector<int>& v) {
		if (l == r) {
			t[startpos] = v[l];
		}
		else {
			long m = (l + r) / 2;
			initialize_with_array(2 * startpos, l, m, v);
			initialize_with_array(2 * startpos + 1, m + 1, r, v);

			t[startpos] = t[startpos * 2] + t[startpos * 2 + 1];
		}
	}

	void initialize_array(vector<int>& v) {

		initialize_with_array(1, 0, size - 1, v);
	}


	void update(long index, long val) { // insert val into location index
		update_full(1, 0, size - 1, index, val);
	}

	void update_full(long startpos, long l, long r, long index, long val) {
		if (l > r) return;
		if (l == r) {
			t[startpos] += val;
		}
		else {
			long m = (l + r) / 2;
			if (index <= m) update_full(2 * startpos, l, m, index, val);
			else update_full(2 * startpos + 1, m + 1, r, index, val);

			t[startpos] = t[startpos * 2] + t[startpos * 2 + 1];	// range sum
		}
	}

	long query(long l, long r) {  // get range min/max between l and r
		if (l > r) {
			return 0;
		}
		return query_full(1, 0, size - 1, l, r);
	}

	long query_full(long startpos, long left, long right, long l, long r) {	 // left/right = current range, l/r = intended query range
		if ((left >= l) && (right <= r)) return t[startpos];
		long m = (left + right) / 2, ans = 0;
		if (m >= l) {
			ans += query_full(startpos * 2, left, m, l, r);
		}
		if (m + 1 <= r) {
			ans += query_full(startpos * 2 + 1, m + 1, right, l, r);
		}
		return ans;
	}
};

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);

	long long n, i, j, k, ans = 0;
	cin >> n >> k;
	vector<long long> s(n + 1, 0), a(n + 1);
	for (i = 1; i <= n; i++) {
		cin >> a[i];
		a[i] -= k;
		s[i] = s[i - 1] + a[i];
	}
	vector<pair<long long, long long>> plist(n + 1);
	for (i = 0; i <= n; i++) plist[i] = { s[i], i };
	sort(plist.begin(), plist.end());

	segment_tree st(n + 1);
	for (i = 0; i <= n; i++) {
		ans += st.query(0, plist[i].second - 1);
		st.update(plist[i].second, 1);
	}

	cout << ans << "\n";


	return 0;
}

