class FenwickTree {
private:
    long long t[maxN];
public:
    void update(int x) {
        for (; x < maxN; x += x & -x)
            t[x]++;
    }
    long long get(int x) {
        long long res = 0;
        for (; x > 0; x -= x & -x)
            res += t[x];
        return res;
    }
} bit;

void Enter() {
    scanf("%d%d", &n, &k);
    for (int i = 1; i <= n; ++i) scanf("%d", a + i);
}

void Init() {
    b[0] = c[0] = -k;
    for (int i = 1; i <= n; ++i) {
        b[i] = b[i - 1] + a[i] - k;
        c[i] = b[i];
    }
    sort(c, c + n + 1);
    for (int i = 0; i <= n; ++i) b[i] = lower_bound(c, c + n + 1, b[i]) - c + 1;
}

void Process() {
    long long answer = 0;
    bit.update(b[0]);
    for (int i = 1; i <= n; ++i) {
        answer += bit.get(b[i]);
        bit.update(b[i]);
    }
    printf("%lld\n", answer);
}

