class Node {
public:
  explicit Node(int64_t v) : val(v) {}

  int64_t val;
  uint64_t count = 0;

  Node *left = nullptr;
  Node *right = nullptr;

  uint64_t insert(int64_t n) noexcept {
    if (n < val) {
      ++count;
      return left->insert(n);
    }
    else if (n == val)
      return count++;
    else
      return count + right->insert(n);
  }
};

Node *build(const vector<int64_t> &v, size_t b, size_t e) {

  size_t mid = b + (e - b) / 2;

  Node *ret = new Node(v[mid]);

  if (mid == b)
    return ret;

  ret->left = build(v, b, mid);

  if (mid + 1 < e)
    ret->right = build(v, mid + 1, e);

  return ret;
}

