	vector<ll> arr(n);
	for(auto& i: arr) cin >> i;

	/*
	 * count of (i,j) st \Sigma{arr[i..j]} / (j - i + 1) >= k
	 *                => presum(j) - presum(i - 1) >= [k * j] - [k * (i - 1)]
	 *                => presum(j) - [k * j] >= presum(i - 1) - [k * (i - 1)]
	 */

	// vec(i) = presum(i) - (k * i)
	vector<ll> vec(n + 1, 0);
	for(int i = 1; i <= n; ++i) vec[i] = arr[i - 1] + vec[i - 1];
	for(int i = 1; i <= n; ++i) vec[i] -= (ll)k * i;

	// ANS = no of inversions in vec (!!)
	ll cou = 0;

	FenwickTree<int> fen{compress(vec)};
	fen.add(vec.front(), 1);

	for(int i = 1; i <= n; ++i){
		cou += fen.sum(vec[i]);
		fen.add(vec[i], 1);
	}

	cout << cou << "\n";
}

