    };
    SegmentTree(int n, Node o) : o0(o), n(n) {
        for (m = 2; m < n; m *= 2);
        st = vector<Node>(m * 2, o0);
    }
    void construct() {
        for (int k = m; k > 1; k /= 2) {
            for (int i = k / 2; i < k; i++) {
                st[i] = st[i * 2] + st[i * 2 + 1];
            }
        }
    }
    void update(int i, const Node& o) {
        for (st[i += m] = o; i /= 2, i > 0;) st[i] = st[i * 2] + st[i * 2 + 1];
    }
    Node query(int i0, int i1, int i, int k, int w) {
        if (i1 - i0 == w) return st[i];
        int l = k + w / 2;
        Node o;
        if (i0 < l) o =     query(i0, min(i1, l), i * 2 + 0, k, w / 2); else o = o0;
        if (l < i1) o = o + query(max(l, i0), i1, i * 2 + 1, l, w / 2);
        return o;
    }
    vector<Node> st;
    Node o0;
    int n, m;
};

