                size <<= 1;
            }

            unit = u;
            func = f;

            init();
        }
        void init(){
            for(int i=0;i<size;++i){
                data[i+size] = unit;
            }

            for(int i=size-1;i>0;--i){
                data[i] = func(data[i*2], data[i*2+1]);
