long long compute(const vector<long long>& a) {
    int n = a.size();
    vector<long long> b ( a );
    sort(b.begin(), b.end());
    b.erase(unique(b.begin(), b.end()), b.end());
    unordered_map<long long, int> dic;
    for (int i = 0; i < b.size(); ++ i) {
        dic[b[i]] = i + 1;
    }
    long long res = 0;
    vector<int> count(b.size() + 1, 0);
    for (auto val : a) {
        int index = dic[val];
        while (index) {
            res += count[index];
            index -= lowbit(index);
        }
        index = dic[val];
        while (index <= b.size()) {
            count[index] ++;
            index += lowbit(index);
        }
    }
    return res;
}

