	sortall(comp);
	map<i64, i64> m;
	upto(0, n, i) {
		if (m.find(comp[i]) == m.end()) {
			m.insert(make_pair(comp[i], m.size()));
		}
	}
	i64 ans = 0;
	fenwicktree tree(n + 1);
	upto(0, n, i) {
		i64 c = m.at(b[i]);
		ans += tree.sum(c);
		tree.add(c, 1);
	}
	out(ans);
	return 0;
}

