/* RangeMinimumQuery(0-index) */

struct RMQ{
  typedef int Type;
  int segn2;
  Type inf;
  vector<Type> data;

  RMQ(int n){
    inf = 0; //init value
    for(segn2=1;segn2<n;segn2*=2);
    data.assign(segn2*2,inf);
  }

  //get minimum value [a,b]
  Type query(int a,int b,int l=0,int r=-1,int k=0){
    if(r==-1) r+=segn2;
    if(a<=l && r<=b) return data[k];
    if(r<a || b<l) return inf;
    return (query(a,b,l,(l+r)/2,k*2+1)+query(a,b,(l+r)/2+1,r,k*2+2));
  }

  //set kth number x
  void set(int k,Type x){
    k+=segn2-1;
    data[k]=x;
    while(k>0){
      k=(k-1)/2;
      data[k]=(data[k*2+1]+data[k*2+2]);
    }
    return;
  }
};




int main(){
  int n,k;
  int a[SIZE];
  ll sum[SIZE] = {};
  vector<ll> vec;
  vector<ll> vec2;
  map<ll,int> mm;

  scanf("%d%d",&n,&k);

  for(int i=1;i<=n;i++){
    scanf("%d",a+i);
    a[i] -= k;
    sum[i] = a[i];
  }

  for(int i=0;i<=n;i++){
    sum[i+1] += sum[i];
    vec.push_back(sum[i]);
  }

  vec2 = vec;

  sort(vec.begin(),vec.end());
  vec.erase(unique(vec.begin(),vec.end()),vec.end());

  for(int i=0;i<vec.size();i++){
    mm[vec[i]] = i;
  }

  RMQ seg(n+1);
  int cc[SIZE] = {};

  for(int i=0;i<=n;i++){
    int p = mm[vec2[i]];
    cc[p]++;
    seg.set(p,cc[p]);
  }

  ll ans = 0;

  for(int i=0;i<n;i++){
    int p = mm[sum[i]];

    cc[p]--;
    seg.set(p,cc[p]);

    ans += seg.query(p,INF);
  }


  cout << ans << endl;

  return 0;
}

