void upd(int idx,int l,int r,int in,int di,int t){
	if(in>r || in<l)return;
	if(l==r){
		if(t==1)maks[idx]=pref[di];
		if(t==1)tree[idx]++;
		else tree[idx]--;
		return;
	}
	upd(idx*2,l,MID,in,di,t);
	upd(idx*2+1,MID+1,r,in,di,t);	
	tree[idx]=(tree[idx*2]+tree[idx*2+1]);
	maks[idx]=max(maks[idx*2],maks[idx*2+1]);
}

int cari(int idx,int l,int r,long long val){
	if(l==r && maks[idx]>=val)return tree[idx];
	if(l==r)return 0;
	if(maks[2*idx]>=val)return cari(idx*2,l,MID,val)+tree[2*idx+1];
	return cari(2*idx+1,MID+1,r,val);
}

