struct BIT {
    BIT(int n) : s(n + 1), n(n) {}
    int sum(int k) {
        int r = 0;
        for (; k > 0; k -= k & -k) r += s[k];
        return r;
    }
    void add(int i, int v) {
        for (int k = i + 1; k <= n; k += k & -k) s[k] += v;
    }
    vector<int> s;
    int n;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, k;
    cin >> n >> k;

    vector<int64_t> b(n + 1);
    for (int i = 0; i < n; i++) {
        int a;
        cin >> a;
        b[i + 1] = b[i] + (a - k);
    }

    vector<int> c(n + 1);
    for (int i = 0; i <= n; i++) {
        c[i] = i;
    }
    sort(c.begin(), c.end(), [&](int i0, int i1) {
        return b[i0] < b[i1];
    });

    vector<int> d(n + 1);
    int m = 0;
    for (int i = 0; i <= n; i++) {
        if (i > 0 && b[c[i]] != b[c[i - 1]]) m++;
        d[c[i]] = m;
    }

    BIT bit(m + 1);
    int64_t r = 0;
    for (int i = 0; i <= n; i++) {
        r += bit.sum(d[i] + 1);
        bit.add(d[i], 1);
    }

    cout << r << endl;

    return 0;
}

