ll mpow(ll a, ll b){
	if(b==0) return 1;
	else if(b%2==0){ll memo = mpow(a,b/2); return memo*memo%MOD;}
	else return mpow(a,b-1) * a % MOD;
}
ll gcd(ll a, ll b){
	if(b==0) return a;
	else return gcd(b, a%b);
}
vector<ll> kaijo_memo;
ll kaijo(ll n){
	if(kaijo_memo.size() > n) return kaijo_memo[n];
	if(kaijo_memo.size() == 0) kaijo_memo.push_back(1);
	while(kaijo_memo.size() <= n) kaijo_memo.push_back(kaijo_memo[kaijo_memo.size()-1] * kaijo_memo.size() % MOD);
	return kaijo_memo[n];
}
ll nCr(ll n, ll r){
	if(n < r || r < 0) return 0;
	ll ret = 1;
	ret *= kaijo(n); ret %= MOD;
	ret *= mpow(kaijo(r), MOD-2); ret %= MOD;
	ret *= mpow(kaijo(n-r), MOD-2); ret %= MOD;
	return ret;
}

ll n,k;
vector<ll> A;
ll ans;
vector<ll> bun(int l, int r, bool isL){
	vector<ll> ret;
	if(r-l == 1){
		if(A[l] >= 0) ans++;
		ret.push_back(A[l]);
		return ret;
	}

	vector<ll> left,right;
	left = bun(l, (l+r)/2, true);
	right = bun((l+r)/2, r, false);
	sort(all(left));sort(all(right));reverse(all(left));
	int li=0, ri=0;
	while(li < left.size()){
		while(ri < right.size() && left[li] + right[ri] < 0) ri++;
		ans += right.size() - ri;
		li++;
	}

	if(isL){
		for(int i=r-1; i>=l; i--){
			if(i==r-1){
				ret.push_back(A[i]);
			}else{
				ret.push_back(A[i] + ret.back());
			}
		}
	}else{
		for(int i=l; i<r; i++){
			if(i==l){
				ret.push_back(A[i]);
			}else{
				ret.push_back(A[i] + ret.back());
			}
		}
	}
	return ret;
}


