void build(int node, int l, int r)
{
	if(l == r)
	{
		st[node] = 1;
		return;
	}
	int mid = (l+r)>>1;
	int left = node<<1;
	int right = left|1;
	build(left,l,mid);
	build(right,mid+1,r);
	st[node] = st[left] + st[right];
	return;
}

void update(int node, int l, int r, int ind, int val)
{
	if(l > r || ind < l || ind > r)
		return;
	if(l == r)
	{
		st[node] = val;
		return;
	}
	int mid = (l+r)>>1;
	int left = node<<1;
	int right = left|1;
	update(left,l,mid,ind,val);
	update(right,mid+1,r,ind,val);
	st[node] = st[left] + st[right];
	return;
}

int query(int node, int l, int r, int p, int q)
{
	if(l > r || l > q || p > r)
		return 0;
	if(l >= p && r <= q)
		return st[node];
	int mid = (l+r)>>1;
	int left = node<<1;
	int right = left|1;
	return (query(left,l,mid,p,q)+query(right,mid+1,r,p,q));
}

int binsea(int l, int r, int n, ll val)
{
	if(l > r)
		return 0;
	int mid = (l+r)>>1;
	if(l == r)
	{
		if(p[mid].F >= val)
		{
			// cout << mid << '\n';
			return query(1,1,n,1,mid);
		}
		return 0;
	}
	if(p[mid].F >= val)
	{
		// cout << mid << '\n';
		return max(query(1,1,n,1,mid), binsea(mid+1,r,n,val));
	}
	return binsea(l,mid-1,n,val);
}

