template<typename T>
struct Compress{
    vector<T> xs;
    Compress() = default;
    Compress(const vector<T> &vs){
        add(vs);
    }
    Compress(const initializer_list<vector<T>> &vs){
        for(auto &p : vs)   add(p);
    }
    void add(const vector<T> &vs){
        copy(begin(vs), end(vs), back_inserter(xs));
    }
    void add(const T &x){
        xs.emplace_back(x);
    }
    void build(){
        sort(begin(xs), end(xs));
        xs.erase(unique(begin(xs), end(xs)), end(xs));
    }
    vector<int> get(const vector<T> &vs) const{
        vector<int> ret;
        transform(begin(vs), end(vs), back_inserter(ret), [&](const T &x){
            return lower_bound(begin(xs), end(xs), x) - begin(xs);
        });
        return ret;
    }
    int get(const T &x) const{
        return lower_bound(begin(xs), end(xs), x) - begin(xs);
    }
    const T &operator[](int k) const{
        return xs[k];
    }
};

template<typename Monoid>
struct SegmentTree{
    using F = function<Monoid(Monoid, Monoid)>;

    int sz;
    vector<Monoid> seg;

    const F f;      // モノイドに対して二項演算を行う関数オブジェクト
    const Monoid M1;

    SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1){
        sz = 1;
        while(sz < n)   sz <<= 1;
        seg.assign(2 * sz, M1);
    }

    void set(int k, const Monoid &x){
        seg[k + sz] = x;
    }

    void build(){
        for(int k = sz - 1; k > 0; --k){
            seg[k] = f(seg[k << 1], seg[k << 1 | 1]);
        }
    }

    void update(int k, const Monoid &x){
        k += sz;
        seg[k] = x;
        while(k >>= 1){
            seg[k] = f(seg[k << 1], seg[k << 1 | 1]);
        }
    }

    Monoid query(int a, int b){
        Monoid L = M1, R = M1;
        for(a += sz, b += sz; a < b; a >>= 1, b >>= 1){
            if(a & 1)   L = f(L, seg[a++]);
            if(b & 1)   R = f(seg[--b], R);
        }
        return f(L, R);
    }

    Monoid operator[](const int &k) const{
        return seg[k + sz];
    }
};

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    ll k;
    cin >> n >> k;
    vector<ll> sum(n, 0);
    for(int i = 0; i < n; ++i){
        cin >> sum[i];
        sum[i] -= k;
        if(i != 0)  sum[i] += sum[i-1];
    }
    Compress<ll> c(sum);
    c.build();
    vector<int> processed = c.get(sum);
    SegmentTree<int> seg(n+5, [](int a, int b){return a+b;}, 0);
    ll res = 0;
    for(int i = 0; i < n; ++i){
        if(sum[i] >= 0) ++res;
        res += seg.query(0, processed[i] + 1);
        seg.update(processed[i], seg[processed[i]] + 1);
    }
    cout << res << endl;
}

