            a2i[sort_a[i]] = a2i.size();
        }
    }

    BIT bit = BIT(N); bit.add(a2i[0], 1);
    ll ans = 0;
    for (int i = 0; i < N; i++) {
        ans += bit.sum(a2i[a[i]]+1);
        //cout << "a[" << i << "] = " << a[i] << ", sum = " << bit.sum(a2i[a[i]]+1) << endl;
        bit.add(a2i[a[i]], 1);
    }

    cout << ans << endl;
    return 0;
}

