int64_t ans;

void merge(vector<int64_t> &x, int p, int r) {
    if (r - p == 1) {
        return;
    } else {
        int q = (p + r) / 2;
        merge(x, p, q);
        merge(x, q, r);

        vector<int64_t> a, b;

        for (int i : rep(p, q)) {
            a.push_back(x[i]);
        }

        for (int i : rep(q, r)) {
            b.push_back(x[i]);
        }

        const int64_t inf = -(1LL << 60);

        a.push_back(inf);
        b.push_back(inf);

        int i = 0, j = 0;
        for (int k : rep(p, r)) {
            if (a[i] <= b[j]) {
                ans += (q - p) - i;
                x[k] = b[j++];
            } else {
                x[k] = a[i++];
            }
        }
    }
}

int main() {
    int64_t n, k;

    in(n, k);

    auto a = vin<int64_t>(n);

    vector<int64_t> s(n);

    s[0] = a[0] - k;
    for (int i : rep(1, n)) {
        s[i] = s[i - 1] + a[i] - k;
    }

    s.insert(s.begin(), 0);

    n++;

    ::merge(s, 0, n);

    out(ans);
}

