template <typename T>
class SegmentTree {
	using func_t = function<T(const T&, const T&)>;
	const int n;
	const T id;
	func_t merge;
	vector<T> data;
	int size(int n) {
		int res;
		for (res = 1; res < n; res <<= 1);
		return res;
	}
	ll sub(int l, int r, int node, int lb, int ub, ll val) {
		if (ub <= l || r <= lb) return 0;
		if (l <= lb && ub <= r) return upper_bound(data[node].begin(), data[node].end(), val) - data[node].begin();
		return sub(l, r, node * 2, lb, (lb + ub) / 2, val) + sub(l, r, node * 2 + 1, (lb + ub) / 2, ub, val);
	}
public:
	SegmentTree(const vector<T>& data_, T id_, func_t merge_) :
		n(size(data_.size())), id(id_), merge(merge_), data(n * 2, id_) {
		for (int i = 0; i < (int)data_.size(); i++)
			data[i + n] = data_[i];
		for (int i = n - 1; i >= 0; i--)
			data[i] = merge(data[i * 2], data[i * 2 + 1]);
	}
	void Update(int p, T val) {
		p += n;
		data[p] = val;
		while (p >>= 1) data[p] = merge(data[p * 2], data[p * 2 + 1]);
	}
	void Add(int p, T val) {
		p += n;
		data[p] += val;
		while (p >>= 1) data[p] = merge(data[p * 2], data[p * 2 + 1]);
	}
	ll Find(int l, int r, ll val) {
		return sub(l, r + 1, 1, 0, n, val);
	}
};

int main()
{
	ll N, K;
	cin >> N >> K;
	vector<ll> a(N), sum(N + 1);
	for (int i = 0; i < N; i++) {
		cin >> a[i]; a[i] -= K;
		sum[i + 1] = sum[i] + a[i];
	}
	vector<vector<ll>> b(N + 1);
	for (int i = 0; i <= N; i++) {
		b[i].push_back(sum[i]);
	}
	SegmentTree<vector<ll>> st(b, vector<ll>(), [](const vector<ll>& l, const vector<ll>& r) {
		int nl = l.size(), nr = r.size();
		vector<ll> res(nl + nr);
		for (int i = 0, j = 0, k = 0; i < nl || j < nr; k++) {
			if (j == nr) {
				res[k] = l[i++];
				continue;
			}
			if (i == nl) {
				res[k] = r[j++];
				continue;
			}
			if (l[i] <= r[j]) {
				res[k] = l[i++];
			}
			else {
				res[k] = r[j++];
			}
		}
		return res;
	});
	ll res = 0;
	for (int i = 0; i < N; i++) {
		res += st.Find(0, i, sum[i + 1]);
	}
	cout << res << endl;
	return 0;
}

