template<class T>
struct BIT{
    vector<T> data;
    int size;
    BIT(int sz){
        init(sz);
    }
    void init(int sz){
        size=sz+2;
        data.assign(size,0);
    }
    T sum(int k){
        T ans=0;
        k++;
        while(k>0){
            ans+=data[k];
            k-=k&(-k);
        }
        return ans;
    }
    // data[r:l]の合計
    T sum(int r,int l){
        if(r>l) swap(r,l);
        return sum(l)-sum(r-1);
    }
    void add(int k,T x){
        k++;
        while(k<=size){
            data[k]+=x;
            k+=k&(-k);
        }
    }
    void update(int k,T x){
        T pre=sum(k,k);
        add(k,x-pre);
    }
};


