template<class T>
void remove_duplication(vector<T> &v){
    sort(v.begin(), v.end());
	v.erase(unique(v.begin(), v.end()), v.end());
}

template<typename T>
struct BIT{
    private:
        using Func = function<T(T, T)>;

        int n;
        vector<T> node;

        T init_v;
        Func func;

    public:

        BIT(int N, Func _func, T _init_v) {
            n = N + 1;
            init_v = _init_v;
            func = _func;

            node.resize(n, init_v);
            for(int i=1; i<n; i++) if((i+(i&-i)) < n) node[i+(i&-i)] = func(node[i+(i&-i)], node[i]);
        }

        BIT() {}

        void add(int pos, T v) {
            // 1-indexed
            while(pos < n){
                node[pos] = func(node[pos], v);
                pos += pos & -pos;
            }
        }

        T sum(int pos){
            // 1-indexed
            T res = init_v;
            while(pos > 0){
                res = func(res, node[pos]);
                pos = pos & (pos-1);
            }
            return res;
        }
};

void Main(){
    ll N,K; cin >> N >> K;
    VL a(N); REP(i,N) cin >> a[i];
    VL S(N+1,0); REP(i,N) S[i+1] = S[i] + a[i];

    VL b(N+1); REP(i,N+1) b[i] = S[i]-K*i; remove_duplication(b);
    map<ll,ll> m;
    REP(i,b.size()) m[b[i]] = i;

    ll ans = 0;
    BIT<ll> bit(N+1,[](ll a,ll b){return a+b;},0);
    bit.add(m[0]+1,1);
    REP(i,N){
        ll c = S[i+1] - K*(i+1);
        ans += bit.sum(m[c]+1);
        bit.add(m[c]+1,1);
    }
    cout << ans << en;
    return;
}

