struct Node{
	///int val;///
	long long val;
	int cnt;
	int num;
	struct Node *left, *right;
};
struct Node root;
long long res=0;
long long sum[200010];

void add_tree(long long v)
{
	struct Node *p = &root;
	struct Node *last = p;
	int flag;
	while(1){
		if(p == 0){
			p = new struct Node;
			p->num = p->cnt = 1;
			p->left = p->right = 0;
			p->val = v;
			if(flag == 0)
				last->left = p;
			else
				last->right = p;
			break;
		}
		p->num ++;
		if(p->val == v){
			p->cnt ++;
			break;
		}
		else if(p->val > v){
			last = p;
			flag = 0;
			p = p->left;
		}
		else{
			last = p;
			flag = 1;
			p = p->right;
		}
	}
}

int find_tree(long long v)
{
	int cc = 0;
	struct Node *p = &root;
	while(1){
		if(p == 0)
			break;
		if(p->val == v){
			cc += p->cnt;
			if(p->left != 0)
				cc += p->left->num;
			break;
		}
		else if(p->val < v){
			cc += p->cnt;
			if(p->left != 0)
				cc += p->left->num;
			p = p->right;
		}
		else{
			p = p->left;
		}
	}
	return cc;
}

void solve()
{
	int i;
	res = 0;
	for(i=0; i<N; i++)
		a[i] -= K;
	sum[0] = a[0];
	for(i=1; i<N; i++)
		sum[i] = sum[i-1] + a[i];
	if(sum[0] >= 0)
		res ++;
	root.val = sum[0];
	root.cnt = 1;
	root.num = 1;
	root.left = root.right = 0;
	for(i=1; i<N; i++){
		if(sum[i] >= 0)
			res ++;
		int cc = find_tree(sum[i]);
		res += cc;
		add_tree(sum[i]);
	}
	printf("%lld\n", res);
}

