template<class T> vector<int> compress(const vector<T> &A) {
    int n = A.size();
    vector<T> B(n);
    vector<int> C(n);
    copy(A.begin(), A.end(), B.begin());
    sort(B.begin(), B.end());
    B.erase(unique(B.begin(), B.end()), B.end());
    for(int i = 0; i < n; ++i) {
        int id = lower_bound(B.begin(), B.end(), A[i]) - B.begin() + 1;
        C[i] = id;
    }
    return C;
}

