ll a[252521];
ll tmp[252521];

ll solve(int l,int r){
  if(r-l <= 32){
    ll ret = (r-l)*(r-l-1)/2;
    REP(k,r-l-1)FOR(i,l,r-1-k)if(a[i]>a[i+1])swap(a[i],a[i+1]),ret--;
    return ret;
  }
  // if(r-l==1){
  //   return 0ll;
  // }
  int mid = (l+r)/2;
  ll ret = solve(l,mid) + solve(mid,r);
  int hl = l, hr = mid;
  FOR(i,l,r){
    if(hl<mid && (hr==r || a[hl]<=a[hr])){
      tmp[i] = a[hl++];
    }else{
      ret += hl-l;
      tmp[i] = a[hr++];
    }
  }
  FOR(i,l,r)a[i]=tmp[i];
  return ret;
}

