inline void insert(LL x) {
	for(; x <= n + 1; x += lowbit(x))
		c[x] += 1;
}

inline LL query(LL x) {
	LL ans = 0;
	for(; x; x -= lowbit(x)) 
		ans += c[x];
	return ans;
}

inline LL find(LL x) {
	LL mid, l = 1, r = n + 1;
	while(l <= r) {
		mid = l + ((r - l) >> 1);
		if(sum[mid] == x) return mid;
		else if(sum[mid] < x) l = mid + 1;
