template <typename T>
class SegmentTree{
    public:
    ll n;
    T *data;
    T INF;  //comp(x, INF) == x
    T (*comp)(T, T);

    SegmentTree(ll size, T (*compArg)(T, T), T inf){
        ll newsize = 1;
        while(newsize < size) newsize = (newsize << 1);
        n = newsize;
        INF = inf;
        comp = compArg;
        data = new T[2 * n - 1];
        for(ll i = 0; i < 2 * n - 1; ++i) data[i] = inf;
    }

    void update(ll pos, T value){
        pos += n - 1;
        data[pos] += value;
        while(pos > 0){
            pos = (pos - 1) / 2;
            data[pos] = comp(data[2 * pos + 1], data[2 * pos + 2]);
        }
    }

    T query(ll a, ll b){
        if(b < 0 || n <= a) return 0;
        if(a < 0) a = 0;
        if(n <= b) b = n;
        return subQuery(a, b, 0, 0, n);
    }

    T subQuery(ll a, ll b, ll k, ll l, ll r){
        return (r <= a || b <= l ? INF : (a <= l && r <= b ? data[k] : comp(subQuery(a, b, k * 2 + 1, l, (l + r) / 2), subQuery(a, b, k * 2 + 2, (l + r) / 2, r))));
    }
};
int main(){
    ll N, K;
    cin >> N >> K;
    ll a[N];
    for(ll i = 0; i < N; i++) cin >> a[i];
