    for(ll i = 0; i < N; i++){
        wa[i + 1] = wa[i] + (a[i] - K);
        v.push_back(wa[i + 1]);
    }
    sort(v.begin(), v.end());
    ll id_num = 0;
    map<ll, ll> id;
    for(ll u : v) if(id.find(u) == id.end()) id[u] = id_num++;
    SegmentTree<ll> S(id.size(), [](ll a, ll b){return a + b;}, 0);
    ll ans = 0;
    for(ll i = N; 0 <= i; i--){
        ll tmp = ans;
        ans += S.query(id[wa[i]], id.size());
        S.update(id[wa[i]], 1);
    }
    cout << ans << endl;
    return 0;
}

