        a[i] = sum - i * K;
        sum += cur;
    }

    map<ll, int> zip; vll unzip;
    compress(a, zip, unzip);
    rep(i, n) a[i] = zip[a[i]];

    Bit<int> bt(n);
    ll res = 0;
    rep(i, n){
        res += bt.sum(a[i]);
        bt.add(a[i], 1);
    }

