long long INF=1e17;
class SegT {
	private:
	int nvalue;
	int size_f;
	SegT *left;
	SegT *right;
	public:
	SegT() {
		msum++;
		left=NULL;
		right=NULL;
		size_f=0;
		nvalue=0;
	}
	~SegT() {
		dsum++;
		if(left!=NULL) delete left;
		if(right!=NULL) delete right;
	}
	int size() {
		return size_f;
	}
	void add(long long lfv,long long rgv,long long value) {
		if(lfv>value) return;
		if(rgv<value) return;
		if(lfv==rgv) {
			nvalue++;
			size_f++;
			return;
		}
		long long hf=(lfv+rgv+INF*2)/2-INF;
		if(value>hf) {
			if(right==NULL) {
				right = new SegT;
			}
			(*right).add(hf+1,rgv,value);
		} else {
			if(left==NULL) {
				left = new SegT;
			}
			(*left).add(lfv,hf,value);
		}
		size_f=nvalue;
		if(left!=NULL) size_f+=(*left).size();
		if(right!=NULL) size_f+=(*right).size();
	}
	int calc(long long lfv,long long rgv,long long value) {
		if(lfv>value) return 0;
		if(rgv<=value) return size();
		long long hf=(lfv+rgv+INF*2)/2-INF;
		int ret=0;
		if(left!=NULL) ret+=(*left).calc(lfv,hf,value);
		if(right!=NULL) ret+=(*right).calc(hf+1,rgv,value);
		return ret;
	}
};
