    for (auto a: as) {
        sum.push_back(sum.back() + a);
    }

    long ans = 0;
    RangeIka r(sum);
    for (int i = 0; i < n; i++) {
        ans += n - i - r.get(i + 1, n + 1, sum[i] - 1);
    }

    cout << ans << endl;
}

