void add(int k,int l,int r,int x)
{
    if (l == r) ++ T[k];
    else
    {
        int mid = (l + r) >> 1;
        if (x <= mid) add((k << 1), l, mid, x); 
        else add((k << 1) | 1, mid + 1, r, x);
        ++ T[k];
    }
}

int query(int k,int l,int r,int x,int y)
{
    if ((x<=l)&&(r<=y))
        return T[k];
    else
    {
        int mid=(l+r)>>1,ans=0;
        if (x<=mid) ans+=query((k<<1),l,mid,x,y);
        if (y>mid) ans+=query((k<<1)|1,mid+1,r,x,y);
        return ans;
    }
}

