struct CumulativeSum {
    int n;
    vector<long long> nums;
    vector<long long> s;
    CumulativeSum(int n) : n(n), s(n + 1, 0) { }
    void add(long long num) {
        nums.push_back(num);
    }
    void build() {
        for (int i = 0; i < n; ++i) s[i+1] = s[i] + nums[i];
    }
    // [l, r), l and r is 0-indexed.
    long long sum(int l, int r) {
        return s[r] - s[l];
    }
};

template<typename T>
struct BIT {
    int n;
    vector<T> bit;
    BIT(int _n) : n(_n), bit(_n + 1) { }
    // [0, i], i is 0-indexed.
    T sum(int i) {
        T s = 0;
        for (i++; i > 0; i -= i & -i) s += bit[i];
        return s;
    }
    // [l, r), l and r is 0-indexed.
    T sum(int l, int r) {
        return sum(r - 1) - sum(l - 1);
    }
    void add(int i, T x) {
        for (i++; i <= n; i += i & -i) bit[i] += x;
    }
};

void Main() {
	int N;
	ll K;
	cin >> N >> K;
	vl A(N);
	CumulativeSum cs(N);
	REP(i,N) {
		cin >> A[i];
		cs.add(A[i]);
	}
	cs.build();
	vl SK(N + 1);
	REP(i,N + 1) {
		SK[i] = cs.sum(0, i) - K * i;
	}

	// zaatsu
	vl sortSK;
	for (auto v : SK) sortSK.push_back(v);
	sort(ALL(sortSK));
	sortSK.erase(unique(ALL(sortSK)), sortSK.end());
	vl compSK;
	for (auto v : SK) compSK.push_back(lower_bound(ALL(sortSK), v) - sortSK.begin());

	BIT<int> bit(N + 1);
	ll res = 0;
	REP(i,N + 1) {
		res += bit.sum(0, compSK[i] + 1);
		bit.add(compSK[i], 1);
	}
	cout << res << endl;
}

