template<class T>class CulSum {
	size_t n; vector<T> s;
public:
	CulSum(const vector<T>& a) :n(a.size()), s(n + 1) {
		for (size_t i = 0; i < n; ++i)s[i + 1] = s[i] + a[i];
	}
	template<class U, class F>CulSum(const U& a, F f) : n(a.size()), s(n + 1) {
		for (int i = 0; i < n; ++i)s[i + 1] = s[i] + static_cast<T>(f(a[i]));
	}
	// [l, r)
	T operator()(size_t l, size_t r)const {
		assert(l < r && r <= n);
		return l > r ? 0 : s[r] - s[l];
	}
	// [0, r)
	T operator()(size_t r)const {
		assert(r <= n);
		return s[r];
	}
	vector<T> get_s()const { return s; }
};

template<class T>void Compression(vector<T>& a) {
	auto v = a;
	sort(v.begin(), v.end());
	v.erase(unique(v.begin(), v.end()), v.end());
	for (auto& i : a)i = lower_bound(v.begin(), v.end(), i) - v.begin();
}

template<class T>class BinaryIndexedTree {
	int n; vector<T> a;
public:
	BinaryIndexedTree(int n_) :n(n_), a(n_ + 1) {}
	T operator()(int i) { // [0,i] の和
		assert(0 < ++i);
		int ret = 0;
		while (i > 0) {
			ret += a[i];
			i -= i & -i;
		}
		return ret;
	}
	T operator()(int i, int j) { // [i,j] の和
		return operator()(j) - (i ? operator()(i - 1) : 0);
	}
	void add(int i, T x) {
		assert(0 < ++i);
		while (i <= n) {
			a[i] += x;
			i += i & -i;
		}
	}
	vector<int> debug() {
		vector<int> res(n);
		for (int i = 0; i < n; ++i)res[i] = operator()(i, i);
		return res;
	}
};

