    c[i]=make_pair(cumsum[i+1], i);
  }

  sort(c.begin(), c.end());

  vll d(N);
  for (int i=0;i<N;++i){
    d[c[i].second]=i;
  }

  ll ans=0;
  for(int j=0;j<N;++j){
    ans+=sum(d[j]);
    add(d[j], 1);
  }

  cout << ans << endl;
  return 0;
}

