struct SegTree{
    ll size;
    vector<ll>data;
    SegTree(ll a){
        size=1;
        while(size<a)size*=2;
        data=vector<ll>(size*2);
    }
    void set(ll at,ll val){
        at+=size;
        data[at]=val;
        while(at/=2)data[at]=data[at*2]+data[at*2+1];
    }
    ll get(ll l,ll r){
        l+=size;
        r+=size;
        ll ans=0;
        while(l<r){
            if(l&1)ans+=data[l++];
            if(r&1)ans+=data[--r];
            l/=2;
            r/=2;
        }
        return ans;
    }
};
