template <typename T>
class FenwickTree {
  const int n;
  vector<T> data;
public:
  FenwickTree(int n) : n(n), data(n, 0) {}
  void add(int i, T value) {
    for (; i < n; i |= i + 1) data[i] += value;
  }
  T sum(int i) const {
    T res = 0;
    for (; i >= 0; i = (i & (i + 1)) - 1) res += data[i];
    return res;
  }
  T sum(int l, int r) const { return sum(r - 1) - sum(l - 1); }
};

void solve(ll N, ll K, vector<ll> a) {
  for (ll &i: a) i -= K;
  FenwickTree<ll> bit(N + 1);
  ll sum = 0;
  vector<pair<ll,int>> vec;
  vec.emplace_back(sum, 0);
  REP(i,N) {
    sum += a[i];
    vec.emplace_back(sum, i + 1);
  }
  sort(ALL(vec));
  ll res = 0;
  for (auto p: vec) {
    int i = p.second;
    res += bit.sum(i);
    bit.add(i, 1);
  }
  cout << res << endl;
}

