    set<int> s;
    asum[0] = 0;
    s.insert(0);
    REP(i, N){
        asum[i + 1] = asum[i] + a[i];
        s.insert(asum[i + 1]);
    }

    BIT bit(N + 1);
    int ans = 0;
    REP(i, N + 1){
        int n = distance(s.begin(), s.find(asum[i]));
        ans += bit.sum(n + 1);
        bit.add(n + 1, 1);
    }

    cout << ans;

    return 0;
}


