	if(l>pos || r<pos) return;
	if(l==r){
		it[x]=1;
		return;
	}
	int mid=(l+r)/2;
	update(x*2,l,mid,pos);
	update(x*2+1,mid+1,r,pos);
	it[x]=(it[x*2]+it[x*2+1]);
}
int get(int x,int l,int r,int L,int R){
	if(l>R || r<L || L>R) return 0;
	if(l>=L && r<=R) return it[x];
	int mid=(l+r)/2;
	return (get(x*2,l,mid,L,R)+get(x*2+1,mid+1,r,L,R));
}
