  }

  memcpy(ss, s, sizeof(s));
  sort(ss, ss + n + 1);
  for(int i = 0; i <= n; i++) {
    s[i] = distance(ss, lower_bound(ss, ss + n, s[i])) + 1;
  }

  ll c = 0;
  for(int i = n; i >= 0; i--) {
