template<typename T> struct BinaryIndexedTree {
private : 
    vector<T> data;
public :
    BinaryIndexedTree(int n) : data(n+1, 0) { }

    T get(int i) {
        T ret = 0;
        for (; i > 0; i -= i&-i) ret += data[i];
        return ret;
    }

    void add (int i, T x) {
        for (++i; i < data.size(); i += i&-i) data[i] += x;
    }

};

