        seg[u] += val;
    }
}

int query(int l, int r, int u = 1, int L = 0, int R = base-1) {
    if(l == L and r == R) return seg[u];
    int M = (L+R)>>1;
    if(r <= M) return query(l, r, u<<1, L, M);
    if(l > M) return query(l, r, u<<1|1, M+1, R);
    return query(l, M, u<<1, L, M) + query(M+1, r, u<<1|1, M+1, R);
}

