#define LSB(i) ((i)&(-(i)))

struct FenwickTree
{
	vector<int> a;
	int n;

	FenwickTree(int _n)
	{
		n = _n;
		a.assign(n+1, 0);
	}

    void update(int i)
    {
        while (i <= n) {
			++a[i];
			i += LSB(i);
        }
    }

    int get(int i)
    {
        int ans = 0;
        while (i > 0) {
            ans += a[i];
            i -= LSB(i);
        }
        return ans;
    }
};

signed main()
{
    int n, k;
    cin >> n >> k;
    long long s[n+1], a;
    map<long long, int> vals;

    s[0] = 0;
    vals[0] = 1;
    for (int i = 1; i <= n; ++i) {
		cin >> a;
		s[i] = s[i-1]+a-k;
		vals[s[i]] = 1;
    }

    int m = 1;
    for (map<long long, int>::iterator it = vals.begin(); it != vals.end(); ++it) {
		it->second = m++;
    }

    for (int i = 0; i <= n; ++i) s[i] = vals[s[i]];
    FenwickTree ft(m);

    long long ans = 0;
    for (int i = 0; i <= n; ++i) {
        ans += ft.get(s[i]);
        ft.update(s[i]);
    }
    cout << ans << endl;
}

