template<class T>
struct BIT {
    ll n;
    vector<T> bit;

    BIT(ll num) : bit(num+1, 0) { n = num; }

    void add(ll i, T w) {
        for (ll x = i; x <= n; x += x & -x) {
            bit[x] += w;
        }
    }

    T sum(ll i) {
        T ret = 0;
        for (ll x = i; x > 0; x -= x & -x) {
            ret += bit[x];
        }
        return ret;
    }
};



