using namespace std;
using Int = long long;
int N, K;
vector<Int> A, S;
Int recur(int i, int j)
{
    if (j - i <= 0) return 0;
    if (j - i == 1) return A[i] >= K;
    vector<Int> B, C;
    int mid = (i + j) / 2;
    for (int t = i; t < mid; t++) B.push_back(S[mid] - S[t] - K*(mid-t));
    for (int t = mid+1; t <= j; t++) C.push_back(S[t] - S[mid] - K*(t-mid));
    sort(begin(B), end(B));
    sort(rbegin(C), rend(C));
    int u = 0;
    Int ans = 0;
    for (int t = 0; t < B.size(); t++) {
        while (u < C.size() && B[t] + C[u] >= 0) u++;
        ans += u;
    }
    return ans + recur(i, mid) + recur(mid, j);
}
int main()
{
    cin >> N >> K;
    A.resize(N);
    S.resize(N+1);
    for (int i = 0; i < N; i++) {
        cin >> A[i];
        S[i+1] = S[i] + A[i];
    }
    cout << recur(0, A.size()) << '\n';
    return 0;
}

