int lowbit(int x){
	return x&(-x);
}

void add(int x, int v){
	for(; x<=m; x+=lowbit(x))	s[x] += v;
}

int Sum(int x){
	int ret = 0;
	for(; x>0; x-=lowbit(x))	ret += s[x];
	return ret;
}

int cal(LL val){
    int j = lower_bound(b, b+m, val) - b + 1;
    return tot - Sum(j - 1);
}

int main(){
	while(~scanf("%d %d", &n, &K)){
		sum[0] = 0;
		for(int i=1; i<=n; i++){
			scanf("%d", a+i);
