		sort(b, b+n);
		m = unique(b, b+n) - b;
        LL ans = 0;
        LL cur = 0;
        for(int i=1; i<=n; i++){
			idx[i] = lower_bound(b, b+m, sum[i]) - b + 1;
			add(idx[i], 1);
        }
        tot = n;
        for(int i=1; i<=n; i++){
			ans = ans + cal(cur);
            add(idx[i], -1);
            cur = cur + a[i] - K;
            tot--;
        }
        printf("%lld\n", ans);
	}
	return 0;
}

