template <typename T>
struct BinaryIndexedTree {
    int n;
    vector<T> bit;
    BinaryIndexedTree(int n_) : n(n_), bit(n_ + 1, 0) {}
    BinaryIndexedTree(const vector<T> &init) : n(init.size()), bit(init.size() + 1, 0) {
        for (int i = 1; i <= n; ++i) {
            bit[i] = init[i - 1];
        }
        for (int i = 1; i <= n; ++i) {
            if (i + (i & -i) <= n)
                bit[i + (i & -i)] += bit[i];
        }
    }
    T sum(int i) {
        i++;
        T s = 0;
        for (int x = i; x > 0; x -= (x & -x))
            s += bit[x];
        return s;
    }
    void add(int i, T a) {
        i++;
        if (i == 0)
            return;
        for (int x = i; x <= n; x += (x & -x))
            bit[x] += a;
    }
    int lower_bound(int w) {
        if (w <= 0)
            return 0;
        int x = 0, r = 1;
        while (r < n)
            r <<= 1;
        for (int k = r; k > 0; k >>= 1) {
            if (x + k <= n && bit[x + k] < w) {
                w -= bit[x + k];
                x += k;
            }
        }
        return x + 1;
    }
    int upper_bound(int w) {
        if (w < 0)
            return 0;
        int x = 0, r = 1;
        while (r < n)
            r <<= 1;
        for (int k = r; k > 0; k >>= 1) {
            if (x + k <= n && bit[x + k] <= w) {
                w -= bit[x + k];
                x += k;
            }
        }
        return x + 1;
    }
    T query(int l, int r) { return sum(r - 1) - sum(l - 1); }
};

int main(){
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    int n; ll k; cin >> n >> k;
    vector<ll> a(n);
    vector<ll> s(n+1);
    s[0] = 0ll;
    vector<ll> vals(n+1,0);
    rep(i,0,n){
        cin >> a[i];
        s[i+1] = s[i] + a[i] - k;
        vals[i+1] = s[i+1];
    }
    sort(all(vals));
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    rep(i,0,n+1){
        s[i] = lower_bound(all(vals),s[i]) - vals.begin();
    }
