#include <cassert>
template <typename T>
class BIT {
    const int n;
    vector<T> tree;

public:
    BIT(int _n) : n(_n), tree((size_t)_n, 0) {}

    // v[a] += w
    template <typename ID>
    void add(ID a, T w) {
        assert(0 <= a); assert(a < n);
        for (int i = (int)a; i < n; i |= (i + 1)) 
            tree[(size_t)i] += w;
    }

    // v[0] + v[1] + ... + v[a-1]
    template <typename ID>
    T sum(ID a) {
        assert(0 < a); assert(a <= n);
        T res = 0;
        for (int i = (int)a - 1; i >= 0; i = (i & (i + 1)) - 1)
            res += tree[(size_t)i];
        return res;
    }

    // v[0] + v[1] + ... + v[a] >= w なる最小のa
    int lower_bound(T w) {
        int x = 0, beki = 1;
        for (int _n=n; _n>0; _n>>=1) beki <<= 1;
        for (int k=beki; k>0; k>>=1) {
            if (x + k <= n && tree[(size_t)(x + k - 1)] < w) {
                w -= tree[(size_t)(x + k - 1)];
                x += k;
            }
            //cerr << k << ' ' << x << ' ' << tree[x] << '\n';
        }
        return x;
    }

    // set(被りなし)としての機能を見やすく
    // ただし同じものをたとえば二回pushする場合、値が+2となって一回のpopでは消えないというバグあり
    template <typename ID>
    void push(ID a) { add(a, 1); }

    template <typename ID>
    void pop(ID a) { add(a, -1); }
};

int main() {
    int n;
    long k;
    cin >> n >> k;
    long rui[n+1], a, s=0;
    rui[0] = 0;
    for (int i=1; i<=n; i++) {
        cin >> a;
        s += a - k;
        rui[i] = s;
    }
    map<long, int> zip;
    vector<long> unzip;
    n = compress(vector<long>(rui, rui+n+1), zip, unzip);
    BIT<int> bit(n);
    long sum = 0;
    for (auto r:rui) {
        int i = zip[r];
        sum += (long)bit.sum(i+1);
        bit.push(i);
    }
    cout << sum << '\n';
    return 0;
}

