struct Fenwick {
    int seg[MN];
    int n;
    Fenwick(int _n) : n(_n) {}
    void add(int k, int v) {
        k++;
        while (k <= n) {
            seg[k] += v;
            k += k & -k;
        }
    }
    int sum(int k) {
        int r = 0;
        k++;
        while (k > 0) {
            r += seg[k];
            k -= k & -k;
        }
        return r;
    }
};

