template<typename T> // T: type of cost
struct BIT {
	int n;
	vector<T> d;
	BIT(int n = 0) :n(n), d(n + 1) {}
	void add(int i, T x = 1) {
		for (i++; i <= n; i += i & -i) {
			d[i] += x;
		}
	}
	T sum(int i) {
		T x = 0;
		for (i++; i; i -= i & -i) {
			x += d[i];
		}
		return x;
	}

	long long inversion(vector<T> a) {
		long long ans = 0;
		for (int j = 0; j < a.size(); j++) {
			ans += sum(a[j]);
			add(a[j], 1);
		}
		return ans;
	}
};
