            b2id[c[i]] = id++;
        }
    }

    for(int i=0; i<=n; i++){
        b[i] = b2id[b[i]];
    }

    SegmentTree seg(vector<ll>(n+1, 0));
    ll ans = 0;
    for(int i=n; i>=0; i--){
        ans += seg.getsum(b[i], n + 1);
        seg.add(b[i], 1);
    }

    cout << ans << endl;

