	// suma[i] = a_0 + a_1 + ... a_{i - 1}
	vector<long long int> suma(n + 1, 0);
	for (int i = 0; i < n; i++) {
		int a;
		cin >> a;
		suma[i + 1] = suma[i] + a;
	}
	//   a[l] ... a[r - 1]間の平均は(suma[r] - suma[l]) / (r - l)
	// よって (suma[r] - suma[l]) / (r - l) >= k
	// となるような(l,r)のペアを探せば良い
	//   (suma[r] - suma[l]) / (r - l) >= k
	// <=> suma[r] - suma[l] >= k * (r - l)
	// <=> suma[r] - k * r >= suma[l] - k * l
	// <=> suma[r] >= suma[l] (suma[i] = suma[i] - k * i)
	for (int i = 1; i <= n; i++) {
		suma[i] = suma[i] - k * i;
	}
	suma = compress(suma);
	BIT bit(n);
	long long int ans = 0;
	for (int i = 0; i <= n; i++) {
		ans += bit.getCntOfLTEX(suma[i]);
		bit.add(suma[i], 1);
	}
	cout << ans << endl;
}

