template<typename Monoid>
struct SegmentTree {
    using Op = function<Monoid(const Monoid& lhs, const Monoid& rhs)>;
    ll width;
    vector<Monoid> node;
    Op op;
    Monoid unit;

    SegmentTree(ll N, Op op, Monoid unit)
    : SegmentTree(vector<Monoid>(N, unit), op, unit) {}
    SegmentTree(const vector<Monoid>& elems, Op op, Monoid unit)
    : op(op)
    , unit(unit) {
        width = 1;
        while (width < elems.size()) {
            width *= 2;
        }
        node.resize(2 * width - 1, unit);
        for (size_t i = 0; i < elems.size(); i++) {
            node[i + width - 1] = elems[i];
        }
        for (size_t i = width - 2; i != numeric_limits<size_t>::max(); i--) {
            node[i] = op(node[2 * i + 1], node[2 * i + 2]);
        }
    }
    void update(ll idx, Monoid elem) {
        idx += width - 1;
        node[idx] = elem;
        while (idx >= 1) {
            idx = (idx - 1) / 2;
            node[idx] = op(node[2 * idx + 1], node[2 * idx + 2]);
        }
    }
    Monoid query(ll a, ll b, ll root = 0) const {
        assert(0 <= a && b <= width);
        ll left = root, right = root;
        while (left < width - 1) {
            left = 2 * left + 1;
        }
        left -= (width - 1);
        while (right < width - 1) {
            right = 2 * right + 2;
        }
        right -= (width - 1);
        right++;
        if (right <= a || b <= left) {
            return unit;
        }
        if (a <= left && right <= b) {
            return node[root];
        }
        Monoid ans_l = query(a, b, 2 * root + 1);
        Monoid ans_r = query(a, b, 2 * root + 2);
        return op(ans_l, ans_r);
    }
    Monoid operator[](size_t idx) { return query(idx, idx + 1); }
};

int main() {
    ll N, K;
    cin >> N >> K;
    vector<ll> As(N);
    rep(i,0,N) {
        cin >> As[i];
        As[i] -= K;
    }
    struct Sum {
        ll idx;
        ll value;
    };
    vector<Sum> sums(N+1);
    rep(n,1,N+1) {
        sums[n].value = sums[n-1].value + As[n-1];
        sums[n].idx = n;
    }
    sort(sums.begin(), sums.end(), [](Sum& lhs, Sum& rhs){ return lhs.value < rhs.value || (lhs.value == rhs.value && lhs.idx < rhs.idx); });
    SegmentTree<ll> tree(N+1, [](ll lhs, ll rhs){ return lhs + rhs; }, 0);
    ll ans = 0;
    rrep(i,sums.size(),0) {
        ans += tree.query(sums[i].idx, sums.size());
        tree.update(sums[i].idx, 1);
    }
    cout << ans << endl;
}

