void build(int l,int r,int rt)
{
    int mid=(l+r)>>1;
    tree[rt].l=l,tree[rt].r=r,tree[rt].sum=0;
    if(l==r) return ;
    build(l,mid,rt*2);
    build(mid+1,r,rt*2+1);
