template <class T>
struct CoordinateCompressionT
{
	vector<T> elems{};
	map<T, int> comp{};

	CoordinateCompressionT() = default;
	CoordinateCompressionT(const vector<T>& orig) : elems(orig)
	{
		build();
	}

	void add(T value)
	{
		elems.emplace_back(value);
	}

	void build()
	{
		sort(allof(elems));
		elems.erase(unique(allof(elems)), elems.end());
		comp.clear();
		REP(i, elems.size()) { comp[elems[i]] = i; }
	}

	size_t size() const { return elems.size(); }
	int compress(T value) const { return comp.at(value); }
	T decompress(int i) const { return elems[i]; }
};

template <class T>
auto CompressCoordinates(const vector<T>& orig)
{
	return CoordinateCompressionT<T>(orig);
}

void solve()
{
	READ(llong, N, K);
	auto A = read<llong>(N);
	REP(i, N) A[i] -= K;

	auto R = Ruisekiwa(A);
	auto C = CompressCoordinates(R);
	auto T = SegTree(C.size(), plus<int>(), 0);

	llong ans = 0;
	RREP(i, R.size())
	{
		int id = C.compress(R[i]);
		ans += T.query(id, C.size());
		T.update(id, T[id] + 1);
	}
	WRITE(ans);
}

