using namespace std;
const int maxn=2e7+10;
const LL inf=2e16+10;
LL x[maxn];
struct AC
{
    struct zp
    {
        int lson,rson;
        LL sum;
    }tree[maxn];
    int cont,root;
    void init()
    {
        cont=0;
        root=-1;
    }
    int newnode()
    {
        tree[cont].lson=tree[cont].rson=-1;
        tree[cont].sum=0;
        cont++;
        return cont-1;
    }
    void update(int &k,LL l,LL r,LL num)
    {
        if(k==-1) k=newnode();
        tree[k].sum++;
        if(l==r) return ;
        LL mid=(l+r)>>1;
        if(num<=mid)
            update(tree[k].lson,l,mid,num);
        else
            update(tree[k].rson,mid+1,r,num);
    }
    LL query(int k,LL l,LL r,LL ql,LL qr)
    {
        if(k==-1) return 0;
        if(l==ql&&r==qr)
            return tree[k].sum;
        LL mid=(l+r)>>1;
        if(qr<=mid)
            return query(tree[k].lson,l,mid,ql,qr);
        else if(ql>mid)
            return query(tree[k].rson,mid+1,r,ql,qr);
        else
            return query(tree[k].lson,l,mid,ql,mid)+query(tree[k].rson,mid+1,r,mid+1,qr);
    }
}ac;
int main()
{
    int n;
    LL m;
    while(~scanf("%d%lld",&n,&m))
    {
        ac.init();
        for(int i=0;i<n;i++)
        {
            scanf("%lld",&x[i]);
            x[i]-=m;
        }
        for(int i=1;i<n;i++)
            x[i]+=x[i-1];
        ac.update(ac.root,-inf,inf,0);
        LL ans=0;
        for(int i=0;i<n;i++)
        {
            ans+=ac.query(ac.root,-inf,inf,-inf,x[i]);
            ac.update(ac.root,-inf,inf,x[i]);
        }
        printf("%lld\n",ans);
    }
}

