	int mid=l+r>>1;
	if(l==r)
		return 0;
	int tot=0;
	ll ans=0;
	for(int i=mid+1;i<=r;i++)
		u[tot++]=s[i];
	sort(u,u+tot);
	for(int i=l;i<=mid;i++)
		if(s[i]<=u[tot-1])
			ans+=u+tot-lower_bound(u,u+tot,s[i]);
	ans+=count(l,mid);
	ans+=count(mid+1,r);
	return ans;
}
