/* -----  2018/03/04  Problem: 075_arc_c / Link: https://arc075.contest.atcoder.jp/tasks/arc075_c?lang=en ----- */
/* ------問題------

長さ N の整数列 a= {a1,a2,…,aN} と、整数 K が与えられます。
a の空でない連続する部分列 {al,al+1,…,ar} (1≤l≤r≤N) は N(N+1)⁄2 個存在します。これらのうち、算術平均が K 以上であるものは何個あるでしょうか？

-----問題ここまで----- */
/* -----解説等-----

平衝二分木がほしいときはBITでだいたいできる

----解説ここまで---- */
template<typename type>
struct BIT { // 1-index
	int N;
	int nn;
	vector<type> data;
	BIT(int n) {
		N = n + 1;
		data = vector<type>(n + 1, 0);
		nn = 1;
		while (nn * 2 <= N)nn *= 2;
	}
	void add(int i, type w) { // a[i] += w
		for (int x = i; x <= N; x += x & -x) {
			data[x] += w;
		}
	}
	type sum(int i) { // iまでの和 [1,i]
		type ret = 0;
		for (int x = i; x > 0; x -= x & -x) {
			ret += data[x];
		}
		return ret;
	}
	// [l, r]
	type sum(int l, int r) {
		if (l > r) return 0;
		return sum(r) - sum(l - 1);
	}
};



LL N, K;

LL ans = 0LL;

int main() {
	cin.tie(0);
	ios_base::sync_with_stdio(false);

	cin >> N >> K;
	VL a(N);
	FOR(i, 0, N) {
		cin >> a[i];
		a[i] -= K;
	}
	VL sum(N + 1, 0);
	FOR(i, 0, N) {
		sum[i + 1] = sum[i] + a[i];
	}

	VL xs;
	FOR(i, 0, N) {
		xs.push_back(sum[i + 1]);
	}
	SORT(xs);
	UNIQ(xs);
	BIT<LL> bit(N + 10);
	FOR(i, 0, N + 1) {
		int id = lower_bound(ALL(xs), sum[i]) - xs.begin();
		ans += bit.sum(id + 1);
		bit.add(id + 1, 1);
	}
	cout << ans << "\n";

	return 0;
}

