template<typename T> 
struct BIT{
  int n;
  vector<T> bit;//1-indexed

  BIT():n(-1){}
  //initialization

  BIT(int n_,T d):n(n_),bit(n_+1,d){}
  //initialization2 n_要素数 d初期値

  T sum(int i){
    T s=bit[0];
    for(int x=i;x>0;x-=(x&-x))
      s+=bit[x];
    return s;
  }
  //1からiまでの和(1-indexed)

  void add(int i,T a){
    if(i==0) return;
    for(int x=i;x<=n;x+=(x&-x))
      bit[x]+=a;
  }
  //iにa加える

  T lower_bound(T w){
    if(w<=0) return 0;
    T x=0,r=1;//xは横の位置を管理するイメージ
    while(r<n) r<<=1;
    for(T k=r;k>0;k>>=1){//上の層から見る
      if(x+k<=n && bit[x+k]<w){
        w-=bit[x+k];
        x+=k;//右の要素に移る
      }
    }
    return x+1;
  }
  //indまでの区間和がw以上になるような最小のindを求める

  T sum0(int i){
    return sum(i+1);
  }
  void add0(int i,T a){
    add(i+1,a);
  }//0-index用

  T query(int l,int r){
    return sum(r-1)-sum(l-1);
  }//[l,r)の和を求める

  T query0(int l,int r){
    return sum(r)-sum(l);
  }//0-index用
};

