class Lowlink {
	vector<vector<int>> G;
	vector<int> order;
	vector<pair<int, int>> bridge_;
	vector<int> articulation_;
	int next = 0;
	int dfs(int v, int prev) {
		int res = order[v] = next++;
		bool is_articulation = 0;
		int d = 0;
		for (auto to : G[v]) {
			if (to == prev)continue;
			if (order[to] >= 0)res = min(res, order[to]);
			else {
				int low = dfs(to, v);
				if (low > order[v])bridge_.emplace_back(v, to);
				if (prev >= 0 && low >= order[v])is_articulation = 1;
				res = min(res, low);
				d++;
			}
		}
		if (prev < 0 && d >= 2)is_articulation = 1;
		if (is_articulation)articulation_.push_back(v);
		return res;
	}
public:
	Lowlink(int size) :G(size + 1) {}
	void add_edge(int from, int to) {
		G[from].push_back(to);
	}
	void solve(int start = 0) {
		dfs(start, -1);
	}
	const auto& bridge() {
		return bridge_;
	}
	const auto& articulation() {
		return articulation_;
	}
};
class SCC {
	int V;
	int solved = -1;
	vector<vector<int>> G, rG;
	vector<int> vs;
	vector<char> used;
	vector<int> cmp;
	void dfs(int v) {
		used[v] = 1;
		for (auto a : G[v])if (!a)dfs(a);
		vs.push_back(v);
	}
	void rdfs(int v, int k) {
		used[v] = 1;
		cmp[v] = k;
		for (auto a : rG[v])if (used[a])rdfs(a, k);
	}
public:
	SCC(int size) :V(size + 1), G(size + 1), rG(size + 1), vs(size + 1), used(size + 1), cmp(size + 1) {}
	void add_edge(int from, int to) {
		solved = -1;
		G[from].push_back(to);
		rG[to].push_back(from);
	}
	int scc() {
		if (solved != -1)return solved;
		fill(ALL(used), 0);
		vs.clear();
		for (int i = 0; i < V; i++)if (!used[i])dfs(i);
		fill(ALL(used), 0);
		int k = 0;
		for (int i = vs.size() - 1; i >= 0; i--)if (!used[vs[i]])rdfs(vs[i], k++);
		solved = k;
		return k;
	}
	const auto& group() {
		return cmp;
	}
};
umap<pair<int, int>, int> m;
int f(int a, int b) {
	b &= (2ll << a - 1);
	if (m.find(pii(a, b)) != m.end())return m[pii(a, b)];
	set<int> s;
	rep1(i, a) {
		if (b & 1 << i)continue;
		s.insert(f(a - i, b | 1 << i));
	}
	rep(i, 60) {
		if (s.find(i) == s.end()) {
			m[pii(a, b)] = i;
			return i;
		}
	}
}
template<class T>
class lazysegtree {
	vector<T> obj;
	int offset;
	T e;
	int bufsize(int num) {
		int i = 1;
		for (; num >i; i <<= 1);
		offset = i - 1;
		return (i << 1) - 1;
	}
	T query(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l)return e;
		if (a <= l && r <= b)return obj[k];
		else {
			T ret(e);
			obj[k].propagate(obj[k * 2 + 1], obj[k * 2 + 2]);
			return ret.merge(query(a, b, k * 2 + 1, l, (l + r) / 2), query(a, b, k * 2 + 2, (l + r) / 2, r));
		}
	}
	template<class Param>
	T update(int a, int b, int k, int l, int r, const Param& param) {
		if (r <= a || b <= l)return obj[k];
		if (a <= l && r <= b) {
			obj[k].update(param);
			return obj[k];
		}
		obj[k].propagate(obj[k * 2 + 1], obj[k * 2 + 2]);
		return obj[k].merge(update(a, b, k * 2 + 1, l, (l + r) / 2, param), update(a, b, k * 2 + 2, (l + r) / 2, r, param));
	}
public:
	T query(int a, int b) {//[a,b)
		return query(a, b, 0, 0, offset + 1);
	}
	template<class Param>
	void update(int a, int b, Param&& param) {
		update(a, b, 0, 0, offset + 1, param);
	}
	void updateall(int l = 0, int r = -1) {
		if (r < 0)r = offset + 1;
		l += offset, r += offset;
		if (l == 0)return;
		do {
			l = l - 1 >> 1, r = r - 1 >> 1;
			for (int i = l; i < r; i++)obj[i].merge(obj[i * 2 + 1], obj[i * 2 + 2]);
		} while (l);
	}
	/*
	void update(int k, T &a) {
	k += offset;
	obj[k] = a;
	while (k) {
	k = k - 1 >> 1;
	obj[k] = updater(obj[k * 2 + 1], obj[k * 2 + 2]);
	}
	}*/
	lazysegtree(int n, T e) :obj(bufsize(n), e), e(e) {}
	lazysegtree(vector<T> &vec, T e) :obj(bufsize(vec.size()), e), e(e) {
		copy(vec.begin(), vec.end(), obj.begin() + offset);
		updateall();
	}
	T& operator[](int n) {
		return obj[n + offset];
	}
};
class lazyRMQ_t {
	int min, add;
public:
	int getmin() {
		return min;
	}
	lazyRMQ_t() {
		min = numeric_limits<int>::max() / 2; add = 0;
	}
	lazyRMQ_t(int a, int b = 0) {
		min = a; add = b;
	}
	void propagate(lazyRMQ_t &a, lazyRMQ_t &b) {
		a.min += add;
		b.min += add;
		a.add += add;
		b.add += add;
		add = 0;
	}
	lazyRMQ_t& merge(const lazyRMQ_t &a, const lazyRMQ_t &b) {
		min = std::min(a.min, b.min);
		add = 0;
		return *this;
	}
	lazyRMQ_t& update(int k) {
		min += k;
		add += k;
		return *this;
	}
};
