struct FenwTree {
	vi t;

	FenwTree(int n = 0) {
		t.assign(n, 0);
	}

	int get(int r) {
		int ans = 0;
		for (int i = r; i >= 0; i &= i + 1, --i) {
			ans += t[i];
		}
		return ans;
	}

	void inc(int pos, int val) {
		for (int i = pos; i < sz(t); i |= i + 1) {
			t[i] += val;
		}
	}
};

vll pref;
vll c;
FenwTree T;

int get_pos(ll sum) {
	int pos = lower_bound(all(c), sum) - c.begin();
	assert(pos < sz(c) && c[pos] == sum);
	return pos;
}

ll solve() {
	pref.resize(n + 1, 0);
	forn(i, n) {
		pref[i + 1] = pref[i] + (a[i] - k);
	}
	T = FenwTree(n + 1);

	c = pref;
	sort(all(c));
	c.resize(unique(all(c)) - c.begin());

	T.inc(get_pos(pref[0]), +1);

	ll ans = 0;
	forn(i, n) {	
		int pos = get_pos(pref[i + 1]);
		ans += T.get(pos);
		T.inc(pos, +1);
	}

	return ans;
}

