using namespace std;
typedef long long ll;
const int N=4e5+7;
const int maxn = 400000;
const int inf = 0x7f7f7f7f;
struct Treap {
    int ch[maxn][2], s[maxn], sum[maxn], key[maxn], root, tot;
    ll val[maxn];
    Treap() {
        root = tot=0;
    }
    void up(int x) {
        s[x] = sum[x] + s[ch[x][0]] + s[ch[x][1]];
    }
    void rotate(int& x, int d) {
        int t = ch[x][d ^ 1];
        ch[x][d ^ 1] = ch[t][d];
        ch[t][d] = x;
        up(x);
        up(t);
        x = t;
    }

    int newnode(ll x) {
        int t = ++tot;
        sum[t] = s[t] = 1;
        ch[t][0] = ch[t][1] = 0;
        val[t] = x;
        key[t] = rand();
        return t;
    }
    void insert(int& u, ll x) {
        if(!u) {
            u = newnode(x);
            return;
        }

        if(x == val[u]) {
            sum[u]++;
            up(u);
            return;
        }

        int d = 0;

        if(x < val[u])insert(ch[u][d], x);
        else insert(ch[u][d ^= 1], x);

        if(key[ch[u][d]] < key[u])rotate(u, d ^ 1);

        up(u);
    }
    int getrank(int u, ll x) {
        if(!u)return 0;

        if(val[u] == x)return s[ch[u][0]] + sum[u];

        if(val[u] < x)return s[ch[u][0]] + sum[u] + getrank(ch[u][1], x);
        else return getrank(ch[u][0], x);
    }
} T;
int n,a[N],K;
ll s[N],ans=0;
int main(){
	scanf("%d%d",&n,&K);
	rep(i,1,n)scanf("%d",&a[i]),a[i]-=K;

	T.insert(T.root,0ll);
	rep(i,1,n){
		s[i]=s[i-1] + a[i];
		int res=T.getrank(T.root,s[i]);
		T.insert(T.root,s[i]);
		ans+=res;
	}
	printf("%lld\n",ans);
}

