unordered_map<LL, int>bit;
LL width = 1;
const LL margin = 3*1e13;

LL range(LL x)
{
	x += margin;
	x--;
	LL ret = 0;
	while (x > 0)
	{
		ret += bit[x];
		x -= (x & (-x));
	}
	return ret;
}

void increment(LL x)
{
	x += margin;
	while (x <= width)
	{
		bit[x]++;
		x += (x & (-x));
	}
}

LL N, K;

int main(void)
{
	while (width < margin + margin)width *= 2;
	cin >> N >> K;
	LL base = 0;
	LL ans = 0;
	increment(0);
	for (int i = 0; i < N; ++i)
	{
		LL a; cin >> a;
		base += (a - K);
		LL inc = range(-base);
		ans += i - inc + 1;
		increment(-base);
	}
	cout << ans << endl;
	return 0;
}

