		if (d[i].key > d[i-1].key) k++;
		a[d[i].id] = k;
	}

	int BIT[200002] = {};
	long long ans = 0;
	for (i = 0; i <= N; i++) {
		ans += sum_BIT(BIT, a[i]);
		add_BIT(BIT, k, a[i], 1);
	}

	printf("%lld\n", ans);
	fflush(stdout);
	return 0;
}

