import java.util.Scanner;
public class Main {
	public static void main(String[] args){
		Main main = new Main();
		main.solveE();
	}

	private void solveE() {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		long K = sc.nextLong();
		long[] sumArr = new long[N + 1];
		sumArr[0] = 0L;
		List<Long> sumList = new ArrayList<Long>();
		sumList.add(sumArr[0]);
		for (int i = 1; i <= N; i++) {
			sumArr[i] = sumArr[i - 1] + sc.nextLong() - K;
			sumList.add(sumArr[i]);
		}
		Collections.sort(sumList);
		int current = 0;
		Map<Long, Integer> map = new HashMap<>();
		for (long value : sumList) {
			map.put(value, current++);
		}
		long ans = 0L;
		BinaryIndexedTree bit = new BinaryIndexedTree(N + 1);
		for (int i = 0; i <= N; i++) {
			int pos = map.get(sumArr[i]);
			ans += bit.getSum(pos);
			bit.addNum(1, pos);
		}
		System.out.println(ans);
	}

	class BinaryIndexedTree {
		int N;
		int[] arr;
		public BinaryIndexedTree(int N) {
			arr = new int[N];
			this.N = N;
		}

		/**
		 * posで指定した位置にval加算する
		 * @param val 加算する値
		 * @param pos 加算する位置
		 */
		public void addNum(int val, int pos) {
			while (pos < N) {
				arr[pos] += val;
				pos += (pos+1)&(-pos-1);
			}
		}

		/**
		 * posで指定した位置までの和を取得する
		 * @param pos 和を取得する位置
		 * @return 0～posの和
		 */
		public int getSum(int pos) {
			int sum = 0;
			while (pos >= 0) {
				sum += arr[pos];
				pos -= (pos+1)&(-pos-1);
			}
			return sum;
		}
	}
}

