class Pair implements Comparable<Pair> {
  int index;
  long val;
  Pair(int i, long v) {
    index = i;
    val = v;
  }
  public int compareTo(Pair p2) {
    if (val==p2.val)
      return index-p2.index;
    return (val-p2.val) > 0 ? 1 : -1;
  }
  public String toString() {
    return "["+val+","+index+"]";
  }
}
class FT1 {
  int[] arr;
  FT1(int n) {
    arr = new int[n+1];
  }
  int sum(int i, int j) {
    return sum(j)-sum(i-1);
  }
  int sum(int i) {
    int sum=0;
    while (i>0) {
      sum+=arr[i];
      i-=i&-i;
    }
    return sum;
  }
  void add(int i, int delta) {
    if (i<=0)
      return;
    while(i<arr.length) {
      arr[i] += delta;
      i+=i&-i;
    }
  }
  String print() {
    String[] s = new String[arr.length-1];
    for (int i=0; i<s.length; i++) {
      s[i] = ""+ sum(i+1,i+1);
    }
    return String.join(", ",s);
  }
}

