import java.util.Arrays;
import java.util.Comparator;
import java.util.Scanner;

class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	void run() {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int k = sc.nextInt();
		long[][] a = new long[n][2];
		int add = 0;
		for (int i = 0; i < n; ++i) {
			a[i][0] = sc.nextInt() - k;
			a[i][1] = i;
			if (i > 0) {
				a[i][0] += a[i - 1][0];
			}
			if (a[i][0] >= 0) {
				++add;
			}
		}
		Arrays.sort(a, new Comparator<long[]>() {
			@Override
			public int compare(long[] o1, long[] o2) {
				return Long.compare(o1[0], o2[0]);
			}
		});

		int[] arr = new int[n];
		int p = 0;
		for (int i = 0; i < n; ++i) {
			if (i > 0) {
				if (a[i][0] != a[i - 1][0]) {
					++p;
				}
			}
			arr[(int)a[i][1]] = p;
		}
		solve(n, arr, add);
	}

	void solve(int n, int[] arr, int add) {
		int[][] e = new int[n][2];
		for (int i = 0; i < n; ++i) {
			e[i][0] = arr[i];
			e[i][1] = i;
		}
		Arrays.sort(e, new Comparator<int[]>() {
			@Override
			public int compare(int[] o1, int[] o2) {
				if (o1[0] != o2[0]) {
					return Integer.compare(o1[0], o2[0]);
				} else {
					return Integer.compare(o1[1], o2[1]);
				}
			}
		});
		Seg seg = new Seg(n);
		long ans = 0;
		for (int i = 0; i < n; ++i) {
			ans += seg.sum(0, e[i][1]);
			seg.set(e[i][1]);
		}
		System.out.println(ans + add);
	}

	class Seg {
		int n;
		int[] v;

		public Seg(int n) {
			this.n = 1;
			while (this.n < n) {
				this.n *= 2;
			}
			v = new int[2 * this.n - 1];
		}

		void set(int k) {
			k += n - 1;
			v[k] = 1;
			while (k > 0) {
				k = (k - 1) / 2;
				v[k] = v[2 * k + 1] + v[2 * k + 2];
			}
		}

		int sum(int a, int b) {
			return sum(a, b, 0, n, 0);
		}

		// [a,b),[l,r)
		int sum(int a, int b, int l, int r, int k) {
			if (a >= r || b <= l) {
				return 0;
			} else if (a <= l && r <= b) {
				return v[k];
			} else {
				int vl = sum(a, b, l, (l + r) / 2, 2 * k + 1);
				int vr = sum(a, b, (l + r) / 2, r, 2 * k + 2);
				return vl + vr;
			}
		}
	}

	static void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

import java.util.*;
import java.io.PrintWriter;
public class Main{
	public static void main(String[] args){
		Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();
		int k=sc.nextInt();
		double[] a=new double[n];
		double[] tmp=new double[n];
		long ans=0;
		for(int i=0; i<n; i++){
			a[i]=sc.nextInt()-k;
			if(i!=0){
				a[i]+=a[i-1];
			}
			tmp[i]=a[i];
			if(tmp[i]>=0){
				ans++;
			}
		}
		Arrays.sort(tmp);
		for(int i=0; i<n; i++){
			a[i]=-Arrays.binarySearch(tmp,a[i]+0.1);
		}
		BIT b=new BIT(n+1);
		for(int i=0; i<n; i++){
			ans+=b.get((int)a[i]);
			b.add((int)a[i]);
		}
		System.out.println(ans);
	}
	static class BIT{
		int n;
		int[] data;
		BIT(int n){
			this.n=n;
			data = new int[n+1];
		}
		void add(int i){
			for(;i<=n;i+=i&(-i))data[i]++;
		}
		int get(int i){
			int res = 0;
			for(;i>0;i-=i&(-i))res+=data[i];
			return res;
		}
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.io.PrintWriter;
import java.io.StreamTokenizer;
import java.util.Arrays;

public class Main {
    static StreamTokenizer in=new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));  
    static PrintWriter out=new PrintWriter(new OutputStreamWriter(System.out));  

    public static int nextInt()throws IOException {in.nextToken();return (int)in.nval;}  
    public static long nextLong()throws IOException {in.nextToken(); return (long)in.nval;}
    public static String next()throws IOException {in.nextToken();return (String)in.sval;}

	static int[] a = new int[200100];
	static int[] num = new int[200100];
	static int[] b = new int[200100];
	static long[] sum = new long[200100];
	static long[] c = new long[200100];

    public static void main(String[] args) throws IOException {
    	int n = nextInt(), k = nextInt();
    	num[1] = 1;
    	for (int i = 2; i <= n + 1; i++) {
    		sum[i] = sum[i - 1] + nextInt() - k;
    		num[i] = i;
    	} 
    	qsort(1, n + 1);
    	for (int i = 1; i <= n + 1; i++)
    		b[num[i]] = i;
    	long ans = 0;
    	for (int i = 1; i <= n + 1; i++) {
			int p = b[i];
			while (p > 0) {
				ans += c[p];
				p -= lowbit(p);
			}
			p = b[i];
			while (p <= n + 1) {
				c[p]++;
				p += lowbit(p);
			}
		}
    	out.println(ans);
    	out.flush();
    	out.close();
    }
    public static int lowbit(int x) {
    	return x & -x;
    }
    public static void qsort(int s, int t) {
    	long x = sum[(s + t) / 2];
    	int y = num[(s + t) / 2];
    	int i = s, j = t;
    	while (i < j) {
    		while (sum[i] < x || sum[i] == x && num[i] < y) i++;
    		while (sum[j] > x || sum[j] == x && num[j] > y) j--;
    		if (i <= j) {
    			long k = sum[i];
    			sum[i] = sum[j];
    			sum[j] = k;
    			int p = num[i];
    			num[i] = num[j];
    			num[j] = p;
    			i++;
    			j--;
    		}
    	}
    	if (i < t) qsort(i, t);
    	if (s < j) qsort(s, j);
    }
}

import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;

public class Main {

	static PrintWriter out;
	static InputReader ir;
	static boolean debug = false;

	static void solve() {
		int n = ir.nextInt();
		int k = ir.nextInt();
		long[] a = new long[n + 1];
		for (int i = 0; i < n; i++) {
			a[i + 1] = ir.nextLong() - k;
			a[i + 1] += a[i];
		}
		int[] b = compress(a);
		BinaryIndexedTree bit = new BinaryIndexedTree(n);
		long res = 0;
		for (int i = 0; i <= n; i++) {
			res += bit.sum(b[i] + 1);
			bit.update(b[i], 1);
		}
		out.println(res);
	}

	public static int[] compress(long[] a) {
		int n = a.length;
		long[] r = a.clone();
		Arrays.sort(r);
		int[] ret = new int[n];
		for (int i = 0; i < n; i++)
			ret[i] = lower_bound(r, 0, n - 1, a[i]);
		return ret;
	}

	public static int lower_bound(long[] a, int fromIndex, int toIndex, long val) {
		if (val > a[toIndex])
			return toIndex + 1;
		if (val <= a[fromIndex])
			return fromIndex;
		int lb = fromIndex - 1, ub = toIndex;
		while (ub - lb > 1) {
			int mid = (ub - lb) / 2 + lb;
			if (a[mid] >= val) {
				ub = mid;
			} else {
				lb = mid;
			}
		}
		return ub;
	}

	static class BinaryIndexedTree {
		// 0-indexed
		private long[] bit;
		private int SIZE;

		public BinaryIndexedTree(int n) {
			bit = new long[n + 1];
			SIZE = n;
		}

		// sum of segment[0,i)
		public long sum(int i) {
			long res = 0;
			while (i > 0) {
				res += bit[i];
				i -= i & -i;
			}
			return res;
		}

		// sum of segment[start,end)
		public long sum(int start, int end) {
			return sum(end) - sum(start);
		}

		public long get(int i) {
			return sum(i + 1) - sum(i);
		}

		public void update(int i, long x) {
			i++;
			while (i <= SIZE) {
				bit[i] += x;
				i += i & -i;
			}
		}

		public int size() {
			return SIZE;
		}
	}

	public static void main(String[] args) {
		ir = new InputReader(System.in);
		out = new PrintWriter(System.out);
		solve();
		out.flush();
	}

	static class InputReader {

		private InputStream in;
		private byte[] buffer = new byte[1024];
		private int curbuf;
		private int lenbuf;

		public InputReader(InputStream in) {
			this.in = in;
			this.curbuf = this.lenbuf = 0;
		}

		public boolean hasNextByte() {
			if (curbuf >= lenbuf) {
				curbuf = 0;
				try {
					lenbuf = in.read(buffer);
				} catch (IOException e) {
					throw new InputMismatchException();
				}
				if (lenbuf <= 0)
					return false;
			}
			return true;
		}

		private int readByte() {
			if (hasNextByte())
				return buffer[curbuf++];
			else
				return -1;
		}

		private boolean isSpaceChar(int c) {
			return !(c >= 33 && c <= 126);
		}

		private void skip() {
			while (hasNextByte() && isSpaceChar(buffer[curbuf]))
				curbuf++;
		}

		public boolean hasNext() {
			skip();
			return hasNextByte();
		}

		public String next() {
			if (!hasNext())
				throw new NoSuchElementException();
			StringBuilder sb = new StringBuilder();
			int b = readByte();
			while (!isSpaceChar(b)) {
				sb.appendCodePoint(b);
				b = readByte();
			}
			return sb.toString();
		}

		public int nextInt() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			int res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public long nextLong() {
			if (!hasNext())
				throw new NoSuchElementException();
			int c = readByte();
			while (isSpaceChar(c))
				c = readByte();
			boolean minus = false;
			if (c == '-') {
				minus = true;
				c = readByte();
			}
			long res = 0;
			do {
				if (c < '0' || c > '9')
					throw new InputMismatchException();
				res = res * 10 + c - '0';
				c = readByte();
			} while (!isSpaceChar(c));
			return (minus) ? -res : res;
		}

		public double nextDouble() {
			return Double.parseDouble(next());
		}

		public int[] nextIntArray(int n) {
			int[] a = new int[n];
			for (int i = 0; i < n; i++)
				a[i] = nextInt();
			return a;
		}

		public long[] nextLongArray(int n) {
			long[] a = new long[n];
			for (int i = 0; i < n; i++)
				a[i] = nextLong();
			return a;
		}

		public char[][] nextCharMap(int n, int m) {
			char[][] map = new char[n][m];
			for (int i = 0; i < n; i++)
				map[i] = next().toCharArray();
			return map;
		}
	}

	static void tr(Object... o) {
		if (debug)
			out.println(Arrays.deepToString(o));
	}
}

