	private static void solve() {
		int n = nei();
		long k = nel();
		long[] as = new long[n];
		for (int i = 0; i < n; i++) {
			as[i] = nel() - k;
		}
		long[] sum = new long[n + 1];
		sum[0] = 0;
		for (int i = 1; i < n + 1; i++) {
			sum[i] = sum[i - 1] + as[i - 1];
		}
		out((long) n * (n + 1) / 2 - invNum(sum, 0, n));
	}

	static long invNum(long[] as, int min, int max) {
		long res = 0;
		if (min < max) {
			int mid = (min + max + 1) / 2;
			res += invNum(as, min, mid - 1) + invNum(as, mid, max);
			long[] ls = Arrays.copyOfRange(as, min, mid);
			long[] rs = Arrays.copyOfRange(as, mid, max + 1);
			int l = 0, r = 0, i = min;
			while (l < ls.length && r < rs.length) {
				if (ls[l] <= rs[r]) {
					as[i] = ls[l];
					l++;
					i++;
				} else {
					as[i] = rs[r];
					r++;
					i++;
					res += ls.length - l;
				}
			}
			System.arraycopy(ls, l, as, i, ls.length - l);
			i += ls.length - l;
			System.arraycopy(rs, r, as, i, rs.length - r);
			i += rs.length - r;
		}
		return res;
	}

