class BIT{
	int n;
	int[] a;
	BIT(int n){
		this.n = n;
		a = new int[n+1];
	}

	void add(int x, int k) {
		 while(x <= n) {
			 a[x] += k;
			 x += x & -x;
		 }
	}

	int getSum(int x) {
		int res = 0;
		while(x > 0) {
			res += a[x];
			x -= x & -x;
		}
		return res;
	}
}

