public class Main {

	int N, K, size;
	int[] a,b,segment;

	public void init(int _size) {
		size = 1;

		while (size < _size)
			size *= 2;
		segment = new int[2 * size];
		for (int i = 0; i < 2 * size - 1; i++) {
			segment[i] = 0;
		}
	}

	public void update(int i, int a) {
		i += size - 1;
		segment[i] += a;

		while (i > 0) {
			i = (i - 1) / 2;
			segment[i] += a;
		}
	}

	public int query(int a, int b, int k, int l, int r) {
		if (r <= a || b <= l)
			return 0;

		if (a <= l && r <= b)
			return segment[k];
		else {
			int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
			int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);

			return vl + vr;
		}
	}

	public void solve() {
		N = nextInt();
		K = nextInt();

		a = new int[N];
		for(int i = 0;i < N;i++){
			a[i] = nextInt() - K;
		}

		b = new int[N+1];
		for(int i = 0;i < N;i++){
			b[i+1] += b[i] + a[i];
		}

		TreeSet<Integer> set = new TreeSet<>();
		for(int i = 0;i <= N;i++){
			set.add(b[i]);
		}

		List<Integer> list = new ArrayList<>();
		for(int i : set){
			list.add(i);
		}

		init(N+1);
		long ans = 0;
		for (int i = 0; i <= N; i++) {
			int x = Collections.binarySearch(list, b[i]);
			ans += query(0, x+1, 0, 0, size);
			update(x, 1);
		}

		out.println(ans);
	}

