public class BIT
{
    //1-indexed
    long[] _item;
    public BIT(int num)
    {
        _item = new long[num + 1];
    }
    public long this[int index]
    {
        get { var s = 0L; for (var i = index; i > 0; i -= i & -i) s += _item[i]; return s; }
    }
    public void add(int index, long value)
    {
        for (var i = index; i < _item.Length; i += i & -i) _item[i] += value;
    }
}

using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Text;
using System.Linq;
using static System.Math;

class Program
{
    static int N;
    static int K;
    static long[] a;
    static long[] b;

    static void Main()
    {
        /* 入力の受け取り */
        int[] input = Console.ReadLine().Split().Select(int.Parse).ToArray();
        N = input[0];
        K = input[1];
        a = new long[N];
        for (int i = 0; i < N; i++)
            a[i] = long.Parse(Console.ReadLine());

        /* b[i] = a[i] - Kとシフト */
        b = a.Select(s => s - K).ToArray();

        /* bの累積和 */
        long[] sum = new long[N + 1];
        for (int i = 0; i < N; i++)
            sum[i + 1] = sum[i] + b[i];

        /* 累積和の転倒数をN(N+1)/2から引いたものが答え */
        long ans = N * (N + 1) / 2;
        ans -= InversionNumber.InvNum(sum);
        Console.WriteLine(ans);
    }
}

static class InversionNumber
{
    public static long InvNum(long[] a)
    {
        long ans = 0;
        SortedList<long, int> sl = new SortedList<long, int>();
        foreach (var i in a)
        {
            try { sl.Add(i, 1); }
            catch { continue; }
        }
        BIT bit = new BIT(sl.Count);
        for (int j = 0; j < a.Length; j++)
        {
            ans += j - bit.Sum(sl.IndexOfKey(a[j]) + 1);
            bit.Add(sl.IndexOfKey(a[j]) + 1, 1);
        }
        return ans;
    }

    public static long InvNum(int[] a)
    {
        long[] al = a.Select(s => (long)s).ToArray();
        return InvNum(al);
    }
}

struct BIT
{
    private long[] bit;
    public int n { get; private set; }

    public BIT(int n)
    {
        this.n = n;
        bit = new long[n + 1];
    }

    public long Sum(int i)
    {
        long s = 0;
        while (i > 0)
        {
            s += bit[i];
            i -= i & -i;
        }
        return s;
    }

    public void Add(int i, int x)
    {
        while (i <= n)
        {
            bit[i] += x;
            i += i & -i;
        }
    }
}

