        class ARC075
        {
            public static void C()
            {
                var N = Read.Int();
                var S = Enumerable.Range(0, N).Select(i => Read.Int()).ToArray();
                var total = S.Sum();
                if (total % 10 > 0) { Console.WriteLine(total); return; }
                var min = 999;
                foreach(var s in S)
                {
                    if(s%10>0 && min > s) { min = s; }
                }
                Console.WriteLine(min == 999 ? 0 : total - min);
            }
            public static void D()
            {
                var N = Read.Int();
                var A = Read.Long();
                var B = Read.Long();
                var H = Enumerable.Range(0, N).Select(i => Read.Long()).ToArray();

                Func<long, bool> Win = K =>
                {
                    long need = 0;
                    foreach(var h in H)
                    {
                        if(h > K * B)
                        {
                            need += (h - K * B + A - B - 1) / (A - B);
                        }
                    }
                    return K >= need;
                };

                long min = 0;
                long max = (long)1e9;
                while (min + 1 < max)
                {
                    var mid = (min + max) / 2;
                    if (Win(mid))
                    {
                        max = mid;
                    }
                    else
                    {
                        min = mid;
                    }
                }
                Console.WriteLine(max);
            }
            public static void E()
            {
                var N = Read.Int();
                var K = Read.Long();
                var A = Enumerable.Range(0, N).Select(i => Read.Long()).ToArray();
                var comp = Util.Compress(Util.ASum(A).Select((x, i) => x - i * K).ToArray());
                var bit = new Util.BIT(N + 1);
                long ans = 0;
                for (int i = 0; i <= N; ++i)
                {
                    ans += bit.Sum(comp[i]);
                    bit.Add(comp[i], 1);
                }
                Console.WriteLine(ans);
            }
        }
        class Util
        {
            public static int[] Compress(long[] array, bool needDistinct = true)
            {
                var sorted = needDistinct ? array.Distinct().ToArray() : array.ToArray(); Array.Sort(sorted);
                Dictionary<long, int> dict = new Dictionary<long, int>(); for (int i = 0; i < sorted.Length; ++i) { dict.Add(sorted[i], i + 1); }
                return array.Select(x => dict[x]).ToArray();
            }
            public static long[] ASum(long[] array)
            {
                var res = new long[array.Length + 1];
                for (int i = 0; i < array.Length; ++i)
                {
                    res[i + 1] = res[i] + array[i];
                }
                return res;
            }
            public class BIT
            {
                int N; long[] array;
                public BIT(int m) { for (int n = 1; ; n *= 2) { if (n >= m) { N = n; array = new long[N + 1]; break; } } }
                public void Add(int idx, int v) { for (int x = idx; x <= N; x += x & -x) { array[x] += v; } }
                public long Sum(int idx) { long ret = 0; for (int x = idx; x > 0; x -= x & -x) { ret += array[x]; } return ret; }
            }
        }

