class Program
{
    static int N;
    static int K;
    static long[] a;

    static void Main()
    {
        /* 入力の受け取り */
        int[] input = Console.ReadLine().Split().Select(int.Parse).ToArray();
        N = input[0];
        K = input[1];
        a = new long[N];
        for (int i = 0; i < N; i++)
            a[i] = long.Parse(Console.ReadLine());

        /* b[i] = a[i] - Kとシフト */
        long[] b = a.Select(s => s - K).ToArray();

        /* bの累積和 */
        long[] sum = new long[N + 1];
        for (int i = 0; i < N; i++)
            sum[i + 1] = sum[i] + b[i];

        Console.WriteLine(Calc(sum));
    }

    /* i < jについて、a[i] <= a[j]なる(i,j)の組数を求める */
    public static long Calc(long[] a)
    {
        int n = a.Length;
        SortedList<long, int> sl = new SortedList<long, int>();
        foreach (var i in a)
        {
            try { sl.Add(i, 0); } catch { continue; }
        }
        n = sl.Count;
        RSQ1 rsq = new RSQ1(n);
        long[] t2 = new long[n];
        long ans = 0;
        for (int j = 0; j < a.Length; j++)
        {
            int i = sl.IndexOfKey(a[j]);
            ans += rsq.Query(0, i + 1);
            rsq[i] += 1;
        }
        return ans;
    }
}

struct RSQ1
{
    private int n;
    private long[] dat;
    public int Length { get; private set; }
    public long this[int i]
    {
        get
        {
            if (i < 0 || i >= this.Length)
                throw new IndexOutOfRangeException();
            return dat[i + n - 1];
        }
        set { this.Update(i, value); }
    }

    /* nを要素数として、すべて0で初期化 */
    public RSQ1(int n)
    {
        Length = n;
        this.n = 1;
        while (this.n < n) this.n *= 2;
        dat = new long[2 * this.n];
    }

    /* k番目(0-indexed)をaに変更 */
    public void Update(int k, long a)
    {
        k += n - 1;
        dat[k] = a;
        while (k > 0)
        {
            k = (k - 1) / 2;
            dat[k] = dat[k * 2 + 1] + dat[k * 2 + 2];
        }
    }

    private long Query_(int a, int b, int k, int l, int r)
    {
        if (r <= a || b <= l) return 0;
        if (a <= l && r <= b) return dat[k];
        long v1 = Query_(a, b, k * 2 + 1, l, (l + r) / 2);
        long v2 = Query_(a, b, k * 2 + 2, (l + r) / 2, r);
        return v1 + v2;
    }

    /* [a,b)の和を求める */
    public long Query(int a, int b)
    {
        return Query_(a, b, 0, 0, n);
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;

class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var N = sc.ReadInt();
        var K = sc.ReadLong();
        var A = sc.ReadLongArray(N);
        var sum = new long[N + 1];
        for (int i = 0; i < N; i++)
        {
            sum[i + 1] = sum[i] + A[i];
        }

        var t = new Treap<long>();
        for (int i = 0; i < N + 1; i++)
        {
            var x = sum[i] - K * i;
            t.Insert(x);
        }
        var ans = 0L;
        for (int i = 0; i < N; i++)
        {
            var x = sum[i] - K * i;
            var y = t.LowerBouond(x);
            var res = t.Length - y;
            ans += res - 1;
            t.Erase(x);
        }
        Console.WriteLine(ans);
    }
    // AC: https://atcoder.jp/contests/arc033/tasks/arc033_3
    //     
    class Treap<T> : IEnumerable<T> where T : IComparable
    {
        public int Length
        {
            get { return this.Root == null ? 0 : this.NodeCount(this.Root); }
        }
        public T this[int i]
        {
            get
            {
                if (this.Root.Count < i - 1) throw new IndexOutOfRangeException();
                return this.Root.Get(i);
            }
        }
        public Node Root;
        private IComparer<T> Cmp = Comparer<T>.Default;
        public Treap(IComparer<T> cmp = null)
        {
            if (cmp != null) this.Cmp = cmp;
        }
        public Node Merge(Node l, Node r)
        {
            if (l == null || r == null) return l == null ? r : l;

            if (l.Priority > r.Priority)
            {
                l.R = this.Merge(l.R, r);
                return this.Update(l);
            }
            else
            {
                r.L = this.Merge(l, r.L);
                return this.Update(r);
            }
        }
        // 左にk個、右に残り(n-k)個に分割する
        public Tuple<Node, Node> Split(int k) { return this.Split(this.Root, k); }
        public Tuple<Node, Node> Split(Node t, int k)
        {
            if (t == null) return Tuple.Create<Node, Node>(null, null);
            if (k <= this.NodeCount(t.L))
            {
                var s = this.Split(t.L, k);
                t.L = s.Item2;
                return Tuple.Create(s.Item1, this.Update(t));
            }
            else
            {
                var s = this.Split(t.R, k - this.NodeCount(t.L) - 1);
                t.R = s.Item1;
                return Tuple.Create(this.Update(t), s.Item2);
            }
        }
        public int NodeCount(Node node)
        {
            return node == null ? 0 : node.Count;
        }
        public int LowerBouond(T value) { return this.LowerBouond(this.Root, value); }
        public int LowerBouond(Node node, T value)
        {
            if (node == null) return 0;
            if (this.Cmp.Compare(value, node.Value) <= 0)
                return this.LowerBouond(node.L, value);
            else
                return this.NodeCount(node.L) + 1 + this.LowerBouond(node.R, value);
        }
        public int UpperBound(T value) { return this.UpperBound(this.Root, value); }
        public int UpperBound(Node node, T value)
        {
            if (node == null) return 0;
            if (this.Cmp.Compare(value, node.Value) >= 0)
                return this.NodeCount(node.L) + 1 + this.UpperBound(node.R, value);
            else
                return this.UpperBound(node.L, value);
        }
        public int ValueCount(T value)
        {
            return this.UpperBound(value) - this.LowerBouond(value);
        }
        public void Insert(T value)
        {
            var sub = this.Split(this.Root, this.LowerBouond(value));
            var newNode = new Node(value);
            var merged = this.Merge(sub.Item1, newNode);
            this.Root = this.Merge(merged, sub.Item2);
        }
        public void Erase(T value)
        {
            if (this.ValueCount(value) == 0) return;
            var sub = this.Split(this.Root, this.LowerBouond(value));
            this.Root = this.Merge(sub.Item1, this.Split(sub.Item2, 1).Item2);
        }
        // 書き換え
        public void InsertAt(Node node, int k)
        {
            var sub = this.Split(this.Root, k);
            var merged = this.Merge(sub.Item1, node);
            this.Root = this.Merge(merged, sub.Item2);
        }
        public void InsertAt(T value, int k)
        {
            var node = new Node(value);
            var sub = this.Split(this.Root, k);
            var merged = this.Merge(sub.Item1, node);
            this.Root = this.Merge(merged, sub.Item2);
        }
        public Node EraseAt(int k)
        {
            var sub = this.Split(this.Root, k);
            var sub2 = this.Split(sub.Item2, 1);
            var res = sub2.Item1;
            this.Root = this.Merge(sub.Item1, sub2.Item2);
            return res;
        }
        public Node Update(Node node)
        {
            node.Count = this.NodeCount(node.L) + this.NodeCount(node.R) + 1;
            // RMQ
            var acc = node.Value;
            if (node.L != null && acc.CompareTo(node.L.Min) > 0) acc = node.L.Min;
            if (node.R != null && acc.CompareTo(node.R.Min) > 0) acc = node.R.Min;
            node.Min = acc;
            return node;
        }
        public T RangeQuery(int l, int r)
        {
            // [l, r)
            // 0-(l-1), l-(r-1), r-N の部分木に分割する
            var tmp = this.Split(this.Root, r);
            var rroot = tmp.Item2;
            tmp = this.Split(tmp.Item1, l);
            var lroot = tmp.Item1;
            var croot = tmp.Item2;
            var ans = croot.Min;
            this.Root = this.Merge(this.Merge(lroot, croot), rroot);
            return ans;
        }
        public void UpdateValue(int k, T value)
        {
            this.EraseAt(k);
            var newNode = new Node(value);
            this.InsertAt(newNode, k);
        }
        public void Shift(int l, int r)
        {
            // [l, r) の区間をシフト
            var node = EraseAt(r - 1);
            this.InsertAt(node, l);
        }
        public class Node
        {
            private static Random Rand = new Random();
            public T Value;
            public Node L = null;
            public Node R = null;
            public int Count;
            public double Priority;
            public T Min;
            public Node(T value, double priority)
            {
                this.Value = value;
                this.Priority = priority;
                this.Count = 1;
                //
                this.Min = value;
            }
            public Node(T value) : this(value, Rand.NextDouble()) { }
            public T Get(int i) { return this.GetNode(i).Value; }
            public Node GetNode(int i)
            {
                var lcount = 0;
                if (this.L != null) lcount = this.L.Count;
                if (lcount == i) return this;
                else if (lcount < i) return this.R.GetNode(i - lcount - 1);
                else return this.L.GetNode(i);
            }
        }
        public IEnumerator<T> GetEnumerator()
        {
            for (int i = 0; i < this.Length; i++) yield return this.Root.Get(i);
        }
        IEnumerator IEnumerable.GetEnumerator() { return this.GetEnumerator(); }
    }
    static Scanner sc = new Scanner();
}
