    static int num;
    static void Solve()
    {
        long k;
        Input.Make(out num, out k);
        var ar = Input.ar1D(num);
        var qq = new long[num + 1];
        var s = 0L;
        for (var i = 1; i <= num; i++)
            qq[i] = (s = s + ar[i - 1]) - k * i;
        WriteLine(Inversion(qq));
    }
    public static long Inversion(long[] ar)
    {
        var dic = new Dictionary<long,int>();
        var d = 0;
        var aar = new long[ar.Length];
        Array.Copy(ar, aar, ar.Length);
        Array.Sort(aar);
        //座圧
        foreach (var v in aar)
            if (!dic.ContainsKey(v))
                dic[v] = ++d;
        var seg = new SegmentTree<int>(ar.Length + 1, 0, (a, b) => a + b,(a,b)=>a+b);
        //var bit = new BIT(num + 2);
        var res = 0L;
        for (var i = 0; i < ar.Length; i++)
        {
            res += seg.Query(0,dic[ar[i]]+1);
            seg.Update(dic[ar[i]], 1);
            //res+=bit[dic[ar[i]]];
           // bit.add(dic[ar[i]], 1);
        }
        return res;
    }
}

