class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
        //WriteLine(Solve());
    }
    static int num;
    static void Solve()
    {
        long k;
        Input.Make(out num, out k);
        var ar = Input.ar1D(num);
        var sum = new long[num + 1];
        var qq = new long[num + 1];
        for (var i = 1; i <= num; i++)
            sum[i] = sum[i - 1] + ar[i - 1];
        for (var i = 1; i <= num; i++)
            qq[i] = sum[i] - k * i;
        WriteLine(Inversion(qq));
    }
    public static long Inversion(long[] ar)
    {
        var dic = new Dictionary<long,int>();
        var d = 0;
        //座圧
        foreach (var v in ar.OrderBy(v=>v))
            if (!dic.ContainsKey(v))
                dic[v] = ++d;
        var bit = new BIT(num + 2); var res = 0L;
        for (var i = 0; i < ar.Length; i++)
        {
            res+=bit[dic[ar[i]]];if (dic[ar[i]] == 0) throw new Exception();
            bit.add(dic[ar[i]], 1);
        }
        return res;
    }
}

