        long res = 0;
        BIT<int> bit = new BIT<int>(distincted.Length, 0, (x, y) => x + y);
        for (int i = 0; i < accum.Length; i++)
        {
            var ind = Array.BinarySearch(distincted, accum[i]);
            res += bit.Query(ind);
            bit.Operate(ind, 1);
        }
        Console.WriteLine(res);
    }
