    public int comb(int _a, int _b, int[] date)
    {
        int a = _a, b = _b;
        double sum, count;
        int rc=0,flag=0;
        for (int i = 0; i < (1 << a); i++)
        {
            sum = 0;
            count = 0;
            flag = 0;
            for (int j = 0; j < a; j++)
            {
                if ((i & (1 << j)) > 0)
                {
                    if (flag == 2) { count = 0; break; }
                    flag = 1;
                    count++;
                    sum += date[j];
                }
                else if(flag == 1)
                {
                    flag=2;
                }
            }
            if(count > 0)
            {
                sum = sum / count;
                if (sum >= b) rc++;
            }
        }
        return rc;
    }
