            sum[i + 1] = sum[i] + A[i];
        }

        var t = new SplayTree<long>();
        for (int i = 0; i < N + 1; i++)
        {
            var x = sum[i] - K * i;
            t.Insert(x);
        }
        var ans = 0L;
        for (int i = 0; i < N; i++)
        {
            var x = sum[i] - K * i;
            var y = t.LowerBouond(x);
            var res = t.Count - y;
            ans += res - 1;
            t.Erase(x);
        }
        Console.WriteLine(ans);
    }

    class SplayTree<T> : IEnumerable<T> where T : IComparable
    {
        public Node<T> Root;
        public int Count { get { return this.Root?.Count ?? 0; } }
        public T this[int i] { get { return this.Get(i); } }
        public void Insert(T value)
        {
            var index = this.LowerBouond(value);
            var sub = Split(index, ref Root);
            var newNode = new Node<T>(value);
            var lroot = sub.Item1;
            var rroot = sub.Item2;
            var merged = Merge(ref lroot, ref newNode);
            this.Root = Merge(ref merged, ref rroot);
        }
        public void Erase(T value)
        {
            if (this.ValueCount(value) == 0) return;
            var sub = Split(this.LowerBouond(value), ref this.Root);
            var lroot = sub.Item1;
            var tmp = sub.Item2;
            var rroot = Split(1, ref tmp).Item2;
            this.Root = Merge(ref lroot, ref rroot);
        }
        public int LowerBouond(T value) { return LowerBouond(this.Root, value); }
        public int UpperBound(T value) { return UpperBound(this.Root, value); }
        public int ValueCount(T value) { return UpperBound(value) - LowerBouond(value); }
        public T Get(int i)
        {
            return this.GetNode(i).Value;
        }
        public Node<T> GetNode(int i)
        {
            Root = Root.GetNode(i);
            return Root;
        }
        public IEnumerator<T> GetEnumerator()
        {
            for (int i = 0; i < Count; i++) yield return this[i];
        }
        IEnumerator IEnumerable.GetEnumerator() { return this.GetEnumerator(); }

        // Node操作用静的関数 ...
        public static Node<T> GetNode(int index, Node<T> node)
        {
            while (true)
            {
                var lcount = node.L?.Count ?? 0;
                if (index < lcount)
                {
                    node = node.L;
                }
                else if (index == lcount)
                {
                    node.Splay();
                    return node;
                }
                else
                {
                    index -= lcount + 1;
                    node = node.R;
                }
            }
        }
        public static int LowerBouond(Node<T> root, T value)
        {
            if (root is null) return 0;
            if (value.CompareTo(root.Value) <= 0)
                return LowerBouond(root.L, value);
            else
                return (root.L?.Count ?? 0) + 1 + LowerBouond(root.R, value);
        }
        public static int UpperBound(Node<T> root, T value)
        {
            if (root is null) return 0;
            if (value.CompareTo(root.Value) >= 0)
                return (root.L?.Count ?? 0) + 1 + UpperBound(root.R, value);
            else
                return UpperBound(root.L, value);
        }
        // 2つのノードを1つにマージする
        public static Node<T> Merge(ref Node<T> lroot, ref Node<T> rroot)
        {
            if (lroot == null) return rroot;
            if (rroot == null) return lroot;

            lroot = lroot.GetNode(lroot.Count - 1);
            lroot.R = rroot;
            rroot.P = lroot;
            lroot.Update();
            return lroot;
        }
        // 与えられたノードを指定の個数で分割する
        public static Tuple<Node<T>, Node<T>> Split(int leftCount, ref Node<T> root)
        {
            if (leftCount == 0) return Tuple.Create((Node<T>)null, root);
            if (leftCount == root.Count) return Tuple.Create(root, (Node<T>)null);
            root = root.GetNode(leftCount);
            var lroot = root.L;
            var rroot = root;
            rroot.L = null;
            lroot.P = null;
            rroot.Update();
            return Tuple.Create(lroot, rroot);
        }
        // ノードの指定された位置に新しいノードを挿入する
        // 指定位置で分割して順番にマージする(l, new, r)
        public static Node<T> InsertNode(int index, Node<T> newNode, ref Node<T> root)
        {
            var trees = Split(index, ref root);
            var lroot = trees.Item1;
            var rroot = trees.Item2;
            var merged = Merge(ref lroot, ref newNode);
            return Merge(ref merged, ref rroot);
        }
        // ある位置のノードを取り除く
        public static Tuple<Node<T>, Node<T>> DeleteNode(int index, ref Node<T> root)
        {
            root = root.GetNode(index);
            var lroot = root.L;
            var rroot = root.R;
            if (lroot != null) lroot.P = null;
            if (rroot != null) rroot.P = null;
            root.R = null;
            root.L = null;
            var deleted = root;
            var merged = Merge(ref lroot, ref rroot);
            deleted.Update();
            return Tuple.Create(merged, deleted);
        }
    }
    class Node<T> : IEnumerable<T> where T : IComparable
    {
        public Node<T> P;
        public Node<T> L;
        public Node<T> R;
        public T Value;
        public int Count = 1;
        public T this[int i] { get { return GetNode(i).Value; } }
        public Node(T value) { this.Value = value; }
        public void Rotate()
        {
            var pp = P.P;
            var p = P;
            Node<T> c;
            if (p.L == this)
            {
                // 親の左が自分の場合
                c = R;
                this.R = p;
                p.L = c;
            }
            else
            {
                // 親の右が自分の場合
                c = L;
                this.L = p;
                p.R = c;
            }
            if (pp != null && pp.L == p) pp.L = this;
            if (pp != null && pp.R == p) pp.R = this;
            this.P = pp;
            p.P = this;
            if (c != null) c.P = p;

            // 状態の更新
            p.Update();
            this.Update();
        }
        public int State()
        {
            if (P == null) return 0;
            else if (P.L == this) return 1;
            else return -1;
        }
        public void Splay()
        {
            while (this.State() != 0)
            {
                if (P.State() == 0) this.Rotate();
                else if (this.State() == P.State())
                {
                    P.Rotate();
                    this.Rotate();
                }
                else
                {
                    this.Rotate();
                    this.Rotate();
                }
            }
        }
        public void Update()
        {
            // TODO: 問題によって書き換える
            this.Count = 1;
            this.Count += L?.Count ?? 0;
            this.Count += R?.Count ?? 0;
            // rmq
            //this.Min = this.Value;
            //if (L != null && Min.CompareTo(L.Value) > 0)
            //{
            //    Min = L.Value;
            //}
            //if (R != null && Min.CompareTo(R.Value) > 0)
            //{
            //    Min = R.Value;
            //}
        }
        public Node<T> GetNode(int index)
        {
            var now = this;
            while (true)
            {
                var lcount = now.L?.Count ?? 0;
                if (index < lcount)
                {
                    now = now.L;
                }
                else if (index == lcount)
                {
                    now.Splay();
                    return now;
                }
                else
                {
                    index -= lcount + 1;
                    now = now.R;
                }
            }
        }
        public IEnumerator<T> GetEnumerator()
        {
            for (int i = 0; i < this.Count; i++) yield return GetNode(i).Value;
        }
        IEnumerator IEnumerable.GetEnumerator() { return this.GetEnumerator(); }
    }
