public class BIT
{
    //1-indexed
    long[] _item;
    public BIT(int num)
    {
        _item = new long[num + 1];
    }
    public long this[int index]
    {
        get { var s = 0L; for (var i = index; i > 0; i -= i & -i) s += _item[i]; return s; }
    }
    public void add(int index, long value)
    {
        for (var i = index; i < _item.Length; i += i & -i) _item[i] += value;
    }
}

