        int inputCount = (int)inpt[0];
        this.Target = inpt[1];
        this.Items = new long[inputCount];
        long ans = 0;
        for (int i = 0; i < inputCount; i++) {
            this.Items[i] = long.Parse(Reader.ReadLine());
            if(this.Items[i] >= this.Target) {
                ans++;
                dic.Add(i, new Dictionary<int, long>());
                dic[i].Add(0, this.Items[i]);
            }
        }
        for (int i = 1; i < inputCount - 1; i++) {
            int add = 0;
            int[] keys = dic.Keys.ToArray();
            foreach(int key in keys) {
                if(key + i < inputCount && dic[key].ContainsKey(i-1) && (!dic[key].ContainsKey(i))) {
                    long tmp = dic[key][i - 1] + this.Items[key + i];
                    if(tmp >= Target * (i+1)) {
                        add++;
                        dic[key][i] = tmp;
                        if(!dic.ContainsKey(key+i)) {
                            dic.Add(key+i, new Dictionary<int, long>());
                        }
                        dic[key + i][i * -1] = tmp;
                    }
                }
                int idx = i * -1;
                if(key - i >= 0 && (dic[key].ContainsKey(idx+1)) && (!dic[key].ContainsKey(idx))) {
					long tmp = dic[key][idx+1] + this.Items[key + idx];
					if (tmp >= Target * (i + 1))
					{
                        add++;
						dic[key][idx] = tmp;
						if (!dic.ContainsKey(key - i))
						{
							dic.Add(key - i, new Dictionary<int, long>());
						}
						dic[key - i][i] = tmp;
					}
				}
            }
            if(add == 0) {
                break;
            }
            ans += add;
        }
        Console.WriteLine(ans);

    }
