		{
			if (unif[node] != Unit)
			{
				seg[node] = Math.Max(seg[node], unif[node]);
				if (node < N2 - 1)
				{
					unif[2 * node + 1] = Math.Max(unif[2 * node + 1], unif[node]);
					unif[2 * node + 2] = Math.Max(unif[2 * node + 2], unif[node]);
				}
				unif[node] = Unit;
			}
