public class Solver
{
	public void Solve()
	{
		long N = GetLong();
		long K = GetLong();
		var a = GetLongs(N);

		long asum = 0;
		var b = new long[N + 1];  // b[0] = 0;
		for(long i = 0; i < N; i++)
		{
			asum += a[i];
			b[i + 1] = asum - (i + 1) * K;
		}

		var tmp = b.Distinct().ToList();
		tmp.Sort();
		var dict = tmp.Select((x, i) => (x, i)).ToDictionary(x => x.Item1, x => x.Item2);
		var st = new SegmentTree<long>(N + 1, 0, (x, y) => x + y);

		long cnt = 0;
		for(long i = 0; i <= N; i++)
		{
			long c = dict[b[i]];
			cnt += st.Query(0, c + 1);
			st.Update(c, st[c] + 1);
		}
		WriteLine(cnt);
	}
}

public class SegmentTree<T>
{
	private long N;
	private T INI;
	private Func<T, T, T> Func;
	private T[] dat;

	public T this[long index]
	{
		get { return dat[index + N - 1]; }
		set { Update(index, value); }
	}

	public SegmentTree(long n, T ini, Func<T, T, T> func)
	{
		N = 1;		
		while(N < n)
			N <<= 1;

		INI = ini;
		Func = func;

		dat = new T[2 * N - 1];
		for(long i = 0; i < 2 * N - 1; i++)
			dat[i] = INI;
	}

	public void Update(long k, T a)
	{
		k += N - 1;
		dat[k] = a;
		while(k > 0)
		{
			k = (k - 1) / 2;
			dat[k] = Func(dat[k * 2 + 1], dat[k * 2 + 2]);
		}
	}

	public T Query(long a, long b, long k = 0, long l = 0, long r = -1)
	{
		if(r == -1)
			r = N;

		if(r <= a || b <= l)
			return INI;

		if(a <= l && r <= b)
			return dat[k];
		else
		{
			T vl = Query(a, b, k * 2 + 1, l, (l + r) / 2);
			T vr = Query(a, b, k * 2 + 2, (l + r) / 2, r);
			return Func(vl, vr);
		}
	}
}

