        public class Node
        {
            private static Random Rand = new Random();
            public T Value;
            public Node L = null;
            public Node R = null;
            public int Count;
            public double Priority;
            //public T Min;
            public Node(T value, double priority)
            {
                this.Value = value;
                this.Priority = priority;
                this.Count = 1;
