    class MeaningfulMean
    {
        public static void Main()
        {
            //BITWithCompresserTest(new long[] { 1, 2, 3, 3, 5, 7, 7, 7, 11, 13, 17, 19 });
            var nk = ReadLine().Trim().Split(' ').Select(i => int.Parse(i)).ToArray();
            var a = new int[nk[0]].Select(_ => int.Parse(ReadLine().Trim())).ToArray();
            WriteLine(Solve(nk[0], nk[1], a));
        }
        static void BitTest(int[] testCase)
        {
            var bit = new BinaryIndexedTree(testCase.Max() + 1);
            foreach (var t in testCase) bit.Add(t, 1);
            for(var i = 0; i < 20; ++i) WriteLine(i.ToString() + " => " + bit[i]);
            return;
        }
        static void CompresserTest(long[] testCase)
        {
            var comp = new CoordinateCompresser(testCase.Distinct().ToArray(), true);
            foreach (var t in testCase) WriteLine(t.ToString() + " => " + comp.CoordinateToRank(t));
            return;
        }
        static void BITWithCompresserTest(long[] testCase)
        {
            var comp = new CoordinateCompresser(testCase.Distinct().ToArray(), true);
            var bwc = new BITWithCoordinateCompress(comp);
            foreach (var t in testCase) bwc.Increment(t);
            foreach(var t in testCase) WriteLine(t.ToString() + " => " + bwc[t]);
            return;
        }
        class CoordinateCompresser
        {
            long[] _RankToCoordinate;
            Dictionary<long, int> _CoordinateToRank;
            public long IndexToPosition(int idx)
            {
                return _RankToCoordinate[idx];
            }
            public int CoordinateToRank(long pos)
            {
                return _CoordinateToRank[pos];
            }
            public CoordinateCompresser(long[] pos, bool discending = false)
            {
                _RankToCoordinate = (discending) ? pos.OrderByDescending(_ => _).ToArray() : pos.OrderBy(_ => _).ToArray();
                _CoordinateToRank = new Dictionary<long, int>();
                for (var i = 0; i < _RankToCoordinate.Length; ++i)
                    _CoordinateToRank.Add(_RankToCoordinate[i], i);
            }
            public int Length
            {
                get { return _RankToCoordinate.Length; }
            }
        }
        static int Solve(int n, int k, int[] a)
        {
            long sum = 0;
            var adiff = a.Select(i => i - k).Select(i => sum += i).ToArray();
            var compresser = new CoordinateCompresser(adiff.Distinct().ToArray(), true);
            var bit = new BITWithCoordinateCompress(compresser);
            var partialBit = new BITWithCoordinateCompress(compresser);
            foreach (var diff in adiff)
                bit.Increment(diff);
            int res = (adiff.Any(_ => _ == 0)) ? bit[0] : 0;
            foreach(var diff in adiff) {
                partialBit.Increment(diff);
                res += bit[diff] - partialBit[diff];
            }
            return res;
        }
        class BITWithCoordinateCompress
        {
            BinaryIndexedTree bit;
            CoordinateCompresser comp;
            public BITWithCoordinateCompress(CoordinateCompresser compressor)
            {
                bit = new BinaryIndexedTree(compressor.Length);
                comp = compressor;
            }
            public void Increment(long pos)
            {
                bit.Add(comp.CoordinateToRank(pos), 1);
            }
            public int this[long pos]
            {
                get
                {
                    return bit[comp.CoordinateToRank(pos)];
                }
            }
        }
        class BinaryIndexedTree
        {
            int[] array;
            public BinaryIndexedTree(int size)
            {
                array = new int[size];
            }
            public void Add(int idx, int num)
            {
                for (Index index = idx; index && index < array.Length; index.MoveUp()) {
                    array[index] += num;
                }
            }
            public int this[int idx]
            {
                get {
                    int res = 0;
                    for (Index index = idx; index; index.MoveLeft()) {
                        res += array[index];
                    }
                    return res;
                }
            }
            struct Index
            {
                int idx;
                Index(int index)
                {
                    idx = index;
                }
                public static implicit operator Index(int index)
                {
                    return new Index(index);
                }
                public static implicit operator int(Index index)
                {
                    return index.idx;
                }
                public static implicit operator bool(Index index)
                {
                    return index >= 0;
                }
                public void MoveUp()
                {
                    idx += (idx + 1) & (~idx);
                }
                public void MoveLeft()
                {
                    idx -= (idx + 1) & (~idx);
                }

            }
        }
    }
}
