class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var N = sc.ReadInt();
        var K = sc.ReadLong();
        var A = sc.ReadLongArray(N);
        var sum = new long[N + 1];
        for (int i = 0; i < N; i++)
        {
            sum[i + 1] = sum[i] + A[i];
        }
        var B = new long[N + 1];
        for (int i = 0; i < N + 1; i++)
        {
            B[i] = sum[i] - K * i;
        }
        var cb = new Compress<long>();
        cb.Add(B);
        cb.Build();
        var bit = new BinaryIndexedTree(N + 1);
        var ans = 0L;
        for (int i = 0; i < N + 1; i++)
        {
            var val = cb.Get(B[i]);
            var count = bit.Sum(0, val + 1);
            ans += count;
            bit.Add(val, 1);
        }
        Console.WriteLine(ans);
    }

    class Compress<T> where T : IComparable<T>
    {
        public List<T> A = new List<T>();
        public T[] Compressed;
        public void Add(T x) { this.A.Add(x); }
        public void Add(IEnumerable<T> x) { this.A.AddRange(x); }
        public T[] Build()
        {
            this.Compressed = this.A.Distinct().OrderBy(a => a).ToArray();
            //this.Compressed = this.A.Distinct().ToArray();
            //Array.Sort(this.Compressed);
            return this.Compressed;
        }
        public int Get(T x)
        {
            if (this.Compressed == null) this.Build();
            var l = -1;
            var r = Compressed.Length;
            while (r - l > 1)
            {
                var mid = l + (r - l) / 2;
                var v = Compressed[mid];
                if (x.CompareTo(v) <= 0) r = mid;
                else l = mid;
            }
            return r;
        }
        public T this[int i] { get { return this.Compressed[i]; } }
    }

    class BinaryIndexedTree
    {
        public int N { get; set; }
        public long[] Array { get; set; }
        public BinaryIndexedTree(int n)
        {
            this.N = n;
            this.Array = new long[N + 1];
        }
        // 0-indexedで指定
        public void Add(int index0, long value)
        {
            var index1 = index0 + 1;
            while (index1 <= this.N)
            {
                this.Array[index1] += value;
                index1 += index1 & (-index1);
            }
        }
        // 区間[l, r)の計算
        public long Sum(int l, int r)
        {
            return this.Sum(r) - this.Sum(l);
        }
        private long Sum(int index)
        {
            var sum = 0L;
            while (index > 0)
            {
                sum += this.Array[index];
                index -= index & (-index);
            }
            return sum;
        }
    }
    static Scanner sc = new Scanner();
}
