public class Bit{
	private int n;
	private int[] bit;
	public Bit(int n){
		this.n=n;
		bit=new int[n+1];
	}
	public void Ud(int a,int p){while(a<=n){bit[a]+=p;a+=a&-a;}}
	public int Get(int n){
		int a=0;
		while(n>0){a+=bit[n];n-=n&-n;}
		return a;
	}
}

