	var ans int64
	for i := 0; i < n; i++ {
		aa[i] = getNextInt64(scanner) - k
		ss[i+1] = ss[i] + aa[i]
		if ss[i+1] >= 0 {
			ans++
		}
	}

	ranks := make(Ranks, n)
	for i := 0; i < n; i++ {
		ranks[i].i = i
		ranks[i].s = ss[i+1]
	}

	sort.Sort(ranks)
	r := 0
	for i := 0; i < n; i++ {
		if i > 0 && ranks[i].s > ranks[i-1].s {
			r++
		}
		ranks[i].r = r
		if i == 0 {
			continue
		}

		ranks[i-1].s = int64(ranks[i-1].i)
	}
