	sort.Sort(ranks)

	seg := Segment{}
	seg.init(r + 1)

	for i := n - 1; i >= 0; i-- {
		ans += seg.sum(ranks[i].r, r+1)
		seg.add(ranks[i].r, 1)
	}

	fmt.Fprintln(writer, ans)
	writer.Flush()
