type Rank struct {
	i, r int
	s    int64
}

type Ranks []Rank

func (a Ranks) Len() int           { return len(a) }
func (a Ranks) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a Ranks) Less(i, j int) bool { return a[i].s < a[j].s }

// Segment ...
type Segment struct {
	n, h, i, chunk, inf int
	unit                []int
	bucket              [][]int
}

func (seg *Segment) init(n int) {
	seg.n = n
	seg.unit = make([]int, 1)
	seg.unit[0] = 1
	seg.bucket = make([][]int, 1)
	seg.bucket[0] = make([]int, n)

	chunk := 8
	for i := 0; n > 1; i++ {
		n = (n-1)/chunk + 1
		seg.bucket = append(seg.bucket, make([]int, n))
		seg.unit = append(seg.unit, seg.unit[i]*chunk)
	}
	seg.h = len(seg.unit)
	seg.chunk = chunk
	seg.inf = math.MaxInt32
}

func (seg *Segment) add(index, value int) {
	for i := 0; i < seg.h; i++ {
		seg.bucket[i][index/seg.unit[i]] += value
	}
}
func (seg *Segment) sum(l, r int) int64 {
	var ans int64
	for i := l; i < r; i++ {
		for seg.i = 0; seg.i < seg.h-1 && i%seg.unit[seg.i+1] == 0; seg.i++ {
			if i+seg.unit[seg.i+1] >= r {
				break
			}
		}
		ans += int64(seg.bucket[seg.i][i/seg.unit[seg.i]])
	}

	return ans
}

