  }
  c := compress(b)
  m := int64(0)
  bit := BinaryIndexTree{make([]int,n+1)}
  for i:=0;i<n+1;i++ {
    m += int64(bit.Sum(c[i]))
    bit.Add(c[i],1)
  }
  fmt.Print(m)
