func compress(a []int64) []int {
  b := make([]int64,len(a))
  copy(b,a)
  sort.Sort(Int64Slice(b))
  m := map[int64]int{}
  v := 1
  for i:=0;i<len(b);i++ {
    if _,ok := m[b[i]];ok { continue }
    m[b[i]] = v
    v++
  }
  c := make([]int,len(a))
  for i:=0;i<len(a);i++ { c[i] = m[a[i]] }
  return c
}

type Int64Slice []int64
func(s Int64Slice) Len() int { return len(s) }
func(s Int64Slice) Less(i,j int) bool { return s[i] < s[j] }
func(s Int64Slice) Swap(i,j int) { s[i],s[j] = s[j],s[i] }

type BinaryIndexTree struct { bit []int }
func(b *BinaryIndexTree) Add(i,v int) {
  for x:=i;x<=len(b.bit);x+=x&-x { b.bit[x-1] += v }
}
func(b *BinaryIndexTree) Sum(i int) int {
  r := 0
  for x:=i;x>0;x-=x&-x { r += b.bit[x-1] }
  return r
}

