  }
  sort.Sort(ASVec(AS))
  ST := InitST(N + 1)
  for _, as := range AS {
    cnt += N - as.Index - ST.GetAfter(as.Index, 1)
    ST.Update(as.Index)
  }
  Write(cnt)
  Output()
}

