func NewTrieNode() *TrieNode {
	var nxt  [char_size]int
	for i := 0; i < char_size; i++ {
		nxt[i] = -1
	}

	return &TrieNode{nxt, make([]int, 0), 0}
}

// Trie Tree
type TrieTree struct {
	nodes	[]TrieNode
	root	int
}

func NewTrieTree() *TrieTree {
