func compress(a []int64) []int {
  b := make([]int64,len(a))
  copy(b,a)
  sort.Sort(Int64Slice(b))
  m := map[int64]int{}
  v := 0
  for i:=0;i<len(b);i++ {
    if _,ok := m[b[i]];ok { continue }
    m[b[i]] = v
    v++
  }
  c := make([]int,len(a))
  for i:=0;i<len(a);i++ { c[i] = m[a[i]] }
  return c
}

