type BinaryIndexTree struct { bit []int }
func(b *BinaryIndexTree) add(i,v int) {
  for x:=i;x<=len(b.bit);x+=x&-x {
    b.bit[x-1] += v
  }
}
func(b *BinaryIndexTree) sum(i int) int {
  r := 0
  for x:=i;x>0;x-=x&-x {
    r += b.bit[x-1]
  }
  return r
}
func(b *BinaryIndexTree) update(i,v int) {
  for x:=i;x<=len(b.bit);x+=x&-x {
    if b.bit[x-1] < v { b.bit[x-1] = v }
  }
}
func(b *BinaryIndexTree) max(i int) int {
  r := 0
  for x:=i;x>0;x-=x&-x {
    if r < b.bit[x-1] { r = b.bit[x-1] }
  }
  return r
}

