type AreaSum struct {
  Sum int
  Index int
}
type ASVec []AreaSum
func (AS ASVec) Len() int { return len(AS) }
func (AS ASVec) Less(i, j int) bool {
  if AS[i].Sum == AS[j].Sum { return AS[i].Index < AS[j].Index }
  return AS[i].Sum < AS[j].Sum
}
func (AS ASVec) Swap(i, j int) { AS[i], AS[j] = AS[j], AS[i] }

type Item struct {
  Value int
  Left int
  Right int
}
type SegmentTree struct {
  Size int
  Data []Item
}
func (ST SegmentTree) Update(i int) {
  idx := ST.Size + i
  for idx > 0 {
    ST.Data[idx].Value += 1
    idx /= 2
  }
}
func (ST SegmentTree) GetAfter(x, i int) int {
  if x < ST.Data[i].Left { return ST.Data[i].Value }
  if ST.Data[i].Right <= x { return 0 }
  return ST.GetAfter(x, 2 * i) + ST.GetAfter(x, 2 * i + 1)
}
func InitST(N int) *SegmentTree {
  Size := 1
  for Size < N {
    Size *= 2
  }
  Data := make([]Item, 2 * Size)
  for i := Size; i < 2 * Size; i++ {
    Data[i] = Item{0, i - Size, i - Size}
  }
  for i := Size - 1; i > 0; i-- {
    Data[i] = Item{0, Data[2 * i].Left, Data[2 * i + 1].Right}
  }
  return &SegmentTree{
    Size: Size,
    Data: Data,
  }
}

