type SegTree []int

func MakeSegTree(n_ int) SegTree {
	n := 1
	for n < n_ {
		n <<= 1
	}
	return make([]int, n*2)
}

func (t SegTree) Add(i int, v int) {
	i += len(t) >> 1
	t[i] += v
	for i > 1 {
		i >>= 1
		t[i] = t[i*2] + t[i*2+1]
	}
}

func (t SegTree) Count(l, r int) int {
	return t.countRecur(l, r, 1, 0, len(t)>>1)
}
func (t SegTree) countRecur(a, b, k, l, r int) int {
	if r <= a || b <= l {
		return 0
	}
	if a <= l && r <= b {
		return t[k]
	}
	lv := t.countRecur(a, b, k*2, l, (l+r)>>1)
	rv := t.countRecur(a, b, k*2+1, (l+r)>>1, r)
	return lv + rv
}

