auto compress(int n, long[] a) {
    auto res = new int[](n);
    auto idx = iota(n).array;

    sort(zip(a, idx));

    int num = 0;
    long p = -inf;

    foreach (i ; 0 .. n) {
        if (a[i] != p) num++;
        res[idx[i]] = num;
        p = a[i];
    }

    return res;
}

struct FenwickTree {
    private {
        int n;
        int[] data;
    }

    this(int N) {
        this.n = N;
        data = new int[](n + 1);
    }

    void add(int i, int x) {
        while (i <= n) {
            data[i] += x;
            i += i & (-i);
        }
    }

    int psum(int i) {
        return i > 0 ? psum(i - (i & (-i))) + data[i] : 0;
    }
}

