const ll inf=100000000000000ll;

ll ans,a[Maxn],b[Maxn];
int cnt,t[Maxn],n,k;

int query(int x,int ans=0) {
	for(int i=x;i;i&=i-1) ans+=t[i];
	for(int i=x;i<=cnt;i+=i&-i) t[i]++;
	return ans;
}

