	for(int i=0;i<=n;i++) b[i]=a[i];
	sort(b,b+n+1);
	map<ll,int> ma;
	for(int i=0;i<=n;i++)
		if(i==0||b[i]!=b[i-1]) {
			cnt++;
			ma[b[i]]=cnt;
		}
