{
	if(a.quan==b.quan)
	return a.pos<b.pos;
	return a.quan<b.quan;
}
#define mid (tree[x].l+tree[x].r)/2
#define lc x<<1
#define rc x<<1|1
void push_up(ll x)
{
	tree[x].sum=tree[lc].sum+tree[rc].sum; 
}
void built(ll l,ll r,ll x)
{
	tree[x].l=l;
	tree[x].r=r;
	tree[x].sum=0;
	if(l==r)
	return;
	built(l,mid,lc);
	built(mid+1,r,rc);
	push_up(x);
}
void update(ll x,ll pot)
{   
	if(tree[x].l==pot&&tree[x].r==pot)
	{
	    tree[x].sum++;
	    return;
	}
	if(pot<=mid)
	update(lc,pot);
	if(pot>mid)
	update(rc,pot);
	push_up(x);
}
ll he(ll l,ll r,ll x)
{  
	if(tree[x].l==l&&tree[x].r==r)
	return tree[x].sum;
	ll ans=0;
	push_up(x);
	if(r<=mid)
	return he(l,r,lc);
	else if(l>mid)
	return he(l,r,rc);
	else
	return he(mid+1,r,rc)+he(l,mid,lc);
}
