ll tl[Maxn],tr[Maxn],tn[Maxn];
ll ans,a[Maxn],n,k;
int cnt,ls[Maxn],rs[Maxn];

int newnode(ll l,ll r) {
	int root=++cnt;
	tl[root]=l,tr[root]=r;
	return root;
}

void add(int root,ll x) {
	ll l=tl[root],r=tr[root],mid=(l+r)/2ll;
	tn[root]++;
	if(l==r) return;
	if(x<=mid) {
		if(!ls[root]) ls[root]=newnode(l,mid);
		add(ls[root],x);
	}
	else {
		if(!rs[root]) rs[root]=newnode(mid+1,r);
		add(rs[root],x);
	}
}

ll query(int root,ll ql,ll qr) {
	if(!root) return 0;
	ll l=tl[root],r=tr[root],mid=l+r>>1;
	if(ql<=l&&qr>=r) return tn[root];
	ll ans=0;
	if(ql<=mid) ans=query(ls[root],ql,qr);
	if(qr>mid) ans+=query(rs[root],ql,qr);
	return ans;
}

