    for(int i = 1; i <= n; i++)
        if(ma.find(b[i]) == ma.end()) ma[b[i]] = ++m;
    build(1, 0, m);
    for(int i = 0; i <= n; i++){
        ans = 0;
        query(1, 0, ma[a[i]]);
        res += ans;
        update(1, ma[a[i]], 1);
    }
    printf("%d\n", res);
    return 0;
}

