{
	long long *temp=(long long*)malloc(sizeof(long long)*(right-left+5));
	int i=left,j=mid+1,tempnum=0;
	while(i<=mid&&j<=right)
	{
		if(sum[i]<=sum[j])
			temp[tempnum++]=sum[i++];
		else
		{
			temp[tempnum++]=sum[j++];
			num+=mid+1-i;
			//printf("%d %d %d %d\n",i,mid,right,num);			
		}
	}
