const int maxn=2e5+100;
int n,k,siz[maxn<<2],mx;
ll a[maxn],b[maxn];
map<ll,int>bh;
inline void lsh(){
	for(int i=1;i<=n;i++) b[i]=a[i];
	sort(b+1,b+n+1),b[0]=b[1]-1;
	for(int i=1;i<=n;i++)
		if(b[i]!=b[i-1]) bh[b[i]]=++mx;
	for(int i=1;i<=n;i++) a[i]=bh[a[i]];
}
void insert(int o,int l,int r,int qz){
	siz[o]++;
	if(l==r) return;
	int mid=l+r>>1;
	if(qz<=mid) insert(o<<1,l,mid,qz);
	else insert(o<<1|1,mid+1,r,qz);
}
int query(int o,int l,int r,int qz){
	if(l==r) return l<=qz?siz[o]:0;
	int mid=l+r>>1;
	if(qz<=mid) return query(o<<1,l,mid,qz);
	else return query(o<<1|1,mid+1,r,qz)+siz[o<<1];
}
