type BinaryIndexedTree = object
  size: int
  data: seq[int]

proc initBinaryIndexedTree(n: int): BinaryIndexedTree =
  result.size = n
  result.data = newSeq[int](n + 1)

proc add(this: var BinaryIndexedTree, a: int, x: int) =
  # BIT[a] に x を加算
  var i = a
  while i <= this.size:
    this.data[i] += x
    i += i and -i

proc prefixSum(this: var BinaryIndexedTree, a: int): int =
  # [1, a] の和
  result = 0
  var i = a
  while i > 0:
    result += this.data[i]
    i -= i and -i
  return result

proc sum(this: var BinaryIndexedTree, a: int, b: int): int =
  # [a, b] の和
  return this.prefixSum(b) - this.prefixSum(a - 1)

