  proc initBIT[T](data: seq[T]; zero: T; ad: (T, T) -> T): BinaryIndexedTree[T] =
    var node = newSeqWith(data.len + 1, zero)
    for i in 1..data.len:
      node[i] = ad(node[i], data[i-1])
      if i + (i and -i) <= data.len:
        node[i + (i and -i)] = ad(node[i + (i and -i)], node[i])
    return BinaryIndexedTree[T](size: data.len, node: node, zero: zero, ad: ad)

  proc initBIT[T](size: int; zero: T; ad: (T, T) -> T): BinaryIndexedTree[T] {.inline.} =
    return BinaryIndexedTree[T](size: size, node: newSeqWith(size+1, zero),
        zero: zero, ad: ad)

  proc query[T](bit: BinaryIndexedTree[T]; n: int): T =
    var i = n
    result = bit.zero
    while i > 0:
      result = bit.ad(bit.node[i], result)
      i = i and not -i

  proc change[T](bit: BinaryIndexedTree[T]; n: int; f: T -> T) =
    var i = n+1
    while i <= bit.size:
      bit.node[i] = f(bit.node[i])
      i += i and -i

