    }

    let mut bb = vec![];
    let mut temp = 0;
    for i in 0..n {
        let a = aa[i];
        temp += a - k;
        bb.push(temp);
    }

    let mut comp = bb.clone();
    comp.sort();
    comp.dedup();

    let mut bit = BIT::new(comp.len());
    for i in 0..n {
        let b = bb[i];
        let idx = comp.binary_search(&b).unwrap();
        bit.add(idx+1, 1i64);
    }

    let mut ans = 0i64;
    let mut threshold = 0;
    for i in 0..n {
        let left = lower_bound(&comp, &threshold);
        ans += bit.range_sum(left+1, comp.len()+1);
        threshold += aa[i] - k;

        let b = bb[i];
        let idx = comp.binary_search(&b).unwrap();
        bit.add(idx+1, -1);
    }
    puts!("{}\n", ans);
}

