// find the first item match.
fn find(sorted_array: &Vec<i32>, target: i32) -> usize {
    let mut left = 0usize;
    let mut right = sorted_array.len();
    while left < right {
        let middle = (right - left) / 2 + left;
        if sorted_array[middle] < target {
            left = middle + 1;
        } else {
            right = middle;
        }
    }
    left
}

