    let mut cc = vec![0];

    for &a in &aa {
        t += a;
        cc.push(t);
    }

    cc.sort();
    cc.dedup();

    let mut seg: SEG<SUM> = SEG::new(cc.len());

    let mut t = 0;
    for &a in &aa {
        t += a;
        let c = cc.binary_search(&t).unwrap();
        seg.add(c, &1);
    }

    let m = cc.len();
    let mut ans = seg.query(cc.binary_search(&0).unwrap(), m).unwrap();

    let mut t = 0;
    for &a in &aa {
        t += a;
        let c = cc.binary_search(&t).unwrap();
        seg.add(c, &(-1));

        ans += seg.query(c, m).unwrap_or(0);
    }

    println!("{}", ans);
}

