        let i = {
            let crit = |i: isize| {
                let i = i as usize;
                let v = set.iter().skip(i).next().cloned().unwrap();
                sum < v
            };
            (lower_bound(-1, set.len() as isize, crit)+1) as usize
        };
        count += i;
        if sum >= 0 {
            count += 1;
        }
        set.insert(sum);
    }
    println!("{}", count);
}

