struct BIT<T> {
	data: Vec<T>
}

impl<T> BIT<T>
where
	T: Clone + Default + std::ops::AddAssign
{
	fn new(n: usize) -> BIT<T> {
		BIT { data: vec![T::default(); n + 1] }
	}
	fn sum(&self, i: usize) -> T {
		let mut r = T::default();
		let mut i = i;
		while i > 0 {
			r += self.data[i].clone();
			i &= i - 1;
		}
		r
	}
	fn add(&mut self, i: usize, value: T) {
		let mut i = i + 1;
		while i < self.data.len() {
			self.data[i] += value.clone();
			i += i & (!i + 1);
		}
	}
}

