fn exec() {
    let mut sc = Scanner::new();
    let n: usize = sc.ne();
    let k: i64 = sc.ne();
    let a: Vec<i64> = (0..n).map(|_| sc.ne()).collect();
    let mut b = Vec::new();
    let mut s = vec![0; n + 1];
    for i in 0..n {
        s[i + 1] = s[i] + a[i];
        s[i + 1] -= k;
        b.push((s[i + 1], i + 1));
    }
    b.sort();
    let mut mp = vec![0; n + 1];
    for i in 0..n {
        mp[b[i].1] = i;
    }
    let mut fwt = FenwickTree::new(n + 2, 0i64);
    let mut sum = 0;
    for i in (0..n).rev() {
        fwt.add(mp[i + 1], 1);
        let bound = lower_bound(&b, &(s[i], 0));
        sum += fwt.sum(n + 2) - fwt.sum(bound);
    }
    println!("{}", sum);
}

fn lower_bound<T: Ord>(a: &[T], q: &T) -> usize {
    let (mut lb, mut ub) = (-1, a.len() as i64);
    while ub - lb > 1 {
        let mid = (lb + ub) / 2;
        if a[mid as usize] >= *q {
            ub = mid;
        } else {
            lb = mid;
        }
    }
    ub as usize
}

