}
impl BinaryIndexedTree {
#[allow(dead_code)]
    fn new(n: usize) -> Self {
        BinaryIndexedTree { tree: vec![0; n+1] }
    }
#[allow(dead_code)]
    fn add(&mut self, a: usize, w: isize) {
        let mut x = a as isize + 1;
        while x < self.tree.len() as isize {
            self.tree[x as usize] += w;
            x += x & (-x);
        }
    }
#[allow(dead_code)]
    fn sum(&self, n: usize) -> isize {
        let mut x = n as isize;
        let mut ret = 0;
        while x > 0 {
            ret += self.tree[x as usize];
            x -= x & (-x);
        }
        ret
    }
#[allow(dead_code)]
    fn sum_with(&self, l: usize, r: usize) -> isize {
        if l == 0 {
            self.sum(r)
        } else {
            self.sum(r) - self.sum(l - 1)
        }
    }
}

fn solve() {
    let (n,k) = get!(usize,isize);
    let a = get!(isize;n);

    let mut sum = 0;
    let mut count = 0;
    let mut vec = Vec::new();
    vec.push(0);
    for &e in &a {
        sum += e-k;
        vec.push(sum);
    }
    vec.sort();
    let mut map = BTreeMap::new();
    for i in 0..vec.len() {
        map.entry(vec[i]).or_insert(VecDeque::new()).push_back(i);
    }

    let mut bit = BinaryIndexedTree::new(n);
    let mut sum = 0;
    if let Some(v) = map.get(&sum) {
        let i = v.iter().next().cloned().unwrap();
        bit.add(i,1);
    }
    for &e in &a {
        sum += e-k;
        if let Some(v) = map.get(&sum) {
            let i = v.iter().next().cloned().unwrap();
            let j = v.iter().rev().next().cloned().unwrap();
            count += bit.sum(j);
            bit.add(i,1);
        }
    }
    println!("{}", count);
}

