struct SegNode {
    lc: Option<Box<SegNode>>,
    rc: Option<Box<SegNode>>,
    beg: usize,
    lst: usize,
    value: i64,
}
impl SegNode {
    fn new(b: usize, e: usize) -> SegNode {
        let piv = (b + e) / 2;
        let (lc, rc) = if b == piv {
            (None, None)
        } else {
            (Some(Box::new(SegNode::new(b, piv))), Some(Box::new(SegNode::new(piv, e))))
        };
        SegNode {
            lc: lc, rc: rc, beg: b, lst: e - 1, value: 0,
        }
    }
    fn get_sum(&self, l: usize, r: usize) -> i64 {
        if l <= self.beg && self.lst <= r{
            self.value
        } else if r < self.beg || self.lst < l {
            0
        } else if let (&Some(ref lc), &Some(ref rc)) = (&self.lc, &self.rc) {
            lc.get_sum(l, r) + rc.get_sum(l, r)
        } else {
            panic!("something goes wrong (SegNode::get_sum)");
        }
    }
    fn add(&mut self, l: usize, r: usize, num: i64) {
        if l <= self.beg && self.lst <= r{
            self.value += num;
        } else if r < self.beg || self.lst < l {
        } else if let (&mut Some(ref mut lc), &mut Some(ref mut rc)) = (&mut self.lc, &mut self.rc) {
            self.value += num * (r - l + 1) as i64;
            lc.add(l, r, num);
            rc.add(l, r, num);
        }
    }
}
struct SegTree {
    size: usize,
    root: SegNode
}
impl SegTree {
    fn new(size: usize) -> SegTree {
        SegTree {
            size: size,
            root: SegNode::new(0, size),
        }
    }
    fn get_sum(&self, l: usize, r: usize) -> i64 {
        self.root.get_sum(l, min(self.size, r))
    }
    fn add(&mut self, l: usize, r: usize, num: i64) {
        self.root.add(l, min(self.size, r), num);
    }
}

