#[allow(dead_code)]
fn arc075_c() {
    input! {
        n: usize,
        k: i64,
        arr: [i64; n],
    }
    let n: usize = n;
    let k: i64 = k;
    let arr: Vec<i64> = arr;

    //    println!("{} {:?}", k, arr);

    type Args = (usize, usize); // left idx, right idx
    type Out = (usize, i64); // n possible, sum

    struct Solver {
        k: i64,
        arr: Vec<i64>,
        cache: HashMap<Args, Out>,
        n_dup: usize,
    }
    impl Solver {
        fn solve(&mut self, args: Args) -> Out {
            if self.cache.contains_key(&args) {
                let res = *self.cache.get(&args).unwrap();
                self.n_dup += res.0;
                return res;
            }
            let res = self.inner(args);
            self.cache.insert(args, res);
            res
        }

        fn inner(&mut self, args: Args) -> Out {
            let (l, r) = args;

            if l == r {
                let n = (self.arr[l] >= self.k) as usize;
                let s = self.arr[l];
//                println!("{} {} {} {}", l, r, n, s);
                return (n, s);
            }

            let out0 = self.solve((l + 1, r));
            let out1 = self.solve((l, r - 1));
            let is_ok = self.arr[r] + out1.1 >= (r - l + 1) as i64 * self.k;
            let n = (is_ok as usize) + out0.0 + out1.0;
            let s = self.arr[r] + out1.1;
//            println!("{} {} {} {}", l, r, n, s);
            (n, s)
        }
    }

    let cache = HashMap::new();
    let mut solver = Solver { k: k, arr: arr, cache: cache, n_dup: 0 };
    let out = solver.solve((0, n - 1));
    let res = out.0 - solver.n_dup;
//    println!("{:?} {}", out.0, solver.n_dup);
    println!("{:?}", res);
}

