        fn mempty(&self) -> Self::T;
        fn mappend(&self, x: &Self::T, y: &Self::T) -> Self::T;
    }
    pub struct BinaryIndexedTree<M: Monoid> {
        bit: Vec<M::T>,
        m: M,
    }
    impl<M: Monoid> BinaryIndexedTree<M> {
        pub fn new(n: usize, m: M) -> BinaryIndexedTree<M> {
            let bit = vec![m.mempty(); n + 1];
            BinaryIndexedTree { bit: bit, m: m }
        }
        #[doc = " 1-indexed"]
        pub fn query(&self, k: usize) -> M::T {
            let mut res = self.m.mempty();
            let mut k = k;
            while k > 0 {
                res = self.m.mappend(&res, &self.bit[k]);
                k -= rmb(k);
            }
            res
        }
        #[doc = " 1-indexed"]
        pub fn update(&mut self, k: usize, x: M::T) {
            let mut k = k;
            while k < self.bit.len() {
                self.bit[k] = self.m.mappend(&self.bit[k], &x);
                k += rmb(k);
            }
        }
    }
    pub struct AnyMonoid<T: Clone, F: Fn(&T, &T) -> T> {
        id: T,
        op: F,
    }
    impl<T: Clone, F: Fn(&T, &T) -> T> AnyMonoid<T, F> {
        pub fn new(id: T, op: F) -> AnyMonoid<T, F> {
            AnyMonoid { id: id, op: op }
        }
    }
    impl<T: Clone + PartialEq, F: Fn(&T, &T) -> T> Monoid for AnyMonoid<T, F> {
        type T = T;
        fn mempty(&self) -> T {
            self.id.clone()
        }
        fn mappend(&self, x: &T, y: &T) -> T {
            (self.op)(x, y)
        }
    }
    pub trait Bisect: Copy {
        fn halve(self, other: Self) -> Self;
        fn section_end(self, other: Self) -> bool;
    }
    impl Bisect for usize {
        fn halve(self, other: Self) -> Self {
            if self > other {
                other + (self - other) / 2
            } else {
                self + (other - self) / 2
            }
        }
        fn section_end(self, other: Self) -> bool {
            (if self > other {
                self - other
            } else {
                other - self
            }) <= 1
        }
    }
    impl Bisect for i64 {
        fn halve(self, other: Self) -> Self {
            (self + other) / 2
        }
        fn section_end(self, other: Self) -> bool {
            (self - other).abs() <= 1
        }
    }
    impl Bisect for f64 {
        fn halve(self, other: Self) -> Self {
            (self + other) / 2.
        }
        fn section_end(self, other: Self) -> bool {
            (self - other).abs() <= 1e-8
        }
    }
    pub fn binary_search<T: Bisect, F: Fn(T) -> bool>(f: F, ok: T, err: T) -> T {
        let mut ok = ok;
        let mut err = err;
        while !ok.section_end(err) {
            let m = ok.halve(err);
            if f(m) {
                ok = m;
            } else {
                err = m;
            }
        }
        ok
    }
    pub fn lower_bound<T: Bisect + Ord>(v: &[T], x: T) -> usize {
        binary_search(|i| v[i as usize] >= x, v.len() as i64, -1) as usize
    }
}
