pub struct BIT {
    size: usize,
    data: Vec<i64>,
}

impl BIT {
    fn new(n: usize) -> BIT {
        BIT {
            size: n,
            data: vec![0;n],
        }
    }

    // sum [0, k)
    fn query_key(&self, k: usize) -> i64 {
        let mut res = 0;
        let mut i = k;
        while i > 0 {
            i -= 1;
            res += self.data[i];
            i &= i + 1;
        }
        res
    }

    // sum [l, r)
    fn query_range(&self, l: usize, r: usize) -> i64 {
        debug_assert!(l <= r);
        if l == 0 {
            self.query_key(r)
        } else {
            self.query_key(r) - self.query_key(l)
        }
    }

    fn add(&mut self, k: usize, x: i64) {
        debug_assert!(k < self.size);
        let mut i = k;
        while i < self.size {
            self.data[i] += x;
            i |= i + 1;
        }
    }
}

