struct Bit {
    array: Vec<i32>,
}

impl Bit {
    fn add(&mut self, index: usize, value: i32) {
        let mut next_index = index;
        while next_index < self.array.len() {
            self.array[next_index] += value;
            next_index += (next_index as i64 & -(next_index as i64)) as usize;
        }
    }

    fn sum(&self, index: usize) -> i32 {
        let mut next_index = index as i64;
        let mut result = 0;
        while next_index > 0 {
            result += self.array[next_index as usize];
            next_index -= (next_index as i64 & -(next_index as i64));
        }
        result
    }
}

