        .split_whitespace()
        .map(|s| s.trim().parse::<i32>().unwrap())
        .collect();
    let n = first_line[0];
    let k = first_line[1];
    input.clear();
    let mut b = vec![0; 1 + n as usize];

    for i in 1..1 + n as usize {
        io::stdin().read_line(&mut input);
        let number: i32 = input.trim().parse().unwrap();
        input.clear();
        b[i] = b[i - 1];
        b[i] += number;
        b[i] -= k;
    }

